const soaEngine = window.SFMSoaEngine.createSoaEngine({
  controls: ANNEX_CONTROLS,
  applicabilityOptions: SOA_APPLICABILITY_OPTIONS,
  implementationOptions: SOA_IMPLEMENTATION_OPTIONS,
  defaultOwnerByModule: SOA_DEFAULT_OWNER_BY_MODULE,
  idFactory: () => crypto.randomUUID()
});

function createDefaultSoaRegister() {
  return soaEngine.normalizeRegister([]);
}

function defaultSoaRecord(control) {
  return soaEngine.defaultRecord(control);
}

function normalizeSoaRegister(records = []) {
  return soaEngine.normalizeRegister(records);
}

function normalizeSoaRecord(record = {}, control = ANNEX_CONTROLS[0]) {
  return soaEngine.normalizeRecord(record, control);
}

