function updateBackendPasswordPolicy(policy) {
  if (!policy || typeof policy !== "object") return;
  backendPasswordPolicy = {
    minLength: Math.max(12, Number(policy.minLength) || 12),
    maxLength: Math.max(64, Number(policy.maxLength) || 256),
    historyCount: Math.max(1, Number(policy.historyCount) || 5),
    compositionRequired: Boolean(policy.compositionRequired)
  };
}

function passwordPolicySummary() {
  return `Mindestens ${backendPasswordPolicy.minLength} Zeichen; nicht Benutzername oder E-Mail enthalten; keines der letzten ${backendPasswordPolicy.historyCount} Passwörter wiederverwenden.`;
}

function passwordPolicyInputAttributes() {
  return `minlength="${backendPasswordPolicy.minLength}" maxlength="${backendPasswordPolicy.maxLength}"`;
}

function passwordClientError(value) {
  const password = String(value || "");
  if (password.length < backendPasswordPolicy.minLength) return `Das Passwort braucht mindestens ${backendPasswordPolicy.minLength} Zeichen.`;
  if (password.length > backendPasswordPolicy.maxLength) return `Das Passwort darf höchstens ${backendPasswordPolicy.maxLength} Zeichen enthalten.`;
  return "";
}

function passwordApiErrorMessage(error) {
  const code = String(error?.payload?.code || "");
  const messages = {
    password_too_short: `Das Passwort braucht mindestens ${backendPasswordPolicy.minLength} Zeichen.`,
    password_too_long: `Das Passwort darf höchstens ${backendPasswordPolicy.maxLength} Zeichen enthalten.`,
    password_contains_control_character: "Das Passwort enthält ein nicht erlaubtes Steuerzeichen.",
    password_too_common: "Dieses Passwort ist zu häufig und deshalb nicht erlaubt.",
    password_contains_account_identity: "Das Passwort darf Benutzername oder E-Mail-Adresse nicht enthalten.",
    password_recently_used: `Dieses Passwort wurde kürzlich verwendet. Die letzten ${backendPasswordPolicy.historyCount} Passwörter sind gesperrt.`
  };
  return messages[code] || error?.message || "Passwort konnte nicht verarbeitet werden.";
}

function invitationApiErrorMessage(error) {
  const code = String(error?.payload?.code || "");
  const message = String(error?.message || "").toLowerCase();
  if (code === "invitation_account_exists" || message.includes("account already exists")) {
    return "Für diese E-Mail-Adresse besteht bereits ein Zugang in diesem Kunden-Workspace.";
  }
  if (message.includes("expired")) return "Dieser Einladungslink ist abgelaufen. Bitte fordere einen neuen Link an.";
  if (message.includes("revoked")) return "Diese Einladung wurde widerrufen. Bitte wende dich an den zuständigen Admin.";
  if (message.includes("accepted") || message.includes("already being accepted")) return "Diese Einladung wurde bereits verwendet.";
  if (message.includes("not found")) return "Dieser Einladungslink ist ungültig oder wurde durch einen neueren Link ersetzt.";
  return error?.message || "Einladung konnte nicht verarbeitet werden.";
}
