function ensureKnowledgeSourceDocuments(documents) {
  const normalized = Array.isArray(documents) ? [...documents] : [];
  SOURCE_FILES.forEach((file) => {
    const exists = normalized.some((doc) => doc.linkedTo === file.key || doc.name === file.name);
    if (!exists) {
      normalized.push({
        id: crypto.randomUUID(),
        name: file.name,
        area: "Wissensbasis",
        status: "Quelle",
        owner: "System",
        linkedTo: file.key,
        size: "",
        note: file.use,
        added: today()
      });
    }
  });
  return normalized;
}

function normalizeDocumentRecord(document, action = "Angelegt") {
  const sourceDocument = document.status === "Quelle" || (document.area === "Wissensbasis" && document.owner === "System");
  const added = document.added || today();
  const status = document.status || (sourceDocument ? "Quelle" : "Entwurf");
  const review = document.review || document.reviewDate || (sourceDocument ? "" : futureDate(DOCUMENT_REVIEW_DAYS));
  const approval = document.approval || (sourceDocument ? "Nicht erforderlich" : status === "Freigegeben" ? "Freigegeben" : "Nicht gestartet");
  const reviewStatus = sourceDocument ? "freigegeben" : normalizeReviewStatus(document.reviewStatus || inferReviewStatusFromDocument({ status, approval }));
  const classification = document.classification || (sourceDocument ? "Quelle" : "Intern");
  const evidenceFor = document.evidenceFor || document.linkedTo || "";
  const submittedAt = document.submittedAt || "";
  const submittedBy = document.submittedBy || "";
  const approvedAt = document.approvedAt || "";
  const approvedBy = document.approvedBy || "";
  const workflowHistory = Array.isArray(document.workflowHistory) && document.workflowHistory.length
    ? document.workflowHistory
    : [{
      date: added,
      action,
      by: document.owner || (sourceDocument ? "System" : "SFM Compliance"),
      note: document.note || "Dokument im Register angelegt."
    }];

  return {
    ...document,
    added,
    status,
    version: document.version || (sourceDocument ? "Quelle" : "0.1"),
    review,
    approval,
    reviewStatus,
    classification,
    evidenceFor,
    submittedAt,
    submittedBy,
    approvedAt,
    approvedBy,
    resubmittedAfterReworkAt: document.resubmittedAfterReworkAt || "",
    resubmissionCount: Number(document.resubmissionCount || 0),
    reworkRequestedAt: document.reworkRequestedAt || "",
    reworkRequestedBy: document.reworkRequestedBy || "",
    reworkReason: document.reworkReason || "",
    reworkDue: document.reworkDue || "",
    consultantInternalComment: document.consultantInternalComment || "",
    customerComment: document.customerComment || document.reworkReason || "",
    auditRelevant: Boolean(document.auditRelevant),
    reviewUpdatedAt: document.reviewUpdatedAt || "",
	    reviewer: document.reviewer || "",
	    reviewTaskId: document.reviewTaskId || "",
	    reviewDecisionHistory: Array.isArray(document.reviewDecisionHistory) ? document.reviewDecisionHistory : [],
	    versionHistory: normalizeVersionHistory(document.versionHistory),
	    workflowHistory
	  };
	}

function normalizeDocuments(documents) {
	  return ensureKnowledgeSourceDocuments(documents)
      .map((document) => normalizeDocumentRecord(document))
      .map(normalizeOnboardingDocumentPresentation);
	}

function customerFacingOnboardingArtifactLabel(value = "") {
  return String(value || "")
    .replaceAll("ISMS Scope aus Kunden-Onboarding", "ISMS Scope Arbeitsvorlage")
    .replaceAll("ISMS Manual Startentwurf", "ISMS Manual Arbeitsvorlage")
    .replaceAll("Asset-Inventar Startentwurf", "Asset-Inventar Arbeitsvorlage")
    .replaceAll("Lieferanten-Sicherheitscheck Startentwurf", "Lieferanten-Sicherheitscheck Arbeitsvorlage")
    .replaceAll("Startentwurf", "Arbeitsvorlage");
}

function normalizeOnboardingDocumentPresentation(document = {}) {
  const note = String(document.note || "");
  const name = String(document.name || "");
  const onboardingDocument = note.includes("Kunden-Onboarding") || name.includes("Startentwurf") || name.includes("aus Kunden-Onboarding");
  if (!onboardingDocument) return document;
  return {
    ...document,
    name: customerFacingOnboardingArtifactLabel(name),
    note: customerFacingOnboardingArtifactLabel(note)
      .replace("Aus Kunden-Onboarding als vorbefüllter Template-Entwurf erzeugt:", "Aus dem Startprofil als Arbeitsvorlage erzeugt:")
      .replace("Aus Kunden-Onboarding vom", "Aus dem Startprofil vom")
  };
}

function normalizeOnboardingTemplateDraftPresentation(draft = {}) {
  if (draft.source !== "Kunden-Onboarding") return draft;
  return {
    ...draft,
    title: customerFacingOnboardingArtifactLabel(draft.title),
    documentKind: draft.documentKind === "Template-Entwurf" ? "Arbeitsvorlage" : draft.documentKind
  };
}

function templateDraftDisplayTitle(draft = {}, fallback = "Arbeitsvorlage") {
  const title = draft.title || draft.templateTitle || fallback;
  return customerFacingOnboardingArtifactLabel(title);
}

function templateDraftDisplayMeta(draft = {}) {
  const date = draft.updated || draft.added || today();
  if (draft.source === "Kunden-Onboarding") {
    return `${draft.templateTitle || draft.area || "Startprofil"} · Arbeitsvorlage · ${date}`;
  }
  return `${draft.templateTitle || draft.area || "Template"} · ${date}`;
}

function templateDraftEditorEyebrow(draft = {}) {
  if (draft.source === "Kunden-Onboarding") return "Arbeitsvorlage";
  const template = TEMPLATE_LIBRARY.find((item) => item.id === draft.templateId);
  return template && isPolicyLikeTemplate(template) ? "Policy-Editor" : "Vorlagen-Editor";
}

function templateDraftEditorHelpText(draft = {}) {
  if (draft.source === "Kunden-Onboarding") {
    return "Aus dem Startprofil vorbereitet. Bitte Inhalte prüfen, ergänzen und danach zur Beraterprüfung einreichen.";
  }
  return "Volltext bearbeiten, Metadaten pflegen und den Dokumentverweis synchron halten.";
}

function isOnboardingRiskAssessmentDraft(draft = {}) {
  const generatedKey = String(draft.generatedKey || "");
  const title = `${draft.title || ""} ${draft.templateTitle || ""}`;
  return draft.source === "Kunden-Onboarding" && (
    draft.templateId === "risk-assessment-report"
    || generatedKey.endsWith(":risk-assessment-report")
    || title.includes("Risk Assessment Startentwurf")
  );
}

function isOnboardingRiskAssessmentDocument(document = {}) {
  const name = String(document.name || "");
  const note = String(document.note || "");
  const onboardingSource = note.includes("Kunden-Onboarding") || note.includes("Startprofil");
  const riskAssessmentName = name.includes("Risk Assessment Startentwurf") || name.includes("Risk Assessment Arbeitsvorlage");
  return (onboardingSource || riskAssessmentName)
    && (note.includes("Risk Assessment Report") || riskAssessmentName);
}

function isRemovedCustomerRiskAnalysisArtifact(record = {}) {
  const blob = JSON.stringify(record || {}).toLowerCase();
  return blob.includes("260619_bfv_dora_ikt_risikoanalyse_2026")
    || blob.includes("bfv_dora_ikt_risikoanalyse")
    || blob.includes("dora_ikt_risikoanalyse_2026")
    || blob.includes("260619_bfv_dora_ikt_risikoanalyse")
    || blob.includes("dora_ikt_risikoanalyse")
    || blob.includes("dora ikt risikoanalyse")
    || blob.includes("dora-ikt-risikoanalyse")
    || blob.includes("bfv dora ikt risikoanalyse")
    || blob.includes("risk assessment startentwurf")
    || blob.includes("risk assessment arbeitsvorlage")
    || isOnboardingRiskAssessmentDocument(record)
    || isOnboardingRiskAssessmentDraft(record);
}

function removeCustomerRiskAnalysisArtifactsFromState(workspace = {}) {
  const cleaned = { ...workspace };
  [
    "documents",
    "templateDrafts",
    "tasks",
    "notifications",
    "auditTrail",
    "reviewCenter",
    "auditPackageItems"
  ].forEach((collection) => {
    if (Array.isArray(cleaned[collection])) {
      cleaned[collection] = cleaned[collection].filter((record) => !isRemovedCustomerRiskAnalysisArtifact(record));
    }
  });
  if (cleaned.auditPackage && typeof cleaned.auditPackage === "object") {
    cleaned.auditPackage = { ...cleaned.auditPackage };
    Object.entries(cleaned.auditPackage).forEach(([key, value]) => {
      if (Array.isArray(value)) {
        cleaned.auditPackage[key] = value.filter((record) => !isRemovedCustomerRiskAnalysisArtifact(record));
      }
    });
  }
  return cleaned;
}

	function normalizePolicies(policies) {
	  return (Array.isArray(policies) ? policies : []).map(normalizePolicyRecord);
	}

	function normalizePolicyRecord(policy = {}) {
	  const enriched = enrichPolicyRecord(policy);
	  return {
	    ...enriched,
	    id: enriched.id || crypto.randomUUID(),
	    title: enriched.title || "Unbenannte Policy",
	    owner: enriched.owner || "",
	    version: enriched.version || "0.1",
	    status: enriched.status || "Entwurf",
	    review: enriched.review || "",
	    reviewStatus: enriched.reviewStatus || canonicalReviewStatus(enriched, "policy"),
	    updated: enriched.updated || "",
	    added: enriched.added || "",
	    reviewDecisionHistory: Array.isArray(enriched.reviewDecisionHistory) ? enriched.reviewDecisionHistory : [],
	    versionHistory: normalizeVersionHistory(enriched.versionHistory),
	    workflowHistory: Array.isArray(enriched.workflowHistory) ? enriched.workflowHistory : []
	  };
	}

	function normalizeVersionHistory(history) {
	  return (Array.isArray(history) ? history : [])
	    .filter(Boolean)
	    .map((entry) => ({
	      id: entry.id || crypto.randomUUID(),
	      date: entry.date || today(),
	      dateTime: entry.dateTime || "",
	      by: entry.by || "SFM Compliance",
	      action: entry.action || "Version aktualisiert",
	      version: entry.version || "",
	      previousVersion: entry.previousVersion || "",
	      status: entry.status || "",
	      previousStatus: entry.previousStatus || "",
	      approval: entry.approval || "",
	      review: entry.review || "",
	      linkedTo: entry.linkedTo || "",
	      fileId: entry.fileId || "",
	      previousFileId: entry.previousFileId || "",
	      sha256: entry.sha256 || "",
	      note: entry.note || "",
	      snapshot: entry.snapshot && typeof entry.snapshot === "object" ? entry.snapshot : {},
	      changes: normalizeVersionChanges(entry.changes)
	    }))
	    .slice(0, 40);
	}

		function normalizeAuditTrail(events) {
		  return (Array.isArray(events) ? events : [])
		    .filter(Boolean)
		    .map((event) => ({
	      id: event.id || crypto.randomUUID(),
	      date: event.date || today(),
	      dateTime: event.dateTime || "",
	      by: event.by || "SFM Compliance",
	      role: event.role || "",
	      action: event.action || "Aktualisiert",
	      entityType: event.entityType || "Workspace",
	      entityId: event.entityId || "",
	      entityTitle: event.entityTitle || "",
	      module: event.module || "",
	      status: event.status || "",
	      note: event.note || "",
	      source: event.source || "local",
	      metadata: event.metadata && typeof event.metadata === "object" ? event.metadata : {}
		    }))
		    .slice(0, 500);
		}

		function normalizeAuditPackageState(auditPackage = {}) {
		  const approvals = Array.isArray(auditPackage.approvals) ? auditPackage.approvals : [];
		  return {
		    approvals: approvals
		      .filter(Boolean)
		      .map((approval) => ({
		        id: approval.id || crypto.randomUUID(),
		        date: approval.date || today(),
		        dateTime: approval.dateTime || "",
		        by: approval.by || "SFM Compliance",
		        role: approval.role || "",
		        status: approval.status || "beraterfreigegeben",
		        comment: approval.comment || "",
		        fingerprint: approval.fingerprint || "",
		        version: approval.version || "1",
		        formalPercent: Number(approval.formalPercent || 0),
		        bundleReady: Number(approval.bundleReady || 0),
		        bundleTotal: Number(approval.bundleTotal || 0),
		        blockers: Array.isArray(approval.blockers) ? approval.blockers : [],
		        criteria: Array.isArray(approval.criteria) ? approval.criteria : []
		      }))
		      .slice(0, 30)
		  };
		}

		function normalizeNotificationState(notifications = {}) {
		  return {
		    readIds: Array.from(new Set(Array.isArray(notifications.readIds) ? notifications.readIds.map(String) : [])).slice(0, 1000),
		    dismissedIds: Array.from(new Set(Array.isArray(notifications.dismissedIds) ? notifications.dismissedIds.map(String) : [])).slice(0, 1000),
		    escalatedIds: Array.from(new Set(Array.isArray(notifications.escalatedIds) ? notifications.escalatedIds.map(String) : [])).slice(0, 1000)
		  };
		}

	function normalizeSocReportRecord(report) {
	  return {
    ...report,
    id: report.id || crypto.randomUUID(),
    title: report.title || socReportTitle(report),
    source: report.source || "SOC / SIEM",
    reportType: report.reportType || "SOC Monatsreport",
    periodStart: report.periodStart || "",
    periodEnd: report.periodEnd || "",
    owner: report.owner || "IT / SOC",
    status: report.status || "In Prüfung",
    alertsTotal: String(report.alertsTotal || "0"),
    criticalAlerts: String(report.criticalAlerts || "0"),
    highAlerts: String(report.highAlerts || "0"),
    openFindings: String(report.openFindings || "0"),
    incidentAssessment: report.incidentAssessment || "Keine Incident-Indikation",
    added: report.added || today()
  };
}

function normalizeSocReports(reports) {
  return (Array.isArray(reports) ? reports : []).map(normalizeSocReportRecord);
}

function loadState() {
  const stored = workspaceStore.read();
  if (!stored.ok || !stored.found) return normalizeState(seedState());
  return normalizeState(removeCustomerRiskAnalysisArtifactsFromState(stored.value));
}

function normalizeState(data) {
  const fallback = seedState();
  data = removeCustomerRiskAnalysisArtifactsFromState(data || {});
  const documents = normalizeDocuments(data.documents || fallback.documents)
    .filter((document) => !isRemovedCustomerRiskAnalysisArtifact(document));
  const templateDrafts = normalizeTemplateDrafts(data.templateDrafts || fallback.templateDrafts)
    .filter((draft) => !isRemovedCustomerRiskAnalysisArtifact(draft));
  const tasks = (Array.isArray(data.tasks) ? data.tasks : fallback.tasks)
    .filter((task) => !isRemovedCustomerRiskAnalysisArtifact(task));
  return {
    ...fallback,
    ...data,
    documents,
	    assets: data.assets || fallback.assets,
	    risks: data.risks || fallback.risks,
	    legal: data.legal || fallback.legal,
	    suppliers: data.suppliers || fallback.suppliers,
	    policies: normalizePolicies(data.policies || fallback.policies),
	    incidents: data.incidents || fallback.incidents,
    contracts: data.contracts || fallback.contracts,
    socReports: normalizeSocReports(data.socReports || fallback.socReports),
    integrations: normalizeIntegrations(data.integrations || fallback.integrations),
    onboarding: normalizeOnboarding(data.onboarding || fallback.onboarding),
    consultantGenerator: data.consultantGenerator || fallback.consultantGenerator,
    riskMethodology: normalizeRiskMethodology(data.riskMethodology || fallback.riskMethodology),
		    projectPlan: normalizeProjectPlan(data.projectPlan || fallback.projectPlan),
		    soa: normalizeSoaRegister(data.soa || fallback.soa),
		    templateDrafts,
		    auditTrail: normalizeAuditTrail(data.auditTrail || fallback.auditTrail),
		    auditPackage: normalizeAuditPackageState(data.auditPackage || fallback.auditPackage),
		    auditFindings: normalizeAuditFindings(data.auditFindings || fallback.auditFindings),
		    managementReview: normalizeManagementReview(data.managementReview || fallback.managementReview),
		    internalAuditPlan: normalizeInternalAuditPlan(data.internalAuditPlan || fallback.internalAuditPlan),
		    demo: normalizeDemoState(data.demo || fallback.demo),
		    notifications: normalizeNotificationState(data.notifications || fallback.notifications),
		    tasks
		  };
		}

function createDefaultRiskMethodology() {
  return riskEngine.defaultMethodology();
}

function normalizeRiskMethodology(methodology = {}) {
  return riskEngine.normalizeMethodology(methodology);
}

function clonePlain(value) {
  return JSON.parse(JSON.stringify(value));
}

function demoWorkspaceActive() {
  return Boolean(state.demo?.active) || demoCollectionCount() > 0;
}

function demoCollectionCount() {
  return ["documents", "assets", "risks", "legal", "suppliers", "policies", "incidents", "contracts", "tasks", "templateDrafts"]
    .reduce((sum, collection) => sum + (Array.isArray(state[collection]) ? state[collection].filter(isDemoRecord).length : 0), 0);
}

function isDemoRecord(record = {}) {
  return Boolean(record.demo) || record.source === DEMO_SOURCE || String(record.id || "").startsWith("demo-");
}

function demoBase(record) {
  return {
    ...record,
    demo: true,
    source: DEMO_SOURCE,
    added: record.added || today(),
    updated: record.updated || today()
  };
}

