function applyDemoWorkspaceData() {
  const records = demoWorkspaceRecords();
  state.demo = normalizeDemoState(state.demo);
  if (!state.demo.projectPlanBackup) state.demo.projectPlanBackup = clonePlain(state.projectPlan);
  if (!state.demo.soaBackup) state.demo.soaBackup = clonePlain(state.soa);

  Object.entries(records).forEach(([collection, rows]) => {
    upsertDemoRows(collection, rows);
  });
  applyDemoProjectPlan();
  applyDemoSoa();

  state.demo = {
    ...state.demo,
    active: true,
    loadedAt: auditTimestamp()
  };
  recordAuditTrailEvent({
    action: "Vorführdaten geladen",
    entityType: "Workspace",
    entityId: "demo-workspace",
    entityTitle: "SFM Compliance Vorführmodus",
    module: "Dashboard",
    status: "Demo aktiv",
    note: "Markierte Beispielwerte für Präsentation ergänzt. Fachliche Bewertung wird nicht ersetzt.",
    metadata: { demoRecords: demoCollectionCount() }
  });
  saveState({ immediate: true });
  showToast("Vorführdaten geladen. Demo-Einträge sind markiert und können wieder entfernt werden.");
  render();
}

function removeDemoWorkspaceData() {
  const demo = normalizeDemoState(state.demo);
  ["documents", "assets", "risks", "legal", "suppliers", "policies", "incidents", "contracts", "tasks", "templateDrafts"].forEach((collection) => {
    state[collection] = Array.isArray(state[collection]) ? state[collection].filter((record) => !isDemoRecord(record)) : [];
  });
  if (demo.projectPlanBackup) state.projectPlan = normalizeProjectPlan(demo.projectPlanBackup);
  if (demo.soaBackup) state.soa = normalizeSoaRegister(demo.soaBackup);
  state.demo = {
    active: false,
    loadedAt: "",
    projectPlanBackup: null,
    soaBackup: null
  };
  recordAuditTrailEvent({
    action: "Vorführdaten entfernt",
    entityType: "Workspace",
    entityId: "demo-workspace",
    entityTitle: "SFM Compliance Vorführmodus",
    module: "Dashboard",
    status: "Demo entfernt",
    note: "Demo-Einträge entfernt und gesicherter Projekt-/SoA-Stand wiederhergestellt.",
    metadata: {}
  });
  saveState({ immediate: true });
  showToast("Vorführdaten entfernt. Ursprünglicher Projekt-/SoA-Stand wurde wiederhergestellt.");
  render();
}

function upsertDemoRows(collection, rows) {
  const current = Array.isArray(state[collection]) ? [...state[collection]] : [];
  rows.forEach((row) => {
    const normalized = normalizeDemoRow(collection, row);
    const index = current.findIndex((item) => item.id === normalized.id);
    if (index >= 0) {
      current[index] = isDemoRecord(current[index]) ? { ...current[index], ...normalized } : current[index];
    } else {
      current.unshift(normalized);
    }
  });
  state[collection] = current;
}

function normalizeDemoRow(collection, row) {
  if (collection === "documents") return normalizeDocumentRecord(row, "Vorführdaten geladen");
  if (collection === "policies") return normalizePolicyRecord(row);
  if (collection === "templateDrafts") return normalizeTemplateDrafts([row])[0];
  if (collection === "socReports") return normalizeSocReportRecord(row);
  return row;
}

function applyDemoProjectPlan() {
  const statusById = {
    "iso-01": ["Erledigt", "ISB", futureDate(-21)],
    "iso-02": ["Erledigt", "Geschäftsleitung", futureDate(-14)],
    "iso-03": ["In Arbeit", "ISB", futureDate(10)],
    "iso-04": ["In Arbeit", "ISB", futureDate(21)],
    "iso-05": ["Offen", "ISB / HR", futureDate(35)],
    "nis-01": ["In Arbeit", "Legal / Geschäftsleitung", futureDate(14)],
    "nis-02": ["Offen", "ISB / IT", futureDate(28)],
    "shared-01": ["In Arbeit", "ISB", futureDate(7)],
    "shared-02": ["Blockiert", "Einkauf / ISB", futureDate(5)]
  };
  state.projectPlan = normalizeProjectPlan(state.projectPlan).map((item) => {
    const demo = statusById[item.id];
    if (!demo) return item;
    return {
      ...item,
      status: demo[0],
      owner: demo[1],
      due: demo[2],
      demo: true,
      source: DEMO_SOURCE
    };
  });
}

function applyDemoSoa() {
  const demoByControl = {
    "A.5.1": ["Anwendbar", "Umgesetzt", "Informationssicherheitsrichtlinie ist freigegeben und kommuniziert.", "Information Security Policy"],
    "A.5.2": ["Anwendbar", "In Umsetzung", "Rollen sind benannt; Stellvertretung und Review werden ergänzt.", "Rollenmatrix"],
    "A.5.9": ["Anwendbar", "Umgesetzt", "Kritische Assets sind initial im Inventar erfasst.", "Demo Asset-Inventar Kundenportal.xlsx"],
    "A.5.15": ["Anwendbar", "Geplant", "Zugriffskontrolle ist relevant; M365-Nachweis fehlt noch.", "Access Control Policy"],
    "A.5.19": ["Anwendbar", "In Umsetzung", "Kritische Lieferanten sind erfasst; Sicherheitscheck braucht Nacharbeit.", "Demo Lieferanten-Sicherheitscheck Cloud Provider.docx"],
    "A.8.13": ["Anwendbar", "In Umsetzung", "Backup-Prozess existiert; Restore-Test muss noch geprüft werden.", "Demo Backup-Restore-Testprotokoll.pdf"]
  };
  state.soa = normalizeSoaRegister(state.soa).map((record) => {
    const demo = demoByControl[record.controlId];
    if (!demo) return record;
    return {
      ...record,
      applicability: demo[0],
      implementation: demo[1],
      justification: demo[2],
      evidence: demo[3],
      review: futureDate(60),
      notes: "Demo-Eintrag für die Kollegenvorstellung; fachlich durch Berater zu prüfen.",
      demo: true,
      source: DEMO_SOURCE
    };
  });
}

