function handleManagementReviewApiError(error) {
  const conflict = error?.status === 409 && error?.payload?.error === "workspace_conflict";
  if (conflict) {
    backendSync = {
      ...backendSync,
      conflict: true,
      remoteUpdateAvailable: true,
      remoteRevision: error.payload.currentRevision ?? null,
      remoteUpdatedAt: error.payload.currentUpdatedAt || null,
      remoteUpdatedBy: error.payload.currentUpdatedBy || "",
      error: "Workspace wurde zwischenzeitlich geändert."
    };
    refreshBackendSyncStatus();
    showToast("Der Workspace wurde zwischenzeitlich geändert. Bitte neu laden und erneut versuchen.", "warning");
    return;
  }
  if (error?.status === 403 && error?.payload?.error === "submission_policy_violation") {
    showToast("Diese Managementbewertungs-Entscheidung benötigt Berater- oder Adminrechte.", "warning");
    return;
  }
  showToast(error?.message || "Managementbewertung konnte nicht gespeichert werden.", "warning");
}

