function refreshBackendSyncStatus() {
  document.querySelectorAll("[data-backend-sync-status]").forEach((node) => {
    node.textContent = backendSyncText();
  });
}

function createDefaultIntegrations() {
  return INTEGRATION_CATALOG.map((connector) => ({
    ...connector,
    status: "Geplant",
    owner: integrationDefaultOwner(connector.category),
    priority: integrationDefaultPriority(connector.category),
    nextStep: "API-Zugang, Datenmapping und Datenschutz-/Security-Freigabe prüfen."
  }));
}

function normalizeIntegrations(rows) {
  const existing = new Map((Array.isArray(rows) ? rows : []).map((row) => [row.id, row]));
  return createDefaultIntegrations().map((fallback) => ({ ...fallback, ...(existing.get(fallback.id) || {}) }));
}

function integrationDefaultOwner(category) {
  if (category.includes("Contracts") || category.includes("Vendor")) return "Einkauf / Legal / ISB";
  if (category.includes("Collaboration")) return "IT / Fachbereich";
  if (category.includes("Business")) return "Fachbereich / IT";
  return "IT / ISB";
}

function integrationDefaultPriority(category) {
  if (["Identity & Access", "Security & Monitoring", "Cloud & Hosting"].includes(category)) return "Hoch";
  return "Mittel";
}

function createDefaultProjectPlan() {
  return projectPlanEngine.createDefault();
}

function normalizeProjectPlan(rows) {
  return projectPlanEngine.normalize(rows);
}

function projectPlanProgress(rows = state.projectPlan) {
  return projectPlanEngine.progress(rows);
}

function dashboardStats() {
  const progress = projectPlanProgress();
  const policiesApproved = state.policies.filter((policy) => policy.status === "Freigegeben").length;
  const taskMetrics = taskEngine.metrics(state.tasks);
  const tasksDone = taskMetrics.done;
  const assetsReady = state.assets.filter((asset) => ["Freigegeben", "Archiviert"].includes(asset.status)).length;
  const risksClosed = state.risks.filter((risk) => ["Akzeptiert", "Erledigt"].includes(risk.status)).length;
  const suppliersReady = state.suppliers.filter((supplier) => supplier.review === "Freigegeben" || supplier.status === "Freigegeben").length;
  const incidentsClosed = state.incidents.filter((incident) => ["Geschlossen", "Erledigt"].includes(incident.status)).length;
  const contractsReady = state.contracts.filter((contract) => ["Aktiv", "Geprüft", "Freigegeben"].includes(contract.status)).length;
  const integrationsActive = state.integrations.filter((integration) => integration.status === "Aktiv").length;
  const integrationsInProgress = state.integrations.filter((integration) => ["In Planung", "In Umsetzung"].includes(integration.status)).length;
  const overdueTasks = taskMetrics.overdue;

  return {
    progress,
    isoPercent: parsePercent(progress.byStream["ISO 27001"]),
    nisPercent: parsePercent(progress.byStream["NIS-2"]),
    policiesApproved,
    tasksDone,
    assetsReady,
    risksClosed,
    suppliersReady,
    incidentsClosed,
    contractsReady,
    integrationsActive,
    integrationsInProgress,
    openRisks: state.risks.length - risksClosed,
    openIncidents: state.incidents.length - incidentsClosed,
    policyDrafts: state.policies.length - policiesApproved,
    overdueTasks,
    modules: [
      { id: "assets", title: "Asset Management", subtitle: "Systeme, Informationen und Owner", done: assetsReady, total: state.assets.length },
      { id: "risks", title: "Risiko Management", subtitle: "Bewertung, Behandlung und Restrisiko", done: risksClosed, total: state.risks.length },
      { id: "suppliers", title: "Vendor Management", subtitle: "Lieferanten und IKT-Lieferkette", done: suppliersReady, total: state.suppliers.length },
      { id: "policies", title: "Policy Management", subtitle: "Versionen, Reviews und Freigaben", done: policiesApproved, total: state.policies.length },
      { id: "incidents", title: "Incident Management", subtitle: "Meldewege, Bewertung und Lessons Learned", done: incidentsClosed, total: state.incidents.length },
      { id: "contracts", title: "Contract Management", subtitle: "Verträge, AVV und Sicherheitsklauseln", done: contractsReady, total: state.contracts.length },
      { id: "integrations", title: "Integrationen", subtitle: "60 API-Connectoren für Nachweise und Automatisierung", done: integrationsActive, total: state.integrations.length },
      { id: "tasks", title: "Task Management", subtitle: "Aufgaben, Fristen und Audit-Readiness", done: tasksDone, total: state.tasks.length }
    ]
  };
}

function hasLocalConsultantUnlock() {
  try {
    return sessionStorage.getItem(CONSULTANT_UNLOCK_KEY) === "enabled";
  } catch {
    return false;
  }
}

function setLocalConsultantUnlock(enabled) {
  try {
    if (enabled) {
      sessionStorage.setItem(CONSULTANT_UNLOCK_KEY, "enabled");
    } else {
      sessionStorage.removeItem(CONSULTANT_UNLOCK_KEY);
    }
  } catch {
    return false;
  }
  return true;
}

function canUseConsultantGenerator() {
  return accessControl.canUseConsultantArea(backendSessionUser, hasLocalConsultantUnlock());
}

function requireConsultantAccess() {
  if (canUseConsultantGenerator()) return true;
  showPermissionToast("den internen Beraterbereich öffnen", "Admin- oder Beraterrechten");
  return false;
}

function shouldShowConsultantEntry() {
  if (canUseConsultantGenerator()) return true;
  if (CUSTOMER_PRESENTATION_MODE) return false;
  return !(backendSessionChecked && backendSessionUser);
}

function userPermissions() {
  return accessControl.permissionsFor(backendSessionUser);
}

function userHasPermission(permission) {
  return accessControl.hasPermission(backendSessionUser, permission);
}

function roleDetails(role) {
  const backendDetails = productionAdminData.security?.roleDetails?.[role] || {};
  return { ...(ROLE_DETAILS_FALLBACK[role] || { label: role, purpose: "", recommendedFor: "" }), ...backendDetails };
}

function roleDisplayName(role) {
  return roleDetails(role).label || role;
}

function roleOptionLabel(role) {
  const detail = roleDetails(role);
  return `${detail.label || role} (${role})`;
}

function generateInitialPassword(length = Math.max(20, backendPasswordPolicy.minLength + 4)) {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!?#%+";
  const values = new Uint32Array(length);
  crypto.getRandomValues(values);
  return Array.from(values, (value) => alphabet[value % alphabet.length]).join("");
}

function appLoginUrl() {
  const origin = window.location.origin && window.location.origin !== "null" ? window.location.origin : "http://127.0.0.1:5173";
  return `${origin}/`;
}

function invitationTokenFromHash() {
  return appRouter.invitationTokenFromHash();
}

function recoveryTokenFromHash() {
  return appRouter.recoveryTokenFromHash();
}

function suggestedUsernameFromInvitation(invitation = {}) {
  const source = String(invitation.email || invitation.displayName || "kunde").split("@")[0];
  const cleaned = source
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, ".")
    .replace(/^[._-]+|[._-]+$/g, "")
    .slice(0, 64);
  return cleaned.length >= 3 ? cleaned : `kunde.${Date.now().toString().slice(-4)}`;
}

function buildTeamInvitationText(invitation = {}) {
  const detail = roleDetails(invitation.role || "customer");
  const lines = [
    "# Einladung zu SFM Compliance",
    "",
    "Hallo,",
    "",
    "du wurdest zum Kunden-Workspace in SFM Compliance eingeladen.",
    "",
    "## Einladung",
    `- Plattform: ${appLoginUrl()}`,
    `- Einladungslink: ${invitation.acceptUrl || "[Link nur direkt nach Erstellung sichtbar]"}`,
    `- Mandant: ${invitation.tenantName || backendSessionUser?.tenant?.name || "Mandant"}`,
    `- E-Mail: ${invitation.email || "[offen]"}`,
    `- Rolle: ${detail.label || invitation.role || "Kunde"} (${invitation.role || "customer"})`,
    `- Gültig bis: ${formatBackendTime(invitation.expiresAt)}`,
    "",
    "## Was du tun musst",
    "1. Einladungslink öffnen.",
    "2. Benutzername und eigenes Passwort festlegen.",
    "3. Danach im Kunden-Workspace Aufgaben, Nachweise oder Registereinträge bearbeiten.",
    "",
    "## Hinweis",
    "Die Plattform bereitet Informationen und Nachweise vor. Fachliche Bewertung und Freigabe bleiben beim Berater/Admin.",
    "",
    `Erstellt am ${today()} durch ${backendSessionUser?.username || "SFM Compliance"}.`
  ];
  return lines.join("\n");
}

function buildUserInvitation({ username, password, role, tenantName }) {
  const detail = roleDetails(role);
  const lines = [
    `# Zugang zu SFM Compliance`,
    "",
    `Hallo,`,
    "",
    `für dich wurde ein Zugang zur Plattform SFM Compliance eingerichtet.`,
    "",
    `## Zugangsdaten`,
    `- Plattform: ${appLoginUrl()}`,
    `- Mandant: ${tenantName || backendSessionUser?.tenant?.name || "Mandant"}`,
    `- Benutzername: ${username}`,
    `- Initialpasswort: ${password}`,
    `- Rolle: ${detail.label || role} (${role})`,
    "",
    `## Was diese Rolle darf`,
    detail.purpose ? `- ${detail.purpose}` : `- Die Berechtigungen sind in der Plattform rollenbasiert eingeschränkt.`,
    "",
    `## Erste Schritte`,
    `1. Plattform öffnen und mit Benutzername sowie Initialpasswort anmelden.`,
    `2. Passwort nach der ersten Anmeldung ändern.`,
    `3. Falls MFA aktiviert werden soll: im Produktivbetrieb den MFA-Prozess starten.`,
    `4. Nachweise, Aufgaben oder Dokumente nur im vorgesehenen Kundenbereich bearbeiten.`,
    "",
    `## Sicherheitshinweis`,
    `Dieses Initialpasswort wird in SFM Compliance nicht im Klartext gespeichert. Bitte über einen getrennten, sicheren Kanal an die Person übergeben und danach nicht weiterleiten.`,
    "",
    `Erstellt am ${today()} durch ${backendSessionUser?.username || "SFM Compliance"}.`
  ];
  return lines.join("\n");
}

function buildTenantProjectHandover({ tenantName, slug, adminUsername, adminPassword, starterSummary = null }) {
  const starterLines = starterSummary ? [
    "",
    "## Automatisch vorbereitete Arbeitsunterlagen",
    `- Dokumentationsanker: ${starterSummary.documents || 0}`,
    `- Startaufgaben: ${starterSummary.tasks || 0}`,
    `- Policy-Arbeitsvorlagen: ${starterSummary.policies || 0}`,
    `- Projektplan-Initialstatus: ${starterSummary.projectPlan || 0}`,
    `- Registeranker: ${(starterSummary.assets || 0) + (starterSummary.risks || 0) + (starterSummary.legal || 0) + (starterSummary.suppliers || 0)}`
  ] : [];
  const lines = [
    "# SFM Compliance Kundenprojekt",
    "",
    `Kundenprojekt: ${tenantName}`,
    `Mandanten-Slug: ${slug}`,
    `Plattform: ${appLoginUrl()}`,
    "",
    "## Erstzugang",
    `- Benutzername: ${adminUsername}`,
    `- Initialpasswort: ${adminPassword}`,
    "- Rolle: Admin (admin)",
    "",
    "## Empfohlene erste Schritte",
    "1. Als Mandanten-Admin anmelden.",
    "2. Passwort im Bereich Mein Konto ändern.",
    "3. MFA im Bereich Mein Konto aktivieren.",
    "4. Weitere Benutzer mit passenden Rollen anlegen: Kunde, Mitwirkender, Auditor oder Nur Lesen.",
    "5. Startprofil im Dashboard ausfüllen und vorbereitete Arbeitsvorlagen prüfen.",
    "6. Projektstrukturplan öffnen und Owner, Fristen sowie Nachweise zuordnen.",
    ...starterLines,
    "",
    "## Sicherheitshinweis",
    "Das Initialpasswort wird in SFM Compliance nicht im Klartext gespeichert. Bitte getrennt und sicher an die zuständige Person übergeben.",
    "",
    `Erstellt am ${today()} durch ${backendSessionUser?.username || "SFM Compliance"}.`
  ];
  return lines.join("\n");
}

