function visibleNavItems() {
  const allowedIds = new Set(navGroupsForAudience().flatMap(([, ids]) => ids));
  const allItems = shouldShowConsultantEntry() ? [...NAV_ITEMS, CONSULTANT_NAV_ITEM] : NAV_ITEMS;
  return allItems.filter(([id]) => allowedIds.has(id) && canAccessView(id));
}

