function updateTopStatusChips(view = currentView) {
  if (!topStatusChips) return;
  const roleLabel = backendSessionUser
    ? (backendSessionUser.roleLabel || roleOptionLabel(backendSessionUser.role || "viewer"))
    : t("top.role.local");
  const mode = view === "invitation"
    ? t("top.mode.invitation")
    : backendSessionUser?.platformAdmin
      ? t("top.mode.admin")
      : isCustomerWorkspaceUser()
        ? t("top.mode.customer")
        : canReviewDocuments()
          ? t("top.mode.review")
          : t("top.mode.work");
  const sync = backendSyncText();
  const reviewText = canReviewDocuments() || isBackendAdmin()
    ? t("top.review.consultant")
    : t("top.review.final");
  topStatusChips.innerHTML = [
    { label: mode, tone: "mode" },
    { label: roleLabel, tone: "role" },
    { label: sync, tone: backendSessionUser ? "sync" : "local" },
    ...(backendSessionUser ? [{ label: liveWorkspaceStatusText(), tone: `live ${liveWorkspaceEvents.status}` }] : []),
    { label: reviewText, tone: "review" }
  ].map((chip) => `<span class="top-status-chip ${escapeHtml(chip.tone)}">${escapeHtml(chip.label)}</span>`).join("");
}

