function resetHorizontalViewport() {
  document.documentElement.scrollLeft = 0;
  document.body.scrollLeft = 0;
  document.querySelector(".main")?.scrollTo({ left: 0, top: document.querySelector(".main")?.scrollTop || 0 });
  if (appView) appView.scrollLeft = 0;
}

function formatBerlinDataState(date = new Date()) {
  const partsFor = (value) => Object.fromEntries(new Intl.DateTimeFormat("de-DE", {
    timeZone: "Europe/Berlin",
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit"
  }).formatToParts(value).filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  const target = partsFor(date);
  const current = partsFor(new Date());
  const time = `${target.hour}:${target.minute}`;
  if (target.day === current.day && target.month === current.month && target.year === current.year) {
    return `Heute, ${time}`;
  }
  return `${target.day}.${target.month}.${target.year}, ${time}`;
}

function refreshBerlinDataState() {
  document.querySelectorAll("[data-live-berlin-time]").forEach((node) => {
    node.textContent = `Datenstand: ${formatBerlinDataState()} Uhr`;
  });
}

function ensureBerlinDataStateTicker() {
  refreshBerlinDataState();
  if (berlinDataStateTimer || typeof window === "undefined") return;
  berlinDataStateTimer = window.setInterval(refreshBerlinDataState, 60000);
}

function loadLanguagePreference() {
  return languageService.load();
}

function t(key, fallback = "") {
  return languageService.translate(key, fallback);
}

function navLabel(viewId, fallback = "") {
  return t(`nav.${viewId}`, fallback || viewId);
}

function setLanguage(language) {
  const next = languageService.normalize(language);
  if (next === currentLanguage) {
    closeLanguageMenu();
    return;
  }
  const result = languageService.set(next);
  currentLanguage = result.language;
  closeLanguageMenu();
  showToast(t("language.changed"));
  render();
}

function toggleLanguageMenu() {
  if (!languageMenu || !languageTrigger) return;
  const nextOpen = languageMenu.hidden;
  languageMenu.hidden = !nextOpen;
  languageTrigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
}

function closeLanguageMenu() {
  if (!languageMenu || !languageTrigger) return;
  languageMenu.hidden = true;
  languageTrigger.setAttribute("aria-expanded", "false");
}

function applyStaticTranslations() {
  document.documentElement.lang = currentLanguage === "en" ? "en" : "de";
  document.title = currentLanguage === "en" ? "SFM Compliance Dashboard" : "SFM Compliance Dashboard";
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    element.textContent = t(key, element.textContent);
  });
  if (languageCurrent) languageCurrent.textContent = t("language.current");
  document.querySelectorAll("[data-language-option]").forEach((button) => {
    const active = button.dataset.languageOption === currentLanguage;
    button.setAttribute("aria-checked", active ? "true" : "false");
    button.classList.toggle("active", active);
  });
  if (guideToggleBtn) {
    guideToggleBtn.title = t("button.help");
    guideToggleBtn.setAttribute("aria-label", t("button.help"));
  }
}

function loadCustomerGuidePreference() {
  try {
    return localStorage.getItem(CUSTOMER_GUIDE_KEY) === "on";
  } catch {
    return false;
  }
}

function setCustomerGuidePreference(enabled) {
  customerGuideEnabled = Boolean(enabled);
  try {
    localStorage.setItem(CUSTOMER_GUIDE_KEY, customerGuideEnabled ? "on" : "off");
  } catch {
    // Local storage can be unavailable in hardened browser contexts.
  }
}

function toggleCustomerGuide() {
  setCustomerGuidePreference(!customerGuideEnabled);
  showToast(customerGuideEnabled ? "Kundenhilfe eingeblendet." : "Kundenhilfe ausgeblendet.");
  render();
}

function getCustomerGuide(view = currentView) {
  return CUSTOMER_GUIDE[view] || {
    title: "Bereich verstehen",
    intro: "Dieser Bereich unterstützt die strukturierte Umsetzung und Nachweisführung im SFM Compliance Workspace.",
    steps: [
      ["Überblick prüfen", "Zuerst die wichtigsten Kennzahlen, offenen Punkte und Statushinweise ansehen.", "dashboard"],
      ["Nachweise ergänzen", "Fehlende oder offene Dokumente im Bereich Dokumentation ergänzen.", "documents"],
      ["Aufgaben steuern", "Nächste Schritte mit Owner und Frist im Task Management nachhalten.", "tasks"]
    ]
  };
}

function normalizeCustomerGuideStep(view = currentView) {
  const guide = getCustomerGuide(view);
  const max = Math.max(0, guide.steps.length - 1);
  customerGuideStep = Math.max(0, Math.min(customerGuideStep, max));
}

function updateGuideToggleButton() {
  if (!guideToggleBtn) return;
  guideToggleBtn.classList.toggle("active", customerGuideEnabled);
  guideToggleBtn.setAttribute("aria-pressed", customerGuideEnabled ? "true" : "false");
  guideToggleBtn.querySelector("span:last-child").textContent = customerGuideEnabled ? t("button.helpOn") : t("button.help");
}

function renderCustomerGuidePanel(view = currentView) {
  if (!customerGuideEnabled) return "";
  const guide = getCustomerGuide(view);
  normalizeCustomerGuideStep(view);
  const step = guide.steps[customerGuideStep] || guide.steps[0];
  const progress = percentOf(customerGuideStep + 1, guide.steps.length);
  return `
    <section class="panel customer-guide-panel">
      <div class="customer-guide-main">
        <div>
          <span class="eyebrow">Kundenhilfe</span>
          <h3>${escapeHtml(guide.title)}</h3>
          <p>${escapeHtml(guide.intro)}</p>
        </div>
        <div class="customer-guide-progress">
          <strong>${customerGuideStep + 1}/${guide.steps.length}</strong>
          <span>Schritt</span>
          <div><i style="width:${progress}%"></i></div>
        </div>
      </div>
      <article class="customer-guide-step">
        <span>${escapeHtml(step[0])}</span>
        <strong>${escapeHtml(step[1])}</strong>
      </article>
      <div class="customer-guide-actions">
        <button class="quiet-button" type="button" data-guide-prev ${customerGuideStep === 0 ? "disabled" : ""}>Zurück</button>
        <button class="primary-button" type="button" data-guide-next>${customerGuideStep >= guide.steps.length - 1 ? "Neu starten" : "Nächster Schritt"}</button>
        ${step[2] && step[2] !== view ? `<button class="quiet-button" type="button" data-guide-jump="${escapeHtml(step[2])}">Bereich öffnen</button>` : ""}
        <button class="quiet-button" type="button" data-guide-close>Ausblenden</button>
      </div>
    </section>
  `;
}

function isDetailScrollView(view = currentView) {
  return view === "iso" || view === "nis2";
}

function rememberDetailScrollPosition() {
  if (!isDetailScrollView() || !appView) return;
  const listPanel = appView.querySelector(".detail-scroll-layout > .list-panel");
  if (!listPanel) return;
  detailScrollState[currentView].list = listPanel.scrollTop;
}

function restoreDetailScrollPosition() {
  if (!isDetailScrollView() || !appView) return;
  const listPanel = appView.querySelector(".detail-scroll-layout > .list-panel");
  if (!listPanel) return;
  listPanel.scrollTop = detailScrollState[currentView].list || 0;
  listPanel.addEventListener("scroll", () => {
    detailScrollState[currentView].list = listPanel.scrollTop;
  }, { passive: true });
}

function renderNav() {
  const badges = navBadges();
  const visible = visibleNavItems();
  const byId = new Map(visible.map((item) => [item[0], item]));
  mainNav.dataset.navMode = navigationAudience();
  mainNav.innerHTML = `
    ${renderNavigationModeCard()}
    ${navGroupsForAudience().map(([group, ids]) => {
    const groupItems = ids.map((id) => byId.get(id)).filter(Boolean);
    if (!groupItems.length) return "";
    const groupInfo = NAV_GROUP_INFO[group] || { label: group, hint: "" };
    const groupKey = NAV_GROUP_KEYS[group] || group;
    const groupLabel = t(`navGroup.${groupKey}.label`, groupInfo.label);
    const groupHint = t(`navGroup.${groupKey}.hint`, groupInfo.hint);
    return renderNavGroup(group, groupLabel, groupHint, groupItems, badges);
  }).join("")}
  `;
  mainNav.querySelectorAll("[data-view]").forEach((button) => {
    button.addEventListener("click", () => {
      sidebar?.classList.remove("mobile-nav-open");
      mobileNavToggle?.setAttribute("aria-expanded", "false");
      navigateToView(button.dataset.view);
    });
  });
}

function renderNavigationModeCard() {
  const customerMode = navigationAudience() === "customer";
  const title = customerMode ? "Kunden-Navigation" : "Berater-Navigation";
  const copy = customerMode
    ? "Nur die wichtigsten Schritte: Aufgaben, Nachweise und offene Punkte."
    : "Prüfung, Compliance, Register und weitere Werkzeuge sauber getrennt.";
  const badge = customerMode ? "Einfach" : "Vollzugriff";
  return `
    <div class="nav-mode-card ${customerMode ? "customer" : "consultant"}">
      <span>${escapeHtml(badge)}</span>
      <strong>${escapeHtml(title)}</strong>
      <small>${escapeHtml(copy)}</small>
    </div>
  `;
}

function renderNavGroup(group, groupLabel, groupHint, groupItems, badges) {
  const collapsed = navigationAudience() === "consultant" && group === "Weitere Werkzeuge";
  const activeInside = groupItems.some(([id]) => id === currentView);
  const buttons = groupItems.map(([id, label, icon]) => renderNavButton(id, label, icon, badges[id])).join("");
  const head = `
    <div class="nav-group-head">
      <span class="nav-group-label">${escapeHtml(groupLabel)}</span>
      ${groupHint ? `<small>${escapeHtml(groupHint)}</small>` : ""}
    </div>
  `;

  if (!collapsed) {
    return `
      <div class="nav-group">
        ${head}
        ${buttons}
      </div>
    `;
  }

  return `
    <details class="nav-group nav-disclosure" ${activeInside ? "open" : ""}>
      <summary>
        ${head}
        <span class="nav-disclosure-count">${groupItems.length}</span>
      </summary>
      <div class="nav-disclosure-body">
        ${buttons}
      </div>
    </details>
  `;
}

function navBadges() {
  const customerDocuments = Math.max(0, state.documents.length - SOURCE_FILES.length);
  const activeReviewStatuses = new Set(["vom_kunden_eingereicht", "in_beraterpruefung", "nacharbeit_noetig", "abgelehnt", "auditrelevant"]);
  const reviewOpen = reviewCenterItems().filter((item) => activeReviewStatuses.has(item.reviewStatus) || item.auditBlocker).length;
  const auditOpen = auditTraceabilityRows(state.documents.filter((document) => document.status !== "Quelle"))
    .filter((row) => ["Fehlt", "Review überfällig"].includes(row.status)).length;
  const activeIntegrations = state.integrations.filter((item) => item.status === "Aktiv").length;
  const production = buildProductionReadiness();
  const pendingInvitations = (productionAdminData.invitations || []).filter((item) => item.status === "pending").length;
  const projectPercent = projectPlanProgress().percent;
  const soa = soaMetrics();
  const openTasks = taskEngine.metrics(state.tasks).open;
  return {
    documents: navNumberBadge(customerDocuments, { min: 2, tone: "neutral", title: "Kundendokumente" }),
    review: navNumberBadge(reviewOpen, { min: 1, tone: "warning", title: "Offene Review-Punkte" }),
    audit: navNumberBadge(auditOpen, { min: 1, tone: "warning", title: "Offene Auditmatrix-Punkte" }),
    capa: navNumberBadge(capaRecords().filter((record) => normalizeReviewStatus(record.reviewStatus || record.status) !== "freigegeben").length, { min: 1, tone: "warning", title: "Offene Korrekturmaßnahmen" }),
    soa: soa.implemented ? navBadge(`${soa.implemented}/${ANNEX_CONTROLS.length}`, "progress", "Umgesetzte Annex-A-Controls") : null,
    guided: navNumberBadge(guidedCustomerTasks(dashboardStats()).length, { min: 1, tone: "attention", title: "Offene Kundenschritte" }),
    project: projectPercent ? navBadge(`${projectPercent}%`, "progress", "Projektfortschritt") : null,
    templates: null,
    assets: navNumberBadge(state.assets.length, { min: 3, tone: "neutral", title: "Erfasste Assets" }),
    risks: navNumberBadge(state.risks.length, { min: 3, tone: "neutral", title: "Erfasste Risiken" }),
    legal: navNumberBadge(state.legal.length, { min: 3, tone: "neutral", title: "Einträge im Rechtsregister" }),
    suppliers: navNumberBadge(state.suppliers.length, { min: 3, tone: "neutral", title: "Erfasste Lieferanten" }),
    policies: navNumberBadge(state.policies.length, { min: 3, tone: "neutral", title: "Policy-Einträge" }),
    incidents: navNumberBadge(state.incidents.length, { min: 3, tone: "neutral", title: "Erfasste Incidents" }),
    contracts: navNumberBadge(state.contracts.length, { min: 3, tone: "neutral", title: "Erfasste Verträge" }),
    integrations: activeIntegrations ? navBadge(`${activeIntegrations}/${INTEGRATION_CATALOG.length}`, "progress", "Aktive Integrationen") : null,
    team: pendingInvitations ? navNumberBadge(pendingInvitations, { min: 1, tone: "attention", title: "Offene Einladungen" }) : null,
	    account: backendSessionUser && !backendSessionUser.mfaEnabled
	      ? navBadge(backendSessionUser.mfaRequired ? "MFA!" : "MFA", "warning", backendSessionUser.mfaRequired ? "MFA ist für Änderungen erforderlich" : "MFA noch aktivieren")
	      : null,
	    production: production.done ? navBadge(`${production.done}/${PRODUCTION_CHECKS.length}`, "progress", "Produktivbetrieb-Checkliste") : null,
	    operations: Number(productionAdminData.operations?.summary?.active || 0)
	      ? navNumberBadge(productionAdminData.operations.summary.active, { min: 1, tone: "warning", title: "Aktive technische Betriebsalarme" })
	      : null,
	    jobs: Number(productionAdminData.jobs?.summary?.queued || 0) + Number(productionAdminData.jobs?.summary?.retry || 0) + Number(productionAdminData.jobs?.summary?.running || 0) + Number(productionAdminData.jobs?.summary?.failed || 0)
	      ? navNumberBadge(
	          Number(productionAdminData.jobs?.summary?.queued || 0) + Number(productionAdminData.jobs?.summary?.retry || 0) + Number(productionAdminData.jobs?.summary?.running || 0) + Number(productionAdminData.jobs?.summary?.failed || 0),
	          { min: 1, tone: "warning", title: "Offene oder fehlerhafte Hintergrundjobs" }
	        )
	      : null,
	    backup: Number(productionAdminData.security?.backupRecovery?.problemCount || 0)
	      ? navNumberBadge(productionAdminData.security.backupRecovery.problemCount, { min: 1, tone: "warning", title: "Backup-/Restore-Hinweise" })
	      : null,
	    lifecycle: Number(productionAdminData.lifecycle?.summary?.purgeEligible || 0)
	      ? navNumberBadge(productionAdminData.lifecycle.summary.purgeEligible, { min: 1, tone: "warning", title: "Mandanten mit abgelaufener Aufbewahrung" })
	      : null,
	    audittrail: navNumberBadge(auditTrailEvents().length, { min: 5, tone: "internal", title: "Lokale Änderungs- und Versionsereignisse" }),
	    quarantine: navNumberBadge(productionAdminData.quarantine?.files?.length || 0, { min: 1, tone: "warning", title: "Isolierte Uploads" }),
	    tasks: navNumberBadge(openTasks, { min: 1, tone: "attention", title: "Offene Aufgaben" }),
    iso: null,
    nis2: null,
	    dashboard: null,
	    executive: null,
	    notifications: navNumberBadge(notificationItems().filter((item) => !item.read).length, { min: 1, tone: "attention", title: "Ungelesene Benachrichtigungen" }),
	    consultant: navBadge("intern", "internal", "Nur Berater/Admin")
  };
}

function navBadge(label, tone = "", title = "") {
  return { label: String(label), tone, title };
}

function navNumberBadge(value, options = {}) {
  const number = Number(value) || 0;
  const minimum = options.min ?? 1;
  if (number < minimum) return null;
  const label = number > 99 ? "99+" : String(number);
  return navBadge(label, options.tone || "", options.title || "");
}

function renderNavButton(id, label, icon, badge) {
  const badgeHint = badge?.title ? ` · ${badge.title}: ${badge.label}` : "";
  const displayLabel = navLabel(id, label);
  const buttonTitle = `${displayLabel}${badgeHint}`;
  return `
    <button class="nav-button ${currentView === id ? "active" : ""} ${id === "consultant" && !canUseConsultantGenerator() ? "locked" : ""}" type="button" data-view="${id}" title="${escapeHtml(buttonTitle)}" aria-label="${escapeHtml(buttonTitle)}">
      <span class="nav-icon" aria-hidden="true">${icon}</span>
      <span class="nav-label">${escapeHtml(displayLabel)}</span>
      ${navCountBadge(id, badge)}
    </button>
  `;
}

function navCountBadge(id, badge) {
  if (!badge || badge.label === "" || badge.label === undefined || badge.label === null) return "";
  const tone = badge.tone ? ` ${escapeHtml(badge.tone)}` : "";
  const title = badge.title ? ` title="${escapeHtml(badge.title)}"` : "";
  return `<span class="nav-count${tone}"${title}>${escapeHtml(badge.label)}</span>`;
}

function renderComplianceCockpit(stats) {
  const data = complianceCockpitData(stats);
  return `
    <section class="panel compliance-cockpit">
      <div class="compliance-cockpit-head">
        <div>
          <span class="eyebrow">Zentrales Compliance-Dashboard</span>
          <h3>SFM Compliance Cockpit</h3>
          <p>Eine Startansicht für Geschäftsleitung, Kunde und Berater: Wo stehen wir, was blockiert, was wartet auf Prüfung?</p>
        </div>
        <div class="compliance-cockpit-gate ${escapeHtml(data.gateTone)}">
          <span>${escapeHtml(data.gateLabel)}</span>
          <strong>${escapeHtml(data.gateTitle)}</strong>
          <small>${escapeHtml(data.gateText)}</small>
        </div>
      </div>

      <div class="compliance-cockpit-grid">
        ${renderComplianceCockpitCard(data.cards[0], "hero")}
        ${data.cards.slice(1).map((card) => renderComplianceCockpitCard(card)).join("")}
      </div>

      <div class="compliance-cockpit-lower">
        <article class="compliance-cockpit-panel">
          <div class="compliance-panel-head">
            <strong>Offene Prioritäten</strong>
            <button class="quiet-button" type="button" data-jump="tasks">Aufgaben öffnen</button>
          </div>
          <div class="compliance-priority-list">
            ${data.priorities.length ? data.priorities.map(renderCompliancePriorityRow).join("") : `
              <div class="management-empty">Keine akuten Blocker erkannt. Regelmäßige Beraterprüfung weiterführen.</div>
            `}
          </div>
        </article>

        <article class="compliance-cockpit-panel">
          <div class="compliance-panel-head">
            <strong>Compliance-Spuren</strong>
            <button class="quiet-button" type="button" data-jump="project">Projektplan</button>
          </div>
          <div class="compliance-track-list">
            ${data.tracks.map((track) => `
              <button type="button" data-jump="${escapeHtml(track.view)}">
                ${renderIsoSnapshotBar(track.label, track.hint, track.percent, track.value)}
              </button>
            `).join("")}
          </div>
        </article>
      </div>
    </section>
  `;
}

function complianceCockpitData(stats = dashboardStats()) {
  const riskData = riskComplianceDashboardData(stats);
  const reviewItems = riskData.reviewItems;
	  const reviewMetrics = riskData.reviewMetrics;
	  const gate = riskData.gate;
	  const packageData = auditPackageReportData();
	  const packageApproved = Boolean(packageData.packageApproval);
	  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const soa = soaMetrics();
  const nisPlan = normalizeProjectPlan(state.projectPlan).filter((item) => item.stream === "NIS-2");
  const nisOpen = nisPlan.filter((item) => item.status !== "Erledigt").length;
  const supplierCritical = state.suppliers.filter((supplier) => ["Hoch", "Kritisch"].includes(supplier.criticality)).length;
  const supplierReviewOpen = state.suppliers.filter((supplier) => !["Freigegeben", "Geprüft", "Erledigt"].includes(supplier.review || supplier.status)).length;
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt");
  const rework = reviewMetrics.returns;
  const waitingReview = reviewMetrics.submitted + reviewMetrics.inReview;
  const policyPercent = percentOf(stats.policiesApproved, state.policies.length);
  const formalScore = riskData.formalScore;
	  const gateTone = packageApproved
	    ? "done"
	    : gate.blockers.length || rework || riskData.criticalRisks.length
	      ? "warning"
	      : "active";
	  const gateTitle = packageApproved
	    ? "Beraterfreigegeben"
	    : gate.consultantApproved
	      ? "Gate formal erfüllt"
	      : gate.blockers.length
	      ? `${gate.blockers.length} Audit-Blocker`
	      : waitingReview
	        ? "Wartet auf Prüfung"
	        : "Vorbereitet";
	  const gateText = packageApproved
	    ? "Auditpaket kann exportiert werden."
	    : gate.consultantApproved
	      ? "Formale Gate-Kriterien erfüllt, explizite Beraterfreigabe fehlt noch."
	      : "Vorbereitet, aber noch nicht durch Berater/Admin freigegeben.";

  const priorities = [
    ...riskData.blockerItems.map((item) => ({
      title: item.title,
      meta: item.meta || "Blocker prüfen",
      status: item.status || "Offen",
      view: item.view || "tasks",
      tone: item.status === "Blockiert" ? "warning" : ""
    })),
    ...riskData.highRisks.slice(0, 3).map((risk) => ({
      title: risk.riskId ? `${risk.riskId}: ${risk.scenario || risk.asset || "Risiko"}` : (risk.scenario || risk.asset || "Risiko prüfen"),
      meta: `Score ${riskScore(risk.likelihood, risk.impact) || "?"} · Owner: ${risk.owner || "offen"}`,
      status: risk.treatment ? "Behandlung prüfen" : "Maßnahme fehlt",
      view: "risks",
      tone: "warning"
    })),
    ...reviewItems
      .filter((item) => ["nacharbeit_noetig", "vom_kunden_eingereicht", "in_beraterpruefung"].includes(item.reviewStatus))
      .slice(0, 3)
      .map((item) => ({
        title: item.title,
        meta: item.reason || item.module || "Beraterprüfung",
        status: reviewStatusLabel(item.reviewStatus),
        view: canAccessView("review") ? "review" : "documents",
        tone: item.reviewStatus === "nacharbeit_noetig" ? "warning" : ""
      }))
  ].slice(0, 6);

  return {
    gateTone,
    gateLabel: riskData.trafficLight.level,
    gateTitle,
    gateText,
    priorities,
    tracks: [
      { label: "ISO 27001", hint: "Projektspur", percent: stats.isoPercent, value: stats.progress.byStream["ISO 27001"] || "0%", view: "iso" },
      { label: "NIS-2", hint: "Regulatorikspur", percent: stats.nisPercent, value: stats.progress.byStream["NIS-2"] || "0%", view: "nis2" },
      { label: "SoA", hint: "Controls vorbereitet", percent: percentOf(soa.implemented, soa.total), value: `${soa.implemented}/${soa.total || 0}`, view: "soa" },
      { label: "Policies", hint: "freigegeben", percent: policyPercent, value: `${stats.policiesApproved}/${state.policies.length || 0}`, view: "policies" },
      { label: "Nachweise", hint: "geprüft/in Prüfung", percent: percentOf(docMetrics.approved + docMetrics.inReview, docMetrics.working), value: `${docMetrics.approved + docMetrics.inReview}/${docMetrics.working || 0}`, view: "documents" },
      { label: "Beraterprüfung", hint: "freigegeben", percent: percentOf(reviewMetrics.approved, reviewItems.length), value: `${reviewMetrics.approved}/${reviewItems.length || 0}`, view: "review" }
    ],
    cards: [
      {
        title: "Gesamtstatus",
	        value: `${formalScore}%`,
	        subtitle: "formal vorbereitet",
	        text: riskData.trafficLight.title,
	        status: packageApproved ? "beraterfreigegeben" : "nicht automatisch auditbereit",
	        view: "review",
	        tone: gateTone
	      },
      {
        title: "ISO 27001",
        value: `${stats.isoPercent}%`,
        subtitle: `${soa.open} SoA offen`,
        text: "Projektspur, SoA, Policies und Nachweise getrennt steuerbar.",
        status: `${stats.progress.byStream["ISO 27001"] || "0%"} Projekt`,
        view: "iso",
        tone: stats.isoPercent >= 80 ? "done" : "active"
      },
      {
        title: "NIS-2",
        value: `${stats.nisPercent}%`,
        subtitle: `${nisOpen} Punkte offen`,
        text: "NIS-2 bleibt separat geführt, aber mit gemeinsamen Nachweisen verknüpfbar.",
        status: "Beraterbewertung nötig",
        view: "nis2",
        tone: nisOpen ? "active" : "done"
      },
      {
        title: "Top-Risiken",
        value: String(riskData.highRisks.length),
        subtitle: `${riskData.criticalRisks.length} kritisch`,
        text: "Höchste Risiken mit Behandlung, Restrisiko und Owner priorisieren.",
        status: riskData.highRisks.length ? "Handlungsbedarf" : "keine Top-Blocker",
        view: "risks",
        tone: riskData.highRisks.length ? "warning" : "done"
      },
      {
        title: "Nachweise",
        value: String(docMetrics.missing),
        subtitle: "Metadaten offen",
        text: `${docMetrics.inReview} Nachweis(e) warten auf Prüfung, ${docMetrics.approved} freigegeben.`,
        status: docMetrics.missing ? "Lücken offen" : "formal vollständig",
        view: "documents",
        tone: docMetrics.missing ? "warning" : docMetrics.inReview ? "active" : "done"
      },
      {
        title: "Lieferanten",
        value: String(supplierReviewOpen),
        subtitle: "Reviews offen",
        text: `${supplierCritical} kritische Lieferanten sind im Register markiert.`,
        status: supplierReviewOpen ? "Review planen" : "kein Review offen",
        view: "suppliers",
        tone: supplierReviewOpen ? "active" : "done"
      },
      {
        title: "Aufgaben",
        value: String(openTasks.length),
        subtitle: "offen",
        text: "Kundenaufgaben, Nacharbeit und Fristen zentral nachverfolgen.",
        status: openTasks.length ? "Heute prüfen" : "keine Aufgaben offen",
        view: "guided",
        tone: openTasks.length ? "active" : "done"
      }
    ]
  };
}

function renderComplianceCockpitCard(card, extraClass = "") {
  return `
    <button class="compliance-cockpit-card ${escapeHtml(card.tone || "")} ${escapeHtml(extraClass)}" type="button" data-jump="${escapeHtml(card.view || "dashboard")}">
      <span>${escapeHtml(card.title)}</span>
      <strong>${escapeHtml(card.value)}</strong>
      <small>${escapeHtml(card.subtitle)}</small>
      <p>${escapeHtml(card.text)}</p>
      ${statusTag(card.status)}
    </button>
  `;
}

function renderCompliancePriorityRow(item) {
  return `
    <button class="compliance-priority-row ${escapeHtml(item.tone || "")}" type="button" data-jump="${escapeHtml(item.view || "tasks")}">
      <div>
        <strong>${escapeHtml(item.title)}</strong>
        <span>${escapeHtml(item.meta || "Bitte prüfen")}</span>
      </div>
      ${statusTag(item.status || "Offen")}
    </button>
  `;
}

function renderDashboardSection(id, eyebrow, title, copy, content) {
  return `
    <section class="dashboard-section" id="${escapeHtml(id)}">
      <div class="dashboard-section-head">
        <div>
          <span class="eyebrow">${escapeHtml(eyebrow)}</span>
          <h3>${escapeHtml(title)}</h3>
          <p>${escapeHtml(copy)}</p>
        </div>
      </div>
      ${content}
    </section>
  `;
}

function renderDashboardSectionNav() {
  const items = [
    ["dashboard-overview", "Überblick"],
    ["dashboard-today", "Heute wichtig"],
    ["dashboard-start", "Projektstart"],
    ["dashboard-control", "Steuerung"],
    ["dashboard-evidence", "Nachweise"],
    ["dashboard-mapping", "ISO/NIS-2"]
  ];
  return `
    <nav class="dashboard-section-nav" aria-label="Dashboard-Bereiche">
      ${items.map(([id, label]) => `<button type="button" data-jump-section="dashboard:${escapeHtml(id)}">${escapeHtml(label)}</button>`).join("")}
    </nav>
  `;
}

function loadDashboardFocusMode() {
  try {
    const value = localStorage.getItem(DASHBOARD_FOCUS_KEY);
    return dashboardFocusModeIds().includes(value) ? value : "today";
  } catch {
    return "today";
  }
}

function dashboardFocusModeIds() {
  return ["today", "customer", "consultant", "management", "evidence", "mapping"];
}

function dashboardFocusOptions(stats = dashboardStats()) {
  const data = auditPackageReportData();
  const reviewMetrics = data.reviewMetrics || reviewCenterMetrics(data.reviewItems || []);
  const docMetrics = data.docMetrics || documentWorkflowMetrics(state.documents);
  const gate = data.gate || { blockers: [], consultantApproved: false };
  const todoCount = customerTodoItems(stats).length;
  const reworkCount = reviewMetrics.returns || 0;
  const evidenceMissing = docMetrics.missing || 0;
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt").length;
  const highRisks = state.risks.filter((risk) => !["Akzeptiert", "Erledigt", "Geschlossen"].includes(risk.status) && riskScore(risk.likelihood, risk.impact) >= 10).length;
  const nisOpen = normalizeProjectPlan(state.projectPlan).filter((item) => item.stream === "NIS-2" && item.status !== "Erledigt").length;

  return [
    {
      id: "today",
      label: "Heute",
      title: "Was muss jetzt als Nächstes passieren?",
      text: "Zeigt die nächsten Aufgaben, Rückgaben und Blocker in einfacher Reihenfolge.",
      value: todoCount || openTasks,
      metric: todoCount ? "Kundenaufgaben" : "offene Aufgaben",
      section: "dashboard-today",
      view: "guided",
      action: "Jetzt weitermachen",
      tone: todoCount || openTasks ? "active" : "done"
    },
    {
      id: "customer",
      label: "Kunde",
      title: "Kundenmodus und Projektstart führen",
      text: "Startprofil, Grundprojekt, Nachweise und nächste Eingaben ohne Fachsprache steuern.",
      value: stats.progress?.percent ?? 0,
      metric: "% Projekt",
      section: "dashboard-start",
      view: "guided",
      action: "Kundenmodus öffnen",
      tone: "active"
    },
    {
      id: "consultant",
      label: "Berater",
      title: "Einreichungen, Nacharbeit und Freigaben prüfen",
      text: "Zentral sehen, was wartet, was zurückgegeben werden muss und was Audit-Blocker ist.",
      value: reviewMetrics.submitted + reviewMetrics.inReview + reworkCount,
      metric: "Review-Punkte",
      section: "dashboard-control",
      view: canAccessView("review") ? "review" : "guided",
      action: canAccessView("review") ? "Review Center öffnen" : "Status ansehen",
      tone: reworkCount || gate.blockers.length ? "warning" : reviewMetrics.submitted + reviewMetrics.inReview ? "active" : "done"
    },
    {
      id: "management",
      label: "Management",
      title: "Risiken, Blocker und Entscheidungen verdichten",
      text: "Für Geschäftsleitung und ISB: Top-Risiken, Audit-Blocker und Entscheidungsbedarf.",
      value: highRisks + gate.blockers.length,
      metric: "kritische Punkte",
      section: "dashboard-control",
      view: "auditpackage",
      action: "Auditpaket prüfen",
      tone: highRisks || gate.blockers.length ? "warning" : "done"
    },
    {
      id: "evidence",
      label: "Nachweise",
      title: "Nachweise sammeln und formal prüfen",
      text: "Fehlende, eingereichte und freigegebene Nachweise direkt öffnen.",
      value: evidenceMissing,
      metric: "formal offen",
      section: "dashboard-evidence",
      view: "documents",
      action: "Nachweise öffnen",
      tone: evidenceMissing ? "warning" : docMetrics.inReview ? "active" : "done"
    },
    {
      id: "mapping",
      label: "ISO/NIS-2",
      title: "ISO 27001 und NIS-2 getrennt steuern",
      text: "Gemeinsame Nachweise nutzen, fachliche Bewertung aber sauber getrennt halten.",
      value: nisOpen,
      metric: "NIS-2 offen",
      section: "dashboard-mapping",
      view: "nis2",
      action: "NIS-2 Navigator",
      tone: nisOpen ? "active" : "done"
    }
  ];
}

function currentDashboardFocus(stats = dashboardStats()) {
  const options = dashboardFocusOptions(stats);
  return options.find((option) => option.id === dashboardFocusMode) || options[0];
}

function renderDashboardInteractiveHub(stats = dashboardStats()) {
  const options = dashboardFocusOptions(stats);
  const active = currentDashboardFocus(stats);
  const actions = dashboardFocusActions(active.id, stats);
  return `
    <section class="panel dashboard-interactive-hub" id="dashboard-interactive-hub" aria-label="Interaktive Dashboard-Steuerung">
      <div class="dashboard-interactive-head">
        <div>
          <span class="eyebrow">Interaktives Dashboard</span>
          <h3>Wähle den Arbeitsfokus.</h3>
          <p>Das Dashboard reagiert auf den gewählten Fokus und führt direkt zu den passenden Arbeitsbereichen. Es zeigt formale Vorbereitung, keine automatische Auditfreigabe.</p>
        </div>
        <div class="dashboard-interactive-actions">
          <button class="quiet-button" type="button" data-dashboard-detail-mode="open">Details aufklappen</button>
          <button class="quiet-button" type="button" data-dashboard-detail-mode="close">Details einklappen</button>
        </div>
      </div>

      <div class="dashboard-focus-switcher" role="tablist" aria-label="Dashboard-Fokus">
        ${options.map((option) => `
          <button class="${option.id === active.id ? "active" : ""} ${escapeHtml(option.tone || "")}" type="button" role="tab" aria-selected="${option.id === active.id ? "true" : "false"}" data-dashboard-focus="${escapeHtml(option.id)}">
            <span>${escapeHtml(option.label)}</span>
            <strong>${escapeHtml(String(option.value))}</strong>
            <small>${escapeHtml(option.metric)}</small>
          </button>
        `).join("")}
      </div>

      <article class="dashboard-active-focus ${escapeHtml(active.tone || "")}">
        <div>
          <span>${escapeHtml(active.label)}</span>
          <h4>${escapeHtml(active.title)}</h4>
          <p>${escapeHtml(active.text)}</p>
        </div>
        <div class="dashboard-active-focus-actions">
          ${statusTag(active.metric)}
          <button class="primary-button" type="button" data-jump="${escapeHtml(active.view)}">${escapeHtml(active.action)}</button>
          <button class="quiet-button" type="button" data-jump-section="dashboard:${escapeHtml(active.section)}">Auf Dashboard zeigen</button>
        </div>
      </article>

      <div class="dashboard-search-panel">
        <label>
          <span>Schnellsuche</span>
          <input type="search" data-dashboard-search value="${escapeHtml(dashboardSearchTerm)}" placeholder="Nach Modul, Policy, Nachweis, Risiko, Lieferant oder Aufgabe suchen" autocomplete="off" />
        </label>
        <div class="dashboard-search-results" data-dashboard-search-results aria-live="polite">
          ${renderDashboardSearchResults(dashboardSearchTerm, stats)}
        </div>
      </div>

      <div class="dashboard-action-board" aria-label="Passende nächste Aktionen">
        ${actions.map((action, index) => renderDashboardActionCard(action, index)).join("")}
      </div>

      ${renderDashboardFocusPreview(active.id, stats)}
    </section>
  `;
}

function dashboardSearchResults(term = "", stats = dashboardStats()) {
  const query = normalizeImportKey(term);
  if (!query) return dashboardDefaultSearchResults(stats);
  const tokens = query.split(" ").filter(Boolean);
  const results = [];
  const push = (item) => {
    const haystack = normalizeImportKey([item.type, item.title, item.text, item.status, item.keywords].filter(Boolean).join(" "));
    const exact = haystack.includes(query);
    const tokenHits = tokens.filter((token) => haystack.includes(token)).length;
    if (!exact && tokenHits === 0) return;
    results.push({ ...item, score: (exact ? 100 : 0) + tokenHits * 18 + (item.priority || 0) });
  };

  visibleNavItems().forEach(([id, label]) => {
    push({
      type: "Bereich",
      title: navLabel(id, label),
      text: viewSubtitleText(id),
      status: "Modul öffnen",
      action: { view: id },
      priority: id === currentView ? 4 : 0
    });
  });

  state.documents
    .filter((document) => document.status !== "Quelle")
    .slice(0, 80)
    .forEach((document) => push({
      type: "Nachweis",
      title: document.name || "Dokument",
      text: `${document.area || "Dokumentation"} · ${document.linkedTo || document.evidenceFor || "ohne Zuordnung"}`,
      status: document.approval || document.status || "Öffnen",
      action: { documentId: document.id },
      keywords: `${document.owner || ""} ${document.note || ""}`,
      priority: 10
    }));

  state.policies.slice(0, 80).forEach((policy) => push({
    type: "Policy",
    title: policy.title || "Policy",
    text: `${policy.owner || "Owner offen"} · ${policy.linkedTo || "ohne Zuordnung"}`,
    status: policy.status || "Entwurf",
    action: { policyRef: policyDetailRefForPolicy(policy) },
    keywords: `${policy.note || ""} ${policy.group || ""}`,
    priority: 8
  }));

  state.risks.slice(0, 80).forEach((risk) => push({
    type: "Risiko",
    title: risk.riskId ? `${risk.riskId}: ${risk.scenario || risk.asset || "Risiko"}` : (risk.scenario || risk.asset || "Risiko"),
    text: `${risk.owner || "Owner offen"} · ${risk.treatment || "Behandlung offen"}`,
    status: risk.status || riskLevel(riskScore(risk.likelihood, risk.impact)),
    action: { view: "risks" },
    keywords: `${risk.asset || ""} ${risk.note || ""}`,
    priority: riskScore(risk.likelihood, risk.impact) >= 10 ? 12 : 4
  }));

  state.suppliers.slice(0, 60).forEach((supplier) => push({
    type: "Lieferant",
    title: supplier.name || supplier.vendor || "Lieferant",
    text: `${supplier.service || "Leistung offen"} · ${supplier.owner || "Owner offen"}`,
    status: supplier.review || supplier.status || "Review offen",
    action: { view: "suppliers" },
    keywords: `${supplier.criticality || ""} ${supplier.evidence || ""}`,
    priority: String(supplier.criticality || "").includes("Hoch") ? 10 : 3
  }));

  state.tasks
    .filter((task) => task.status !== "Erledigt")
    .slice(0, 100)
    .forEach((task) => push({
      type: "Aufgabe",
      title: task.title || "Aufgabe",
      text: `${task.module || "Task Management"} · ${task.owner || "Owner offen"}`,
      status: task.status || "Offen",
      action: { view: moduleToView(task.module || "tasks") },
      keywords: `${task.note || ""} ${task.due || ""}`,
      priority: task.due && task.due < today() ? 14 : 5
    }));

  return results
    .sort((left, right) => right.score - left.score || String(left.title).localeCompare(String(right.title), "de"))
    .slice(0, 8);
}

function dashboardDefaultSearchResults(stats = dashboardStats()) {
  const data = auditPackageReportData();
  const docMetrics = data.docMetrics || documentWorkflowMetrics(state.documents);
  const reviewMetrics = data.reviewMetrics || reviewCenterMetrics(data.reviewItems || []);
  return [
    { type: "Schnellziel", title: "Kundenmodus", text: "Geführte Strecke für Kundeneingaben öffnen.", status: `${customerTodoItems(stats).length} Aufgabe(n)`, action: { view: "guided" } },
    { type: "Schnellziel", title: "Geschäftsführung", text: "Management Cockpit für NHD / Daume Gruppe öffnen.", status: "Lagebild", action: { view: "executive" } },
    { type: "Schnellziel", title: "Nachweise", text: "Nachweise hochladen, zuordnen und einreichen.", status: `${docMetrics.missing || 0} formal offen`, action: { view: "documents" } },
    { type: "Schnellziel", title: "Risiko Management", text: "Risiken erfassen und Behandlung dokumentieren.", status: `${state.risks.length} Risiken`, action: { view: "risks" } },
    { type: "Schnellziel", title: "Policy Management", text: "Policies öffnen, bearbeiten und zur Prüfung bringen.", status: `${state.policies.length} Policies`, action: { view: "policies" } },
    { type: "Schnellziel", title: "Beraterprüfung", text: "Einreichungen, Rückgaben und Freigaben prüfen.", status: `${reviewMetrics.submitted + reviewMetrics.inReview} wartet`, action: { view: canAccessView("review") ? "review" : "guided" } },
    { type: "Schnellziel", title: "Auditpaket", text: "Formales Paket prüfen, Beraterfreigabe bleibt separat.", status: data.packageApproval ? "freigegeben" : "nicht final", action: { view: "auditpackage" } }
  ];
}

function renderDashboardSearchResults(term = "", stats = dashboardStats()) {
  const results = dashboardSearchResults(term, stats);
  if (!results.length) {
    return `
      <div class="dashboard-search-empty">
        <strong>Nichts gefunden</strong>
        <span>Versuche Begriffe wie Risiko, Policy, Nachweis, NIS-2, Lieferant oder Aufgabe.</span>
      </div>
    `;
  }
  return results.map((result) => renderDashboardSearchResult(result)).join("");
}

function renderDashboardSearchResult(result) {
  const action = result.action || {};
  return `
    <button class="dashboard-search-result" type="button"
      data-dashboard-search-action
      data-dashboard-search-view="${escapeHtml(action.view || "")}"
      data-dashboard-search-section="${escapeHtml(action.section || "")}"
      data-dashboard-search-document="${escapeHtml(action.documentId || "")}"
      data-dashboard-search-policy="${escapeHtml(action.policyRef || "")}"
      data-dashboard-search-guided="${escapeHtml(action.guidedStep || "")}">
      <span>${escapeHtml(result.type || "Treffer")}</span>
      <strong>${escapeHtml(result.title || "Öffnen")}</strong>
      <small>${escapeHtml(result.text || "")}</small>
      ${statusTag(result.status || "Öffnen")}
    </button>
  `;
}

function updateDashboardSearchResults(input) {
  dashboardSearchTerm = String(input?.value || "");
  const container = appView.querySelector("[data-dashboard-search-results]");
  if (container) container.innerHTML = renderDashboardSearchResults(dashboardSearchTerm);
}

function openDashboardSearchResult(button) {
  const documentId = button.dataset.dashboardSearchDocument;
  const policyRef = button.dataset.dashboardSearchPolicy;
  const guidedStep = button.dataset.dashboardSearchGuided;
  const view = button.dataset.dashboardSearchView;
  const section = button.dataset.dashboardSearchSection;
  if (documentId) {
    openDocumentFromAnywhere(documentId);
    return;
  }
  if (policyRef) {
    selectPolicyDetail(policyRef);
    return;
  }
  if (guidedStep) {
    selectedGuidedStepId = guidedStep;
    navigateToView("guided");
    return;
  }
  navigateToView(view || "dashboard");
  if (section) {
    window.requestAnimationFrame(() => {
      document.getElementById(section)?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }
}

