function dashboardFocusPreviewData(focusId, stats = dashboardStats()) {
  const data = auditPackageReportData();
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const reviewItems = reviewCenterItems();
  const docMetrics = data.docMetrics || documentWorkflowMetrics(state.documents);
  const reviewMetrics = data.reviewMetrics || reviewCenterMetrics(reviewItems);
  const gate = data.gate || auditPackageGate(reviewItems);
  const rowsByFocus = {
    today: customerTodoItems(stats).slice(0, 5).map((item) => ({
      type: item.category || "Heute",
      title: item.title,
      text: item.meta || "Bitte prüfen.",
      status: item.status || "Offen",
      attrs: item.scrollTarget ? dashboardStartJumpAttrs(item.view || "guided", item.scrollTarget) : dashboardStartJumpAttrs(item.view || "guided"),
      tone: item.status === "Blockiert" || item.status === "Nacharbeit nötig" ? "warning" : ""
    })),
    customer: customerGuidanceLanes(stats).map((lane) => ({
      type: lane.step,
      title: lane.title,
      text: lane.text,
      status: `${lane.percent}%`,
      attrs: dashboardStartJumpAttrs(lane.primaryView || "guided"),
      tone: lane.percent >= 80 ? "done" : lane.percent > 0 ? "active" : ""
    })),
    consultant: reviewItems
      .filter((item) => item.reviewStatus !== "freigegeben" || item.auditBlocker)
      .slice(0, 5)
      .map((item) => ({
        type: item.type || "Review",
        title: item.title,
        text: item.reason || item.module || "Fachlich prüfen.",
        status: reviewStatusLabel(item.reviewStatus || "offen"),
        attrs: dashboardStartJumpAttrs(canAccessView("review") ? "review" : "guided"),
        tone: item.auditBlocker || ["nacharbeit_noetig", "abgelehnt"].includes(item.reviewStatus) ? "warning" : ""
      })),
    management: complianceCockpitData(stats).priorities.slice(0, 5).map((item) => ({
      type: "Management",
      title: item.title,
      text: item.meta || "Entscheidung oder Blocker prüfen.",
      status: item.status || "Offen",
      attrs: dashboardStartJumpAttrs(item.view || "tasks"),
      tone: item.tone || ""
    })),
    evidence: [
      ...documentEvidenceGaps(documents).slice(0, 4).map((gap) => ({
        type: "Nachweis fehlt",
        title: gap.title,
        text: gap.meta,
        status: "Upload vorbereiten",
        attrs: `data-document-upload-ref="${escapeHtml(gap.ref || gap.title)}" data-document-upload-area="${escapeHtml(gap.area || "Dokumentation")}"`,
        tone: "warning"
      })),
      ...documents
        .filter((document) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(document.reviewStatus) || document.status === "In Prüfung")
        .slice(0, 3)
        .map((document) => ({
          type: "In Prüfung",
          title: document.name || "Nachweis",
          text: document.linkedTo || document.evidenceFor || document.area || "Nachweis prüfen.",
          status: document.approval || document.status || "In Prüfung",
          attrs: `data-open-document="${escapeHtml(document.id)}"`,
          tone: "active"
        }))
    ].slice(0, 5),
    mapping: dashboardMappingPreviewRows(stats)
  };

  const labels = {
    today: {
      title: "Was jetzt zuerst erledigt werden sollte",
      text: "Die wichtigsten Kundenschritte, Rückgaben und Fristen in einer kurzen Arbeitsliste.",
      status: `${customerTodoItems(stats).length} offen`,
      tone: customerTodoItems(stats).length ? "active" : "done"
    },
    customer: {
      title: "Kundenstrecke in Phasen",
      text: "Vom Startprofil bis zum Auditpaket, ohne Fachsprache zu überladen.",
      status: `${stats.progress.percent}% Projekt`,
      tone: stats.progress.percent >= 80 ? "done" : "active"
    },
    consultant: {
      title: "Was fachlich geprüft werden muss",
      text: "Neue Einreichungen, Nacharbeit und Audit-Blocker bleiben beim Berater/Admin.",
      status: `${reviewMetrics.submitted + reviewMetrics.inReview} wartet`,
      tone: reviewMetrics.returns || gate.blockers.length ? "warning" : "active"
    },
    management: {
      title: "Entscheidungen und Blocker",
      text: "Top-Risiken, Management-Entscheidungen und Audit-Blocker auf einen Blick.",
      status: `${gate.blockers.length} Blocker`,
      tone: gate.blockers.length ? "warning" : "active"
    },
    evidence: {
      title: "Nachweise und formale Lücken",
      text: "Zeigt fehlende oder eingereichte Nachweise. Keine automatische Erfüllungsbehauptung.",
      status: `${docMetrics.missing || 0} offen`,
      tone: docMetrics.missing ? "warning" : "done"
    },
    mapping: {
      title: "ISO 27001 und NIS-2 getrennt führen",
      text: "Gemeinsame Nachweise sind möglich, die fachliche Bewertung bleibt je Regelwerk getrennt.",
      status: "Getrennte Sicht",
      tone: "active"
    }
  };

  return {
    ...(labels[focusId] || labels.today),
    rows: rowsByFocus[focusId] || rowsByFocus.today
  };
}

function dashboardMappingPreviewRows(stats = dashboardStats()) {
  const plan = normalizeProjectPlan(state.projectPlan);
  const streams = [
    { id: "ISO 27001", label: "ISO 27001", view: "iso", percent: stats.isoPercent },
    { id: "NIS-2", label: "NIS-2", view: "nis2", percent: stats.nisPercent },
    { id: "Gemeinsam", label: "Gemeinsame Pakete", view: "project", percent: stats.progress.percent }
  ];
  return streams.map((stream) => {
    const items = plan.filter((item) => item.stream === stream.id || (stream.id === "Gemeinsam" && item.stream === "Gemeinsam"));
    const open = items.filter((item) => item.status !== "Erledigt").length;
    return {
      type: stream.label,
      title: open ? `${open} Arbeitspaket(e) offen` : "Keine offenen Arbeitspakete",
      text: stream.id === "Gemeinsam"
        ? "Einmal erfassen, aber ISO- und NIS-2-Bewertung getrennt halten."
        : `${stream.label}-Arbeitsstand und Nachweise separat prüfen.`,
      status: `${stream.percent || 0}% formal`,
      attrs: dashboardStartJumpAttrs(stream.view),
      tone: open ? "active" : "done"
    };
  });
}

