function createManagementDecisionTasks() {
  if (!canEditWorkspace()) {
    showPermissionToast("Management-Beschlüsse anlegen", "Bearbeitungsrechten");
    return;
  }
  const data = riskComplianceDashboardData();
  const sourceItems = data.decisionItems.length
    ? data.decisionItems
    : data.actionPlanRows.slice(0, 5).map((row) => ({
      type: row.type,
      title: row.title,
      meta: row.nextStep,
      view: row.view || "tasks"
    }));

  let created = 0;
  sourceItems.slice(0, 8).forEach((item) => {
    const added = addTaskIfMissing({
      title: `Management-Beschluss klären: ${item.title}`,
      module: "Management Review",
      owner: "Geschäftsleitung / ISB",
      due: futureDate(14),
      status: "Offen",
      source: "Management-Beschluss",
      workflowType: "management-decision",
      linkedTo: item.title,
      note: `${item.type || "Entscheidung"} aus dem Management Cockpit. Hinweis: ${item.meta || "Entscheidung, Begründung und Verantwortlichkeit dokumentieren."} Bereich: ${viewToTaskModule(item.view || "tasks")}.`
    });
    if (added) created += 1;
  });

  saveState();
  showToast(created ? `${created} Beschlussaufgabe(n) angelegt.` : "Beschlussaufgaben waren bereits vorhanden.");
  render();
}

function createManagementDashboardTasks() {
  if (!canEditWorkspace()) {
    showPermissionToast("Management-Blocker-Aufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const data = riskComplianceDashboardData();
  const candidates = [];

  data.highRisks.slice(0, 5).forEach((risk) => {
    const score = riskScore(risk.likelihood, risk.impact);
    candidates.push({
      title: `Top-Risiko klären: ${risk.riskId || risk.scenario || risk.asset || "Risiko"}`,
      module: "Risiko Management",
      owner: risk.owner || "ISB / Risk Owner",
      dueDays: score >= 16 ? 7 : 14,
      linkedTo: risk.riskId || risk.scenario || "Management Cockpit",
      note: `Aus dem Management Cockpit erzeugt. Score: ${score || "offen"} (${riskLevel(score)}). Behandlung: ${risk.treatment || "offen"}.`
    });
  });

  data.blockerItems.slice(0, 6).forEach((item) => {
    candidates.push({
      title: `Management-Blocker schließen: ${item.title}`,
      module: viewToTaskModule(item.view || "tasks"),
      owner: "ISB / Verantwortliche Rolle",
      dueDays: item.status === "Blockiert" ? 7 : 14,
      linkedTo: item.title,
      note: `Aus dem Management Cockpit erzeugt. Status: ${item.status || "Offen"}. Hinweis: ${item.meta || "-"}`
    });
  });

  data.decisionItems.slice(0, 4).forEach((item) => {
    candidates.push({
      title: `Management-Entscheidung dokumentieren: ${item.title}`,
      module: viewToTaskModule(item.view || "tasks"),
      owner: "Geschäftsleitung / ISB",
      dueDays: 14,
      linkedTo: item.title,
      note: `Aus dem Management Cockpit erzeugt. Typ: ${item.type}. Hinweis: ${item.meta || "-"}`
    });
  });

  if (!candidates.length) {
    showToast("Keine Management-Blocker oder Entscheidungspunkte gefunden.");
    return;
  }

  let created = 0;
  candidates.forEach((task) => {
    if (addTaskIfMissing({
      title: task.title,
      module: task.module,
      owner: task.owner,
      due: futureDate(task.dueDays),
      status: "Offen",
      linkedTo: task.linkedTo,
      workflowType: "management-cockpit",
      source: "Risk-/Compliance-Dashboard",
      note: task.note
    })) {
      created += 1;
    }
  });
  saveState();
  showToast(created ? `${created} Management-Aufgabe(n) angelegt.` : "Management-Aufgaben waren bereits vorhanden.");
  render();
}

function managementDashboardNextSteps(data) {
  const steps = [];
  if (data.criticalRisks.length) steps.push("Kritische Top-Risiken mit Owner, Behandlung und Akzeptanzentscheidung klären.");
  if (data.gate.blockers.length) steps.push("Audit-Blocker im Review Center oder in der Auditmatrix fachlich prüfen.");
  if (data.reviewMetrics.returns) steps.push("Rückgaben aus der Beraterprüfung klären: Nacharbeit prüfen, Ablehnungen begründen oder erneut einreichen lassen.");
  if (data.overdueTasks.length) steps.push("Überfällige Aufgaben terminieren, abschließen oder bewusst neu priorisieren.");
  if (data.docMetrics.missing) steps.push("Nachweis-Metadaten ergänzen: Owner, Zuordnung, Version und Review-Datum.");
  if (!steps.length) steps.push("Regelmäßige Beraterprüfung durchführen und Management-Report als Arbeitsunterlage exportieren.");
  return steps.slice(0, 6);
}

function renderPageActionStrip(viewId) {
  const data = pageActionStripData(viewId);
  if (!data) return "";
  return `
    <section class="panel page-action-strip ${escapeHtml(viewId)}">
      <div class="page-action-head">
        <div>
          <span class="eyebrow">${escapeHtml(data.eyebrow || "Einfacher Arbeitsmodus")}</span>
          <h3>${escapeHtml(data.title)}</h3>
          <p>${escapeHtml(data.copy)}</p>
        </div>
        ${data.primaryAction ? renderPageActionButton(data.primaryAction, true) : ""}
      </div>
      <div class="page-action-grid">
        ${data.cards.map(renderPageActionCard).join("")}
      </div>
    </section>
  `;
}

function renderPageActionCard(card) {
  return `
    <article class="page-action-card ${escapeHtml(card.tone || "")}">
      <div class="page-action-card-top">
        <span>${escapeHtml(card.label)}</span>
        ${statusTag(card.status || "Offen")}
      </div>
      <strong>${escapeHtml(card.title)}</strong>
      <p>${escapeHtml(card.text)}</p>
      ${card.action ? renderPageActionButton(card.action, Boolean(card.action.primary)) : ""}
    </article>
  `;
}

function renderPageActionButton(action, primary = false) {
  const attrs = pageActionAttributes(action);
  if (!attrs) return "";
  return `<button class="${primary ? "primary-button" : "quiet-button"}" type="button" ${attrs}>${escapeHtml(action.label || "Öffnen")}</button>`;
}

function pageActionAttributes(action = {}) {
  if (action.type === "project") return `data-project-scroll="${escapeHtml(action.target || "")}"`;
  if (action.type === "projectUpload") return `data-project-document-upload="${escapeHtml(action.target || "")}"`;
  if (action.type === "soaEvidence") return `data-soa-evidence="${escapeHtml(action.target || "")}"`;
  if (action.type === "section") return `data-jump-section="${escapeHtml(action.target || "")}"`;
  if (action.type === "upload") return `data-document-upload-ref="${escapeHtml(action.ref || "")}" data-document-upload-area="${escapeHtml(action.area || "Dokumentation")}"`;
  if (action.type === "registerSubmit") return `data-register-submit="${escapeHtml(action.target || "")}"`;
  if (action.type === "documentSubmit") return `data-document-submit="${escapeHtml(action.target || "")}"`;
  if (action.type === "scroll") return `data-scroll-target="${escapeHtml(action.target || "")}"`;
  if (action.type === "jump") return `data-jump="${escapeHtml(action.target || "dashboard")}"`;
  if (action.type === "document") return `data-open-document="${escapeHtml(action.target || "")}"`;
  return "";
}

function pageActionStripData(viewId) {
  if (viewId === "iso") return pageActionProjectStreamData("ISO 27001");
  if (viewId === "nis2") return pageActionProjectStreamData("NIS-2");
  if (viewId === "documents") return pageActionDocumentsData();
  if (["assets", "risks", "legal", "suppliers", "policies", "incidents", "contracts"].includes(viewId)) return pageActionRegisterData(viewId);
  if (viewId === "review") return pageActionReviewData();
  if (viewId === "soa") return pageActionSoaData();
  if (viewId === "audit") return pageActionAuditData();
  if (viewId === "tasks") return pageActionTasksData();
  return null;
}

function pageActionFromRegisterAction(action = {}, fallbackView = "dashboard") {
  if (!action) return { type: "jump", target: fallbackView, label: "Bereich öffnen" };
  if (action.kind === "upload") {
    return {
      type: "upload",
      ref: action.ref || "",
      area: action.area || registerFullModuleLabel(fallbackView),
      label: action.label || "Nachweis anlegen"
    };
  }
  if (action.kind === "section") return { type: "section", target: action.target || `${fallbackView}:`, label: action.label || "Öffnen" };
  if (action.kind === "registerSubmit") return { type: "registerSubmit", target: action.target || "", label: action.label || "Zur Prüfung" };
  return { type: "jump", target: action.target || fallbackView, label: action.label || "Öffnen" };
}

function pageActionFromDocumentAction(action = {}) {
  if (!action) return { type: "jump", target: "documents", label: "Nachweise öffnen" };
  if (action.kind === "document") return { type: "document", target: action.target || "", label: action.label || "Nachweis öffnen" };
  if (action.kind === "documentSubmit") return { type: "documentSubmit", target: action.target || "", label: action.label || "Einreichen" };
  if (action.kind === "upload") {
    return {
      type: "upload",
      ref: action.ref || "",
      area: action.area || "Dokumentation",
      label: action.label || "Upload vorbereiten"
    };
  }
  return { type: "jump", target: action.target || "documents", label: action.label || "Öffnen" };
}

function pageActionDocumentsData() {
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const metrics = documentWorkflowMetrics(state.documents);
  const groups = documentCustomerHubGroups(documents);
  const firstAction = [...groups.rework, ...groups.missing, ...groups.waiting][0] || null;
  const missingTotal = groups.rework.length + groups.missing.length;
  const nextTitle = firstAction
    ? firstAction.title
    : documents.length
      ? "Nachweise beobachten"
      : "Ersten Nachweis hochladen";
  const nextText = firstAction
    ? firstAction.text
    : documents.length
      ? "Aktuell wirkt kein Nachweis akut zurückgegeben. Prüfe Owner, Review und Zuordnung regelmäßig."
      : "Starte mit dem wichtigsten Nachweis, einer Policy, einem Registerexport oder einem Ablage-Link.";
  return {
    eyebrow: "Nachweise einfach steuern",
    title: "Was fehlt, was wartet, was ist freigegeben?",
    copy: "Kunden sollen hier nur hochladen, fehlende Angaben ergänzen oder auf Beraterprüfung warten. Die Plattform bewertet Nachweise nicht automatisch fachlich.",
    primaryAction: firstAction ? pageActionFromDocumentAction(firstAction.action) : { type: "jump", target: "documents", label: documents.length ? "Nachweise öffnen" : "Nachweis anlegen" },
    cards: [
      {
        label: "Nächster Schritt",
        title: nextTitle,
        text: nextText,
        status: firstAction?.status || (documents.length ? "Beobachten" : "Starten"),
        tone: firstAction ? "warning" : "active",
        action: firstAction ? pageActionFromDocumentAction(firstAction.action) : { type: "jump", target: "documents", label: "Öffnen", primary: true }
      },
      {
        label: "Formaler Stand",
        title: `${metrics.working} Kundendokument(e)`,
        text: `${metrics.approved} freigegeben · ${metrics.inReview} in Prüfung · ${metrics.overdue} Review überfällig.`,
        status: metrics.missing || metrics.overdue ? "Prüfen" : "OK",
        tone: metrics.missing || metrics.overdue ? "warning" : "done"
      },
      {
        label: "Nacharbeit",
        title: `${missingTotal} Punkt(e)`,
        text: groups.rework.length ? "Zurückgegebene Nachweise zuerst nacharbeiten." : "Fehlende Nachweise oder Metadaten ergänzen.",
        status: missingTotal ? "Offen" : "Bereit",
        tone: missingTotal ? "warning" : "done"
      },
      {
        label: "Beraterprüfung",
        title: `${groups.waiting.length} wartet`,
        text: "Freigabe, Ablehnung und Audit-Relevanz bleiben beim Berater/Admin.",
        status: groups.waiting.length ? "In Prüfung" : "Kein Stau",
        tone: groups.waiting.length ? "active" : "done",
        action: { type: "jump", target: canAccessView("review") ? "review" : "documents", label: canAccessView("review") ? "Review Center" : "Status ansehen" }
      }
    ]
  };
}

function pageActionRegisterData(collection) {
  const rows = registerRows(collection);
  const groups = registerCustomerHubGroups(collection, rows);
  const next = registerCustomerNextAction(collection, groups);
  const complete = rows.filter((row) => !registerCustomerNeedsAction(collection, row)).length;
  const missingEvidence = rows.filter((row) => !registerRowLinked(collection, row)).length;
  const rework = rows.filter((row) => ["nacharbeit_noetig", "abgelehnt"].includes(canonicalReviewStatus(row, registerReviewType(collection)))).length;
  const waiting = groups.waiting.length;
  const labels = {
    assets: ["Assets einfach vorbereiten", "Systeme, Informationen und Owner sauber erfassen"],
    risks: ["Risiken einfach bearbeiten", "Was kann schiefgehen und was macht ihr dagegen?"],
    legal: ["Rechtsregister einfach steuern", "Anforderungen einordnen, Fristen setzen, Nachweise verknüpfen"],
    suppliers: ["Lieferanten einfach prüfen", "Kritikalität, Verträge und Nachweise zusammenführen"],
    policies: ["Policies einfach steuern", "Vorlage, Entwurf, Review und Freigabe verbinden"],
    incidents: ["Incidents einfach dokumentieren", "Ereignis, Bewertung, Maßnahmen und Lessons Learned sammeln"],
    contracts: ["Verträge einfach prüfen", "Vertrag, AVV, Sicherheitsbezug und Review nachvollziehen"]
  }[collection] || ["Register einfach steuern", "Einträge erfassen, Nachweise verknüpfen, Prüfung vorbereiten"];
  return {
    eyebrow: "Nächster Schritt",
    title: labels[0],
    copy: `${labels[1]}. Die Plattform zeigt formale Lücken; die fachliche Bewertung bleibt beim Berater/Admin.`,
    primaryAction: pageActionFromRegisterAction(next, collection),
    cards: [
      {
        label: "Jetzt tun",
        title: next.title || "Bereich öffnen",
        text: next.text || emptyRegisterAction(collection),
        status: next.warning ? "Offen" : "OK",
        tone: next.warning ? "warning" : "active",
        action: { ...pageActionFromRegisterAction(next, collection), primary: true }
      },
      {
        label: "Formaler Stand",
        title: `${complete}/${rows.length || 0} vorbereitet`,
        text: rows.length ? "Vorbereitet bedeutet: keine offensichtliche formale Lücke. Keine fachliche Freigabe." : emptyRegisterAction(collection),
        status: rows.length ? `${percentOf(complete, rows.length)}%` : "Start",
        tone: rows.length && complete === rows.length ? "done" : ""
      },
      {
        label: "Nachweise",
        title: `${missingEvidence} fehlen`,
        text: missingEvidence ? "Datei, Link oder Dokumentverweis ergänzen." : "Formaler Nachweisbezug ist vorhanden.",
        status: missingEvidence ? "Fehlt" : "Vorhanden",
        tone: missingEvidence ? "warning" : "done",
        action: { type: "jump", target: "documents", label: "Nachweise öffnen" }
      },
      {
        label: "Prüfstatus",
        title: `${waiting} wartet · ${rework} Nacharbeit`,
        text: "Kunden reichen ein. Berater/Admin entscheidet über Freigabe, Ablehnung und Auditrelevanz.",
        status: rework ? "Nacharbeit" : waiting ? "In Prüfung" : "Offen",
        tone: rework ? "warning" : waiting ? "active" : "",
        action: { type: "jump", target: canAccessView("review") ? "review" : collection, label: canAccessView("review") ? "Review Center" : "Status ansehen" }
      }
    ]
  };
}

