function pageActionProjectStreamData(stream) {
  const plan = normalizeProjectPlan(state.projectPlan).filter((item) => item.stream === stream);
  const done = plan.filter((item) => item.status === "Erledigt").length;
  const blocked = plan.filter((item) => item.status === "Blockiert").length;
  const missingEvidence = plan.filter((item) => projectDocumentationStatus(item).missingTotal > 0).length;
  const next = plan.find((item) => item.status !== "Erledigt") || plan[0];
  const reviewOpen = pageActionReviewCount(stream);
  const isNis = stream === "NIS-2";
  const reviewTarget = canAccessView("review") ? "review" : "documents";
  return {
    eyebrow: isNis ? "NIS-2 einfach steuern" : "ISO 27001 einfach steuern",
    title: isNis ? "NIS-2: klären, umsetzen, nachweisen, prüfen lassen" : "ISO 27001: Arbeitspakete statt Normsuche",
    copy: "Oben steht immer der nächste praktische Schritt. Die fachlichen Details bleiben darunter verfügbar, ohne den Kunden zu überladen.",
    primaryAction: next ? { type: "project", target: next.id, label: "Nächsten Schritt öffnen" } : null,
    cards: [
      {
        label: "Nächster Schritt",
        title: next ? next.phase : "Keine Arbeitspakete",
        text: next ? next.title : "Für diesen Bereich sind aktuell keine Einträge vorhanden.",
        status: next?.status || "Offen",
        tone: "active",
        action: next ? { type: "project", target: next.id, label: "Öffnen", primary: true } : null
      },
      {
        label: "Status",
        title: `${done}/${plan.length || 0} erledigt`,
        text: blocked ? `${blocked} Arbeitspaket(e) sind blockiert und sollten entschieden werden.` : "Fortschritt wird über erledigte Arbeitspakete gemessen.",
        status: `${percentOf(done, plan.length)}%`,
        tone: blocked ? "warning" : done === plan.length && plan.length ? "done" : ""
      },
      {
        label: "Nachweis",
        title: missingEvidence ? `${missingEvidence} Nachweis-/Vorlagenlücke(n)` : "Nachweise wirken vollständig",
        text: missingEvidence ? "Kunde soll Vorlage oder Nachweis ergänzen." : "Formale Nachweislage prüfen und bei Bedarf einreichen.",
        status: missingEvidence ? "Fehlt" : "Bereit",
        tone: missingEvidence ? "warning" : "done",
        action: next ? { type: "projectUpload", target: next.id, label: "Nachweis vorbereiten" } : { type: "jump", target: "documents", label: "Nachweise öffnen" }
      },
      {
        label: "Beraterprüfung",
        title: reviewOpen ? `${reviewOpen} Punkt(e) offen` : "Keine offenen Reviewpunkte",
        text: "Fachliche Freigabe und Auditentscheidung bleiben beim Berater/Admin.",
        status: reviewOpen ? "In Prüfung" : "Freigegeben",
        tone: reviewOpen ? "active" : "done",
        action: { type: "jump", target: reviewTarget, label: canAccessView("review") ? "Review Center" : "Nachweise ansehen" }
      }
    ]
  };
}

function pageActionReviewCount(stream) {
  const items = reviewCenterItems().filter((item) => item.reviewStatus !== "freigegeben");
  if (stream === "NIS-2") {
    return items.filter((item) =>
      String(item.mapping || item.module || "").includes("NIS")
      || ["Rechtsregister", "Incident Management", "Vendor Management"].includes(item.module)
    ).length;
  }
  return items.filter((item) =>
    String(item.mapping || "").includes("Clause")
    || String(item.mapping || "").includes("A.")
    || item.module === "SoA Matrix"
    || item.module === "Policy Management"
    || item.module === "Risiko Management"
  ).length;
}

