function renderIsoSnapshotDashboard(stats) {
  const records = normalizeSoaRegister(state.soa);
  const metrics = soaMetrics(records);
  const isoPlan = normalizeProjectPlan(state.projectPlan).filter((item) => item.stream === "ISO 27001");
  const isoPlanDone = isoPlan.filter((item) => item.status === "Erledigt").length;
  const policyTotal = Math.max(state.policies.length, 1);
  const overall = percentOf(metrics.implemented + isoPlanDone + stats.policiesApproved, metrics.total + isoPlan.length + policyTotal);
  const openSoa = records.filter((record) => record.applicability === "Zu prüfen" || ["Offen", "Geplant"].includes(record.implementation)).length;
  const highRisks = state.risks.filter((risk) => !["Akzeptiert", "Erledigt"].includes(risk.status) && riskScore(risk.likelihood, risk.impact) >= 10).length;
  const customerDocuments = state.documents.filter((document) => document.status !== "Quelle");
  const isoDocuments = customerDocuments.filter((document) => normalizeImportKey(`${document.area} ${document.linkedTo} ${document.evidenceFor} ${document.note}`).includes("iso")
    || normalizeImportKey(`${document.linkedTo} ${document.evidenceFor} ${document.note}`).includes("annex")
    || /A\.\d+\.\d+|Clause\s+\d/i.test(`${document.linkedTo || ""} ${document.evidenceFor || ""} ${document.note || ""}`)).length;
  const policyPercent = percentOf(stats.policiesApproved, state.policies.length);
  const templatePercent = percentOf(state.templateDrafts.length, TEMPLATE_LIBRARY.length);
  const evidencePercent = percentOf(isoDocuments, Math.max(ANNEX_CONTROLS.length, 1));
  const soaById = new Map(records.map((record) => [record.controlId, record]));

  return `
    <section class="panel iso-snapshot-dashboard">
      <div class="iso-snapshot-head">
        <div>
          <span class="eyebrow">ISO 27001 Cockpit</span>
          <h3>Policies, Controls und Nachweise auf einer Sicht</h3>
          <p>Eine bewusst einfache Management-Übersicht: SoA-Status, Annex-A-Gruppen, Arbeitsbereiche, Policy-Fortschritt und offene Risiken.</p>
        </div>
        <div class="iso-snapshot-actions">
          <button class="primary-button" type="button" data-jump="soa">SoA Matrix öffnen</button>
          <button class="quiet-button" type="button" data-jump="policies">Policies</button>
          <button class="quiet-button" type="button" data-jump="documents">Nachweise</button>
        </div>
      </div>

      <div class="iso-snapshot-layout">
        <button class="iso-snapshot-ring-card" type="button" data-jump="soa">
          <div class="iso-snapshot-ring" style="--angle:${overall * 3.6}deg">
            <strong>${overall}%</strong>
            <span>ISO Readiness</span>
          </div>
          <small>${metrics.implemented}/${metrics.total} SoA-Controls umgesetzt · ${isoPlanDone}/${isoPlan.length} ISO-Arbeitspakete erledigt</small>
        </button>

        <div class="iso-snapshot-main">
          <div class="iso-snapshot-block">
            <div class="iso-snapshot-block-head">
              <strong>Annex-A-Gruppen</strong>
              <span>${ANNEX_CONTROLS.length} Controls</span>
            </div>
            <div class="iso-snapshot-bars">
              ${ANNEX_GROUPS.map(([groupId, label]) => {
                const controls = ANNEX_CONTROLS.filter((control) => control.group === groupId);
                const done = controls.filter((control) => soaById.get(control.id)?.implementation === "Umgesetzt").length;
                return renderIsoSnapshotBar(groupId, label, percentOf(done, controls.length), `${done}/${controls.length}`);
              }).join("")}
            </div>
          </div>

          <div class="iso-snapshot-block">
            <div class="iso-snapshot-block-head">
              <strong>Arbeitsbereiche</strong>
              <span>nach Modulen</span>
            </div>
            <div class="iso-snapshot-domain-grid">
              ${isoSnapshotDomains(records).map((domain) => renderIsoSnapshotBar(domain.label, domain.hint, domain.percent, `${domain.done}/${domain.total}`)).join("")}
            </div>
          </div>
        </div>

        <aside class="iso-snapshot-side">
          <strong>Policy- und Nachweisfortschritt</strong>
          ${renderIsoSnapshotBar("Policies", "freigegeben", policyPercent, `${stats.policiesApproved}/${state.policies.length || 0}`)}
          ${renderIsoSnapshotBar("Arbeitsvorlagen", "ausgefüllt", templatePercent, `${state.templateDrafts.length}/${TEMPLATE_LIBRARY.length}`)}
          ${renderIsoSnapshotBar("Nachweise", "ISO-/Annex-Bezug", Math.min(evidencePercent, 100), `${isoDocuments} Dokument(e)`)}
          <div class="iso-snapshot-side-total">
            <span>Gesamt vorbereitet</span>
            <strong>${percentOf(stats.policiesApproved + state.templateDrafts.length + isoDocuments, state.policies.length + TEMPLATE_LIBRARY.length + Math.max(isoDocuments, ANNEX_CONTROLS.length))}%</strong>
          </div>
        </aside>
      </div>

      <div class="iso-snapshot-mini-grid">
        <button class="iso-snapshot-mini" type="button" data-jump="soa">
          <span>SoA offen</span>
          <strong>${openSoa}</strong>
          <small>Anwendbarkeit oder Umsetzung prüfen</small>
        </button>
        <button class="iso-snapshot-mini" type="button" data-jump="risks">
          <span>Risiken</span>
          <strong>${highRisks}</strong>
          <small>hohe offene Risiken</small>
        </button>
        <button class="iso-snapshot-mini" type="button" data-jump="policies">
          <span>Policy Packs</span>
          <strong>${policyPercent}%</strong>
          <small>${stats.policiesApproved} von ${state.policies.length || 0} freigegeben</small>
        </button>
        <button class="iso-snapshot-mini" type="button" data-jump="auditpackage">
          <span>Audit</span>
          <strong>${auditTraceabilityRows(customerDocuments).filter((row) => row.status === "Fehlt").length}</strong>
          <small>Nachweiszeilen offen</small>
        </button>
      </div>
    </section>
  `;
}

function isoSnapshotDomains(records = normalizeSoaRegister(state.soa)) {
  const definitions = [
    ["Governance", ["Governance", "Policies", "Legal"], "Rollen, Regeln, Anforderungen"],
    ["Asset Management", ["Assets"], "Inventar und Klassifizierung"],
    ["Access", ["Access"], "Identitäten und Berechtigungen"],
    ["Supplier", ["Suppliers"], "Lieferanten und Cloud"],
    ["Incident", ["Incidents"], "Vorfälle und Nachweise"],
    ["Technology", ["Technology", "Monitoring"], "Betrieb und technische Controls"],
    ["Continuity", ["Continuity"], "Störung und Wiederanlauf"],
    ["People", ["People"], "HR und Awareness"]
  ];
  const byControl = new Map(records.map((record) => [record.controlId, record]));
  return definitions.map(([label, modules, hint]) => {
    const controls = ANNEX_CONTROLS.filter((control) => modules.includes(control.module));
    const done = controls.filter((control) => byControl.get(control.id)?.implementation === "Umgesetzt").length;
    return { label, hint, done, total: controls.length, percent: percentOf(done, controls.length) };
  });
}

function renderIsoSnapshotBar(label, hint, percent, value) {
  const width = Math.max(0, Math.min(Number(percent) || 0, 100));
  return `
    <div class="iso-snapshot-bar">
      <div class="iso-snapshot-bar-head">
        <div>
          <span>${escapeHtml(label)}</span>
          <small>${escapeHtml(hint)}</small>
        </div>
        <strong>${escapeHtml(value || `${width}%`)}</strong>
      </div>
      <div class="iso-snapshot-meter" aria-label="${escapeHtml(label)} ${width}%"><i style="width:${width}%"></i></div>
    </div>
  `;
}

function renderWorkspaceConflictBanner() {
  if (!backendSessionUser || !backendSync.conflict) return "";
  const revisionHint = backendSync.remoteRevision !== null
    ? `Der Server enthält inzwischen Arbeitsstand ${backendSync.remoteRevision}.`
    : "Der Server enthält inzwischen einen neueren Arbeitsstand.";
  const editorHint = backendSync.remoteUpdatedBy
    ? `Zuletzt geändert von ${backendSync.remoteUpdatedBy}${backendSync.remoteUpdatedAt ? ` am ${formatBackendTime(backendSync.remoteUpdatedAt)}` : ""}.`
    : backendSync.remoteUpdatedAt
      ? `Zuletzt geändert am ${formatBackendTime(backendSync.remoteUpdatedAt)}.`
      : "";
  return `
    <section class="workspace-conflict-banner" role="alert" aria-live="assertive">
      <div class="workspace-conflict-icon" aria-hidden="true">!</div>
      <div class="workspace-conflict-copy">
        <span class="eyebrow">Speicherkonflikt</span>
        <h3>Eine andere Sitzung hat diesen Workspace geändert.</h3>
        <p>${escapeHtml(`${revisionHint} ${editorHint}`.trim())} Deine lokale Fassung wurde nicht überschrieben. Sichere sie zuerst und entscheide danach bewusst, welchen Stand du weiterbearbeitest.</p>
      </div>
      <div class="workspace-conflict-actions">
        <button class="quiet-button" type="button" data-conflict-export>Lokale Fassung sichern</button>
        <button class="quiet-button" type="button" data-conflict-reload>Serverstand laden</button>
        <button class="primary-button" type="button" data-conflict-compare>Fassungen vergleichen</button>
      </div>
    </section>
  `;
}

function renderWorkspaceConflictComparison() {
  if (!backendSync.conflict || !conflictRemoteState) return "";
  const rows = workspaceMerge.compare(state, conflictRemoteState, WORKSPACE_MERGE_SECTIONS)
    .filter((row) => row.changed);
  return `
    <section class="workspace-conflict-comparison" aria-label="Fassungsvergleich">
      <div class="workspace-conflict-comparison-head">
        <div>
          <span class="eyebrow">Manueller Fassungsvergleich</span>
          <h3>${rows.length} geänderte Bereiche prüfen</h3>
          <p>Standardmäßig bleibt der Serverstand erhalten. Wähle die lokale Fassung nur für Bereiche, die bewusst übernommen werden sollen. Die Plattform bewertet keine fachliche Richtigkeit.</p>
        </div>
        <button class="quiet-button" type="button" data-conflict-compare-close>Schließen</button>
      </div>
      <form data-conflict-merge-form>
        <div class="workspace-conflict-comparison-list">
          ${rows.map((row) => `
            <label class="workspace-conflict-comparison-row">
              <span>
                <strong>${escapeHtml(row.label)}</strong>
                <small>Lokal: ${escapeHtml(workspaceMergeSummary(row.local))} · Server: ${escapeHtml(workspaceMergeSummary(row.remote))}</small>
              </span>
              <select name="${escapeHtml(row.key)}">
                <option value="remote" ${conflictMergeChoices[row.key] !== "local" ? "selected" : ""}>Serverstand behalten</option>
                <option value="local" ${conflictMergeChoices[row.key] === "local" ? "selected" : ""}>Lokalen Bereich übernehmen</option>
              </select>
            </label>
          `).join("")}
        </div>
        <div class="workspace-conflict-comparison-footer">
          <p><strong>Sicherheitsregel:</strong> Nicht ausgewählte Bereiche bleiben unverändert auf dem aktuellen Serverstand.</p>
          <button class="primary-button" type="submit" ${rows.length ? "" : "disabled"}>Auswahl zusammenführen und speichern</button>
        </div>
      </form>
    </section>
  `;
}

function workspaceMergeSummary(summary = {}) {
  if (summary.kind === "list") return `${summary.count || 0} Einträge`;
  if (summary.kind === "object") return `${summary.count || 0} Felder`;
  return summary.count ? "Wert vorhanden" : "leer";
}

function renderWorkspaceConnectivityBanner() {
  if (!backendSessionUser || backendSync.online !== false) return "";
  return `
    <section class="workspace-connectivity-banner" role="status" aria-live="polite">
      <div class="workspace-connectivity-icon" aria-hidden="true">i</div>
      <div class="workspace-connectivity-copy">
        <span class="eyebrow">Offline-Modus</span>
        <h3>Die Verbindung zum Server ist unterbrochen.</h3>
        <p>Deine Änderungen bleiben in diesem Browser gespeichert. Sobald die Verbindung zurückkehrt, versucht die Plattform automatisch erneut zu synchronisieren.</p>
      </div>
      <button class="quiet-button" type="button" data-connectivity-retry>Verbindung erneut prüfen</button>
    </section>
  `;
}

function renderSessionExpiredBanner() {
  if (!backendSessionUser || !backendSync.sessionExpired) return "";
  return `
    <section class="session-expired-banner" role="alert" aria-live="assertive">
      <div class="session-expired-copy">
        <span class="eyebrow">Sitzung abgelaufen</span>
        <h3>Bitte melde dich erneut an.</h3>
        <p>Deine Änderungen bleiben lokal gespeichert. Nach der Anmeldung prüft die Plattform zuerst den Serverstand und synchronisiert nur, wenn keine fremden Änderungen überschrieben werden.</p>
      </div>
      <form class="session-reauth-form" data-session-reauth>
        <label>
          <span>Benutzername</span>
          <input name="username" autocomplete="username" value="${escapeHtml(backendSessionUser.username || "")}" required />
        </label>
        <label>
          <span>Passwort</span>
          <input name="password" type="password" autocomplete="current-password" required />
        </label>
        <label>
          <span>MFA-Code</span>
          <input name="totp" inputmode="numeric" autocomplete="one-time-code" placeholder="Optional" />
        </label>
        <button class="primary-button" type="submit">Erneut anmelden</button>
      </form>
    </section>
  `;
}

function renderRemoteUpdateBanner() {
  if (!backendSessionUser || !backendSync.remoteUpdateAvailable || backendSync.conflict) return "";
  const editor = backendSync.remoteUpdatedBy ? ` von ${backendSync.remoteUpdatedBy}` : "";
  const changedAt = backendSync.remoteUpdatedAt ? ` am ${formatBackendTime(backendSync.remoteUpdatedAt)}` : "";
  return `
    <section class="remote-update-banner" role="status" aria-live="polite">
      <div>
        <span class="eyebrow">Neuer Arbeitsstand</span>
        <h3>Auf dem Server wurde eine neuere Fassung gespeichert.</h3>
        <p>Arbeitsstand ${escapeHtml(String(backendSync.remoteRevision ?? "neu"))}${escapeHtml(editor)}${escapeHtml(changedAt)}. Lokal sind keine ungespeicherten Änderungen vorhanden.</p>
      </div>
      <button class="primary-button" type="button" data-remote-workspace-reload>Neuen Stand laden</button>
    </section>
  `;
}

function renderWorkspaceLiveStrip() {
  if (!backendSessionUser) return "";
  const updateAvailable = backendSync.remoteUpdateAvailable && !backendSync.conflict;
  const conflict = backendSync.conflict;
  const actor = backendSync.remoteUpdatedBy || backendSync.updatedBy || "";
  const detail = conflict
    ? "Lokale Änderungen und Serverstand müssen abgeglichen werden."
    : updateAvailable
      ? "Ein neuer Serverstand kann geladen werden."
      : actor
        ? `Letzte Änderung: ${actor}`
        : "Änderungen werden automatisch erkannt.";
  return `
    <div class="workspace-live-strip ${escapeHtml(workspaceLiveTone())}" role="status" aria-live="polite">
      <span class="workspace-live-dot ${escapeHtml(workspaceLiveTone())}" data-workspace-live-dot></span>
      <div>
        <strong data-live-sync-status>${escapeHtml(liveWorkspaceStatusText())}</strong>
        <small><span data-workspace-live-freshness>${escapeHtml(workspaceFreshnessText())}</span> · ${escapeHtml(detail)}</small>
      </div>
      ${conflict
        ? `<button class="quiet-button" type="button" data-live-conflict-compare>Abgleichen</button>`
        : updateAvailable
          ? `<button class="quiet-button" type="button" data-remote-workspace-reload>Stand laden</button>`
          : backendSync.dirty && canEditWorkspace()
            ? `<button class="quiet-button" type="button" data-backend-save>Synchronisieren</button>`
            : ""}
    </div>
  `;
}

function renderWorkspaceContextBar(view = currentView) {
  if (!backendSessionUser) return "";
  const stats = dashboardStats();
  const tenant = backendSessionUser.tenant || {};
  const tenantName = tenant.name || "Mandant";
  const roleLabel = backendSessionUser.roleLabel || roleOptionLabel(backendSessionUser.role || "viewer");
  const mode = backendSessionUser.platformAdmin
    ? t("top.mode.admin")
    : isBackendAdmin()
      ? t("top.mode.customerAdmin")
      : t("top.mode.customer");
  const projectPercent = stats.progress?.percent ?? projectPlanProgress().percent;
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt").length;
  const evidenceCount = Math.max(0, state.documents.length - SOURCE_FILES.length);
  const policyOpen = state.policies.filter((policy) => policy.status !== "Freigegeben").length;
  const syncText = backendSyncText();
  const lastEditor = backendSync.updatedBy || "";
  const onboardingDone = Boolean(state.onboarding?.completed);
  const onboardingLabel = onboardingDone ? "Startprofil prüfen" : "Startprofil starten";
  const nextTodo = customerTodoItems(stats)[0];
  const nextTitle = nextTodo?.title || (canReviewDocuments() ? "Beraterprüfung regelmäßig prüfen" : "Kundenmodus fortführen");
  const nextMeta = nextTodo?.meta || "Keine akuten Rückgaben. Arbeitsstand weiter pflegen und bei Bedarf einreichen.";
  const nextStatus = nextTodo?.status || "Bereit";
  const nextTarget = nextTodo?.view || (canReviewDocuments() ? "review" : "guided");
  const nextActionAttrs = nextTodo?.scrollTarget
    ? `data-jump-section="${escapeHtml(nextTarget)}:${escapeHtml(nextTodo.scrollTarget)}"`
    : `data-jump="${escapeHtml(nextTarget)}"`;

  return `
    <section class="workspace-context-bar ${view === "dashboard" ? "dashboard-context" : ""}">
      <div class="workspace-context-main">
        <span class="eyebrow">${escapeHtml(t("context.eyebrow"))}</span>
        <h3>${escapeHtml(tenantName)}</h3>
        <p class="workspace-context-meta">
          <span>${escapeHtml(t("context.view"))}: <strong>${escapeHtml(mode)}</strong></span>
          <span>${escapeHtml(t("context.role"))}: <strong>${escapeHtml(roleLabel)}</strong></span>
          <span>${escapeHtml(t("context.status"))}: <strong data-backend-sync-status>${escapeHtml(syncText)}</strong></span>
          ${lastEditor ? `<span>Letzte Bearbeitung: <strong>${escapeHtml(lastEditor)}</strong></span>` : ""}
          <span>${escapeHtml(t("context.approval"))}: <strong>${escapeHtml(t("context.approvalValue"))}</strong></span>
        </p>
        ${renderWorkspaceLiveStrip()}
        <button class="workspace-context-next" type="button" ${nextActionAttrs}>
          <span>${escapeHtml(t("context.nextStep"))}</span>
          <strong>${escapeHtml(nextTitle)}</strong>
          <small>${escapeHtml(nextMeta)}</small>
          ${statusTag(nextStatus)}
        </button>
      </div>
      <div class="workspace-context-metrics" aria-label="Projektstatus">
        <div><strong>${projectPercent}%</strong><span>${escapeHtml(t("context.project"))}</span></div>
        <div><strong>${openTasks}</strong><span>${escapeHtml(t("context.openTasks"))}</span></div>
        <div><strong>${evidenceCount}</strong><span>${escapeHtml(t("context.evidence"))}</span></div>
        <div><strong>${policyOpen}</strong><span>${escapeHtml(t("context.policiesOpen"))}</span></div>
      </div>
      <div class="workspace-context-actions">
        <button class="primary-button" type="button" data-jump-section="dashboard:customerOnboarding">${escapeHtml(onboardingLabel)}</button>
        ${isBackendAdmin() || canReviewDocuments() ? `<button class="quiet-button" type="button" data-jump="clients">${escapeHtml(t("context.customerProjects"))}</button>` : ""}
        <button class="quiet-button" type="button" data-jump="guided">${escapeHtml(t("context.customerMode"))}</button>
        <button class="quiet-button" type="button" data-jump="documents">${escapeHtml(canEditWorkspace() ? t("context.uploadEvidence") : t("context.viewEvidence"))}</button>
        <button class="quiet-button" type="button" data-jump="project">${escapeHtml(t("context.projectPlan"))}</button>
      </div>
    </section>
  `;
}

