function renderDashboardCuratedHome(stats = dashboardStats(), reviewMetrics = reviewCenterMetrics(reviewCenterItems())) {
  const todoItems = customerTodoItems(stats);
  const next = todoItems[0] || {
    title: "Kundenmodus fortführen",
    meta: "Keine akute Rückgabe. Projektstand weiter pflegen und neue Nachweise bei Bedarf einreichen.",
    view: "guided",
    action: "Kundenmodus öffnen",
    status: "Bereit"
  };
  const packageData = auditPackageReportData();
  const gate = packageData.gate || { blockers: [], consultantApproved: false };
  const management = managementReviewData(stats);
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const waitingReview = reviewMetrics.submitted + reviewMetrics.inReview;
  const rework = todoItems.filter((item) => ["rework", "onboarding-rework"].includes(item.kind) || item.category === "Nacharbeit").length;
  const topAction = dashboardExecutiveTopAction(riskComplianceDashboardData(stats), reviewSlaRows(reviewCenterItems()).filter((row) => row.bucket === "overdue").length);
  const nextAttrs = dashboardStartJumpAttrs(next.view || "guided", next.scrollTarget);

  const cards = [
    {
      label: "Heute zuerst",
      title: next.title,
      text: next.meta || "Nächsten offenen Punkt bearbeiten.",
      value: todoItems.length,
      valueLabel: "offene Punkte",
      tone: rework ? "warning" : "active",
      action: next.action || "Jetzt weitermachen",
      attrs: nextAttrs
    },
    {
      label: "Blocker",
      title: gate.blockers.length ? "Audit-Blocker klären" : "Keine akuten Audit-Blocker",
      text: gate.blockers.length ? `${gate.blockers.length} Punkt(e) verhindern eine Beraterfreigabe.` : "Auditpaket bleibt vorbereitet, Freigabe erfolgt nur durch Berater/Admin.",
      value: gate.blockers.length,
      valueLabel: "Blocker",
      tone: gate.blockers.length ? "danger" : "done",
      action: "Auditpaket öffnen",
      attrs: 'data-jump="auditpackage"'
    },
    {
      label: "Beraterprüfung",
      title: waitingReview ? "Einreichungen prüfen" : "Nichts Neues in Prüfung",
      text: waitingReview ? `${waitingReview} Punkt(e) warten auf Prüfung oder Entscheidung.` : `${reviewMetrics.returns || 0} Rückgabe(n), ${reviewMetrics.approved || 0} freigegeben.`,
      value: waitingReview,
      valueLabel: "wartet",
      tone: waitingReview ? "active" : "done",
      action: canAccessView("review") ? "Review Center" : "Kundenmodus",
      attrs: `data-jump="${canAccessView("review") ? "review" : "guided"}"`
    },
    {
      label: "Management-Status",
      title: topAction.title,
      text: topAction.text,
      value: management.readiness,
      valueLabel: "% formal",
      tone: management.blockers ? "warning" : management.readiness >= 80 ? "done" : "active",
      action: "Executive Cockpit",
      attrs: 'data-jump="executive"'
    }
  ];

  return `
    <section class="panel dashboard-curated-home" aria-label="Kuratierter Dashboard-Einstieg">
      <div class="dashboard-curated-head">
        <div>
          <span class="eyebrow">Startklarer Überblick</span>
          <h3>Was ist jetzt wichtig?</h3>
          <p>Diese Startseite zeigt nur die nächsten Entscheidungen. Details, Auswertungen und Demo-Inhalte bleiben verfügbar, aber sie blockieren nicht den ersten Blick.</p>
        </div>
        <div class="dashboard-curated-summary">
          <span><strong>${stats.progress.percent}%</strong><small>Projekt</small></span>
          <span><strong>${docMetrics.missing}</strong><small>Nachweislücken</small></span>
          <span><strong>${reviewMetrics.returns}</strong><small>Nacharbeit</small></span>
        </div>
      </div>

      <div class="dashboard-curated-grid">
        ${cards.map(renderDashboardCuratedCard).join("")}
      </div>

      <div class="dashboard-curated-actions">
        <button class="primary-button" type="button" data-jump="guided">Kundenmodus öffnen</button>
        <button class="quiet-button" type="button" data-jump="documents">Nachweise</button>
        <button class="quiet-button" type="button" data-jump="executive">Geschäftsführung</button>
        <button class="quiet-button" type="button" data-jump="nis2">NIS-2 Navigator</button>
        <button class="quiet-button" type="button" data-jump="policies">Policies</button>
      </div>
    </section>
  `;
}

function renderDashboardCuratedCard(card) {
  return `
    <article class="dashboard-curated-card ${escapeHtml(card.tone || "")}">
      <div class="dashboard-curated-card-top">
        <span>${escapeHtml(card.label)}</span>
        <strong>${escapeHtml(String(card.value))}</strong>
      </div>
      <h4>${escapeHtml(card.title)}</h4>
      <p>${escapeHtml(card.text)}</p>
      <div class="dashboard-curated-card-foot">
        <small>${escapeHtml(card.valueLabel)}</small>
        <button class="${card.tone === "danger" || card.tone === "warning" ? "primary-button" : "quiet-button"}" type="button" ${card.attrs}>${escapeHtml(card.action)}</button>
      </div>
    </article>
  `;
}

function renderDashboardExecutiveBrief(stats = dashboardStats(), reviewMetrics = reviewCenterMetrics(reviewCenterItems())) {
  const data = riskComplianceDashboardData(stats);
  const docMetrics = data.docMetrics;
  const slaRows = reviewSlaRows(data.reviewItems || reviewCenterItems());
  const dueNow = slaRows.filter((row) => row.bucket === "overdue").length;
  const waitingReview = reviewMetrics.submitted + reviewMetrics.inReview;
  const topAction = dashboardExecutiveTopAction(data, dueNow);
  const rows = dashboardExecutiveBriefRows(data, docMetrics, waitingReview, dueNow);
  const topRisks = data.highRisks.slice(0, 4);
  const decisions = data.decisionItems.slice(0, 4);
  const sevenDays = data.focusItems.sevenDays.slice(0, 3);
  const thirtyDays = data.focusItems.thirtyDays.slice(0, 3);
  const ninetyDays = [
    { title: "Management Review aktualisieren", text: "Status, Risiken, Maßnahmen und Entscheidungen für die nächste Review-Routine bündeln.", view: "dashboard", status: "90 Tage" },
    { title: "Policy-Reviews planen", text: "Freigaben, Review-Daten und offene Policy-Pakete konsolidieren.", view: "policies", status: "90 Tage" },
    { title: "Nachweisroutine stabilisieren", text: "Wiederkehrende Nachweise und Verantwortliche für den Betrieb festlegen.", view: "documents", status: "90 Tage" }
  ];
  return `
    <section class="panel dashboard-executive-brief executive-cockpit" aria-label="Geschäftsführungs-Cockpit">
      <div class="dashboard-executive-main">
        <div>
          <span class="eyebrow">Geschäftsführungs-Cockpit</span>
          <h3>60-Sekunden-Blick auf Status, Risiken und Entscheidungen.</h3>
          <p>${escapeHtml(data.trafficLight.text)} Die Anzeige ist eine formale Managementübersicht. Fachliche Freigabe und Auditentscheidung bleiben beim Berater/Admin.</p>
        </div>
        <article class="dashboard-executive-status ${escapeHtml(data.trafficLight.tone)}">
          <span>${escapeHtml(data.trafficLight.level)}</span>
          <strong>${escapeHtml(data.packageApproved ? "Beraterfreigegeben" : data.gate.consultantApproved ? "Freigabe offen" : "Prüfung offen")}</strong>
          <small>${escapeHtml(data.packageApproved ? "Explizite Beraterfreigabe liegt vor." : data.gate.consultantApproved ? "Gate formal erfüllt, Beraterfreigabe bewusst setzen." : "Auditpaket vorbereitet, aber noch nicht beraterfreigegeben.")}</small>
        </article>
      </div>

      <div class="dashboard-executive-grid">
        ${rows.map((row) => `
          <button class="dashboard-executive-card ${escapeHtml(row.tone || "")}" type="button" data-jump="${escapeHtml(row.view || "dashboard")}">
            <span>${escapeHtml(row.label)}</span>
            <strong>${escapeHtml(row.value)}</strong>
            <small>${escapeHtml(row.hint)}</small>
          </button>
        `).join("")}
      </div>

      <div class="executive-cockpit-board">
        <article class="executive-cockpit-list">
          <div class="executive-cockpit-list-head">
            <strong>Top-Risiken mit Managementbedarf</strong>
            <span>${topRisks.length} offen</span>
          </div>
          ${topRisks.length ? topRisks.map((risk) => `
            <button class="executive-cockpit-row" type="button" data-jump="risks">
              <span>${escapeHtml(risk.riskId || "Risiko")}</span>
              <strong>${escapeHtml(risk.scenario || risk.asset || "Risiko prüfen")}</strong>
              <small>${escapeHtml(`Owner: ${risk.owner || "offen"} · Behandlung: ${risk.treatment ? "vorhanden" : "offen"}`)}</small>
            </button>
          `).join("") : `<div class="executive-empty">Keine Top-Risiken mit Sofortbedarf erkannt.</div>`}
        </article>

        <article class="executive-cockpit-list">
          <div class="executive-cockpit-list-head">
            <strong>Offene Entscheidungen</strong>
            <span>${decisions.length} Punkt(e)</span>
          </div>
          ${decisions.length ? decisions.map((item) => `
            <button class="executive-cockpit-row" type="button" data-jump="${escapeHtml(item.view || "tasks")}">
              <span>${escapeHtml(item.type || item.status || "Entscheidung")}</span>
              <strong>${escapeHtml(item.title || "Entscheidung dokumentieren")}</strong>
              <small>${escapeHtml(item.meta || "Begründung, Owner und Entscheidung festhalten.")}</small>
            </button>
          `).join("") : `<div class="executive-empty">Keine akuten Management-Entscheidungen erkannt.</div>`}
        </article>
      </div>

      <div class="executive-cockpit-bottom">
        <article class="executive-traces">
          <div class="executive-cockpit-list-head">
            <strong>Compliance-Spuren</strong>
            <span>formal</span>
          </div>
          ${[
            { label: "ISO 27001", value: `${stats.isoPercent}%`, view: "iso" },
            { label: "NIS-2", value: `${stats.nisPercent}%`, view: "nis2" },
            { label: "Nachweise", value: `${docMetrics.approved + docMetrics.inReview}/${docMetrics.working || 0}`, view: "documents" },
            { label: "Auditpaket", value: data.packageApproved ? "freigegeben" : "vorbereitet", view: "auditpackage" }
          ].map((track) => `
            <button class="executive-trace-row" type="button" data-jump="${escapeHtml(track.view)}">
              <span>${escapeHtml(track.label)}</span>
              <strong>${escapeHtml(track.value)}</strong>
            </button>
          `).join("")}
        </article>

        <article class="executive-deadlines">
          <div class="executive-cockpit-list-head">
            <strong>Fristen</strong>
            <span>7 · 30 · 90 Tage</span>
          </div>
          ${[
            ["7 Tage", sevenDays],
            ["30 Tage", thirtyDays],
            ["90 Tage", ninetyDays]
          ].map(([label, items]) => `
            <div class="executive-deadline-lane">
              <span>${escapeHtml(label)}</span>
              ${(items || []).slice(0, 2).map((item) => `
                <button type="button" data-jump="${escapeHtml(item.view || "tasks")}">
                  <strong>${escapeHtml(item.title)}</strong>
                  <small>${escapeHtml(item.text || item.status || "")}</small>
                </button>
              `).join("")}
            </div>
          `).join("")}
        </article>
      </div>

      <div class="dashboard-executive-action">
        <div>
          <span class="dashboard-start-pill">Nächste sinnvolle Aktion</span>
          <strong>${escapeHtml(topAction.title)}</strong>
          <p>${escapeHtml(topAction.text)}</p>
        </div>
        <div class="dashboard-executive-buttons">
          <button class="primary-button" type="button" data-jump="${escapeHtml(topAction.view)}">${escapeHtml(topAction.action)}</button>
          <button class="quiet-button" type="button" data-copy-dashboard-brief>Lage kopieren</button>
          <button class="quiet-button" type="button" data-management-dashboard-report>Report exportieren</button>
        </div>
      </div>
    </section>
  `;
}

