function dashboardExecutiveBriefRows(data, docMetrics, waitingReview, dueNow) {
  const nextDeadline = dueNow
    ? `${dueNow} fällig`
    : (data.focusItems.sevenDays[0]?.title || data.focusItems.thirtyDays[0]?.title || "Routine");
  return [
    {
      label: "Gesamtstatus",
      value: data.trafficLight.level,
      hint: `${data.formalScore}% formal vorbereitet`,
      view: "dashboard",
      tone: data.formalScore < 60 ? "warning" : data.formalScore >= 85 ? "done" : "active"
    },
    {
      label: "Top-Risiken",
      value: data.highRisks.length,
      hint: `${data.criticalRisks.length} kritisch`,
      view: "risks",
      tone: data.highRisks.length ? "warning" : "done"
    },
    {
      label: "Offene Entscheidungen",
      value: data.decisionItems.length,
      hint: `${waitingReview} Punkt(e) in Prüfung`,
      view: "tasks",
      tone: data.decisionItems.length ? "warning" : waitingReview ? "active" : "done"
    },
    {
      label: "Nächste Frist",
      value: nextDeadline,
      hint: dueNow ? "überfällig/heute" : "nächster Management-Fokus",
      view: canAccessView("review") ? "review" : "tasks",
      tone: dueNow ? "warning" : "done"
    }
  ];
}

function dashboardExecutiveTopAction(data, dueNow = 0) {
  if (data.gate.blockers.length) {
    return {
      title: "Audit-Blocker fachlich klären",
      text: `${data.gate.blockers.length} Punkt(e) blockieren aktuell die Beraterfreigabe des Auditpakets.`,
      action: "Auditpaket öffnen",
      view: "auditpackage"
    };
  }
  if (data.criticalRisks.length) {
    return {
      title: "Kritische Risiken behandeln",
      text: `${data.criticalRisks.length} kritische Risiko(s) brauchen Behandlung, Restrisiko oder Management-Entscheidung.`,
      action: "Risiken öffnen",
      view: "risks"
    };
  }
  if (data.reviewMetrics.returns) {
    return {
      title: "Nacharbeit an Kunden steuern",
      text: `${data.reviewMetrics.returns} Rückgabe(n) sollten konkret nachverfolgt oder erneut geprüft werden.`,
      action: "Review öffnen",
      view: canAccessView("review") ? "review" : "guided"
    };
  }
  if (dueNow) {
    return {
      title: "Überfällige Reviews prüfen",
      text: `${dueNow} Review-Frist(en) sind überfällig oder heute fällig.`,
      action: "Fristen öffnen",
      view: canAccessView("review") ? "review" : "tasks"
    };
  }
  if (data.docMetrics.missing) {
    return {
      title: "Nachweis-Metadaten bereinigen",
      text: `${data.docMetrics.missing} Nachweis(e) brauchen noch formale Angaben wie Owner, Zuordnung oder Review.`,
      action: "Nachweise öffnen",
      view: "documents"
    };
  }
  return {
    title: "Regelmäßige Beraterprüfung fortführen",
    text: "Keine akuten Blocker erkannt. Review Center, Aufgaben und Nachweise kurz gegenprüfen.",
    action: "Beraterprüfung öffnen",
    view: canAccessView("review") ? "review" : "guided"
  };
}

function buildDashboardExecutiveBriefText(stats = dashboardStats()) {
  const data = riskComplianceDashboardData(stats);
  const docMetrics = data.docMetrics;
  const reviewMetrics = data.reviewMetrics;
  const slaRows = reviewSlaRows(data.reviewItems || reviewCenterItems());
  const dueNow = slaRows.filter((row) => row.bucket === "overdue").length;
  const topAction = dashboardExecutiveTopAction(data, dueNow);
  const rows = dashboardExecutiveBriefRows(data, docMetrics, reviewMetrics.submitted + reviewMetrics.inReview, dueNow);
  return [
    "SFM Compliance Lagekarte",
    `Stand: ${today()}`,
    "",
    `Ampel: ${data.trafficLight.level}`,
    `Status: ${data.trafficLight.title}`,
    `Hinweis: ${data.trafficLight.text}`,
    "",
    "Kennzahlen:",
    ...rows.map((row) => `- ${row.label}: ${row.value} (${row.hint})`),
    "",
    `Nächste sinnvolle Aktion: ${topAction.title}`,
    topAction.text,
    "",
    "Grenze: Diese Lagekarte ist eine formale Arbeitsübersicht. Sie ersetzt keine Berater-/Admin-Freigabe und behauptet keine automatische ISO-Konformität, NIS-2-Erfüllung oder Auditbereitschaft."
  ].join("\n");
}

function renderDashboardMappingFocus(stats = dashboardStats()) {
  const plan = normalizeProjectPlan(state.projectPlan);
  const isoPlan = plan.filter((item) => item.stream === "ISO 27001");
  const nisPlan = plan.filter((item) => item.stream === "NIS-2");
  const sharedPlan = plan.filter((item) => item.stream === "Gemeinsam");
  const isoDone = isoPlan.filter((item) => item.status === "Erledigt").length;
  const nisDone = nisPlan.filter((item) => item.status === "Erledigt").length;
  const sharedDone = sharedPlan.filter((item) => item.status === "Erledigt").length;
  const customerDocuments = state.documents.filter((document) => document.status !== "Quelle");
  const sharedDocuments = customerDocuments.filter((document) => {
    const value = normalizeImportKey(`${document.area || ""} ${document.linkedTo || ""} ${document.evidenceFor || ""} ${document.note || ""}`);
    return value.includes("nis") && (value.includes("iso") || value.includes("annex") || /a\.\d+\.\d+/.test(value));
  });

  return `
    <section class="panel dashboard-mapping-focus">
      <div class="dashboard-simple-copy">
        <span class="eyebrow">Fachliche Trennung</span>
        <h3>Eine Datenbasis, aber getrennte Bewertungen.</h3>
        <p>ISO 27001, NIS-2 und gemeinsame Nachweise werden sichtbar verbunden, aber nicht vermischt. Die Plattform zeigt Überschneidungen, die fachliche Einordnung bleibt beim Berater/Admin.</p>
      </div>
      <div class="dashboard-mapping-cards">
        ${renderDashboardMappingCard("ISO 27001", `${stats.isoPercent}%`, `${isoDone}/${isoPlan.length || 0} Arbeitspakete`, "Normprojekt mit Clauses, Annex A, SoA, Policies und Nachweisen.", "iso", "iso")}
        ${renderDashboardMappingCard("NIS-2", `${stats.nisPercent}%`, `${nisDone}/${nisPlan.length || 0} Arbeitspakete`, "Separate Regulatorik-Spur für Einordnung, Pflichten, Vorfälle und Nachweise.", "nis2", "nis")}
        ${renderDashboardMappingCard("Gemeinsame Nachweise", `${sharedDone}/${sharedPlan.length || 0}`, `${sharedDocuments.length} Dokument(e) mit Doppelbezug`, "Nachweise können mehrfach genutzt werden, die Bewertung bleibt pro Regelwerk getrennt.", "documents", "shared")}
      </div>
      <article class="dashboard-mapping-rule">
        <span>Grundregel</span>
        <strong>ISO 27001 ersetzt NIS-2 nicht automatisch.</strong>
        <p>Gemeinsame Assets, Risiken, Lieferanten, Incidents und Nachweise vermeiden Doppelarbeit. Eine finale Aussage zu ISO, NIS-2 oder Auditfähigkeit darf die Plattform nicht automatisch treffen.</p>
        <div class="dashboard-simple-actions">
          <button class="primary-button" type="button" data-jump="review">Beraterprüfung öffnen</button>
          <button class="quiet-button" type="button" data-jump="auditpackage">Auditpaket-Gate</button>
        </div>
      </article>
    </section>
  `;
}

function renderDashboardMappingCard(title, value, meta, text, view, tone = "") {
  return `
    <button class="dashboard-mapping-card ${escapeHtml(tone)}" type="button" data-jump="${escapeHtml(view)}">
      <span>${escapeHtml(title)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(meta)}</small>
      <p>${escapeHtml(text)}</p>
    </button>
  `;
}

function renderDashboardOverviewLibrary(stats = dashboardStats()) {
  return `
    <details class="dashboard-details dashboard-overview-library">
      <summary>
        <span>
          <strong>Arbeitsbereiche und Auswertungen</strong>
          <small>Tool-Hub, Projektpfad, Cockpit und Detail-Dashboards bei Bedarf öffnen.</small>
        </span>
        <em>anzeigen</em>
      </summary>
      <div class="dashboard-overview-detail-stack">
        ${renderDashboardToolHub(stats)}
        ${renderDashboardCustomerPath(stats)}
        ${renderComplianceCockpit(stats)}
        <details class="dashboard-details dashboard-overview-details">
          <summary>
            <span>
              <strong>Management- und ISO-Detailansichten</strong>
              <small>Risk-/Compliance-Dashboard, ISO-Cockpit und Fokusstreifen.</small>
            </span>
            <em>anzeigen</em>
          </summary>
          <div class="dashboard-overview-detail-stack nested">
            ${renderDashboardFocusStrip(stats)}
            ${renderRiskComplianceDashboard(stats)}
            ${renderIsoSnapshotDashboard(stats)}
          </div>
        </details>
        ${renderDashboardCommandCenter(stats)}
      </div>
    </details>
  `;
}

function renderDashboardCommandCenter(stats = dashboardStats()) {
  return `
    <section class="panel command-center">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Command Center</span>
          <h3>SFM Compliance Workspace</h3>
          <p>Projektsteuerung, Nachweise, Register und Management-Reviews in einer klaren Arbeitsansicht.</p>
        </div>
        <div class="action-row">
          <button class="${canEditWorkspace() ? "primary-button" : "quiet-button"}" type="button" data-jump="documents">${canEditWorkspace() ? "+ Nachweis" : "Nachweise ansehen"}</button>
          <button class="quiet-button" type="button" data-jump="project">Projektstrukturplan</button>
          <button class="quiet-button" type="button" data-jump="audit">Auditmatrix</button>
          <button class="quiet-button" type="button" data-jump="templates">Arbeitsvorlagen</button>
          ${canAccessView("production") ? `<button class="quiet-button" type="button" data-jump="production">Produktivbetrieb</button>` : ""}
          ${shouldShowConsultantEntry() ? `<button class="quiet-button consultant-quick" type="button" data-jump="consultant">Beraterbereich</button>` : ""}
        </div>
      </div>

      <div class="dashboard-program-grid">
        ${programCard("ISO 27001:2022", stats.isoPercent, `${stats.progress.byStream["ISO 27001"] || "0%"}`, "Normprojekt", "project", "Clause 4-10 / Annex A")}
        ${programCard("NIS-2", stats.nisPercent, `${stats.progress.byStream["NIS-2"] || "0%"}`, "Regulatorik", "nis2", "§28 bis §39")}
        ${programCard("Policies", percentOf(stats.policiesApproved, state.policies.length), `${stats.policiesApproved} freigegeben`, `${state.policies.length} total`, "policies", "Policy Management")}
        ${programCard("Tasks", percentOf(stats.tasksDone, state.tasks.length), `${stats.tasksDone} erledigt`, `${state.tasks.length} total`, "tasks", "Task Management")}
      </div>
    </section>
  `;
}

function renderDashboardTodayFocus(stats = dashboardStats()) {
  const todoItems = customerTodoItems(stats);
  const next = todoItems[0] || {
    title: "Keine dringende Aufgabe",
    meta: "Aktuellen Projektstand pflegen und neue Nachweise bei Bedarf einreichen.",
    view: "guided",
    action: "Kundenmodus öffnen",
    status: "Bereit"
  };
  const reviewMetrics = reviewCenterMetrics(reviewCenterItems());
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const overdueTasks = state.tasks.filter((task) => task.status !== "Erledigt" && task.due && task.due < today()).length;
  const rework = todoItems.filter((item) => ["rework", "onboarding-rework"].includes(item.kind) || item.category === "Nacharbeit").length;
  const nextAttrs = dashboardStartJumpAttrs(next.view || "guided", next.scrollTarget);

  return `
    <section class="panel dashboard-simple-focus">
      <div class="dashboard-simple-copy">
        <span class="eyebrow">Heute wichtig</span>
        <h3>Erst das Nächste erledigen, dann Details prüfen.</h3>
        <p>Diese Ansicht reduziert den Arbeitstag auf wenige Entscheidungen: Was muss der Kunde jetzt tun, was wartet auf Beraterprüfung und was blockiert gerade?</p>
      </div>
      <article class="dashboard-simple-primary">
        <span>${escapeHtml(next.category || "Nächster Schritt")}</span>
        <strong>${escapeHtml(next.title)}</strong>
        <p>${escapeHtml(next.meta || "Bitte den nächsten offenen Punkt bearbeiten.")}</p>
        <div class="dashboard-simple-actions">
          ${statusTag(next.status || "Offen")}
          <button class="primary-button" type="button" ${nextAttrs}>${escapeHtml(next.action || "Jetzt weitermachen")}</button>
        </div>
      </article>
      <div class="dashboard-simple-grid">
        ${renderDashboardSimpleMiniCard("Nacharbeit", rework, "zuerst klären", rework ? "warning" : "done", "guided")}
        ${renderDashboardSimpleMiniCard("Überfällig", overdueTasks, "Aufgaben", overdueTasks ? "warning" : "done", "tasks")}
        ${renderDashboardSimpleMiniCard("Wartet", reviewMetrics.submitted + reviewMetrics.inReview, "Beraterprüfung", reviewMetrics.submitted + reviewMetrics.inReview ? "active" : "done", canAccessView("review") ? "review" : "guided")}
        ${renderDashboardSimpleMiniCard("Nachweise", docMetrics.missing, "formal offen", docMetrics.missing ? "warning" : "done", "documents")}
      </div>
    </section>
  `;
}

function renderDashboardProjectStartFocus(stats = dashboardStats()) {
  const onboarding = normalizeOnboarding(state.onboarding);
  const projectReady = onboardingProjectSetupReady(onboarding.project);
  const completed = Boolean(onboarding.completed);
  const draftCount = onboardingTemplateDrafts(onboarding).length;
  const evidenceCount = Math.max(0, state.documents.length - SOURCE_FILES.length);
  const projectMissing = projectSetupMissingFields(normalizeProjectSetup(onboarding.project, onboarding.answers)).length;
  const nextTitle = !projectReady
    ? "Grundprojekt anlegen"
    : !completed
      ? "Startprofil ausfüllen"
      : draftCount
        ? "Arbeitsvorlagen prüfen"
        : "Kundenarbeitsplatz fortführen";
  const nextText = !projectReady
    ? `${projectMissing} Pflichtfeld(er) im Projektrahmen offen.`
    : !completed
      ? "Startfragen beantworten, damit erste Assets, Nachweise und Aufgaben entstehen."
      : `${draftCount} Arbeitsvorlage(n) und ${evidenceCount} Nachweisverweis(e) vorhanden.`;

  return `
    <section class="panel dashboard-project-focus">
      <div class="dashboard-simple-copy">
        <span class="eyebrow">Projektstart</span>
        <h3>Vom Grundprojekt zur prüfbaren Übergabe</h3>
        <p>Kunden sollen nicht überlegen müssen, wo sie anfangen. Die Strecke bleibt einfach: Rahmen anlegen, Startprofil ausfüllen, Nachweise vorbereiten und an den Berater übergeben.</p>
      </div>
      <div class="dashboard-project-steps">
        ${renderDashboardProjectStep("01", "Grundprojekt", projectReady ? "fertig" : "offen", projectReady ? "Projektrahmen ist angelegt." : "Organisation, Ansprechpartner und Zielrahmen ergänzen.", projectReady ? "done" : "active")}
        ${renderDashboardProjectStep("02", "Startprofil", completed ? "fertig" : "offen", completed ? "Startfragen sind gespeichert." : "Kundendaten und Ausgangslage erfassen.", completed ? "done" : projectReady ? "active" : "locked")}
        ${renderDashboardProjectStep("03", "Arbeitsvorlagen", draftCount ? `${draftCount} Vorlage(n)` : "vorbereiten", "Vorlagen, Dokumentverweise und erste Aufgaben bündeln.", draftCount ? "active" : completed ? "active" : "locked")}
        ${renderDashboardProjectStep("04", "Beraterprüfung", "fachlich", "Freigabe und Bewertung bleiben beim Berater/Admin.", "review")}
      </div>
      <article class="dashboard-project-next">
        <span>Nächster Projektschritt</span>
        <strong>${escapeHtml(nextTitle)}</strong>
        <p>${escapeHtml(nextText)}</p>
        <button class="primary-button" type="button" data-jump-section="dashboard:customerOnboarding">${escapeHtml(nextTitle)}</button>
      </article>
    </section>
  `;
}

function dashboardProjectStartNeedsAttention() {
  const onboarding = normalizeOnboarding(state.onboarding);
  return !onboardingProjectSetupReady(onboarding.project) || !onboarding.completed;
}

function renderDashboardSimpleMiniCard(title, value, label, tone, view) {
  return `
    <button class="dashboard-simple-mini ${escapeHtml(tone || "")}" type="button" data-jump="${escapeHtml(view || "dashboard")}">
      <span>${escapeHtml(title)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(label)}</small>
    </button>
  `;
}

function renderDashboardProjectStep(number, title, stateLabel, text, tone) {
  return `
    <div class="dashboard-project-step ${escapeHtml(tone || "")}">
      <span>${escapeHtml(number)}</span>
      <strong>${escapeHtml(title)}</strong>
      <small>${escapeHtml(stateLabel)}</small>
      <p>${escapeHtml(text)}</p>
    </div>
  `;
}

function renderDashboardControlFocus(stats = dashboardStats()) {
  const review = managementReviewData(stats);
  const packageData = auditPackageReportData();
  const gate = packageData.gate || { blockers: [], consultantApproved: false };
  const packageApproved = Boolean(packageData.packageApproval);
  const overdueTasks = state.tasks.filter((task) => task.status !== "Erledigt" && task.due && task.due < today()).length;
  const reviewOpen = packageData.reviewMetrics.submitted + packageData.reviewMetrics.inReview;
  const primaryTitle = review.blockers
    ? "Blocker fachlich klären"
    : review.decisions.length
      ? "Management-Entscheidungen prüfen"
      : "Review-Paket vorbereiten";
  const primaryText = review.blockers
    ? `${review.blockers} formale Blocker vor der Beraterfreigabe bearbeiten.`
    : review.decisions.length
      ? `${review.decisions.length} Entscheidungspunkt(e) für Leitung oder Berater/Admin sichtbar.`
      : "Keine akuten Management-Blocker erkannt. Trotzdem vor Export fachlich prüfen lassen.";

  return `
    <section class="panel dashboard-control-focus">
      <div class="dashboard-simple-copy">
        <span class="eyebrow">Steuerung</span>
        <h3>Management sieht nur, was wirklich entscheidungsrelevant ist.</h3>
        <p>Diese Sicht bündelt Review-Reife, offene Blocker, Entscheidungen und Beraterprüfung. Sie zeigt nur formale Vorbereitung und ersetzt keine fachliche Freigabe.</p>
      </div>
      <article class="dashboard-simple-primary ${review.blockers ? "warning" : "active"}">
        <span>Management-Fokus</span>
        <strong>${escapeHtml(primaryTitle)}</strong>
        <p>${escapeHtml(primaryText)}</p>
        <div class="dashboard-simple-actions">
          ${statusTag(packageApproved ? "Freigegeben" : gate.consultantApproved ? "Freigabe offen" : review.blockers ? "Blockiert" : "Vorbereitet")}
          <button class="primary-button" type="button" data-jump="${canAccessView("review") ? "review" : "auditpackage"}">${canAccessView("review") ? "Beraterprüfung öffnen" : "Auditpaket öffnen"}</button>
          <button class="quiet-button" type="button" data-jump="tasks">Aufgaben</button>
        </div>
      </article>
      <div class="dashboard-simple-grid">
        ${renderDashboardSimpleMiniCard("Readiness", `${review.readiness}%`, "formal", review.readiness >= 80 ? "done" : "active", "auditpackage")}
        ${renderDashboardSimpleMiniCard("Blocker", gate.blockers.length, "Auditpaket", gate.blockers.length ? "warning" : "done", "auditpackage")}
        ${renderDashboardSimpleMiniCard("Entscheidungen", review.decisions.length, "Management", review.decisions.length ? "active" : "done", "tasks")}
        ${renderDashboardSimpleMiniCard("Überfällig", overdueTasks, "Aufgaben", overdueTasks ? "warning" : "done", "tasks")}
        ${renderDashboardSimpleMiniCard("In Prüfung", reviewOpen, "Berater", reviewOpen ? "active" : "done", canAccessView("review") ? "review" : "guided")}
        ${renderDashboardSimpleMiniCard("Top-Risiken", review.highRisks.length, "offen", review.highRisks.length ? "warning" : "done", "risks")}
      </div>
    </section>
  `;
}

function renderDashboardEvidenceFocus(stats = dashboardStats()) {
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const evidenceRows = evidenceMappingRows(documents);
  const missingEvidence = evidenceRows.filter((row) => row.status === "Fehlt").length;
  const moduleOpen = stats.modules.reduce((sum, module) => sum + Math.max((module.total || 0) - (module.done || 0), 0), 0);
  const uploadAllowed = canEditWorkspace();
  const primaryTitle = missingEvidence
    ? "Nachweise vervollständigen"
    : docMetrics.inReview
      ? "Eingereichte Nachweise verfolgen"
      : "Nachweise und Betrieb aktuell halten";
  const primaryText = missingEvidence
    ? `${missingEvidence} Nachweiszuordnung(en) fehlen formal.`
    : docMetrics.inReview
      ? `${docMetrics.inReview} Nachweis(e) warten auf Prüfung.`
      : `${documents.length} Kundennachweis(e) im Arbeitsbereich.`;

  return `
    <section class="panel dashboard-evidence-focus">
      <div class="dashboard-simple-copy">
        <span class="eyebrow">Nachweise und Betrieb</span>
        <h3>Erfassen, zuordnen, einreichen, prüfen lassen.</h3>
        <p>Die Plattform sammelt Dateien, Registerdaten und operative Hinweise. Sie zeigt, ob formal etwas fehlt, aber bewertet Nachweise nicht automatisch als ausreichend.</p>
      </div>
      <article class="dashboard-simple-primary ${missingEvidence || docMetrics.missing ? "warning" : "active"}">
        <span>Nachweis-Fokus</span>
        <strong>${escapeHtml(primaryTitle)}</strong>
        <p>${escapeHtml(primaryText)}</p>
        <div class="dashboard-simple-actions">
          ${statusTag(missingEvidence || docMetrics.missing ? "Nachweis fehlt" : docMetrics.inReview ? "In Prüfung" : "Vorbereitet")}
          <button class="primary-button" type="button" data-jump="documents">${uploadAllowed ? "Nachweis hinzufügen" : "Nachweise ansehen"}</button>
          <button class="quiet-button" type="button" data-jump="integrations">Integrationen</button>
        </div>
      </article>
      <div class="dashboard-simple-grid">
        ${renderDashboardSimpleMiniCard("Nachweise", documents.length, "erfasst", documents.length ? "active" : "warning", "documents")}
        ${renderDashboardSimpleMiniCard("Metadaten", docMetrics.missing, "formal offen", docMetrics.missing ? "warning" : "done", "documents")}
        ${renderDashboardSimpleMiniCard("In Prüfung", docMetrics.inReview, "Nachweise", docMetrics.inReview ? "active" : "done", "documents")}
        ${renderDashboardSimpleMiniCard("Freigegeben", docMetrics.approved, "durch Review", docMetrics.approved ? "done" : "active", "documents")}
        ${renderDashboardSimpleMiniCard("Module", moduleOpen, "offene Einträge", moduleOpen ? "active" : "done", "dashboard")}
        ${renderDashboardSimpleMiniCard("APIs", `${stats.integrationsActive}/${state.integrations.length}`, "aktiv", stats.integrationsActive ? "done" : "active", "integrations")}
      </div>
    </section>
  `;
}

function renderDashboardStartCenter(stats = dashboardStats()) {
  const todoItems = customerTodoItems(stats);
  const next = todoItems[0] || {
    title: "Kundenmodus fortführen",
    meta: "Keine akute Rückgabe. Nächste Eingaben und Nachweise strukturiert weiterbearbeiten.",
    view: "guided",
    action: "Kundenmodus öffnen",
    status: "Bereit"
  };
  const data = auditPackageReportData();
  const reviewMetrics = data.reviewMetrics || reviewCenterMetrics(data.reviewItems || []);
  const docMetrics = data.docMetrics || documentWorkflowMetrics(state.documents);
  const gate = data.gate || { blockers: [], consultantApproved: false };
  const packageApproved = Boolean(data.packageApproval);
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt").length;
  const reworkTasks = todoItems.filter((item) => ["rework", "onboarding-rework"].includes(item.kind) || item.category === "Nacharbeit").length;
  const nextActionAttrs = dashboardStartJumpAttrs(next.view || "guided", next.scrollTarget);
  const nextStatus = next.status || "Offen";
  const reviewOpen = reviewMetrics.submitted + reviewMetrics.inReview;
  const evidenceMissing = docMetrics.missing || 0;
  const evidenceInReview = docMetrics.inReview || 0;
  const auditLabel = packageApproved
    ? "Beraterfreigegeben"
    : gate.consultantApproved
      ? "Freigabe fehlt"
      : `${gate.blockers.length} Blocker`;

  return `
    <section class="panel dashboard-start-center" aria-label="Dashboard Start-Zentrale">
      <div class="dashboard-start-lead">
        <span class="eyebrow">Start-Zentrale</span>
        <h3>Heute zuerst</h3>
        <p>Eine einfache Einstiegssicht für Kunden und Berater: offene Aufgaben, eingereichte Punkte, Nachweise und Auditpaket-Blocker ohne unnötige Fachsprache.</p>
        <div class="dashboard-start-note">
          <strong>Wichtig:</strong>
          <span>Die Plattform zeigt formale Vorbereitung. Fachliche Freigabe und Auditentscheidung bleiben beim Berater/Admin.</span>
        </div>
      </div>

      <article class="dashboard-start-next">
        <div>
          <span class="dashboard-start-pill">${escapeHtml(next.category || "Nächster Schritt")}</span>
          <h4>${escapeHtml(next.title)}</h4>
          <p>${escapeHtml(next.meta || "Bitte den nächsten offenen Punkt bearbeiten.")}</p>
        </div>
        <div class="dashboard-start-next-actions">
          ${statusTag(nextStatus)}
          <button class="primary-button" type="button" ${nextActionAttrs}>${escapeHtml(next.action || "Jetzt weitermachen")}</button>
          <button class="quiet-button" type="button" data-jump="guided">Kundenmodus</button>
        </div>
      </article>

      <div class="dashboard-start-status-grid">
        ${renderDashboardStartStatusCard({
          title: "Heute erledigen",
          value: openTasks,
          label: "offen",
          text: reworkTasks ? `${reworkTasks} Nacharbeit(en) zuerst klären.` : "Nächste Kundenaufgaben strukturiert abarbeiten.",
          view: "tasks",
          tone: openTasks ? "active" : "done"
        })}
        ${renderDashboardStartStatusCard({
          title: "Beraterprüfung",
          value: reviewOpen,
          label: "wartet",
          text: `${reviewMetrics.returns} Rückgabe(n), ${reviewMetrics.approved} freigegeben.`,
          view: canAccessView("review") ? "review" : "guided",
          tone: reviewMetrics.returns ? "warning" : reviewOpen ? "active" : "done"
        })}
        ${renderDashboardStartStatusCard({
          title: "Nachweise",
          value: evidenceMissing,
          label: "formal offen",
          text: `${evidenceInReview} Nachweis(e) in Prüfung, ${docMetrics.approved || 0} freigegeben.`,
          view: "documents",
          tone: evidenceMissing ? "warning" : evidenceInReview ? "active" : "done"
        })}
        ${renderDashboardStartStatusCard({
          title: "Auditpaket",
          value: auditLabel,
          label: packageApproved ? "exportbereit" : "nicht final",
          text: packageApproved ? "Aktueller Paketstand wurde durch Berater/Admin freigegeben." : "Vorbereitet, aber noch nicht automatisch auditbereit.",
          view: "auditpackage",
          tone: packageApproved ? "done" : gate.blockers.length ? "warning" : "active"
        })}
      </div>
    </section>
  `;
}

function dashboardStartJumpAttrs(view = "dashboard", sectionId = "") {
  if (sectionId) return `data-jump-section="${escapeHtml(view)}:${escapeHtml(sectionId)}"`;
  return `data-jump="${escapeHtml(view)}"`;
}

function renderDashboardStartStatusCard({ title, value, label, text, view, sectionId, tone = "neutral" }) {
  return `
    <button class="dashboard-start-status-card ${escapeHtml(tone)}" type="button" ${dashboardStartJumpAttrs(view, sectionId)}>
      <span>${escapeHtml(title)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(label)}</small>
      <p>${escapeHtml(text)}</p>
    </button>
  `;
}

function renderDemoModePanel(stats = dashboardStats()) {
  const active = demoWorkspaceActive();
  const count = demoCollectionCount();
  const loadedAt = state.demo?.loadedAt ? formatBackendTime(state.demo.loadedAt) : "";
  return `
    <section class="demo-mode-panel ${active ? "active" : ""}">
      <div class="demo-mode-copy">
        <span class="eyebrow">${active ? "Vorführmodus aktiv" : "Kollegenvorstellung vorbereiten"}</span>
        <h3>${active ? "Demo-Arbeitsstand ist geladen" : "Beispieldaten laden, damit die Plattform nicht leer wirkt"}</h3>
        <p>${active
          ? "Die Beispielwerte zeigen Assets, Risiken, Nachweise, Policies, Lieferanten und Review-Fälle. Sie sind markiert und ersetzen keine fachliche Beraterbewertung."
          : "Für kurze Präsentationen kannst du markierte Beispieldaten ergänzen. Bestehende Kundendaten bleiben erhalten und die Demo-Einträge lassen sich wieder entfernen."}</p>
      </div>
      <div class="demo-mode-metrics">
        <span><strong>${active ? count : `${stats.progress.percent}%`}</strong><small>${active ? "Demo-Einträge" : "aktueller Projektstand"}</small></span>
        <span><strong>${state.documents.filter((document) => document.status !== "Quelle").length}</strong><small>Nachweise</small></span>
        <span><strong>${state.risks.length}</strong><small>Risiken</small></span>
      </div>
      <div class="demo-mode-actions">
        ${active && loadedAt ? `<small>Geladen: ${escapeHtml(loadedAt)}</small>` : `<small>Empfohlen vor internen Demos oder Screen-Sharing.</small>`}
        <button class="primary-button" type="button" data-demo-load ${canEditWorkspace() ? "" : "disabled"}>${active ? "Demo aktualisieren" : "Vorführdaten laden"}</button>
        ${active ? `<button class="quiet-button danger-button" type="button" data-demo-remove ${canEditWorkspace() ? "" : "disabled"}>Demo entfernen</button>` : `<button class="quiet-button" type="button" data-jump="guided">Kundenmodus ansehen</button>`}
      </div>
    </section>
  `;
}

function renderPresentationQuickGuide(stats = dashboardStats(), reviewMetrics = reviewCenterMetrics(reviewCenterItems())) {
  const evidenceCount = state.documents.filter((document) => document.status !== "Quelle").length;
  const steps = [
    {
      number: "01",
      title: "Dashboard zeigen",
      text: "Gesamtstatus, offene Aufgaben und formale Lücken zuerst erklären.",
      meta: `${stats.progress.percent}% Vorbereitungsstand`,
      action: "Dashboard",
      view: "dashboard",
      section: "dashboard-overview"
    },
    {
      number: "02",
      title: "Kundenmodus öffnen",
      text: "In einfacher Sprache zeigen, was der Kunde als Nächstes ausfüllen soll.",
      meta: `${state.tasks.filter((task) => task.status !== "Erledigt").length} offene Aufgabe(n)`,
      action: "Kundenmodus",
      view: "guided"
    },
    {
      number: "03",
      title: "Beraterprüfung erklären",
      text: "Einreichungen, Nacharbeit und Freigaben bleiben fachlich beim Berater/Admin.",
      meta: `${reviewMetrics.submitted + reviewMetrics.inReview} Punkt(e) in Prüfung`,
      action: "Review Center",
      view: "review"
    },
    {
      number: "04",
      title: "Auditpaket einordnen",
      text: "Das Paket wird vorbereitet, aber erst nach Beraterfreigabe exportreif.",
      meta: `${evidenceCount} Nachweis(e) im System`,
      action: "Auditpaket",
      view: "dashboard",
      section: "dashboard-evidence"
    }
  ];

  return `
    <section class="presentation-guide" aria-label="Demo-Kompass">
      <div class="presentation-guide-intro">
        <span class="eyebrow">Demo-Kompass</span>
        <h3>In vier Schritten professionell vorstellen</h3>
        <p>Diese Reihenfolge hilft bei internen Demos: erst Orientierung, dann Kundensicht, danach Beraterprüfung und zum Schluss das Auditpaket. Die Plattform zeigt Vorbereitung und formale Lücken, keine automatische Auditbereitschaft.</p>
      </div>
      <div class="presentation-guide-steps">
        ${steps.map((step) => `
          <article class="presentation-guide-step">
            <span class="presentation-guide-number">${escapeHtml(step.number)}</span>
            <div>
              <h4>${escapeHtml(step.title)}</h4>
              <p>${escapeHtml(step.text)}</p>
              <small>${escapeHtml(step.meta)}</small>
            </div>
            <button class="quiet-button" type="button" data-jump="${escapeHtml(step.view)}" ${step.section ? `data-jump-section="${escapeHtml(step.section)}"` : ""}>${escapeHtml(step.action)}</button>
          </article>
        `).join("")}
      </div>
      <div class="presentation-guide-note">
        <strong>Vorführsatz:</strong>
        <span>“SFM Compliance sammelt strukturiert Informationen und Nachweise. Die finale Bewertung und Freigabe macht weiterhin der Berater.”</span>
      </div>
    </section>
  `;
}

