function renderPresentationReadinessChecklist(stats = dashboardStats(), reviewMetrics = reviewCenterMetrics(reviewCenterItems())) {
  const demoActive = demoWorkspaceActive();
  const evidenceCount = state.documents.filter((document) => document.status !== "Quelle").length;
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt").length;
  const hasRegisters = state.assets.length > 0 || state.risks.length > 0 || state.suppliers.length > 0;
  const reviewOpen = reviewMetrics.submitted + reviewMetrics.inReview + reviewMetrics.rework;
  const checks = [
    {
      title: "Vorführdaten",
      text: demoActive ? "Beispieldaten sind geladen und markiert." : "Optional Vorführdaten laden, falls das Projekt leer wirkt.",
      status: demoActive ? "bereit" : "optional",
      tone: demoActive ? "good" : "neutral"
    },
    {
      title: "Kundenweg",
      text: openTasks > 0 ? "Es gibt sichtbare Aufgaben und nächste Schritte." : "Für die Demo können Beispielaufgaben helfen.",
      status: openTasks > 0 ? "sichtbar" : "prüfen",
      tone: openTasks > 0 ? "good" : "warn"
    },
    {
      title: "Nachweise",
      text: evidenceCount > 0 ? "Nachweise sind im System sichtbar." : "Noch keine Kundennachweise vorhanden.",
      status: evidenceCount > 0 ? `${evidenceCount}` : "leer",
      tone: evidenceCount > 0 ? "good" : "warn"
    },
    {
      title: "Register",
      text: hasRegisters ? "Assets, Risiken oder Lieferanten können gezeigt werden." : "Register wirken leer, wenn keine Beispiele vorhanden sind.",
      status: hasRegisters ? "vorhanden" : "leer",
      tone: hasRegisters ? "good" : "warn"
    },
    {
      title: "Beraterprüfung",
      text: reviewOpen > 0 ? "Review-Fälle zeigen die Trennung zwischen Kunde und Berater." : "Für die Demo kann ein Review-Fall sinnvoll sein.",
      status: reviewOpen > 0 ? `${reviewOpen}` : "prüfen",
      tone: reviewOpen > 0 ? "good" : "neutral"
    },
    {
      title: "Sichere Aussage",
      text: "Keine automatische ISO-Konformität, NIS-2-Erfüllung oder Auditbereitschaft behaupten.",
      status: "gesetzt",
      tone: "good"
    }
  ];

  return `
    <details class="presentation-readiness">
      <summary>
        <span>
          <strong>Vorführ-Checkliste</strong>
          <small>Schneller Qualitätscheck vor Kollegenvorstellung oder Kundentermin.</small>
        </span>
        <em>prüfen</em>
      </summary>
      <div class="presentation-readiness-grid">
        ${checks.map((check) => `
          <article class="presentation-readiness-item ${escapeHtml(check.tone)}">
            <span>${escapeHtml(check.status)}</span>
            <h4>${escapeHtml(check.title)}</h4>
            <p>${escapeHtml(check.text)}</p>
          </article>
        `).join("")}
      </div>
      <div class="presentation-readiness-actions">
        <button class="quiet-button" type="button" data-demo-load ${canEditWorkspace() ? "" : "disabled"}>Vorführdaten laden</button>
        <button class="quiet-button" type="button" data-jump="guided">Kundenweg zeigen</button>
        <button class="quiet-button" type="button" data-jump="review">Beraterprüfung zeigen</button>
      </div>
    </details>
  `;
}

