function renderCustomerOnboardingWizard(stats) {
  const onboarding = normalizeOnboarding(state.onboarding);
  const projectReady = onboardingProjectSetupReady(onboarding.project);
  const answered = CUSTOMER_ONBOARDING_FIELDS.filter((field) => String(onboarding.answers[field.id] || "").trim()).length;
  const progress = percentOf(answered, CUSTOMER_ONBOARDING_FIELDS.length);
  const completed = onboarding.completed;
  const assets = splitAnswerList(onboarding.answers.criticalAssets || onboarding.answers.scopeSummary).slice(0, 4);
  const evidence = splitAnswerList(onboarding.answers.existingEvidence).slice(0, 4);
  return `
    <section class="panel customer-onboarding" id="customerOnboarding">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Startprofil</span>
          <h3>${!projectReady ? "Grundprojekt anlegen" : completed ? "Startprofil ist angelegt" : "Startfragen für ein sauberes Projektprofil"}</h3>
          <p>${!projectReady
            ? "Lege zuerst den einfachen Projektrahmen an. Danach folgen Startprofil, Assets, Risiken, Nachweise und Beraterprüfung."
            : completed
            ? "Die wichtigsten Kundenangaben sind gespeichert und können jederzeit nachgeschärft werden."
            : "Aus diesen Angaben erstellt SFM Compliance erste Assets, Lieferanten, Nachweisverweise, Aufgaben und einen ersten Arbeitsstand."}</p>
        </div>
        <div class="onboarding-score">
          <strong>${progress}%</strong>
          <span>${answered}/${CUSTOMER_ONBOARDING_FIELDS.length} beantwortet</span>
        </div>
      </div>

      ${renderProjectSetupPanel(onboarding)}

      ${!projectReady ? renderProjectSetupNextNotice() : completed ? `
        <div class="onboarding-summary-grid">
          ${onboardingSummaryCard("Organisation", onboarding.answers.organizationName || "Noch offen", onboarding.answers.mainContact || "Ansprechpartner offen")}
          ${onboardingSummaryCard("Projektziel", onboarding.answers.projectGoal || "Noch offen", onboarding.answers.firstPriority || "Priorität offen")}
          ${onboardingSummaryCard("Assets", assets.length ? assets.join(", ") : "Noch keine Assets genannt", `${state.assets.length} im Register`)}
          ${onboardingSummaryCard("Nachweise", evidence.length ? evidence.join(", ") : "Noch keine Nachweise genannt", `${Math.max(0, state.documents.length - SOURCE_FILES.length)} Dokumentverweis`)}
        </div>
        ${renderOnboardingStartPackage(onboarding)}
        ${renderOnboardingCustomerReviewStatus(onboarding)}
        ${renderOnboardingReviewCenter(onboarding)}
        <div class="onboarding-actions">
          <button class="primary-button" type="button" data-onboarding-edit>Startprofil aktualisieren</button>
          <button class="quiet-button" type="button" data-onboarding-apply>Arbeitsvorlagen aktualisieren</button>
          <button class="quiet-button" type="button" data-jump="project">Projektplan öffnen</button>
          <button class="quiet-button" type="button" data-jump="documents">Nachweise öffnen</button>
        </div>
      ` : `
        <form class="customer-onboarding-form" data-onboarding-wizard>
          <div class="onboarding-question-grid">
            ${CUSTOMER_ONBOARDING_FIELDS.map((field) => renderOnboardingField(field, onboarding.answers[field.id])).join("")}
          </div>
          <div class="onboarding-actions">
            <button class="primary-button" type="submit">Startprofil speichern und Arbeitsvorlagen erstellen</button>
            <button class="quiet-button" type="button" data-jump="templates">Arbeitsvorlagen ansehen</button>
            <span>Bestehende Einträge werden nicht doppelt angelegt.</span>
          </div>
        </form>
      `}
    </section>
  `;
}

function renderProjectSetupPanel(onboarding) {
  const project = normalizeProjectSetup(onboarding.project, onboarding.answers);
  const ready = onboardingProjectSetupReady(project);
  const missing = projectSetupMissingFields(project);
  if (!ready) {
    return `
      <div class="project-setup-card">
        <div class="project-setup-head">
          <div>
            <span class="eyebrow">Schritt 1</span>
            <h4>Grundprojekt anlegen</h4>
            <p>Diese Angaben schaffen nur den Projektrahmen. Die spätere fachliche Bewertung und Freigabe bleibt beim Berater/Admin.</p>
          </div>
          <span class="tag warning">${missing.length ? `${missing.length} Pflichtfeld(er) offen` : "Bereit zum Speichern"}</span>
        </div>
        <form class="project-setup-form" data-project-setup-form>
          <div class="project-setup-grid">
            ${PROJECT_SETUP_FIELDS.map((field) => renderProjectSetupField(field, project[field.id])).join("")}
          </div>
          <div class="project-setup-actions">
            <button class="primary-button" type="submit">Grundprojekt speichern</button>
            <span>Danach wird die Startstrecke freigeschaltet: Startprofil, Assets, Risiken, Nachweise und Review.</span>
          </div>
        </form>
      </div>
    `;
  }

  return `
    <div class="project-setup-summary">
      <div class="project-setup-summary-main">
        <span class="eyebrow">Grundprojekt angelegt</span>
        <h4>${escapeHtml(project.organizationName || "Kundenprojekt")}</h4>
        <p>${escapeHtml(project.projectIntent || "Projektziel kann im Startprofil weiter geschärft werden.")}</p>
      </div>
      <div class="project-setup-summary-grid">
        ${onboardingSummaryCard("Projektmodus", project.projectMode || "Noch offen", "ISO und NIS-2 bleiben fachlich getrennt")}
        ${onboardingSummaryCard("Ansprechpartner", project.mainContact || "Noch offen", project.consultantOwner || "Berater/Admin prüft final")}
        ${onboardingSummaryCard("Kontext", project.industry || "Noch offen", project.companySize || "Größe offen")}
        ${onboardingSummaryCard("Zeitrahmen", project.targetDate || "Zieltermin offen", project.startDate ? `Start: ${project.startDate}` : "Start offen")}
      </div>
      <div class="project-setup-actions">
        <button class="quiet-button" type="button" data-project-setup-edit>Grundprojekt bearbeiten</button>
        <button class="primary-button" type="button" data-jump-section="dashboard:customerOnboarding">${onboarding.completed ? "Startprofil prüfen" : "Startprofil ausfüllen"}</button>
      </div>
    </div>
  `;
}

function renderProjectSetupNextNotice() {
  return `
    <div class="project-setup-next">
      <strong>Als Nächstes:</strong>
      <span>Nach dem Speichern beantwortet der Kunde die Startfragen. Daraus entstehen erst dann Arbeitsvorlagen, Dokumentverweise und erste Aufgaben.</span>
    </div>
  `;
}

function renderProjectSetupField(field, value = "") {
  const required = field.required ? "required" : "";
  const common = `name="${escapeHtml(field.id)}" ${required}`;
  const wide = field.type === "textarea" || field.id === "projectIntent" ? "wide" : "";
  const help = [field.help, field.example ? `Beispiel: ${field.example}` : ""].filter(Boolean).join(" ");
  const helper = help ? `<small>${escapeHtml(help)}</small>` : "";
  if (field.type === "textarea") {
    return `
      <label class="question-card project-setup-field ${wide}">
        <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
        <textarea ${common} placeholder="${escapeHtml(field.placeholder || "")}">${escapeHtml(value)}</textarea>
        ${helper}
      </label>
    `;
  }
  if (field.type === "select") {
    return `
      <label class="question-card project-setup-field ${wide}">
        <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
        <select ${common}>
          ${(field.options || []).map((option) => `<option value="${escapeHtml(option)}" ${value === option ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
        </select>
        ${helper}
      </label>
    `;
  }
  return `
    <label class="question-card project-setup-field ${wide}">
      <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
      <input ${common} type="${field.type === "date" ? "date" : "text"}" value="${escapeHtml(value)}" placeholder="${escapeHtml(field.placeholder || "")}" />
      ${helper}
    </label>
  `;
}

function renderOnboardingCustomerReviewStatus(onboarding) {
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    document: findDocumentForTemplateDraft(draft, draft.title),
    quality: onboardingDraftQuality(draft)
  }));
  const activeRows = rows.filter((row) => onboardingDraftInReview(row.draft, row.document)
    || onboardingDraftApproved(row.draft, row.document)
    || onboardingDraftNeedsRework(row.draft, row.document));
  if (!activeRows.length) return "";
  const inReview = activeRows.filter((row) => onboardingDraftInReview(row.draft, row.document)).length;
  const approved = activeRows.filter((row) => onboardingDraftApproved(row.draft, row.document)).length;
  const reworkRows = activeRows.filter((row) => onboardingDraftNeedsRework(row.draft, row.document));
  const reworkBlockers = reworkRows.filter((row) => row.quality.requiredMissing.length).length;
  return `
    <div class="onboarding-customer-status">
      <div class="onboarding-customer-status-head">
        <div>
          <strong>Prüfstatus Arbeitsvorlagen</strong>
          <span>Hier sieht der Kunde, was eingereicht, freigegeben oder zur Nachbesserung zurückgegeben wurde.</span>
        </div>
        <button class="primary-button" type="button" data-onboarding-resubmit-rework ${reworkRows.length && !reworkBlockers && canSubmitDocuments() ? "" : "disabled"}>Nachbesserungen erneut einreichen</button>
      </div>
      <div class="onboarding-customer-status-summary">
        <div><strong>${inReview}</strong><span>In Prüfung</span></div>
        <div><strong>${approved}</strong><span>Freigegeben</span></div>
        <div class="${reworkRows.length ? "warning" : ""}"><strong>${reworkRows.length}</strong><span>Nachbesserung</span></div>
        <div class="${reworkBlockers ? "warning" : ""}"><strong>${reworkBlockers}</strong><span>Pflichtfelder</span></div>
      </div>
      <div class="onboarding-customer-status-list">
        ${activeRows.map((row) => renderOnboardingCustomerReviewItem(row.draft, row.document, row.quality)).join("")}
      </div>
      ${renderOnboardingAcceptancePanel(rows)}
      ${renderOnboardingImplementationPlanPanel(rows)}
      ${renderOnboardingActivityTimeline(activeRows)}
    </div>
  `;
}

function renderOnboardingCustomerReviewItem(draft, document, quality) {
  const approved = onboardingDraftApproved(draft, document);
  const rework = onboardingDraftNeedsRework(draft, document);
  const inReview = onboardingDraftInReview(draft, document);
  const status = approved ? "Freigegeben" : rework ? "Überarbeiten" : inReview ? "In Prüfung" : draft.status || "Entwurf";
  const note = rework
    ? (draft.reworkReason || document?.reworkReason || "Bitte Entwurf fachlich nachbessern und erneut einreichen.")
    : approved
      ? `Freigegeben${draft.approvedAt || document?.approvedAt ? ` am ${draft.approvedAt || document?.approvedAt}` : ""}.`
      : "Wartet auf Prüfung durch Berater/Manager.";
  return `
    <article class="onboarding-customer-status-item">
      <div class="onboarding-customer-status-copy">
        <small>${escapeHtml(draft.templateTitle || draft.area || "Template")}</small>
        <strong>${escapeHtml(draft.title || "Unbenannte Arbeitsvorlage")}</strong>
        <span>${escapeHtml(note)}</span>
      </div>
      <div class="onboarding-customer-status-state">
        ${statusTag(status)}
        <span>${quality.percent}% befüllt</span>
      </div>
      <div class="onboarding-customer-status-actions">
        <button class="quiet-button" type="button" data-open-onboarding-draft="${escapeHtml(draft.id)}">Arbeitsvorlage öffnen</button>
        <button class="quiet-button" type="button" data-template-draft-document="${escapeHtml(draft.id)}">Dokument</button>
        ${rework && canSubmitDocuments() ? `<button class="primary-button" type="button" data-onboarding-resubmit-draft="${escapeHtml(draft.id)}" ${quality.requiredMissing.length ? "disabled" : ""}>Erneut einreichen</button>` : ""}
      </div>
    </article>
  `;
}

function renderOnboardingAcceptancePanel(rows) {
  const total = rows.length;
  const approved = rows.filter((row) => onboardingDraftApproved(row.draft, row.document)).length;
  const inReview = rows.filter((row) => onboardingDraftInReview(row.draft, row.document)).length;
  const rework = rows.filter((row) => onboardingDraftNeedsRework(row.draft, row.document)).length;
  const blockers = rows.filter((row) => row.quality.requiredMissing.length).length;
  const ready = total > 0 && approved === total && !inReview && !rework && !blockers;
  const message = ready
    ? "Alle Arbeitsvorlagen sind freigegeben und können als Projektübergabe dokumentiert werden."
    : "Die Abnahme wird verfügbar, sobald alle Arbeitsvorlagen geprüft und freigegeben sind.";
  return `
    <div class="onboarding-acceptance ${ready ? "ready" : ""}">
      <div class="onboarding-acceptance-copy">
        <small>Projektübergabe</small>
        <strong>${ready ? "Arbeitsvorlagen abnahmebereit" : "Arbeitsvorlagen noch nicht abnahmebereit"}</strong>
        <span>${escapeHtml(message)}</span>
      </div>
      <div class="onboarding-acceptance-metrics">
        <div><strong>${approved}/${total}</strong><span>freigegeben</span></div>
        <div class="${rework ? "warning" : ""}"><strong>${rework}</strong><span>Nachbesserung</span></div>
        <div class="${blockers ? "warning" : ""}"><strong>${blockers}</strong><span>Pflichtfelder</span></div>
      </div>
      <div class="onboarding-acceptance-actions">
        <button class="primary-button" type="button" data-onboarding-acceptance-report ${ready ? "" : "disabled"}>Abnahmeprotokoll exportieren</button>
        <button class="quiet-button" type="button" data-onboarding-implementation-pack ${ready && canEditWorkspace() ? "" : "disabled"}>Folgeaufgaben anlegen</button>
        <button class="quiet-button" type="button" data-jump="project">Projektplan öffnen</button>
        <button class="quiet-button" type="button" data-jump="documents">Nachweise öffnen</button>
      </div>
    </div>
  `;
}

function renderOnboardingImplementationPlanPanel(rows) {
  const total = rows.length;
  const approved = rows.filter((row) => onboardingDraftApproved(row.draft, row.document)).length;
  const inReview = rows.filter((row) => onboardingDraftInReview(row.draft, row.document)).length;
  const rework = rows.filter((row) => onboardingDraftNeedsRework(row.draft, row.document)).length;
  const blockers = rows.filter((row) => row.quality.requiredMissing.length).length;
  const ready = total > 0 && approved === total && !inReview && !rework && !blockers;
  const tasks = onboardingImplementationTasks();
  if (!ready && !tasks.length) return "";
  const done = tasks.filter((task) => task.status === "Erledigt").length;
  const overdue = tasks.filter((task) => task.status !== "Erledigt" && task.due && task.due < today()).length;
  const evidenceCount = tasks.filter((task) => onboardingImplementationTaskEvidence(task)).length;
  const doneWithoutEvidence = tasks.filter((task) => onboardingImplementationTaskNeedsEvidence(task)).length;
  const progress = percentOf(done, tasks.length);
  return `
    <div class="onboarding-implementation ${tasks.length ? "" : "empty"}">
      <div class="onboarding-implementation-head">
        <div>
          <small>Umsetzungssteuerung</small>
          <strong>${tasks.length ? "Folgeaufgaben aus der Abnahme" : "Folgeaufgaben noch nicht angelegt"}</strong>
          <span>${tasks.length
            ? `${done} von ${tasks.length} Folgeaufgaben erledigt.`
            : "Nach der Abnahme kann SFM Compliance die ersten Umsetzungsaufgaben automatisch erzeugen."}</span>
        </div>
        <div class="onboarding-implementation-progress" aria-label="Umsetzungsfortschritt ${progress}%">
          <span style="width:${progress}%"></span>
        </div>
      </div>
      <div class="onboarding-implementation-summary">
        <div><strong>${tasks.length}</strong><span>Aufgaben</span></div>
        <div><strong>${done}</strong><span>Erledigt</span></div>
        <div class="${overdue ? "warning" : ""}"><strong>${overdue}</strong><span>Überfällig</span></div>
        <div><strong>${evidenceCount}/${tasks.length}</strong><span>Nachweise</span></div>
        <div class="${doneWithoutEvidence ? "warning" : ""}"><strong>${doneWithoutEvidence}</strong><span>Erledigt ohne Nachweis</span></div>
      </div>
      ${tasks.length ? `
        <div class="onboarding-implementation-list">
          ${tasks.slice(0, 5).map(renderOnboardingImplementationTask).join("")}
        </div>
      ` : ""}
      <div class="onboarding-implementation-actions">
        <button class="primary-button" type="button" data-onboarding-implementation-report ${tasks.length ? "" : "disabled"}>Umsetzungsplan exportieren</button>
        <button class="quiet-button" type="button" data-onboarding-implementation-evidence-pack ${doneWithoutEvidence && canSubmitDocuments() ? "" : "disabled"}>Fehlende Nachweise anlegen</button>
        <button class="quiet-button" type="button" data-onboarding-implementation-pack ${ready && canEditWorkspace() ? "" : "disabled"}>${tasks.length ? "Folgeaufgaben ergänzen" : "Folgeaufgaben anlegen"}</button>
        <button class="quiet-button" type="button" data-jump="tasks">Task Management öffnen</button>
      </div>
    </div>
  `;
}

function renderOnboardingImplementationTask(task) {
  const overdue = task.status !== "Erledigt" && task.due && task.due < today();
  const done = task.status === "Erledigt";
  const nextStatus = done ? "Offen" : "Erledigt";
  const evidence = onboardingImplementationTaskEvidence(task);
  const missingEvidence = onboardingImplementationTaskNeedsEvidence(task);
  const evidenceText = evidence
    ? (evidence.status || "angelegt")
    : missingEvidence
      ? "fehlt trotz erledigt"
      : "offen";
  return `
    <article class="onboarding-implementation-task ${overdue ? "overdue" : ""} ${missingEvidence ? "missing-evidence" : ""}">
      <div>
        <strong>${escapeHtml(task.title || "Folgeaufgabe")}</strong>
        <span>${escapeHtml(dueText(task.due, task.module || "Task Management"))} · Owner: ${escapeHtml(task.owner || "offen")} · Nachweis: ${escapeHtml(evidenceText)}</span>
      </div>
      ${statusTag(missingEvidence ? "Nachweis fehlt" : overdue ? "Blockiert" : (task.status || "Offen"))}
      <div class="onboarding-implementation-task-actions">
        <button class="quiet-button" type="button" data-jump="tasks">Öffnen</button>
        <button class="${missingEvidence ? "primary-button" : "quiet-button"}" type="button" data-onboarding-implementation-task-evidence="${escapeHtml(task.id)}" ${canSubmitDocuments() ? "" : "disabled"}>${evidence ? "Nachweis" : "Nachweisverweis"}</button>
        <button class="${done ? "quiet-button" : "primary-button"}" type="button" data-onboarding-implementation-task-status="${escapeHtml(task.id)}" data-task-status="${escapeHtml(nextStatus)}" ${canEditWorkspace() ? "" : "disabled"}>${done ? "Wieder öffnen" : "Erledigt"}</button>
      </div>
    </article>
  `;
}

const ONBOARDING_IMPLEMENTATION_SOURCE = "Arbeitsvorlagen-Übergabe";
const ONBOARDING_IMPLEMENTATION_LEGACY_SOURCE = "Startpaket-Abnahme";

function isOnboardingImplementationTask(task = {}) {
  return [ONBOARDING_IMPLEMENTATION_SOURCE, ONBOARDING_IMPLEMENTATION_LEGACY_SOURCE].includes(task.source);
}

function onboardingImplementationTasks() {
  return (state.tasks || [])
    .filter(isOnboardingImplementationTask)
    .sort((left, right) => {
      const leftDone = left.status === "Erledigt" ? 1 : 0;
      const rightDone = right.status === "Erledigt" ? 1 : 0;
      if (leftDone !== rightDone) return leftDone - rightDone;
      return String(left.due || "9999-12-31").localeCompare(String(right.due || "9999-12-31"));
    });
}

function onboardingImplementationTaskNeedsEvidence(task) {
  return task?.status === "Erledigt" && !onboardingImplementationTaskEvidence(task);
}

function onboardingImplementationTaskEvidence(task) {
  if (!task) return null;
  const keys = [
    task.evidenceDocumentId,
    task.title,
    task.linkedTo,
    task.id
  ].filter(Boolean).map(normalizeImportKey);
  return state.documents.find((document) => {
    const documentKeys = [
      document.id,
      document.name,
      document.linkedTo,
      document.evidenceFor,
      document.implementationTaskId
    ].filter(Boolean).map(normalizeImportKey);
    return documentKeys.some((key) => keys.includes(key));
  }) || null;
}

function renderOnboardingActivityTimeline(rows) {
  const events = onboardingActivityEvents(rows);
  if (!events.length) return "";
  return `
    <div class="onboarding-activity">
      <div class="onboarding-activity-head">
        <strong>Arbeitsvorlagen-Aktivität</strong>
        <span>Letzte Einreichungen, Freigaben und Nachbesserungen.</span>
      </div>
      <div class="onboarding-activity-list">
        ${events.slice(0, 8).map((event) => `
          <div class="onboarding-activity-event">
            <span>${escapeHtml(event.date || "-")}</span>
            <div>
              <strong>${escapeHtml(event.action)}</strong>
              <small>${escapeHtml(event.title)}${event.by ? ` · ${escapeHtml(event.by)}` : ""}</small>
              ${event.note ? `<p>${escapeHtml(event.note)}</p>` : ""}
            </div>
            ${statusTag(event.status || event.action)}
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function onboardingActivityEvents(rows) {
  const events = [];
  const seen = new Set();
  const pushEvent = (event) => {
    if (!event.date) return;
    const normalized = normalizeOnboardingActivityAction(event.action);
    if (!normalized) return;
    const title = event.title || "Arbeitsvorlage";
    const key = normalizeImportKey(`${event.date || ""} ${normalized} ${title}`);
    if (seen.has(key)) return;
    seen.add(key);
    events.push({
      ...event,
      action: normalized,
      title,
      status: event.status || onboardingActivityStatus(normalized)
    });
  };

  rows.forEach(({ draft, document }) => {
    const title = templateDraftDisplayTitle(draft, document?.name || "Arbeitsvorlage");
    pushEvent({
      date: draft.submittedAt,
      action: "Zur Prüfung eingereicht",
      by: draft.submittedBy,
      title,
      note: draft.lastReworkReason ? "Nachbesserung wurde erneut eingereicht." : "",
      status: "In Prüfung"
    });
    pushEvent({
      date: draft.reworkRequestedAt,
      action: "Nachbesserung angefordert",
      by: draft.reworkRequestedBy,
      title,
      note: draft.reworkReason || document?.reworkReason || "",
      status: "Überarbeiten"
    });
    pushEvent({
      date: draft.approvedAt,
      action: "Freigegeben",
      by: draft.approvedBy,
      title,
      note: "",
      status: "Freigegeben"
    });

    (document?.workflowHistory || []).forEach((entry) => {
      pushEvent({
        date: entry.date,
        action: entry.action,
        by: entry.by,
        title,
        note: entry.note,
        status: onboardingActivityStatus(entry.action)
      });
    });
  });

  return events.sort((left, right) => {
    const dateSort = String(right.date || "").localeCompare(String(left.date || ""));
    if (dateSort) return dateSort;
    return onboardingActivityPriority(right.action) - onboardingActivityPriority(left.action);
  });
}

function normalizeOnboardingActivityAction(action) {
  const text = String(action || "").trim();
  const key = normalizeImportKey(text);
  if (!key) return "";
  if (key.includes("nachbesserung") && key.includes("erneut")) return "Nachbesserung erneut eingereicht";
  if (key.includes("nachbesserung") && (key.includes("angefordert") || key.includes("abgelehnt"))) return "Nachbesserung angefordert";
  if (key.includes("freigegeben")) return "Freigegeben";
  if (key.includes("eingereicht") || key.includes("pruefung")) return "Zur Prüfung eingereicht";
  return "";
}

function onboardingActivityStatus(action) {
  const normalized = normalizeOnboardingActivityAction(action);
  if (normalized === "Freigegeben") return "Freigegeben";
  if (normalized === "Nachbesserung angefordert") return "Überarbeiten";
  if (normalized === "Nachbesserung erneut eingereicht") return "In Prüfung";
  return "In Prüfung";
}

function onboardingActivityPriority(action) {
  const normalized = normalizeOnboardingActivityAction(action);
  if (normalized === "Nachbesserung angefordert") return 4;
  if (normalized === "Freigegeben") return 3;
  if (normalized === "Nachbesserung erneut eingereicht") return 2;
  if (normalized === "Zur Prüfung eingereicht") return 1;
  return 0;
}

function renderOnboardingReviewCenter(onboarding) {
  if (!canReviewDocuments()) return "";
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    document: findDocumentForTemplateDraft(draft, draft.title),
    quality: onboardingDraftQuality(draft)
  }));
  if (!rows.length) return "";
  const inReview = rows.filter((row) => onboardingDraftInReview(row.draft, row.document)).length;
  const approved = rows.filter((row) => onboardingDraftApproved(row.draft, row.document)).length;
  const rework = rows.filter((row) => onboardingDraftNeedsRework(row.draft, row.document)).length;
  const blockers = rows.filter((row) => row.quality.requiredMissing.length).length;
  return `
    <div class="onboarding-review-center">
      <div class="onboarding-review-head">
        <div>
          <strong>Arbeitsvorlagen-Prüfung</strong>
          <span>Berater-/Manageransicht für eingereichte Arbeitsvorlagen aus dem Startprofil.</span>
        </div>
        <button class="primary-button" type="button" data-onboarding-approve-package ${inReview && !blockers && !rework ? "" : "disabled"}>Arbeitsvorlagen freigeben</button>
      </div>
      <div class="onboarding-review-summary">
        <div><strong>${inReview}</strong><span>In Prüfung</span></div>
        <div><strong>${approved}</strong><span>Freigegeben</span></div>
        <div class="${rework ? "warning" : ""}"><strong>${rework}</strong><span>Nachbesserung</span></div>
        <div class="${blockers ? "warning" : ""}"><strong>${blockers}</strong><span>Blocker</span></div>
      </div>
      <div class="onboarding-review-list">
        ${rows.map(({ draft, document, quality }) => renderOnboardingReviewItem(draft, document, quality)).join("")}
      </div>
    </div>
  `;
}

function renderOnboardingReviewItem(draft, document, quality) {
  const approved = onboardingDraftApproved(draft, document);
  const rework = onboardingDraftNeedsRework(draft, document);
  const inReview = onboardingDraftInReview(draft, document);
  const status = approved ? "Freigegeben" : rework ? "Überarbeiten" : inReview ? "In Prüfung" : draft.status || "Entwurf";
  const blockerText = quality.requiredMissing.length
    ? `Pflichtfelder offen: ${quality.requiredMissing.map((field) => field.label).join(", ")}`
    : quality.missing.length
      ? `Nacharbeiten: ${quality.missing.slice(0, 4).map((field) => field.label).join(", ")}`
      : "Keine offenen Template-Felder erkannt.";
  return `
    <article class="onboarding-review-item" data-onboarding-review-row="${escapeHtml(draft.id)}">
      <div class="onboarding-review-copy">
        <small>${escapeHtml(draft.source === "Kunden-Onboarding" ? "Arbeitsvorlage aus Startprofil" : draft.templateTitle || draft.area || "Template")}</small>
        <strong>${escapeHtml(templateDraftDisplayTitle(draft, "Unbenannte Arbeitsvorlage"))}</strong>
        <span>${escapeHtml(blockerText)}</span>
      </div>
      <div class="onboarding-review-state">
        ${statusTag(status)}
        <span>${quality.percent}% befüllt</span>
      </div>
      <textarea class="onboarding-review-note" data-onboarding-review-note placeholder="Nachbesserungshinweis an den Kunden">${escapeHtml(draft.reworkReason || document?.reworkReason || "")}</textarea>
      <div class="onboarding-review-actions">
        <button class="quiet-button" type="button" data-open-onboarding-draft="${escapeHtml(draft.id)}">Öffnen</button>
        <button class="quiet-button" type="button" data-onboarding-rework-draft="${escapeHtml(draft.id)}" ${approved || !inReview ? "disabled" : ""}>Nachbesserung</button>
        <button class="primary-button" type="button" data-onboarding-approve-draft="${escapeHtml(draft.id)}" ${approved || !inReview || quality.requiredMissing.length ? "disabled" : ""}>Freigeben</button>
      </div>
    </article>
  `;
}

function renderOnboardingStartPackage(onboarding) {
  const drafts = onboardingTemplateDrafts(onboarding);
  const draftRows = drafts.map((draft) => ({ draft, quality: onboardingDraftQuality(draft) }));
  const readiness = onboardingStartPackageReadiness(draftRows);
  return `
    <div class="onboarding-start-package">
      <div class="onboarding-package-head">
        <div>
          <strong>Vorbereitete Arbeitsvorlagen</strong>
          <span>${drafts.length ? `${drafts.length} Arbeitsvorlage(n) aus dem Startprofil` : "Noch keine Arbeitsvorlagen vorbereitet"}</span>
        </div>
        <div class="onboarding-package-actions">
          <button class="quiet-button" type="button" data-onboarding-gap-tasks ${readiness.missingFields ? "" : "disabled"}>Lücken als Aufgaben</button>
          <button class="quiet-button" type="button" data-onboarding-report>Arbeitsvorlagen-Report</button>
          <button class="primary-button" type="button" data-onboarding-submit-review ${drafts.length ? "" : "disabled"}>Zur Prüfung einreichen</button>
          <button class="quiet-button" type="button" data-onboarding-apply>${drafts.length ? "Arbeitsvorlagen aktualisieren" : "Arbeitsvorlagen vorbereiten"}</button>
        </div>
      </div>
      ${drafts.length ? `
        ${renderOnboardingReadiness(readiness)}
        <div class="onboarding-draft-grid">
          ${draftRows.map(({ draft, quality }) => `
            <article class="onboarding-draft-card">
              <div>
                <small>${escapeHtml(draft.source === "Kunden-Onboarding" ? "Arbeitsvorlage aus Startprofil" : draft.templateTitle || draft.area || "Template")}</small>
                <strong>${escapeHtml(templateDraftDisplayTitle(draft, "Unbenannte Arbeitsvorlage"))}</strong>
                <span>${escapeHtml(draft.linkedTo || "Noch nicht zugeordnet")} · ${quality.filled}/${quality.total || 0} Felder befüllt</span>
                <div class="onboarding-draft-progress" aria-label="${escapeHtml(draft.title || "Entwurf")} ${quality.percent}% befüllt">
                  <i style="width:${quality.percent}%"></i>
                </div>
              </div>
              <div class="onboarding-draft-actions">
                ${statusTag(quality.status)}
                <button class="quiet-button" type="button" data-open-onboarding-draft="${escapeHtml(draft.id)}">Arbeitsvorlage öffnen</button>
                <button class="quiet-button" type="button" data-template-draft-document="${escapeHtml(draft.id)}">Im Register öffnen</button>
              </div>
            </article>
          `).join("")}
        </div>
      ` : `
        <div class="empty-state compact">Klicke auf Arbeitsvorlagen vorbereiten, damit Scope, ISMS Manual, Asset-Inventar und bei Bedarf Lieferantencheck als bearbeitbare Arbeitsvorlagen erscheinen.</div>
      `}
    </div>
  `;
}

function renderOnboardingReadiness(readiness) {
  return `
    <div class="onboarding-readiness">
      <div><strong>${readiness.percent}%</strong><span>Ausfüllgrad</span></div>
      <div><strong>${readiness.readyDrafts}/${readiness.totalDrafts}</strong><span>Vorlagen bereit</span></div>
      <div class="${readiness.requiredMissing ? "warning" : ""}"><strong>${readiness.requiredMissing}</strong><span>Pflichtfelder offen</span></div>
      <div class="${readiness.missingFields ? "warning" : ""}"><strong>${readiness.missingFields}</strong><span>Felder nacharbeiten</span></div>
      <div><strong>${readiness.documentsLinked}/${readiness.totalDrafts}</strong><span>Im Register</span></div>
    </div>
    ${readiness.topGaps.length ? `
      <div class="onboarding-gap-list">
        <strong>Nächste Nacharbeiten</strong>
        ${readiness.topGaps.map((gap) => `<span>${escapeHtml(gap)}</span>`).join("")}
      </div>
    ` : ""}
  `;
}

function onboardingTemplateDrafts(onboarding = normalizeOnboarding(state.onboarding)) {
  const organization = onboarding.answers?.organizationName || "";
  const customerKey = normalizeImportKey(organization || "kunde");
  const prefix = `onboarding:${customerKey}:`;
  return (state.templateDrafts || [])
    .filter((draft) => draft.generatedKey?.startsWith(prefix) || draft.source === "Kunden-Onboarding")
    .sort((left, right) => String(right.updated || right.added || "").localeCompare(String(left.updated || left.added || "")));
}

function onboardingDraftInReview(draft, document) {
  return draft.status === "In Prüfung" || draft.approval === "Prüfung läuft" || document?.status === "In Prüfung" || document?.approval === "Prüfung läuft";
}

function onboardingDraftApproved(draft, document) {
  return draft.status === "Freigegeben" || draft.approval === "Freigegeben" || document?.status === "Freigegeben" || document?.approval === "Freigegeben";
}

function onboardingDraftNeedsRework(draft, document) {
  return draft.status === "Überarbeiten" || draft.approval === "Abgelehnt" || document?.status === "Überarbeiten" || document?.approval === "Abgelehnt";
}

function onboardingDraftQuality(draft) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === draft.templateId);
  const fields = template?.fields || [];
  const data = draft.data || {};
  const fieldRows = fields.map((field) => {
    const filled = isDraftFieldFilled(data[field.name]);
    return {
      name: field.name,
      label: field.label || field.name,
      required: Boolean(field.required),
      filled
    };
  });
  const filled = fieldRows.filter((field) => field.filled).length;
  const missing = fieldRows.filter((field) => !field.filled);
  const requiredMissing = missing.filter((field) => field.required);
  const percent = fields.length ? percentOf(filled, fields.length) : 0;
  return {
    total: fields.length,
    filled,
    missing,
    requiredMissing,
    percent,
    status: requiredMissing.length ? "Pflichtfelder offen" : missing.length ? "Nacharbeiten" : "Bereit"
  };
}

function onboardingStartPackageReadiness(draftRows) {
  const rows = Array.isArray(draftRows) ? draftRows : [];
  const totals = rows.reduce((sum, row) => ({
    total: sum.total + row.quality.total,
    filled: sum.filled + row.quality.filled,
    missing: sum.missing + row.quality.missing.length,
    requiredMissing: sum.requiredMissing + row.quality.requiredMissing.length,
    ready: sum.ready + (row.quality.missing.length ? 0 : 1),
    linked: sum.linked + (findDocumentForTemplateDraft(row.draft, row.draft.title) ? 1 : 0)
  }), { total: 0, filled: 0, missing: 0, requiredMissing: 0, ready: 0, linked: 0 });

  const topGaps = rows.flatMap((row) => {
    const title = row.draft.templateTitle || row.draft.title || "Entwurf";
    return row.quality.missing.slice(0, 3).map((field) => `${title}: ${field.label}`);
  }).slice(0, 6);

  return {
    totalDrafts: rows.length,
    readyDrafts: totals.ready,
    documentsLinked: totals.linked,
    percent: totals.total ? percentOf(totals.filled, totals.total) : 0,
    missingFields: totals.missing,
    requiredMissing: totals.requiredMissing,
    topGaps
  };
}

function isDraftFieldFilled(value) {
  const text = String(value || "").trim().toLowerCase();
  if (!text) return false;
  return ![
    "[ausfüllen]",
    "noch offen",
    "noch zu ergänzen",
    "noch ergänzen",
    "zu ergänzen",
    "fachlich prüfen",
    "finalisieren"
  ].some((marker) => text.includes(marker));
}

function onboardingSummaryCard(title, value, meta) {
  return `
    <article class="onboarding-summary-card">
      <span>${escapeHtml(title)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(meta || "")}</small>
    </article>
  `;
}

function renderOnboardingField(field, value = "") {
  const required = field.required ? "required" : "";
  const common = `name="${escapeHtml(field.id)}" ${required}`;
  const help = CUSTOMER_ONBOARDING_FIELD_HELP[field.id] || "";
  const helper = help ? `<small>${escapeHtml(help)}</small>` : "";
  if (field.type === "textarea") {
    return `
      <label class="question-card onboarding-field ${field.id === "firstPriority" ? "wide" : ""}">
        <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
        <textarea ${common} placeholder="${escapeHtml(field.placeholder || "")}">${escapeHtml(value)}</textarea>
        ${helper}
      </label>
    `;
  }
  if (field.type === "select") {
    return `
      <label class="question-card onboarding-field">
        <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
        <select ${common}>
          ${(field.options || []).map((option) => `<option value="${escapeHtml(option)}" ${value === option ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
        </select>
        ${helper}
      </label>
    `;
  }
  return `
    <label class="question-card onboarding-field">
      <span>${escapeHtml(field.label)}${field.required ? " *" : ""}</span>
      <input ${common} type="text" value="${escapeHtml(value)}" placeholder="${escapeHtml(field.placeholder || "")}" />
      ${helper}
    </label>
  `;
}

function renderCustomerGuidanceMap(stats) {
  const lanes = customerGuidanceLanes(stats);
  return `
    <section class="panel customer-guidance">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Kunden-Kompass</span>
          <h3>Was muss als Nächstes passieren?</h3>
          <p>Die Plattform übersetzt ISO 27001 und NIS-2 in konkrete Arbeitsphasen mit direktem Sprung in die passenden Bereiche.</p>
        </div>
      </div>
      <div class="guidance-lane-grid">
        ${lanes.map((lane) => `
          <article class="guidance-lane">
            <div class="guidance-lane-top">
              <span>${escapeHtml(lane.step)}</span>
              <strong>${escapeHtml(lane.title)}</strong>
            </div>
            <div class="guidance-progress" aria-label="${escapeHtml(lane.title)} ${lane.percent}%">
              <i style="width:${lane.percent}%"></i>
            </div>
            <p>${escapeHtml(lane.text)}</p>
            <div class="guidance-checks">
              ${lane.checks.map((check) => `
                <span class="${check.done ? "done" : ""}">
                  <b>${check.done ? "✓" : "•"}</b>
                  ${escapeHtml(check.label)}
                </span>
              `).join("")}
            </div>
            <div class="guidance-actions">
              <button class="primary-button" type="button" data-jump="${escapeHtml(lane.primaryView)}">${escapeHtml(lane.primaryAction)}</button>
              ${lane.secondaryView ? `<button class="quiet-button" type="button" data-jump="${escapeHtml(lane.secondaryView)}">${escapeHtml(lane.secondaryAction)}</button>` : ""}
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function notificationStore() {
  state.notifications = normalizeNotificationState(state.notifications);
  return state.notifications;
}

function notificationPriorityValue(value = "Mittel") {
  if (typeof value === "number") return value;
  return {
    Kritisch: 100,
    Hoch: 88,
    Mittel: 65,
    Niedrig: 40
  }[value] || 60;
}

function buildNotificationItems() {
  const items = [];
  const reviewer = canReviewDocuments();
  const reviewItems = reviewCenterItems()
    .filter((item) => !isRemovedCustomerRiskAnalysisArtifact(item));
  const soon = futureDate(14);

  reviewItems.forEach((item) => {
    const status = item.reviewStatus;
    const reviewDueDays = reviewDaysUntil(item.reviewDue);
    const reviewDeadlineRelevant = reviewDueDays !== null && reviewDueDays <= 3 && status !== "freigegeben";
    const reviewOverdue = reviewDueDays !== null && reviewDueDays < 0;
    const reviewDueSoon = reviewDueDays !== null && reviewDueDays >= 0 && reviewDueDays <= 3;
    const assignedToMe = Boolean(item.reviewAssignee && item.reviewAssignee === workflowActor());
    if (reviewer && (["vom_kunden_eingereicht", "in_beraterpruefung", "nacharbeit_noetig", "abgelehnt"].includes(status) || reviewDeadlineRelevant)) {
      const submitted = status === "vom_kunden_eingereicht";
      const rework = ["nacharbeit_noetig", "abgelehnt"].includes(status);
      const deadlineTitle = reviewOverdue
        ? `Review überfällig: ${item.title}`
        : reviewDueSoon
          ? `Review bald fällig: ${item.title}`
          : "";
      const deadlineText = reviewOverdue
        ? `Die interne Review-Frist ${item.reviewDue} ist überschritten. Bitte fachlich entscheiden oder neu terminieren.`
        : reviewDueSoon
          ? `Die interne Review-Frist endet ${item.reviewDue}. Bitte Prüfung einplanen und Entscheidung dokumentieren.`
          : "";
      items.push({
        id: `review:${item.key}:${status}:${item.reviewDue || "ohne-frist"}`,
        type: reviewDeadlineRelevant ? "Review-Frist" : rework ? "Nacharbeit" : "Beraterprüfung",
        title: deadlineTitle || (submitted ? `Neue Einreichung: ${item.title}` : rework ? `Rückgabe offen: ${item.title}` : `Prüfung entscheiden: ${item.title}`),
        text: deadlineText || item.reason || item.module || "Dieser Punkt braucht eine fachliche Entscheidung.",
        status: reviewOverdue ? "Überfällig" : reviewDueSoon ? "Bald fällig" : reviewStatusLabel(status),
        priority: notificationPriorityValue(item.priority) + (item.auditBlocker ? 15 : 0) + (reviewOverdue ? 18 : reviewDueSoon ? 8 : 0) + (assignedToMe ? 6 : 0),
        view: "review",
        reviewKey: item.key,
        meta: `${item.type} · Prüfer: ${item.reviewAssignee || "nicht zugewiesen"}${item.auditBlocker ? " · Audit-Blocker" : ""}`,
        date: item.reviewDue || item.modified || "",
        actionable: true
      });
    }
    if (!reviewer && ["nacharbeit_noetig", "abgelehnt"].includes(status)) {
      const isTemplateDraft = Boolean(item.templateDraftId);
      items.push({
        id: `customer-review:${item.key}:${status}`,
        type: "Nacharbeit",
        title: simpleCustomerTitle(item.title || "Nacharbeit ergänzen"),
        text: simpleCustomerText(item.reason || "Der Berater benötigt noch eine Ergänzung."),
        status: "Nacharbeit nötig",
        priority: 100,
        view: isTemplateDraft ? "templates" : item.rawType === "document" ? "documents" : "guided",
        documentId: !isTemplateDraft && item.rawType === "document" ? item.id : "",
        templateDraftId: item.templateDraftId || "",
        meta: "Vom Berater zurückgegeben",
        date: item.modified || "",
        actionable: true
      });
    }
    if (!reviewer && ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(status) && item.templateDraftId) {
      items.push({
        id: `customer-template-waiting:${item.key}:${status}`,
        type: "Beraterprüfung",
        title: `Wartet auf Berater: ${simpleCustomerTitle(item.title || "Arbeitsvorlage")}`,
        text: status === "in_beraterpruefung"
          ? "Die Arbeitsvorlage ist gerade in Prüfung. Du musst im Moment nichts tun."
          : "Die Arbeitsvorlage wurde eingereicht und wartet auf fachliche Prüfung.",
        status: "Wartet auf Berater",
        priority: 52,
        view: "templates",
        templateDraftId: item.templateDraftId,
        meta: item.module || "Arbeitsvorlagen",
        date: item.modified || "",
        actionable: true,
        escalatable: false
      });
    }
    if (!reviewer && status === "freigegeben") {
      const isTemplateDraft = Boolean(item.templateDraftId);
      items.push({
        id: `customer-approved:${item.key}:${status}`,
        type: "Freigabe",
        title: `Freigegeben: ${simpleCustomerTitle(item.title || "Einreichung")}`,
        text: "Der Berater/Admin hat diesen Punkt freigegeben.",
        status: "Freigegeben",
        priority: 55,
        view: isTemplateDraft ? "templates" : item.rawType === "document" ? "documents" : "guided",
        documentId: !isTemplateDraft && item.rawType === "document" ? item.id : "",
        templateDraftId: item.templateDraftId || "",
        meta: item.module || item.type,
        date: item.modified || "",
        actionable: true
      });
    }
  });

  if (reviewer) {
    capaRecords().forEach((record) => {
      const execution = capaExecutionStatus(record);
      const reviewStatus = normalizeReviewStatus(record.reviewStatus || record.status);
      if (execution.readyForEffectivenessReview) {
        items.push({
          id: `capa-effectiveness:${record.id}:${record.serverUpdatedAt || record.updated || record.due || "bereit"}`,
          type: "Beraterprüfung",
          title: `CAPA zur Wirksamkeitsprüfung bereit: ${record.title || "Korrekturmaßnahme"}`,
          text: "Umsetzung und Nachweis liegen formal vor. Bitte fachlich bewerten und Entscheidung dokumentieren.",
          status: "Zur Prüfung bereit",
          priority: 91,
          view: "review",
          reviewKey: capaReviewItemKey(record),
          meta: `${execution.completedTasks.length}/${execution.tasks.length} Aufgabe(n) erledigt · ${execution.documents.length} Nachweis(e)`,
          date: record.due || record.reviewUpdatedAt || record.serverUpdatedAt || "",
          actionable: true
        });
      } else if (record.auditRelevant && reviewStatus !== "freigegeben" && execution.gateBlockers.length) {
        items.push({
          id: `capa-audit-blocker:${record.id}:${execution.gateBlockers.length}`,
          type: "Auditpaket",
          title: `CAPA blockiert Auditpaket: ${record.title || "Korrekturmaßnahme"}`,
          text: execution.gateBlockers[0],
          status: "Blockiert",
          priority: 93,
          view: "review",
          reviewKey: capaReviewItemKey(record),
          meta: "CAPA-Gate",
          date: record.due || record.reviewUpdatedAt || record.serverUpdatedAt || "",
          actionable: true
        });
      }
    });
  }

  state.tasks
    .filter((task) => !isRemovedCustomerRiskAnalysisArtifact(task))
    .filter((task) => task.status !== "Erledigt")
    .filter((task) => isConsultantRequestedTask(task) || task.status === "Blockiert" || (task.due && task.due <= soon))
    .forEach((task) => {
      const overdue = Boolean(task.due && task.due < today());
      const requested = isConsultantRequestedTask(task);
      items.push({
        id: `task:${task.id}:${task.status || "Offen"}:${task.due || "ohne-frist"}`,
        type: requested ? "Nacharbeit" : "Frist",
        title: task.title || "Aufgabe bearbeiten",
        text: requested ? simpleCustomerText(task.note || "Der Berater hat diesen Punkt angefordert.") : dueText(task.due, task.module || "Task Management"),
        status: overdue ? "Überfällig" : task.status || "Offen",
        priority: requested ? 96 : overdue ? 92 : task.status === "Blockiert" ? 88 : 68,
        view: moduleToView(task.module || "tasks"),
        documentId: task.documentId || "",
        meta: `${task.module || "Task Management"} · Owner: ${task.owner || "offen"}`,
        date: task.due || "",
        actionable: true,
        escalatable: false
      });
    });

  state.documents
    .filter((document) => !isRemovedCustomerRiskAnalysisArtifact(document))
    .filter((document) => document.status !== "Quelle" && document.status !== "Archiviert")
    .filter((document) => document.review && document.review <= soon)
    .forEach((document) => {
      const overdue = document.review < today();
      items.push({
        id: `document-review:${document.id}:${document.review}`,
        type: "Frist",
        title: overdue ? `Review überfällig: ${document.name}` : `Review bald fällig: ${document.name}`,
        text: `Review-Datum ${document.review}. Bitte Inhalt, Owner und Freigabestatus prüfen.`,
        status: overdue ? "Überfällig" : "Bald fällig",
        priority: overdue ? 90 : 65,
        view: "documents",
        documentId: document.id,
        meta: `${document.area || "Dokumentation"} · Owner: ${document.owner || "offen"}`,
        date: document.review,
        actionable: true
      });
    });

  const packageData = auditPackageReportData();
  if (reviewer && packageData.approvalStale) {
    items.push({
      id: `audit-package:stale:${packageData.packageFingerprint}`,
      type: "Auditpaket",
      title: "Auditpaket-Freigabe ist veraltet",
      text: "Der Paketstand hat sich seit der letzten Freigabe geändert und muss erneut geprüft werden.",
      status: "Freigabe veraltet",
      priority: 98,
      view: "auditpackage",
      meta: `${packageData.gate.blockers.length} Blocker · Fingerprint ${packageData.packageFingerprint}`,
      actionable: true
    });
  } else if (reviewer && packageData.gate.consultantApproved && !packageData.packageApproval) {
    items.push({
      id: `audit-package:ready:${packageData.packageFingerprint}`,
      type: "Auditpaket",
      title: "Auditpaket kann fachlich freigegeben werden",
      text: "Die formalen Gate-Kriterien sind erfüllt. Berater/Admin muss den Paketstand bewusst prüfen und freigeben.",
      status: "Freigabe offen",
      priority: 86,
      view: "auditpackage",
      meta: `${packageData.formalPercent}% formal vorbereitet`,
      actionable: true
    });
  } else if (reviewer && packageData.gate.blockers.length) {
    items.push({
      id: `audit-package:blockers:${packageData.packageFingerprint}`,
      type: "Auditpaket",
      title: `${packageData.gate.blockers.length} Auditpaket-Blocker offen`,
      text: packageData.gate.blockers[0] || "Blocker vor der Beraterfreigabe klären.",
      status: "Blockiert",
      priority: 94,
      view: "review",
      meta: "Auditpaket-Gate",
      actionable: true
    });
  } else if (!reviewer && packageData.packageApproval) {
    items.push({
      id: `audit-package:approved:${packageData.packageApproval.id}`,
      type: "Freigabe",
      title: "Auditpaket wurde durch Berater/Admin freigegeben",
      text: packageData.packageApproval.comment || "Der aktuelle Paketstand wurde fachlich freigegeben.",
      status: "Freigegeben",
      priority: 70,
      view: "auditpackage",
      meta: `Version ${packageData.packageApproval.version || "-"}`,
      date: packageData.packageApproval.dateTime || packageData.packageApproval.date || "",
      actionable: true
    });
  }

  if (backendSessionUser && !backendSessionUser.mfaEnabled) {
    items.push({
      id: `security:mfa:${backendSessionUser.username || "user"}`,
      type: "Sicherheit",
      title: "MFA für dein Konto aktivieren",
      text: "Mehrfaktor-Authentifizierung schützt den Zugriff auf den Compliance-Workspace.",
      status: "Empfohlen",
      priority: 82,
      view: "account",
      meta: "Mein Konto",
      actionable: true
    });
  }

  if (isBackendAdmin()) {
    (productionAdminData.invitations || [])
      .filter((invitation) => invitation.status === "pending")
      .forEach((invitation) => {
        items.push({
          id: `invitation:${invitation.id || invitation.token || invitation.email}:pending`,
          type: "Team",
          title: `Einladung noch offen: ${invitation.email || invitation.username || "Benutzer"}`,
          text: "Die Einladung wurde noch nicht angenommen.",
          status: "Ausstehend",
          priority: 58,
          view: "team",
          meta: roleDisplayName(invitation.role || "customer"),
          date: invitation.expiresAt || "",
          actionable: true
        });
      });
  }

  if (backendSessionUser?.platformAdmin) {
    (productionAdminData.operations?.alerts || [])
      .filter((alert) => alert.status !== "resolved")
      .forEach((alert) => {
        const critical = alert.severity === "critical";
        items.push({
          id: `operations:${alert.key}`,
          type: "Betrieb",
          title: alert.title || "Technischen Betriebsalarm prüfen",
          text: alert.detail || "Der automatische Betriebsmonitor hat einen technischen Prüfpunkt erkannt.",
          status: alert.status === "acknowledged" ? "Bearbeitung bestätigt" : critical ? "Kritisch" : "Warnung",
          priority: critical ? 100 : 86,
          view: alert.actionView || "operations",
          meta: `${alert.source || "Betriebsmonitor"} · ${alert.scope || "Plattform"}`,
          date: alert.lastSeenAt ? formatBackendTime(alert.lastSeenAt) : "",
          actionable: true
        });
      });
  }

  return [...new Map(items.map((item) => [item.id, item])).values()]
    .filter((item) => !isRemovedCustomerRiskAnalysisArtifact(item));
}

function backendNotificationStateMap() {
  return new Map((backendNotificationData.states || []).map((item) => [String(item.id), item]));
}

function notificationItems(options = {}) {
  const store = notificationStore();
  const serverStates = backendNotificationStateMap();
  const useServerState = Boolean(backendSessionUser && backendNotificationData.loaded);
  return buildNotificationItems()
    .filter((item) => !isRemovedCustomerRiskAnalysisArtifact(item))
    .map((item) => {
      const serverState = serverStates.get(item.id);
      return {
        ...item,
        read: useServerState ? Boolean(serverState?.readAt) : store.readIds.includes(item.id),
        dismissed: useServerState ? Boolean(serverState?.dismissedAt) : store.dismissedIds.includes(item.id),
        escalated: useServerState ? Boolean(serverState?.escalatedAt) : store.escalatedIds.includes(item.id)
      };
    })
    .filter((item) => options.includeDismissed || !item.dismissed)
    .sort((left, right) => Number(left.read) - Number(right.read) || Number(right.priority || 0) - Number(left.priority || 0) || String(left.date || "").localeCompare(String(right.date || "")));
}

function applyNotificationFilters(items = notificationItems()) {
  const query = normalizeImportKey(notificationFilters.search);
  return items.filter((item) => {
    if (notificationFilters.type !== "Alle" && item.type !== notificationFilters.type) return false;
    if (notificationFilters.status === "Ungelesen" && item.read) return false;
    if (notificationFilters.status === "Gelesen" && !item.read) return false;
    if (notificationFilters.status === "Dringend" && Number(item.priority || 0) < 85) return false;
    if (notificationFilters.status === "Eskaliert" && !item.escalated) return false;
    if (!query) return true;
    return normalizeImportKey([item.title, item.text, item.type, item.status, item.meta].filter(Boolean).join(" ")).includes(query);
  });
}

function notificationDeliveryStatusLabel(status) {
  return {
    queued: "Eingeplant",
    retry: "Wiederholung geplant",
    delivering: "Wird zugestellt",
    sent: "Zugestellt",
    failed: "Fehlgeschlagen"
  }[status] || status || "Unbekannt";
}

function configuredNotificationDeliveryChannels() {
  const config = notificationDeliveryData.config || {};
  if (!config.enabled) return [];
  return Object.entries(config.channels || {})
    .filter(([, detail]) => detail?.configured)
    .map(([channel, detail]) => ({ channel, label: channel === "webhook" ? "Webhook" : "E-Mail", destination: detail.destinationLabel || "" }));
}

function renderNotificationDeliveryCenter() {
  if (!backendSessionUser || !canReviewDocuments()) return "";
  const config = notificationDeliveryData.config || {};
  const summary = notificationDeliveryData.summary || {};
  const deliveries = notificationDeliveryData.deliveries || [];
  const channels = configuredNotificationDeliveryChannels();
  const stateTitle = notificationDeliveryData.loading
    ? "Zustellstatus wird geladen"
    : notificationDeliveryData.error
      ? "Zustellcenter prüfen"
      : !config.enabled
        ? "Externe Zustellung deaktiviert"
        : channels.length
          ? "Kontrollierte Zustellung aktiv"
          : "Noch kein Zustellkanal konfiguriert";
  const stateText = !config.enabled
    ? "Es verlässt keine Benachrichtigung das System. Die Funktion muss serverseitig ausdrücklich aktiviert werden."
    : channels.length
      ? `${channels.map((item) => `${item.label}: ${item.destination}`).join(" · ")}. Zustellungen ändern keine fachliche Freigabe.`
      : "Aktivierung ist gesetzt, aber Webhook oder SMTP sind noch nicht vollständig konfiguriert.";
  return `
    <section class="panel notification-delivery-center">
      <div class="panel-header compact">
        <div>
          <span class="eyebrow">Nur Berater/Admin</span>
          <h3>Zustellcenter</h3>
          <p>Dringende Hinweise bewusst an einen fest konfigurierten Kanal weitergeben. Ziele und Secrets bleiben ausschließlich auf dem Server.</p>
        </div>
        <div class="notification-delivery-state ${config.enabled && channels.length ? "ready" : "disabled"}">
          <strong>${escapeHtml(stateTitle)}</strong>
          <small>${escapeHtml(stateText)}</small>
        </div>
      </div>
      <div class="notification-delivery-kpis">
        <div><strong>${escapeHtml(summary.queued || 0)}</strong><span>eingeplant</span></div>
        <div><strong>${escapeHtml(summary.sent || 0)}</strong><span>zugestellt</span></div>
        <div><strong>${escapeHtml(summary.failed || 0)}</strong><span>fehlgeschlagen</span></div>
        <div><strong>${escapeHtml(summary.total || 0)}</strong><span>Historie</span></div>
      </div>
      <div class="notification-delivery-list">
        ${deliveries.length ? deliveries.slice(0, 8).map((delivery) => `
          <article>
            <div>
              <strong>${escapeHtml(delivery.channel === "webhook" ? "Webhook-Zustellung" : "E-Mail-Zustellung")}</strong>
              <small>${escapeHtml(delivery.destinationLabel || "Konfiguriertes Ziel")} · ${escapeHtml(formatBackendTime(delivery.createdAt))}</small>
            </div>
            ${statusTag(notificationDeliveryStatusLabel(delivery.status))}
            <small>${delivery.attemptCount ? `${escapeHtml(delivery.attemptCount)} Versuch(e)` : "Noch kein Versuch"}${delivery.lastError ? ` · ${escapeHtml(delivery.lastError)}` : ""}</small>
            ${delivery.status === "failed" && config.enabled ? `<button class="quiet-button" type="button" data-notification-delivery-retry="${escapeHtml(delivery.id)}">Erneut versuchen</button>` : ""}
          </article>
        `).join("") : `<div class="management-empty">Noch keine externe Zustellung eingeplant. Dringende Hinweise bieten die Aktion direkt in der Inbox an.</div>`}
      </div>
    </section>
  `;
}

function notificationTextBundle(item = {}) {
  return [item.type, item.title, item.text, item.status, item.meta].filter(Boolean).join(" ");
}

function notificationMatches(item = {}, pattern) {
  return pattern.test(notificationTextBundle(item));
}

function notificationDateValue(item = {}) {
  const match = String(item.date || "").match(/\d{4}-\d{2}-\d{2}/);
  return match ? match[0] : "";
}

function notificationIsWaitingForReview(item = {}) {
  return notificationMatches(item, /beraterpr[uü]fung|eingereicht|freigabe offen|wartet|pr[uü]fung entscheiden|in pr[uü]fung/i);
}

function notificationIsRework(item = {}) {
  return item.type === "Nacharbeit" || notificationMatches(item, /nacharbeit|r[uü]ckgabe|abgelehnt|nachbesserung|zur[uü]ckgegeben/i);
}

function notificationIsSoon(item = {}) {
  const date = notificationDateValue(item);
  return item.type === "Frist" || notificationMatches(item, /frist|f[aä]llig|[uü]berf[aä]llig|review bald/i) || Boolean(date && date <= futureDate(14) && item.type !== "Freigabe");
}

function notificationInboxGroups(items = notificationItems()) {
  const taken = new Set();
  const pick = (predicate, limit = 4) => {
    const selected = [];
    items.forEach((item) => {
      if (selected.length >= limit || taken.has(item.id) || !predicate(item)) return;
      selected.push(item);
      taken.add(item.id);
    });
    return selected;
  };
  const urgent = pick((item) => !item.read && Number(item.priority || 0) >= 85, 4);
  const rework = pick(notificationIsRework, 4);
  const waiting = pick(notificationIsWaitingForReview, 4);
  const soon = pick(notificationIsSoon, 4);
  const next = [urgent[0], rework[0], waiting[0], soon[0], items.find((item) => !item.read), items[0]].find(Boolean);
  return { urgent, rework, waiting, soon, next };
}

function renderNotificationInboxHub(items = notificationItems()) {
  const groups = notificationInboxGroups(items);
  const unread = items.filter((item) => !item.read).length;
  const urgentCount = items.filter((item) => !item.read && Number(item.priority || 0) >= 85).length;
  const reworkCount = items.filter(notificationIsRework).length;
  const waitingCount = items.filter(notificationIsWaitingForReview).length;
  return `
    <section class="panel notification-inbox-hub">
      <div class="notification-inbox-head">
        <div>
          <span class="eyebrow">Heute zuerst</span>
          <h3>Was braucht deine Aufmerksamkeit?</h3>
          <p>Hier siehst du neue Rückgaben, Prüfungen und Fristen in einfacher Sprache. Die Inbox sortiert formal, fachliche Freigaben bleiben beim Berater/Admin.</p>
        </div>
        ${groups.next ? `
          <button class="notification-next-card" type="button" data-notification-open="${escapeHtml(groups.next.id)}">
            <span>Nächster sinnvoller Schritt</span>
            <strong>${escapeHtml(groups.next.title)}</strong>
            <small>${escapeHtml(groups.next.text || "Punkt öffnen und bearbeiten.")}</small>
          </button>
        ` : `
          <div class="notification-next-card calm">
            <span>Aktueller Stand</span>
            <strong>Keine akute Nachricht</strong>
            <small>Wenn etwas eingereicht, zurückgegeben oder fällig wird, erscheint es hier.</small>
          </div>
        `}
      </div>
      <div class="notification-inbox-kpis" aria-label="Benachrichtigungsüberblick">
        ${renderNotificationInboxKpi("Neu", unread, "noch nicht gelesen", "Ungelesen")}
        ${renderNotificationInboxKpi("Dringend", urgentCount, "zuerst prüfen", "Dringend")}
        ${renderNotificationInboxKpi("Nacharbeit", reworkCount, "vom Berater zurück", "Nacharbeit")}
        ${renderNotificationInboxKpi("Wartet", waitingCount, "in Prüfung oder eingereicht", "Alle")}
      </div>
      <div class="notification-inbox-lanes">
        ${renderNotificationInboxLane("Dringend", "Heute zuerst ansehen", groups.urgent, "Keine dringenden neuen Hinweise.", "urgent")}
        ${renderNotificationInboxLane("Nacharbeit", "Was zurückkam", groups.rework, "Keine offene Nacharbeit.", "rework")}
        ${renderNotificationInboxLane("Wartet auf Prüfung", "Beim Berater/Admin", groups.waiting, "Nichts wartet gerade auf Prüfung.", "waiting")}
        ${renderNotificationInboxLane("Bald fällig", "Fristen und Reviews", groups.soon, "Keine fälligen Punkte in Sicht.", "soon")}
      </div>
    </section>
  `;
}

function renderNotificationInboxKpi(label, value, hint, preset) {
  return `
    <button class="notification-inbox-kpi" type="button" data-notification-preset="${escapeHtml(preset)}">
      <strong>${escapeHtml(value)}</strong>
      <span>${escapeHtml(label)}</span>
      <small>${escapeHtml(hint)}</small>
    </button>
  `;
}

function renderNotificationInboxLane(title, subtitle, items, emptyText, tone = "") {
  return `
    <article class="notification-inbox-lane ${escapeHtml(tone)}">
      <div class="notification-inbox-lane-head">
        <div>
          <strong>${escapeHtml(title)}</strong>
          <small>${escapeHtml(subtitle)}</small>
        </div>
        <span>${escapeHtml(items.length)}</span>
      </div>
      <div class="notification-inbox-list">
        ${items.length ? items.map((item) => renderNotificationInboxCard(item)).join("") : `<div class="notification-inbox-empty">${escapeHtml(emptyText)}</div>`}
      </div>
    </article>
  `;
}

function renderNotificationInboxCard(item) {
  return `
    <button class="notification-inbox-card ${item.read ? "read" : "unread"}" type="button" data-notification-open="${escapeHtml(item.id)}">
      <span>${escapeHtml(item.type)}</span>
      <strong>${escapeHtml(item.title)}</strong>
      <small>${escapeHtml(item.status || "Offen")}${item.date ? ` · ${escapeHtml(notificationDateValue(item) || item.date)}` : ""}</small>
    </button>
  `;
}

function renderNotificationCenter() {
  const items = notificationItems();
  const visible = applyNotificationFilters(items);
  const unread = items.filter((item) => !item.read).length;
  const urgent = items.filter((item) => !item.read && Number(item.priority || 0) >= 85).length;
  const rework = items.filter((item) => item.type === "Nacharbeit").length;
  const escalated = items.filter((item) => item.escalated).length;
  const dismissed = notificationItems({ includeDismissed: true }).filter((item) => item.dismissed).length;
  const types = ["Alle", ...Array.from(new Set(items.map((item) => item.type))).sort((left, right) => left.localeCompare(right, "de"))];
  const syncNote = !backendSessionUser
    ? "Lokaler Status"
    : backendNotificationData.error
      ? "Persönliche Speicherung prüfen"
      : backendNotificationData.loaded
        ? "Persönlich servergespeichert"
        : "Persönlicher Status wird geladen";
  return `
    <div class="notification-center">
      <section class="panel notification-hero">
        <div>
          <span class="eyebrow">Persönliche Arbeits-Inbox</span>
          <h3>Benachrichtigungen und Fristen</h3>
          <p>Diese Ansicht sammelt Aufgaben, Einreichungen, Rückgaben, Reviews und Betriebsalarme. ${backendSessionUser ? "Gelesen, ausgeblendet und eskaliert werden persönlich und serverseitig gespeichert." : "Ohne Anmeldung bleibt der Status nur lokal gespeichert."}</p>
        </div>
        <div class="notification-hero-actions">
          <small class="${backendNotificationData.error ? "warning" : ""}">${escapeHtml(syncNote)}</small>
          <button class="primary-button" type="button" data-notification-mark-all ${unread ? "" : "disabled"}>Alle als gelesen</button>
          <button class="quiet-button" type="button" data-notification-restore ${dismissed ? "" : "disabled"}>${dismissed} ausgeblendete zurückholen</button>
        </div>
      </section>

      ${renderNotificationInboxHub(items)}

      <section class="notification-kpis">
        ${renderNotificationKpi("Ungelesen", unread, "Neue oder geänderte Punkte", unread ? "attention" : "done", "Ungelesen")}
        ${renderNotificationKpi("Dringend", urgent, "Hohe Priorität oder Blocker", urgent ? "warning" : "done", "Dringend")}
        ${renderNotificationKpi("Nacharbeit", rework, "Vom Berater oder aus Review", rework ? "warning" : "done", "Nacharbeit")}
        ${renderNotificationKpi("Eskaliert", escalated, "Als gemeinsame Aufgabe markiert", escalated ? "attention" : "done", "Eskaliert")}
        ${renderNotificationKpi("Gesamt sichtbar", items.length, `${dismissed} ausgeblendet`, "", "Alle")}
      </section>

      ${renderNotificationDeliveryCenter()}

      <section class="panel notification-filter-panel">
        <div class="notification-filter-grid">
          <label>
            <span>Suche</span>
            <input type="search" value="${escapeHtml(notificationFilters.search)}" placeholder="Titel, Bereich, Status" data-notification-filter="search" />
          </label>
          <label>
            <span>Typ</span>
            <select data-notification-filter="type">
              ${types.map((type) => `<option value="${escapeHtml(type)}" ${notificationFilters.type === type ? "selected" : ""}>${escapeHtml(type)}</option>`).join("")}
            </select>
          </label>
          <label>
            <span>Status</span>
            <select data-notification-filter="status">
              ${["Alle", "Ungelesen", "Gelesen", "Dringend", "Eskaliert"].map((status) => `<option value="${status}" ${notificationFilters.status === status ? "selected" : ""}>${status}</option>`).join("")}
            </select>
          </label>
          <button class="quiet-button" type="button" data-notification-filter-reset>Filter zurücksetzen</button>
        </div>
      </section>

      <section class="panel notification-list-panel">
        <div class="panel-header compact">
          <div>
            <span class="eyebrow">Inbox</span>
            <h3>${visible.length} sichtbare Nachricht(en)</h3>
            <p>Öffnen markiert eine Nachricht als gelesen und führt direkt zum ursprünglichen Arbeitsbereich.</p>
          </div>
        </div>
        <div class="notification-list">
          ${visible.length ? visible.map(renderNotificationItem).join("") : renderEmptyState("Keine Benachrichtigungen in dieser Ansicht", "Neue Einreichungen, Nacharbeiten, Fristen und Freigaben erscheinen automatisch.", [{ label: "Dashboard öffnen", view: "dashboard", primary: true }], { mark: "OK" })}
        </div>
      </section>
    </div>
  `;
}

function renderNotificationKpi(label, value, hint, tone = "", preset = "Alle") {
  return `
    <button class="notification-kpi ${escapeHtml(tone)}" type="button" data-notification-preset="${escapeHtml(preset)}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
      <small>${escapeHtml(hint)}</small>
    </button>
  `;
}

function renderNotificationItem(item) {
  const tone = Number(item.priority || 0) >= 85 ? "urgent" : item.type === "Freigabe" ? "approved" : "";
  const canEscalate = canEditWorkspace() && Number(item.priority || 0) >= 85 && item.escalatable !== false && !item.escalated;
  const deliveryChannels = canReviewDocuments() && Number(item.priority || 0) >= 85 ? configuredNotificationDeliveryChannels() : [];
  const latestDelivery = (notificationDeliveryData.deliveries || []).find((delivery) => delivery.notificationId === item.id);
  return `
    <article class="notification-item ${item.read ? "read" : "unread"} ${tone}">
      <div class="notification-item-mark" aria-hidden="true"></div>
      <div class="notification-item-main">
        <div class="notification-item-labels">
          <span>${escapeHtml(item.type)}</span>
          ${statusTag(item.status || "Offen")}
          ${item.escalated ? statusTag("Eskaliert") : ""}
          ${latestDelivery ? statusTag(`Zustellung: ${notificationDeliveryStatusLabel(latestDelivery.status)}`) : ""}
        </div>
        <strong>${escapeHtml(item.title)}</strong>
        <p>${escapeHtml(item.text || "")}</p>
        <small>${escapeHtml(item.meta || "")}${item.date ? ` · ${escapeHtml(item.date)}` : ""}</small>
      </div>
      <div class="notification-item-actions">
        ${item.actionable ? `<button class="primary-button" type="button" data-notification-open="${escapeHtml(item.id)}">Öffnen</button>` : ""}
        ${canEscalate ? `<button class="quiet-button" type="button" data-notification-escalate="${escapeHtml(item.id)}">Als Aufgabe eskalieren</button>` : ""}
        ${deliveryChannels.map((detail) => `<button class="quiet-button" type="button" data-notification-deliver="${escapeHtml(item.id)}" data-notification-delivery-channel="${escapeHtml(detail.channel)}">${escapeHtml(detail.label)} zustellen</button>`).join("")}
        <button class="quiet-button" type="button" data-notification-read="${escapeHtml(item.id)}">${item.read ? "Als ungelesen" : "Als gelesen"}</button>
        <button class="quiet-button" type="button" data-notification-dismiss="${escapeHtml(item.id)}">Ausblenden</button>
      </div>
    </article>
  `;
}

function renderNotificationDashboardPreview() {
  const items = notificationItems().filter((item) => !item.read).slice(0, 4);
  return `
    <section class="panel notification-preview">
      <div class="panel-header compact">
        <div>
          <span class="eyebrow">Persönliche Inbox</span>
          <h3>${items.length ? `${items.length} wichtige neue Hinweise` : "Keine neuen Hinweise"}</h3>
          <p>Einreichungen, Rückgaben, Fristen und Freigaben werden hier gebündelt.</p>
        </div>
        <button class="quiet-button" type="button" data-jump="notifications">Alle Benachrichtigungen</button>
      </div>
      <div class="notification-preview-list">
        ${items.length ? items.map((item) => `
          <button type="button" data-notification-open="${escapeHtml(item.id)}">
            <span>${escapeHtml(item.type)}</span>
            <strong>${escapeHtml(item.title)}</strong>
            ${statusTag(item.status || "Offen")}
          </button>
        `).join("") : `<div class="management-empty">Wenn ein Punkt deine Aufmerksamkeit braucht, erscheint er automatisch hier.</div>`}
      </div>
    </section>
  `;
}

async function persistNotificationAction(action, notificationIds) {
  if (!backendSessionUser) return false;
  const ids = Array.from(new Set((Array.isArray(notificationIds) ? notificationIds : [notificationIds]).filter(Boolean)));
  if (!ids.length) return false;
  try {
    const payload = await apiRequest("/api/notifications/state", {
      method: "POST",
      json: { action, notificationIds: ids }
    });
    backendNotificationData = {
      loaded: true,
      loading: false,
      error: "",
      states: payload.states || [],
      summary: payload.summary || {}
    };
    return true;
  } catch (error) {
    backendNotificationData = { ...backendNotificationData, error: error.message || "Benachrichtigungsstatus konnte nicht gespeichert werden." };
    showToast(`Benachrichtigungsstatus konnte nicht gespeichert werden: ${error.message}`, "warning");
    return false;
  }
}

function applyNotificationDeliveryPayload(payload = {}) {
  notificationDeliveryData = {
    loaded: true,
    loading: false,
    error: "",
    config: payload.config || { enabled: false, configured: false, channels: {}, runtime: {} },
    deliveries: payload.deliveries || [],
    summary: payload.summary || {}
  };
}

async function loadNotificationDeliveries(showSuccess = false) {
  if (!backendSessionUser || !canReviewDocuments()) return false;
  notificationDeliveryData = { ...notificationDeliveryData, loading: true, error: "" };
  try {
    const payload = await apiRequest("/api/notifications/deliveries");
    applyNotificationDeliveryPayload(payload);
    if (showSuccess) showToast("Zustellhistorie aktualisiert.");
    return true;
  } catch (error) {
    notificationDeliveryData = {
      ...notificationDeliveryData,
      loaded: true,
      loading: false,
      error: error.message || "Zustellhistorie konnte nicht geladen werden."
    };
    return false;
  } finally {
    if (currentView === "notifications") render();
  }
}

async function queueNotificationDelivery(notificationId, channel) {
  if (!backendSessionUser || !canReviewDocuments()) return;
  const item = notificationItems({ includeDismissed: true }).find((candidate) => candidate.id === notificationId);
  if (!item) {
    showToast("Benachrichtigung wurde nicht gefunden.", "warning");
    return;
  }
  try {
    const payload = await apiRequest("/api/notifications/deliveries", {
      method: "POST",
      json: {
        notificationId: item.id,
        channel,
        notification: {
          id: item.id,
          type: item.type,
          title: item.title,
          text: item.text,
          status: item.status,
          priority: item.priority,
          view: item.view,
          meta: item.meta,
          date: item.date
        }
      }
    });
    applyNotificationDeliveryPayload(payload);
    showToast(payload.reused ? "Diese Zustellung ist bereits eingeplant." : "Zustellung sicher eingeplant. Sie ändert keine fachliche Freigabe.");
    render();
  } catch (error) {
    showToast(`Zustellung konnte nicht eingeplant werden: ${error.message}`, "warning");
  }
}

async function retryNotificationDelivery(deliveryId) {
  if (!backendSessionUser || !canReviewDocuments()) return;
  try {
    const payload = await apiRequest(`/api/notifications/deliveries/${encodeURIComponent(deliveryId)}/retry`, {
      method: "POST",
      json: {}
    });
    applyNotificationDeliveryPayload(payload);
    showToast("Erneuter Zustellversuch eingeplant.");
    render();
  } catch (error) {
    showToast(`Zustellung konnte nicht erneut eingeplant werden: ${error.message}`, "warning");
  }
}

async function setNotificationRead(id, read) {
  if (backendSessionUser) {
    await persistNotificationAction(read ? "read" : "unread", [id]);
    render();
    return;
  }
  const store = notificationStore();
  store.readIds = read
    ? Array.from(new Set([id, ...store.readIds])).slice(0, 1000)
    : store.readIds.filter((itemId) => itemId !== id);
  saveState();
  render();
}

async function dismissNotification(id) {
  if (backendSessionUser) {
    await persistNotificationAction("dismiss", [id]);
    render();
    return;
  }
  const store = notificationStore();
  store.dismissedIds = Array.from(new Set([id, ...store.dismissedIds])).slice(0, 1000);
  saveState();
  render();
}

async function markAllNotificationsRead() {
  const ids = notificationItems().map((item) => item.id);
  if (backendSessionUser) {
    await persistNotificationAction("read", ids);
    showToast("Alle sichtbaren Benachrichtigungen als gelesen markiert.");
    render();
    return;
  }
  const store = notificationStore();
  store.readIds = Array.from(new Set([...ids, ...store.readIds])).slice(0, 1000);
  saveState();
  showToast("Alle sichtbaren Benachrichtigungen als gelesen markiert.");
  render();
}

async function restoreDismissedNotifications() {
  if (backendSessionUser) {
    const ids = (backendNotificationData.states || []).filter((item) => item.dismissedAt).map((item) => item.id);
    if (ids.length) await persistNotificationAction("restore", ids);
    showToast("Ausgeblendete Benachrichtigungen wiederhergestellt.");
    render();
    return;
  }
  notificationStore().dismissedIds = [];
  saveState();
  showToast("Ausgeblendete Benachrichtigungen wiederhergestellt.");
  render();
}

async function openNotification(id) {
  const item = notificationItems({ includeDismissed: true }).find((candidate) => candidate.id === id);
  if (!item) return;
  if (backendSessionUser) {
    await persistNotificationAction("read", [id]);
  } else {
    const store = notificationStore();
    store.readIds = Array.from(new Set([id, ...store.readIds])).slice(0, 1000);
    saveState();
  }
  if (item.reviewKey && canAccessView("review")) {
    selectedReviewItemKey = item.reviewKey;
    navigateToView("review");
    return;
  }
  if (item.templateDraftId && openTemplateDraftFromAnywhere(item.templateDraftId)) {
    return;
  }
  if (item.documentId) {
    openDocumentFromAnywhere(item.documentId);
    return;
  }
  navigateToView(item.view || "dashboard");
}

async function escalateNotification(id) {
  const item = notificationItems({ includeDismissed: true }).find((candidate) => candidate.id === id);
  if (!item || !canEditWorkspace() || item.escalatable === false) return;
  const taskTitle = `Eskalation: ${item.title}`;
  const created = addTaskIfMissing({
    title: taskTitle,
    module: viewToTaskModule(item.view || "tasks"),
    owner: backendSessionUser?.username || "ISB / Verantwortliche Rolle",
    due: futureDate(Number(item.priority || 0) >= 95 ? 2 : 7),
    status: "Offen",
    linkedTo: item.meta || item.title,
    source: "Benachrichtigungscenter",
    note: `Aus der persönlichen Inbox eskaliert. Typ: ${item.type}; Status: ${item.status}; Hinweis: ${item.text || "-"}.`
  });
  recordAuditTrailEvent({
    action: "Benachrichtigung als Aufgabe eskaliert",
    entityType: "Aufgabe",
    entityId: id,
    entityTitle: taskTitle,
    module: viewToTaskModule(item.view || "tasks"),
    status: created ? "Offen" : "Bereits vorhanden",
    note: item.text || item.meta || "Dringender Hinweis eskaliert.",
    metadata: { notificationId: id, priority: item.priority || 0, sourceType: item.type || "" }
  });
  saveState({ immediate: true });
  if (backendSessionUser) {
    await persistNotificationAction("escalate", [id]);
  } else {
    const store = notificationStore();
    store.escalatedIds = Array.from(new Set([id, ...store.escalatedIds])).slice(0, 1000);
    saveState();
  }
  showToast(created ? "Dringender Hinweis als gemeinsame Aufgabe eskaliert." : "Passende Eskalationsaufgabe war bereits vorhanden.");
  render();
}

function renderCustomerTodoCenter(stats) {
  const items = customerTodoItems(stats);
  const urgent = items.filter((item) => item.priority >= 85).length;
  const uploads = items.filter((item) => item.kind === "upload").length;
  const reviews = items.filter((item) => item.kind === "review").length;
  return `
    <section class="panel customer-todo-center">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Kunden-To-do-Center</span>
          <h3>Meine nächsten Schritte</h3>
          <p>Eine priorisierte Arbeitsliste aus Nachbesserungen, Aufgaben, Nachweisen, SOC/SIEM-Findings und Reviews.</p>
        </div>
        <div class="customer-todo-summary">
          <div class="${urgent ? "warning" : ""}"><strong>${urgent}</strong><span>dringend</span></div>
          <div><strong>${uploads}</strong><span>Uploads</span></div>
          <div><strong>${reviews}</strong><span>Reviews</span></div>
        </div>
      </div>
      <div class="customer-todo-list">
        ${items.length ? items.slice(0, 8).map((item, index) => renderCustomerTodoItem(item, index)).join("") : `
          <div class="customer-todo-empty">
            <strong>Aktuell nichts Dringendes offen</strong>
            <span>Projektplan, Nachweise und Aufgaben enthalten momentan keinen unmittelbaren Kunden-Blocker.</span>
          </div>
        `}
      </div>
    </section>
  `;
}

function renderGuidedCustomerMode() {
  const stats = dashboardStats();
  const stepStates = guidedStepStates(stats);
  if (!stepStates.some((step) => step.id === selectedGuidedStepId)) {
    selectedGuidedStepId = nextGuidedStepId(stepStates);
  }
  const activeStep = stepStates.find((step) => step.id === selectedGuidedStepId) || stepStates[0];
  const completedSteps = stepStates.filter((step) => step.state === "ready").length;
  const routePercent = percentOf(completedSteps, stepStates.length);
  const tasks = guidedCustomerTasks(stats);
  const sections = customerSimpleCockpitSections(tasks);

  return `
    <div class="guided-mode customer-mode-page">
      ${renderCustomerModeCommandCenter(stats, stepStates, sections, activeStep, routePercent)}
      ${renderCustomerActionTrafficLight(stats, stepStates, sections, activeStep, routePercent)}
      ${renderCustomerModeFastTrack(stats, stepStates, sections, routePercent)}
      ${renderCustomerStepCoach(activeStep, stats)}
      ${renderCustomerSimpleCockpit(tasks)}
      ${renderCustomerReworkInbox(sections)}
      ${renderCustomerSubmissionFlow(stats, stepStates, sections, routePercent)}
      ${renderGuidedStepPanel(activeStep, stats)}
      ${renderCustomerModeSupportDetails(stats, stepStates, sections, activeStep, routePercent, tasks)}
    </div>
  `;
}

function renderCustomerActionTrafficLight(stats, stepStates, sections, activeStep, routePercent) {
  const counts = customerModeCounts(stats, stepStates, sections);
  const decision = customerActionTrafficDecision(stats, stepStates, sections, activeStep, routePercent, counts);
  const packageData = auditPackageReportData();
  const blockers = packageData.gate?.blockers?.length || 0;
  const submission = latestGuidedSubmission();
  const cards = [
    {
      label: "Jetzt du",
      value: counts.today,
      text: counts.today ? "Bitte diese Punkte aktiv bearbeiten." : "Gerade nichts Dringendes offen.",
      tone: counts.today ? "warning" : "ready"
    },
    {
      label: "Nacharbeit",
      value: counts.rework,
      text: counts.rework ? "Vom Berater zurückgegeben." : "Keine Rückgabe offen.",
      tone: counts.rework ? "warning" : "ready"
    },
    {
      label: "Wartet",
      value: counts.waiting,
      text: counts.waiting ? "Liegt bei Berater/Admin." : "Nichts wartet auf Prüfung.",
      tone: counts.waiting ? "waiting" : "ready"
    },
    {
      label: "Abgabe",
      value: submission ? "eingereicht" : `${routePercent}%`,
      text: blockers ? `${blockers} Blocker vor Freigabe.` : "Nur Berater/Admin gibt final frei.",
      tone: blockers ? "warning" : submission ? "waiting" : routePercent >= 80 ? "active" : "open"
    }
  ];

  return `
    <section class="panel customer-action-traffic ${escapeHtml(decision.tone)}">
      <div class="customer-action-traffic-main">
        <div>
          <span class="eyebrow">Kunden-Ampel</span>
          <h3>${escapeHtml(decision.title)}</h3>
          <p>${escapeHtml(decision.text)}</p>
        </div>
        <div class="customer-action-traffic-next">
          <span>${escapeHtml(decision.badge)}</span>
          <strong>${escapeHtml(decision.focus)}</strong>
          <small>${escapeHtml(decision.helper)}</small>
          ${renderCustomerTrafficAction(decision)}
        </div>
      </div>
      <div class="customer-action-traffic-grid">
        ${cards.map((card) => `
          <article class="${escapeHtml(card.tone)}">
            <strong>${escapeHtml(card.value)}</strong>
            <span>${escapeHtml(card.label)}</span>
            <small>${escapeHtml(card.text)}</small>
          </article>
        `).join("")}
      </div>
      <div class="customer-action-traffic-note">
        <strong>Wichtig:</strong>
        <span>Die Plattform zeigt nur formale Vorbereitung und Prüfstatus. Sie behauptet nicht automatisch ISO-konform, NIS-2-erfüllt oder auditbereit.</span>
      </div>
    </section>
  `;
}

function customerActionTrafficDecision(stats, stepStates, sections, activeStep, routePercent, counts = customerModeCounts(stats, stepStates, sections)) {
  const packageData = auditPackageReportData();
  const blockers = packageData.gate?.blockers?.length || 0;
  const submission = latestGuidedSubmission();
  const primary = customerModePrimaryAction(sections);

  if (counts.rework) {
    return {
      tone: "warning",
      badge: "Nacharbeit",
      title: "Bitte zuerst die Rückgabe bearbeiten.",
      text: "Der Berater/Admin hat etwas zurückgegeben. Ergänze genau diesen Punkt, dann kann er erneut geprüft werden.",
      focus: primary.title,
      helper: "Öffnen, ergänzen, erneut speichern oder einreichen.",
      action: primary.action
    };
  }

  if (counts.today) {
    return {
      tone: "active",
      badge: "Heute erledigen",
      title: "Du hast einen klaren nächsten Schritt.",
      text: "Arbeite diesen Punkt zuerst ab. Danach aktualisiert sich die Strecke automatisch.",
      focus: primary.title,
      helper: primary.text,
      action: primary.action
    };
  }

  if (counts.waiting) {
    return {
      tone: "waiting",
      badge: "Wartet",
      title: "Aktuell liegt der Arbeitsstand beim Berater.",
      text: "Du musst hier gerade nichts freigeben. Der Status ändert sich, sobald die Prüfung abgeschlossen oder Nacharbeit angefordert wird.",
      focus: `${counts.waiting} Punkt(e) in Prüfung`,
      helper: "Kunden können Status sehen, aber nicht final freigeben.",
      target: canAccessView("review") ? "review" : "documents",
      label: "Prüfstatus ansehen"
    };
  }

  if (routePercent >= 80 && !submission && !blockers) {
    return {
      tone: "ready",
      badge: "Einreichen",
      title: "Der Stand kann formal zur Prüfung eingereicht werden.",
      text: "Das ist noch keine Auditfreigabe. Es ist die Übergabe an Berater/Admin zur fachlichen Prüfung.",
      focus: "Zur Beraterprüfung bereit",
      helper: "Nur Berater/Admin kann danach freigeben oder zurückgeben.",
      submit: true,
      label: "Arbeitsstand einreichen"
    };
  }

  if (blockers) {
    return {
      tone: "warning",
      badge: "Blocker",
      title: "Vor der Abgabe sind noch Blocker offen.",
      text: "Öffne den Abgabecheck und schließe die Punkte, die das Auditpaket blockieren.",
      focus: `${blockers} Blocker offen`,
      helper: "Blocker verhindern eine Beraterfreigabe.",
      target: "auditpackage",
      label: "Auditpaket prüfen"
    };
  }

  return {
    tone: "open",
    badge: "Weiter ausfüllen",
    title: "Mach mit dem nächsten offenen Schritt weiter.",
    text: "Die Plattform führt dich durch die Vorbereitung. Es geht zuerst um vollständige Angaben und prüfbare Nachweise.",
    focus: customerModeStepLabel(activeStep),
    helper: `${activeStep.statusText || "Offen"} · ${activeStep.percent || 0}%`,
    auto: true,
    label: "Nächsten Schritt öffnen"
  };
}

function renderCustomerTrafficAction(decision = {}) {
  if (decision.submit) {
    return `<button class="primary-button" type="button" data-guided-submit-package ${canSubmitDocuments() ? "" : "disabled"}>${escapeHtml(decision.label || "Einreichen")}</button>`;
  }
  if (decision.auto) {
    return `<button class="primary-button" type="button" data-guided-auto>${escapeHtml(decision.label || "Nächsten Schritt öffnen")}</button>`;
  }
  if (decision.action) return renderGuidedTaskAction(decision.action, true);
  if (decision.target) return `<button class="primary-button" type="button" data-jump="${escapeHtml(decision.target)}">${escapeHtml(decision.label || "Öffnen")}</button>`;
  return "";
}

