function renderCustomerModeFastTrack(stats, stepStates, sections, routePercent) {
  const stages = customerModeFastTrackStages(stats, stepStates, sections, routePercent);
  const nextStage = stages.find((stage) => stage.state !== "done") || stages[stages.length - 1];
  return `
    <section class="panel customer-fast-track">
      <div class="customer-fast-track-head">
        <div>
          <span class="eyebrow">Abgabe-Strecke</span>
          <h3>Von der ersten Eingabe bis zur Beraterprüfung.</h3>
          <p>Diese Übersicht zeigt in einfacher Sprache, was schon vorbereitet ist und welcher Abschnitt als nächstes dran ist.</p>
        </div>
        <div class="customer-fast-track-next">
          <span>Nächster Abschnitt</span>
          <strong>${escapeHtml(nextStage.title)}</strong>
          <button class="quiet-button" type="button" ${nextStage.attrs}>Öffnen</button>
        </div>
      </div>
      <div class="customer-fast-track-grid">
        ${stages.map((stage, index) => renderCustomerModeFastTrackStage(stage, index)).join("")}
      </div>
    </section>
  `;
}

function customerModeFastTrackStages(stats, stepStates, sections, routePercent) {
  const step = (id) => stepStates.find((item) => item.id === id) || { percent: 0, state: "missing", statusText: "Offen" };
  const section = (id) => sections.find((item) => item.id === id)?.items.length || 0;
  const packageData = auditPackageReportData();
  const packageApproved = Boolean(packageData.packageApproval);
  const submission = latestGuidedSubmission();
  const reviewMetrics = packageData.reviewMetrics || reviewCenterMetrics(reviewCenterItems());
  const waiting = Math.max(section("waiting"), (reviewMetrics.submitted || 0) + (reviewMetrics.inReview || 0));
  const rework = Math.max(section("rework"), reviewMetrics.returns || reviewMetrics.rework || 0);
  const blockers = packageData.gate?.blockers?.length || 0;

  const stageState = (ids) => {
    const states = ids.map(step);
    if (states.every((item) => item.state === "ready")) return "done";
    if (states.some((item) => item.state === "review")) return "active";
    return "open";
  };
  const stagePercent = (ids) => Math.round(ids.map((id) => Number(step(id).percent || 0)).reduce((sum, value) => sum + value, 0) / Math.max(ids.length, 1));

  return [
    {
      number: "01",
      title: "Grundprojekt",
      text: "Projekt, Ansprechpartner, Zielrahmen und Startprofil ausfüllen.",
      status: `${stagePercent(["projectsetup", "start"])}%`,
      state: stageState(["projectsetup", "start"]),
      attrs: 'data-guided-step="projectsetup"'
    },
    {
      number: "02",
      title: "Assets und Risiken",
      text: "Wichtige Systeme erfassen und beschreiben, was schiefgehen kann.",
      status: `${stagePercent(["assets", "risks"])}%`,
      state: stageState(["assets", "risks"]),
      attrs: step("assets").state !== "ready" ? 'data-guided-step="assets"' : 'data-guided-step="risks"'
    },
    {
      number: "03",
      title: "Policies und Nachweise",
      text: "Richtlinien vorbereiten und Belege, Links oder Dateien zuordnen.",
      status: `${stagePercent(["policies", "evidence", "soa"])}%`,
      state: stageState(["policies", "evidence", "soa"]),
      attrs: step("policies").state !== "ready" ? 'data-guided-step="policies"' : step("evidence").state !== "ready" ? 'data-guided-step="evidence"' : 'data-guided-step="soa"'
    },
    {
      number: "04",
      title: rework ? "Nacharbeit" : waiting ? "Beraterprüfung" : "Zur Prüfung vorbereiten",
      text: rework
        ? "Einige Punkte wurden zurückgegeben und müssen ergänzt werden."
        : waiting
          ? "Eingaben liegen beim Berater. Du musst hier gerade nichts tun."
          : "Arbeitsstand für die fachliche Prüfung vorbereiten.",
      status: rework ? `${rework} zurück` : waiting ? `${waiting} wartet` : `${step("handover").percent || 0}%`,
      state: rework ? "warning" : waiting ? "waiting" : step("handover").state === "ready" ? "done" : "active",
      attrs: rework ? 'data-jump="tasks"' : 'data-guided-step="handover"'
    },
    {
      number: "05",
      title: "Auditpaket",
      text: packageApproved
        ? "Der Paketstand wurde bewusst durch Berater/Admin freigegeben."
        : blockers
          ? "Das Paket ist vorbereitet, aber noch nicht freigegeben."
          : "Einreichen oder Paketstand öffnen. Keine automatische Auditbereitschaft.",
      status: packageApproved ? "Freigegeben" : blockers ? `${blockers} Blocker` : submission ? "Eingereicht" : `${routePercent}%`,
      state: packageApproved ? "done" : blockers ? "warning" : submission ? "waiting" : "open",
      attrs: submission || packageApproved ? 'data-jump="auditpackage"' : 'data-guided-step="submit"'
    }
  ];
}

function renderCustomerModeFastTrackStage(stage, index) {
  return `
    <button class="customer-fast-track-stage ${escapeHtml(stage.state)}" type="button" ${stage.attrs || 'data-guided-step="projectsetup"'}>
      <span>${escapeHtml(stage.number || String(index + 1).padStart(2, "0"))}</span>
      <div>
        <strong>${escapeHtml(stage.title)}</strong>
        <small>${escapeHtml(stage.text)}</small>
      </div>
      ${statusTag(stage.status || "Offen")}
    </button>
  `;
}

