function renderCustomerSubmissionFlow(stats, stepStates, sections, routePercent) {
  const submission = latestGuidedSubmission();
  const packageData = auditPackageReportData();
  const reviewMetrics = packageData.reviewMetrics || reviewCenterMetrics(reviewCenterItems());
  const counts = customerModeCounts(stats, stepStates, sections);
  const waiting = Math.max(counts.waiting, (reviewMetrics.submitted || 0) + (reviewMetrics.inReview || 0));
  const rework = Math.max(counts.rework, reviewMetrics.returns || reviewMetrics.rework || 0);
  const blockers = packageData.gate?.blockers?.length || 0;
  const packageApproved = Boolean(packageData.packageApproval);
  const prepared = routePercent >= 80;
  const stages = [
    {
      number: "01",
      title: "Vorbereiten",
      text: `${routePercent}% der Kundenstrecke vorbereitet.`,
      state: prepared ? "done" : "active",
      status: prepared ? "bereit" : "weiter ausfüllen"
    },
    {
      number: "02",
      title: "Einreichen",
      text: submission ? `Arbeitsstand wurde ${submission.submittedAt || submission.added || "heute"} eingereicht.` : "Arbeitsstand noch nicht übergeben.",
      state: submission ? "done" : prepared ? "active" : "open",
      status: submission ? "eingereicht" : "offen"
    },
    {
      number: "03",
      title: "Beraterprüfung",
      text: waiting ? `${waiting} Punkt(e) warten auf Prüfung.` : "Keine aktive Prüfung oder alles entschieden.",
      state: waiting ? "active" : submission ? "done" : "open",
      status: waiting ? "wartet" : "kein Stau"
    },
    {
      number: "04",
      title: "Rückmeldung",
      text: rework ? `${rework} Punkt(e) brauchen Nacharbeit.` : `${reviewMetrics.approved || 0} Punkt(e) freigegeben.`,
      state: rework ? "warning" : reviewMetrics.approved ? "done" : "open",
      status: rework ? "Nacharbeit" : reviewMetrics.approved ? "freigegeben" : "offen"
    },
    {
      number: "05",
      title: "Auditpaket",
      text: packageApproved ? "Paketstand ist beraterfreigegeben." : blockers ? `${blockers} Blocker vor Freigabe.` : "Formal vorbereitet, Freigabe fehlt.",
      state: packageApproved ? "done" : blockers ? "warning" : submission ? "active" : "open",
      status: packageApproved ? "exportbereit" : blockers ? "blockiert" : "Freigabe offen"
    }
  ];
  const next = customerSubmissionFlowNext({ prepared, submission, waiting, rework, blockers, packageApproved });
  return `
    <section class="customer-submission-flow ${escapeHtml(next.tone)}">
      <div class="customer-submission-flow-head">
        <div>
          <span class="eyebrow">Übergabeprozess</span>
          <h3>${escapeHtml(next.title)}</h3>
          <p>${escapeHtml(next.text)}</p>
        </div>
        <div class="customer-submission-flow-actions">
          ${next.primary === "submit"
            ? `<button class="primary-button" type="button" data-guided-submit-package ${canSubmitDocuments() ? "" : "disabled"}>${escapeHtml(next.label)}</button>`
            : next.primary === "auto"
              ? `<button class="primary-button" type="button" data-guided-auto>${escapeHtml(next.label)}</button>`
              : `<button class="primary-button" type="button" data-jump="${escapeHtml(next.target)}">${escapeHtml(next.label)}</button>`}
          <button class="quiet-button" type="button" data-jump="auditpackage">Auditpaket</button>
          <button class="quiet-button" type="button" data-jump="${canAccessView("review") ? "review" : "documents"}">${canAccessView("review") ? "Beraterprüfung" : "Prüfstatus"}</button>
        </div>
      </div>
      <div class="customer-submission-flow-steps">
        ${stages.map((stage) => `
          <article class="${escapeHtml(stage.state)}">
            <span>${escapeHtml(stage.number)}</span>
            <div>
              <strong>${escapeHtml(stage.title)}</strong>
              <small>${escapeHtml(stage.text)}</small>
            </div>
            <em>${escapeHtml(stage.status)}</em>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function customerSubmissionFlowNext({ prepared, submission, waiting, rework, blockers, packageApproved }) {
  if (rework) {
    return {
      tone: "warning",
      title: "Nacharbeit zuerst bearbeiten",
      text: "Der Berater hat Punkte zurückgegeben. Ergänze die Angaben und reiche sie danach erneut ein.",
      label: "Nacharbeit öffnen",
      target: "tasks"
    };
  }
  if (!prepared) {
    return {
      tone: "open",
      title: "Erst die wichtigsten Angaben vorbereiten",
      text: "Arbeite die offenen Schritte im Kundenmodus ab. Danach kann der Arbeitsstand sauber übergeben werden.",
      label: "Nächsten Schritt öffnen",
      primary: "auto"
    };
  }
  if (!submission) {
    return {
      tone: "active",
      title: "Arbeitsstand kann eingereicht werden",
      text: "Reiche den aktuellen Stand zur Beraterprüfung ein. Die Plattform zeigt nur formale Vorbereitung, keine finale Auditbereitschaft.",
      label: "Arbeitsstand einreichen",
      primary: "submit"
    };
  }
  if (waiting) {
    return {
      tone: "waiting",
      title: "Liegt beim Berater/Admin",
      text: "Der Arbeitsstand wurde übergeben. Kunden können den Status sehen, aber nicht final freigeben.",
      label: "Prüfstatus ansehen",
      target: canAccessView("review") ? "review" : "documents"
    };
  }
  if (blockers) {
    return {
      tone: "warning",
      title: "Auditpaket hat noch Blocker",
      text: "Vor einer Beraterfreigabe müssen die offenen Gate-Punkte geklärt werden.",
      label: "Auditpaket prüfen",
      target: "auditpackage"
    };
  }
  if (packageApproved) {
    return {
      tone: "done",
      title: "Paketstand wurde freigegeben",
      text: "Der aktuelle Paketstand ist beraterfreigegeben und kann als Arbeitsstand exportiert werden.",
      label: "Auditpaket öffnen",
      target: "auditpackage"
    };
  }
  return {
    tone: "active",
    title: "Beraterfreigabe steht noch aus",
    text: "Das Paket ist vorbereitet. Berater/Admin müssen den konkreten Paketstand bewusst freigeben.",
    label: "Auditpaket öffnen",
    target: "auditpackage"
  };
}

function customerModeCompletionState(stats, stepStates, sections, routePercent) {
  const counts = customerModeCounts(stats, stepStates, sections);
  const primary = customerModePrimaryAction(sections);
  const packageData = auditPackageReportData();
  const reviewMetrics = packageData.reviewMetrics || reviewCenterMetrics(reviewCenterItems());
  const blockerCount = packageData.gate?.blockers?.length || 0;
  const waitingForConsultant = Math.max(counts.waiting, (reviewMetrics.submitted || 0) + (reviewMetrics.inReview || 0));
  const reviewReturns = Math.max(counts.rework, reviewMetrics.returns || reviewMetrics.rework || 0);
  const packageApproved = Boolean(packageData.packageApproval);
  const formalPercent = packageData.gate?.autoPreparedPercent ?? packageData.formalPercent ?? 0;
  const consultantTarget = canAccessView("review") ? "review" : "documents";
  const base = {
    tone: "neutral",
    label: "Arbeitsstand",
    title: "Noch nicht fertig, aber gut vorbereitet",
    text: "Die Plattform sammelt deinen Arbeitsstand und zeigt formale Lücken. Die fachliche Prüfung und Freigabe macht danach der Berater/Admin.",
    helper: "Tipp: Erst offene Kundenaufgaben erledigen, dann einreichen und auf Rückmeldung warten.",
    primaryAction: primary.action,
    reviewTarget: consultantTarget,
    reviewLabel: canAccessView("review") ? "Beraterprüfung öffnen" : "Prüfstatus ansehen"
  };

  if (reviewReturns) {
    Object.assign(base, {
      tone: "warning",
      label: "Nacharbeit zuerst",
      title: "Der Berater braucht eine Ergänzung",
      text: "Mindestens ein Punkt wurde zurückgegeben. Öffne die Aufgabe, ergänze die fehlenden Angaben und reiche sie erneut ein.",
      helper: "Das ist normal im Projekt: Rückfragen werden sichtbar gesammelt, damit nichts per E-Mail verloren geht."
    });
  } else if (counts.today) {
    Object.assign(base, {
      tone: "action",
      label: "Heute wichtig",
      title: "Es gibt noch aktive Kundenschritte",
      text: "Bearbeite zuerst die offenen Angaben, Uploads oder Fragen. Danach kann der Berater den Stand sauber prüfen.",
      helper: "Die Plattform zeigt nur formale Vollständigkeit, keine automatische Normfreigabe."
    });
  } else if (waitingForConsultant) {
    Object.assign(base, {
      tone: "waiting",
      label: "Wartet auf Prüfung",
      title: "Dein Arbeitsstand liegt beim Berater",
      text: "Aktuell ist für dich wenig zu tun. Der Berater/Admin prüft die eingereichten Punkte und gibt sie frei oder fordert Nacharbeit an.",
      helper: "Du kannst weiter ergänzen, aber finale Freigaben bleiben beim Berater/Admin.",
      primaryAction: { label: "Prüfstatus ansehen", type: "view", target: "documents" }
    });
  } else if (packageApproved) {
    Object.assign(base, {
      tone: "approved",
      label: "Freigegeben",
      title: "Dieser Paketstand ist beraterfreigegeben",
      text: "Der aktuelle Auditpaket-Stand wurde durch Berater/Admin freigegeben und kann als Arbeitsbericht exportiert werden.",
      helper: "Das ersetzt keine externe Auditentscheidung; es dokumentiert die interne Beraterfreigabe.",
      primaryAction: { label: "Auditpaket öffnen", type: "view", target: "auditpackage" }
    });
  } else if (blockerCount) {
    Object.assign(base, {
      tone: "blocked",
      label: "Blocker klären",
      title: "Auditpaket ist vorbereitet, aber blockiert",
      text: "Es gibt noch Punkte, die vor einer Beraterfreigabe geklärt werden müssen. Diese Blocker werden im Review Center oder Auditpaket angezeigt.",
      helper: "Die Plattform sagt bewusst nicht auditbereit, solange diese Punkte offen sind.",
      primaryAction: { label: "Blocker ansehen", type: "view", target: consultantTarget }
    });
  } else if (packageData.gate?.consultantApproved) {
    Object.assign(base, {
      tone: "waiting",
      label: "Freigabe offen",
      title: "Formal vorbereitet, Beraterfreigabe fehlt",
      text: "Die formalen Gate-Kriterien wirken vorbereitet. Der Berater/Admin muss den Paketstand trotzdem bewusst freigeben.",
      helper: "Automatisch geprüft heißt hier nur: formal vollständig beziehungsweise zur Prüfung bereit.",
      primaryAction: { label: "Freigabe prüfen", type: "view", target: consultantTarget }
    });
  }

  base.kpis = [
    { label: "Kundenstrecke", value: `${routePercent}%`, text: `${counts.readySteps}/${counts.totalSteps} Schritte vorbereitet`, tone: routePercent >= 100 ? "ready" : "" },
    { label: "Beim Berater", value: String(waitingForConsultant), text: "eingereicht oder in Prüfung", tone: waitingForConsultant ? "waiting" : "" },
    { label: "Nacharbeit", value: String(reviewReturns), text: "zurück an Kunde", tone: reviewReturns ? "warning" : "ready" },
    { label: "Auditpaket", value: `${formalPercent}%`, text: blockerCount ? `${blockerCount} Blocker offen` : packageApproved ? "beraterfreigegeben" : "Freigabe offen", tone: packageApproved ? "approved" : blockerCount ? "blocked" : "" }
  ];
  return base;
}

function renderCustomerModeStatusGuide(sections) {
  const metrics = guidedHandoverReviewMetrics(reviewCenterItems());
  const sectionMap = new Map(sections.map((section) => [section.id, section]));
  const statusItems = [
    {
      label: "Von dir eingereicht",
      value: metrics.submitted + metrics.inReview,
      tone: "waiting",
      meaning: "Dein Arbeitsstand ist gespeichert und liegt zur Prüfung vor.",
      next: "Du musst nur reagieren, wenn der Berater eine Rückfrage stellt."
    },
    {
      label: "Nacharbeit nötig",
      value: sectionMap.get("rework")?.items.length || metrics.rework,
      tone: "warning",
      meaning: "Ein Punkt reicht noch nicht aus oder braucht eine Ergänzung.",
      next: "Öffne die Aufgabe, ergänze konkret, was fehlt, und reiche erneut ein."
    },
    {
      label: "Freigegeben",
      value: sectionMap.get("approved")?.items.length || metrics.approved,
      tone: "approved",
      meaning: "Berater/Admin hat diesen einzelnen Punkt geprüft.",
      next: "Keine Aktion nötig, außer der Berater bittet später um Aktualisierung."
    },
    {
      label: "Audit-Blocker",
      value: metrics.blockers,
      tone: metrics.blockers ? "blocked" : "approved",
      meaning: "Dieser Punkt verhindert aktuell eine bewusste Beraterfreigabe.",
      next: "Blocker werden fachlich im Review Center oder gemeinsam im Projekt geklärt."
    }
  ];
  return `
    <section class="customer-status-guide" aria-label="Status einfach erklärt">
      <div class="customer-status-guide-head">
        <div>
          <span class="eyebrow">Status einfach erklärt</span>
          <h3>Was bedeutet mein Projektstand?</h3>
        </div>
        <p>Diese Begriffe sind bewusst in Kundensprache gehalten. Die Plattform zeigt Vorbereitung und Prüfstatus, aber keine automatische Audit- oder Normfreigabe.</p>
      </div>
      <div class="customer-status-guide-grid">
        ${statusItems.map((item) => `
          <article class="customer-status-guide-card ${escapeHtml(item.tone)}">
            <div>
              <strong>${escapeHtml(String(item.value))}</strong>
              <span>${escapeHtml(item.label)}</span>
            </div>
            <p>${escapeHtml(item.meaning)}</p>
            <small>${escapeHtml(item.next)}</small>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function renderCustomerReworkInbox(sections) {
  const reworkSection = sections.find((section) => section.id === "rework");
  const items = reworkSection?.items || [];
  if (!items.length) return "";
  return `
    <section class="customer-rework-inbox">
      <div class="customer-rework-inbox-head">
        <div>
          <span class="eyebrow">Nacharbeit zuerst</span>
          <h3>Das kam vom Berater zurück</h3>
          <p>Diese Punkte brauchen eine Ergänzung. Öffne den Punkt, ergänze die Angaben oder den Nachweis und reiche ihn danach erneut ein.</p>
        </div>
        <div class="customer-rework-count">
          <strong>${items.length}</strong>
          <span>Rückgabe${items.length === 1 ? "" : "n"}</span>
        </div>
      </div>
      <div class="customer-rework-inbox-list">
        ${items.map((item, index) => renderCustomerReworkInboxItem(item, index)).join("")}
      </div>
    </section>
  `;
}

function renderCustomerReworkInboxItem(item, index) {
  const actions = (item.actions || [item.action]).filter(Boolean);
  const guidance = item.guidance || parseCustomerReworkGuidance(item, {
    missing: item.text || "Der Berater benötigt eine Ergänzung.",
    reference: item.title || "Nacharbeit"
  });
  return `
    <article class="customer-rework-inbox-item">
      <div class="customer-rework-inbox-title">
        <span>${String(index + 1).padStart(2, "0")}</span>
        <div>
          <strong>${escapeHtml(item.title || "Nacharbeit bearbeiten")}</strong>
          <small>${escapeHtml(item.status || "Nacharbeit nötig")}</small>
        </div>
      </div>
      <div class="customer-rework-inbox-steps">
        <div>
          <b>Was fehlt?</b>
          <p>${escapeHtml(guidance.missing || "Bitte fehlende Angaben ergänzen.")}</p>
        </div>
        <div>
          <b>Warum?</b>
          <p>${escapeHtml(guidance.why || "Der Berater braucht eine nachvollziehbare Grundlage für die Prüfung.")}</p>
        </div>
        <div>
          <b>Was tun?</b>
          <p>${escapeHtml(guidance.action || "Bitte ergänzen und erneut einreichen.")}</p>
        </div>
      </div>
      ${guidance.reference ? `<small class="customer-rework-reference">Bezug: ${escapeHtml(guidance.reference)}</small>` : ""}
      <div class="customer-rework-inbox-actions">
        ${actions.slice(0, 2).map((action, actionIndex) => renderGuidedTaskAction(action, actionIndex === 0)).join("")}
      </div>
    </article>
  `;
}

function renderCustomerReviewPipeline(sections) {
  const metrics = guidedHandoverReviewMetrics(reviewCenterItems());
  const sectionMap = new Map(sections.map((section) => [section.id, section]));
  const waiting = Math.max(sectionMap.get("waiting")?.items.length || 0, metrics.submitted + metrics.inReview);
  const rework = Math.max(sectionMap.get("rework")?.items.length || 0, metrics.rework);
  const approved = Math.max(sectionMap.get("approved")?.items.length || 0, metrics.approved);
  const packageData = auditPackageReportData();
  const packageApproved = Boolean(packageData.packageApproval);
  const blockers = packageData.gate?.blockers?.length || 0;
  const pipeline = [
    {
      label: "Einreichen",
      text: "Kunde übergibt den Arbeitsstand.",
      value: metrics.submitted,
      state: metrics.submitted || waiting || rework || approved ? "done" : "open"
    },
    {
      label: "Berater prüft",
      text: "Berater/Admin bewertet fachlich.",
      value: metrics.inReview,
      state: metrics.submitted || metrics.inReview ? "active" : approved || rework ? "done" : "open"
    },
    {
      label: "Rückfrage",
      text: "Falls etwas fehlt, kommt es zurück.",
      value: rework,
      state: rework ? "warning" : approved ? "done" : "open"
    },
    {
      label: "Freigabe",
      text: "Nur Berater/Admin gibt final frei.",
      value: approved,
      state: packageApproved || approved ? "done" : blockers ? "blocked" : "open"
    }
  ];
  const guidance = customerReviewPipelineGuidance({ waiting, rework, approved, blockers, packageApproved });
  return `
    <section class="customer-review-pipeline ${escapeHtml(guidance.tone)}">
      <div class="customer-review-pipeline-head">
        <div>
          <span class="eyebrow">Prüfablauf</span>
          <h3>Was passiert nach dem Einreichen?</h3>
          <p>Diese Timeline zeigt den formalen Prüfstand. Inhaltliche Bewertung, Freigabe und Auditentscheidung bleiben beim Berater/Admin.</p>
        </div>
        <div class="customer-review-pipeline-action">
          <strong>${escapeHtml(guidance.title)}</strong>
          <span>${escapeHtml(guidance.text)}</span>
          <button class="${guidance.primary ? "primary-button" : "quiet-button"}" type="button" ${guidance.target}>${escapeHtml(guidance.label)}</button>
        </div>
      </div>
      <div class="customer-review-pipeline-steps">
        ${pipeline.map((step, index) => `
          <article class="${escapeHtml(step.state)}">
            <span>${String(index + 1).padStart(2, "0")}</span>
            <div>
              <strong>${escapeHtml(step.label)}</strong>
              <p>${escapeHtml(step.text)}</p>
            </div>
            <small>${escapeHtml(String(step.value))}</small>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function customerReviewPipelineGuidance({ waiting, rework, approved, blockers, packageApproved }) {
  if (rework) {
    return {
      tone: "warning",
      title: "Nacharbeit zuerst",
      text: `${rework} Punkt(e) brauchen deine Ergänzung.`,
      label: "Nacharbeit öffnen",
      target: 'data-jump="tasks"',
      primary: true
    };
  }
  if (waiting) {
    return {
      tone: "waiting",
      title: "Liegt beim Berater",
      text: `${waiting} Punkt(e) warten auf Prüfung oder Entscheidung.`,
      label: "Prüfstatus ansehen",
      target: 'data-jump="documents"',
      primary: false
    };
  }
  if (packageApproved) {
    return {
      tone: "done",
      title: "Paketstand freigegeben",
      text: "Der aktuelle Paketstand wurde bewusst freigegeben.",
      label: "Auditpaket öffnen",
      target: 'data-jump="auditpackage"',
      primary: false
    };
  }
  if (blockers) {
    return {
      tone: "blocked",
      title: "Blocker offen",
      text: `${blockers} Punkt(e) blockieren die Beraterfreigabe.`,
      label: canAccessView("review") ? "Review Center" : "Nachweise öffnen",
      target: `data-jump="${canAccessView("review") ? "review" : "documents"}"`,
      primary: false
    };
  }
  if (approved) {
    return {
      tone: "done",
      title: "Einzelpunkte freigegeben",
      text: `${approved} Punkt(e) wurden durch Berater/Admin freigegeben.`,
      label: "Freigaben ansehen",
      target: 'data-jump="documents"',
      primary: false
    };
  }
  return {
    tone: "open",
    title: "Noch nicht eingereicht",
    text: "Bereite erst die offenen Kundenschritte vor.",
    label: "Nächsten Schritt öffnen",
    target: "data-guided-auto",
    primary: true
  };
}

function renderCustomerSubmissionReadiness(stats, stepStates, sections, routePercent) {
  const readiness = customerSubmissionReadiness(stats, stepStates, sections, routePercent);
  const primaryDisabled = !canSubmitDocuments() || !readiness.canSubmit ? "disabled" : "";
  return `
    <section class="customer-submission-check ${escapeHtml(readiness.tone)}">
      <div class="customer-submission-head">
        <div>
          <span class="eyebrow">Abgabe-Check</span>
          <h3>${escapeHtml(readiness.title)}</h3>
          <p>${escapeHtml(readiness.text)}</p>
        </div>
        <div class="customer-submission-score">
          <strong>${escapeHtml(String(readiness.done))}/${escapeHtml(String(readiness.total))}</strong>
          <span>formal erledigt</span>
        </div>
      </div>

      <div class="customer-submission-grid">
        ${readiness.criteria.map((criterion) => `
          <article class="customer-submission-item ${criterion.ok ? "done" : "open"}">
            <div>
              <span>${criterion.ok ? "OK" : "Offen"}</span>
              <strong>${escapeHtml(criterion.label)}</strong>
            </div>
            <p>${escapeHtml(criterion.text)}</p>
            <button class="quiet-button" type="button" ${criterion.step ? `data-guided-step="${escapeHtml(criterion.step)}"` : `data-jump="${escapeHtml(criterion.view || "guided")}"`}>${escapeHtml(criterion.action)}</button>
          </article>
        `).join("")}
      </div>

      <div class="customer-submission-actions">
        <button class="primary-button" type="button" data-guided-submit-package ${primaryDisabled}>${escapeHtml(readiness.primaryLabel)}</button>
        <button class="quiet-button" type="button" data-guided-auto>Nächsten offenen Punkt öffnen</button>
        <button class="quiet-button" type="button" data-guided-step="handover">Abgabecheck öffnen</button>
      </div>
    </section>
  `;
}

function customerSubmissionReadiness(stats, stepStates, sections, routePercent) {
  const onboarding = normalizeOnboarding(state.onboarding);
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const packageData = auditPackageReportData();
  const reviewMetrics = packageData.reviewMetrics || reviewCenterMetrics(reviewCenterItems());
  const sectionMap = new Map(sections.map((section) => [section.id, section]));
  const rework = Math.max(sectionMap.get("rework")?.items.length || 0, reviewMetrics.returns || reviewMetrics.rework || 0);
  const waiting = Math.max(sectionMap.get("waiting")?.items.length || 0, (reviewMetrics.submitted || 0) + (reviewMetrics.inReview || 0));
  const openStepCount = stepStates.filter((step) => step.state !== "ready").length;
  const gateBlockers = packageData.gate?.blockers?.length || 0;
  const hasAssetAndRisk = state.assets.length > 0 && state.risks.length > 0;
  const criteria = [
    {
      label: "Grundprojekt angelegt",
      ok: onboardingProjectSetupReady(onboarding.project),
      text: onboardingProjectSetupReady(onboarding.project)
        ? "Projektname, Ansprechpartner und Zielrahmen sind erfasst."
        : "Bitte Projektname, Ansprechpartner und Zielrahmen ergänzen.",
      step: "projectsetup",
      action: "Grundprojekt öffnen"
    },
    {
      label: "Assets und Risiken begonnen",
      ok: hasAssetAndRisk,
      text: hasAssetAndRisk
        ? `${state.assets.length} Asset(s) und ${state.risks.length} Risiko(s) sind erfasst.`
        : "Mindestens wichtige Systeme und erste Risiken erfassen.",
      step: state.assets.length ? "risks" : "assets",
      action: state.assets.length ? "Risiken öffnen" : "Assets öffnen"
    },
    {
      label: "Nachweise sauber erfasst",
      ok: docMetrics.working > 0 && docMetrics.missing === 0,
      text: docMetrics.working
        ? `${docMetrics.working} Nachweis(e), ${docMetrics.missing} mit offenen Metadaten.`
        : "Bitte mindestens relevante Dateien, Links oder Dokumentverweis erfassen.",
      step: "evidence",
      action: "Nachweise öffnen"
    },
    {
      label: "Kundenstrecke bearbeitet",
      ok: routePercent >= 80 || openStepCount <= 2,
      text: `${routePercent}% vorbereitet. ${openStepCount} Abschnitt(e) sind noch nicht abgeschlossen.`,
      step: nextGuidedStepId(stepStates),
      action: "Nächsten Abschnitt"
    },
    {
      label: "Keine Nacharbeit offen",
      ok: rework === 0,
      text: rework ? `${rework} Rückgabe(n) müssen noch ergänzt werden.` : "Keine offene Rückgabe an den Kunden erkannt.",
      view: "tasks",
      action: "Nacharbeit öffnen"
    },
    {
      label: "Keine Audit-Blocker offen",
      ok: gateBlockers === 0,
      text: gateBlockers ? `${gateBlockers} Blocker verhindern aktuell eine Beraterfreigabe.` : "Keine formalen Audit-Blocker erkannt.",
      view: canAccessView("review") ? "review" : "documents",
      action: "Blocker ansehen"
    }
  ];
  const done = criteria.filter((criterion) => criterion.ok).length;
  const total = criteria.length;
  const canSubmit = done === total && !waiting;
  if (waiting) {
    return {
      criteria,
      done,
      total,
      canSubmit: false,
      tone: "waiting",
      title: "Arbeitsstand liegt bereits beim Berater",
      text: "Aktuell wartet mindestens ein Punkt auf Beraterprüfung. Du kannst weiter ergänzen, aber finale Freigaben setzt nur Berater/Admin.",
      primaryLabel: "Bereits eingereicht"
    };
  }
  if (canSubmit) {
    return {
      criteria,
      done,
      total,
      canSubmit: true,
      tone: "ready",
      title: "Formal bereit zur Beraterprüfung",
      text: "Die wichtigsten formalen Punkte sind vorbereitet. Jetzt kann der Arbeitsstand zur Prüfung eingereicht werden.",
      primaryLabel: "Zur Beraterprüfung einreichen"
    };
  }
  return {
    criteria,
    done,
    total,
    canSubmit: false,
    tone: "open",
    title: "Vor dem Einreichen noch ergänzen",
    text: "Der Arbeitsstand ist noch nicht vollständig vorbereitet. Öffne zuerst die offenen Punkte unten.",
    primaryLabel: "Noch nicht einreichbar"
  };
}

