function renderCustomerModeWorkboard(sections) {
  const actionItems = customerModeActionItems(sections);
  const waiting = sections.find((section) => section.id === "waiting")?.items || [];
  const approved = sections.find((section) => section.id === "approved")?.items || [];
  return `
    <section class="customer-mode-workboard">
      ${renderCustomerModeList("Heute erledigen", "Die wichtigsten Punkte für dich", actionItems, "Aktuell gibt es nichts, was du aktiv bearbeiten musst.", "action")}
      ${renderCustomerModeList("Wartet auf Berater", "Du musst hier gerade nichts tun", waiting, "Noch nichts zur Prüfung eingereicht.", "waiting")}
      ${renderCustomerModeList("Freigegeben", "Durch Berater/Admin geprüft", approved, "Noch keine freigegebenen Punkte.", "approved")}
    </section>
  `;
}

function customerModeActionItems(sections) {
  const labels = {
    rework: "Nacharbeit",
    uploads: "Nachweis",
    questions: "Angabe"
  };
  return sections
    .filter((section) => ["rework", "uploads", "questions"].includes(section.id))
    .flatMap((section) => section.items.map((item) => ({
      ...item,
      sectionLabel: labels[section.id] || section.label,
      sectionTone: section.tone
    })))
    .sort((left, right) => Number(right.priority || 0) - Number(left.priority || 0) || String(left.title || "").localeCompare(String(right.title || "")))
    .slice(0, 6);
}

