function renderGuidedTaskAction(action = {}, primary = false) {
  const target = guidedTaskActionTarget(action);
  if (!target) return "";
  const variant = action.variant || (primary ? "primary" : "quiet");
  const disabled = action.disabled ? "disabled" : "";
  return `<button class="${variant === "primary" ? "primary-button" : "quiet-button"}" type="button" ${target} ${disabled}>${escapeHtml(action.label || "Öffnen")}</button>`;
}

function guidedTaskActionTarget(action = {}) {
  if (action.type === "soa") return `data-guided-soa="${escapeHtml(action.target || "")}"`;
  if (action.type === "jumpSection") return `data-jump-section="${escapeHtml(action.view || "dashboard")}:${escapeHtml(action.target || "")}"`;
  if (action.type === "openTemplateDraft") return `data-open-template-draft="${escapeHtml(action.target || "")}"`;
  if (action.type === "policy") return `data-policy-open="${escapeHtml(action.target || "")}" data-policy-open-target="${escapeHtml(action.targetMode || "best")}"`;
  if (action.type === "document") return `data-open-document="${escapeHtml(action.target || "")}"`;
  return customerTodoActionTarget(action);
}

function guidedCustomerTasks(stats = dashboardStats()) {
  const tasks = [];
  const onboarding = normalizeOnboarding(state.onboarding);
  const addTask = (task) => {
    if (!task?.title) return;
    tasks.push({
      kind: task.kind || "guided",
      category: task.category || "Eingabe",
      title: task.title,
      description: task.description || task.meta || "",
      meta: task.meta || "",
      status: task.status || "Offen",
      priority: Number(task.priority) || 50,
      effort: task.effort || "5-10 Min.",
      action: task.action || { label: task.actionLabel || "Öffnen", type: "view", target: task.view || "dashboard" }
    });
  };

  if (!onboardingProjectSetupReady(onboarding.project)) {
    addTask({
      kind: "project-setup",
      category: "Start",
      title: "Grundprojekt anlegen",
      description: "Projekt, Organisation, Ansprechpartner, Projektmodus und Zieltermin festlegen. Danach folgt das Startprofil.",
      status: "Offen",
      priority: 110,
      effort: "5 Min.",
      action: { label: "Grundprojekt öffnen", type: "jumpSection", view: "dashboard", target: "customerOnboarding", variant: "primary" }
    });
  } else if (!onboarding.completed) {
    addTask({
      kind: "onboarding",
      category: "Start",
      title: "Startprofil ausfüllen",
      description: "Scope, vorhandene Nachweise, kritische Assets, Lieferanten und erste Priorität erfassen.",
      status: "Offen",
      priority: 100,
      effort: "10-15 Min.",
      action: { label: "Startfragen öffnen", type: "jumpSection", view: "dashboard", target: "customerOnboarding", variant: "primary" }
    });
  } else {
    const onboardingDrafts = onboardingTemplateDrafts(onboarding);
    if (!onboardingDrafts.length) {
      addTask({
        kind: "onboarding-package",
        category: "Arbeitsvorlagen",
        title: "Arbeitsvorlagen aus Kundenangaben erzeugen",
        description: "Vorbereitete Arbeitsvorlagen und Nachweisverweise aus dem Startprofil anlegen.",
        status: "Offen",
        priority: 92,
        effort: "2 Min.",
        action: { label: "Arbeitsvorlagen öffnen", type: "jumpSection", view: "dashboard", target: "customerOnboarding", variant: "primary" }
      });
    }
    onboardingDrafts
      .map((draft) => ({ draft, quality: onboardingDraftQuality(draft), document: findDocumentForTemplateDraft(draft, draft.title) }))
      .filter(({ draft, quality, document }) => quality.missing.length || onboardingDraftNeedsRework(draft, document))
      .slice(0, 6)
      .forEach(({ draft, quality, document }) => {
        const rework = onboardingDraftNeedsRework(draft, document);
        addTask({
          kind: "onboarding-draft",
          category: rework ? "Nachbesserung" : "Arbeitsvorlagen",
          title: templateDraftDisplayTitle(draft, "Arbeitsvorlage vervollständigen"),
          description: rework
            ? (draft.reworkReason || document?.reworkReason || "Die Arbeitsvorlage wurde zur Nachbesserung zurückgegeben.")
            : `${quality.missing.length} Feld(er) in der Arbeitsvorlage ergänzen.`,
          status: rework ? "Überarbeiten" : quality.status,
          priority: rework ? 98 : quality.requiredMissing.length ? 90 : 74,
          effort: quality.requiredMissing.length ? "10 Min." : "5 Min.",
          action: { label: "Arbeitsvorlage öffnen", type: "openOnboardingDraft", target: draft.id, variant: rework ? "primary" : "quiet" }
        });
      });
  }

  soaRows()
    .filter(({ record }) => record.applicability === "Zu prüfen" || ["Offen", "Geplant"].includes(record.implementation) || !record.justification)
    .slice(0, 8)
    .forEach(({ control, record }) => {
      addTask({
        kind: "soa",
        category: "SoA",
        title: `${control.id} bewerten`,
        description: `${control.de}: Anwendbarkeit, Umsetzung, Owner und Nachweis ausfüllen.`,
        status: record.applicability === "Zu prüfen" ? "Zu prüfen" : record.implementation,
        priority: record.applicability === "Zu prüfen" ? 84 : 72,
        effort: "5 Min.",
        action: { label: "Control ausfüllen", type: "soa", target: control.id, variant: record.applicability === "Zu prüfen" ? "primary" : "quiet" }
      });
    });

  state.documents
    .filter((document) => document.status !== "Quelle")
    .filter((document) => !document.owner || !document.review || !(document.evidenceFor || document.linkedTo))
    .slice(0, 6)
    .forEach((document) => {
      const missing = [
        !document.owner ? "Owner" : "",
        !document.review ? "Review-Datum" : "",
        !(document.evidenceFor || document.linkedTo) ? "Zuordnung" : ""
      ].filter(Boolean).join(", ");
      addTask({
        kind: "document",
        category: "Nachweis",
        title: document.name || "Nachweis vervollständigen",
        description: `Bitte ${missing} ergänzen, damit der Nachweis prüfbar wird.`,
        status: "Metadaten offen",
        priority: 76,
        effort: "3 Min.",
        action: { label: "Nachweis öffnen", type: "document", target: document.id }
      });
    });

  state.templateDrafts
    .map((draft) => ({ draft, quality: onboardingDraftQuality(draft) }))
    .filter(({ quality }) => quality.missing.length)
    .slice(0, 5)
    .forEach(({ draft, quality }) => {
      addTask({
        kind: "template",
        category: "Template",
        title: draft.title || draft.templateTitle || "Vorlage ausfüllen",
        description: `${quality.missing.length} offene Feld(er) in der Vorlage ergänzen.`,
        status: quality.status,
        priority: quality.requiredMissing.length ? 82 : 62,
        effort: "5-10 Min.",
        action: { label: "Vorlage öffnen", type: "openTemplateDraft", target: draft.id }
      });
    });

  state.policies
    .filter((policy) => policy.status !== "Freigegeben")
    .slice(0, 5)
    .forEach((policy) => {
      addTask({
        kind: "policy",
        category: "Policy",
        title: policy.title || "Policy prüfen",
        description: `Status ${policy.status || "Entwurf"} · Owner: ${policy.owner || "offen"}.`,
        status: policy.status || "Entwurf",
        priority: policy.owner ? 56 : 68,
        effort: "5 Min.",
        action: { label: "Policy öffnen", type: "policy", target: policy.id }
      });
    });

  customerTodoItems(stats).slice(0, 8).forEach((todo) => {
    const action = Array.isArray(todo.actions) && todo.actions.length
      ? todo.actions[0]
      : todo.scrollTarget
        ? { label: todo.action || "Öffnen", type: "jumpSection", view: todo.view || "dashboard", target: todo.scrollTarget }
        : { label: todo.action || "Öffnen", type: "view", target: todo.view || "tasks" };
    addTask({
      kind: todo.kind || "todo",
      category: todo.category || "Aufgabe",
      title: todo.title,
      description: todo.meta || "",
      status: todo.status || "Offen",
      priority: todo.priority || 50,
      effort: todo.kind === "task" ? "abhängig von Aufgabe" : "5-10 Min.",
      action
    });
  });

  workspaceGapItems(stats).slice(0, 6).forEach((gap) => {
    addTask({
      kind: gap.kind || "gap",
      category: gap.category || "Fehlstelle",
      title: gap.title,
      description: gap.meta || "",
      status: gap.status || "Offen",
      priority: gap.priority || 60,
      effort: gap.category === "Nachweise" ? "5 Min." : "10 Min.",
      action: { label: gap.action || "Öffnen", type: "view", target: gap.view || "documents" }
    });
  });

  return deduplicateGuidedTasks(tasks)
    .sort((left, right) => right.priority - left.priority || String(left.title).localeCompare(String(right.title)));
}

function deduplicateGuidedTasks(tasks) {
  const seen = new Set();
  return tasks.filter((task) => {
    const key = normalizeImportKey(`${task.category} ${task.title}`);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function guidedPriorityLabel(priority) {
  if (priority >= 95) return "sofort";
  if (priority >= 85) return "wichtig";
  if (priority >= 70) return "als nächstes";
  return "später";
}

function renderWorkspaceGapRadar(stats = dashboardStats()) {
  const gaps = workspaceGapItems(stats);
  const critical = gaps.filter((gap) => gap.priority >= 85).length;
  const evidence = gaps.filter((gap) => gap.category === "Nachweise").length;
  const owners = gaps.filter((gap) => gap.category === "Verantwortung").length;
  const grouped = workspaceGapGroups(gaps);
  const taskDisabled = gaps.length && canEditWorkspace() ? "" : "disabled";
  return `
    <section class="panel gap-radar-panel">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Was fehlt mir noch?</span>
          <h3>Geführter Fehlstellen-Modus</h3>
          <p>Diese Sicht sammelt fehlende Nachweise, offene Owner, überfällige Reviews, offene Risiken, nicht freigegebene Policies und blockierte Aufgaben an einer Stelle.</p>
        </div>
        <div class="gap-radar-summary">
          <div class="${critical ? "warning" : ""}"><strong>${critical}</strong><span>kritisch</span></div>
          <div class="${evidence ? "warning" : ""}"><strong>${evidence}</strong><span>Nachweise</span></div>
          <div class="${owners ? "warning" : ""}"><strong>${owners}</strong><span>Owner offen</span></div>
        </div>
      </div>

      <div class="gap-radar-groups">
        ${grouped.map((group) => `
          <button class="gap-group-card ${group.count ? "active" : ""}" type="button" data-jump="${escapeHtml(group.view)}">
            <span>${escapeHtml(group.label)}</span>
            <strong>${group.count}</strong>
            <small>${escapeHtml(group.hint)}</small>
          </button>
        `).join("")}
      </div>

      <div class="gap-radar-list">
        ${gaps.length ? gaps.slice(0, 10).map((gap) => renderWorkspaceGapItem(gap)).join("") : `
          ${renderEmptyState("Keine wesentlichen Fehlstellen erkannt", "Die Plattform findet aktuell keine priorisierten Lücken. Reviews und Freigaben trotzdem regelmäßig prüfen.", [{ label: "Auditmatrix öffnen", view: "audit", primary: true }], { compact: true, mark: "OK" })}
        `}
      </div>

      <div class="gap-radar-actions">
        <button class="primary-button" type="button" data-workspace-gap-tasks ${taskDisabled}>Fehlstellen als Aufgaben anlegen</button>
        <button class="quiet-button" type="button" data-jump="audit">Auditmatrix öffnen</button>
        <button class="quiet-button" type="button" data-jump="documents">Nachweise öffnen</button>
      </div>
    </section>
  `;
}

function renderWorkspaceGapItem(gap) {
  return `
    <article class="gap-radar-item ${gap.priority >= 85 ? "critical" : ""}">
      <div class="gap-radar-rank">
        <strong>${escapeHtml(gap.scoreLabel || String(gap.priority))}</strong>
        <span>${gap.priority >= 85 ? "hoch" : gap.priority >= 65 ? "mittel" : "normal"}</span>
      </div>
      <div class="gap-radar-copy">
        <small>${escapeHtml(gap.category)}</small>
        <strong>${escapeHtml(gap.title)}</strong>
        <span>${escapeHtml(gap.meta || "")}</span>
      </div>
      <div class="gap-radar-state">
        ${statusTag(gap.status || "Offen")}
      </div>
      <div class="gap-radar-item-actions">
        <button class="${gap.priority >= 85 ? "primary-button" : "quiet-button"}" type="button" data-jump="${escapeHtml(gap.view || "tasks")}">${escapeHtml(gap.action || "Öffnen")}</button>
      </div>
    </article>
  `;
}

function workspaceGapItems(stats = dashboardStats()) {
  const gaps = [];
  const todayValue = today();
  const visibleDocuments = state.documents.filter((document) => document.status !== "Quelle");

  customerEvidenceGaps().forEach((gap) => {
    gaps.push({
      kind: "starter-gap",
      category: "Nachweise",
      title: gap.title,
      meta: gap.meta,
      view: gap.view || "documents",
      status: gap.status || "Offen",
      priority: 82,
      taskTitle: gap.title,
      module: viewToTaskModule(gap.view || "documents"),
      dueDays: 14
    });
  });

  documentEvidenceGaps(visibleDocuments).slice(0, 12).forEach((gap) => {
    gaps.push({
      kind: "evidence-gap",
      category: "Nachweise",
      title: gap.title,
      meta: gap.meta,
      view: gap.view || "documents",
      status: "Nachweis fehlt",
      priority: 78,
      taskTitle: `Nachweis ergänzen: ${gap.title}`,
      module: viewToTaskModule(gap.view || "documents"),
      dueDays: 14
    });
  });

  visibleDocuments
    .filter((document) => !document.owner || !document.version || !document.review || !(document.evidenceFor || document.linkedTo))
    .slice(0, 8)
    .forEach((document) => {
      const missing = [
        !document.owner ? "Owner" : "",
        !document.version ? "Version" : "",
        !document.review ? "Review" : "",
        !(document.evidenceFor || document.linkedTo) ? "Zuordnung" : ""
      ].filter(Boolean).join(", ");
      gaps.push({
        kind: "document-metadata",
        category: "Dokumente",
        title: document.name || "Dokument-Metadaten ergänzen",
        meta: `Fehlt: ${missing}`,
        view: "documents",
        status: "Metadaten offen",
        priority: 70,
        taskTitle: `Dokument-Metadaten ergänzen: ${document.name || "Nachweis"}`,
        module: "Dokumentation",
        dueDays: 10
      });
    });

  visibleDocuments
    .filter((document) => document.review && document.review < todayValue && !["Archiviert", "Quelle"].includes(document.status))
    .forEach((document) => {
      gaps.push({
        kind: "document-review",
        category: "Reviews",
        title: document.name || "Review überfällig",
        meta: `Review ${document.review} · Owner: ${document.owner || "offen"}`,
        view: "documents",
        status: "Review überfällig",
        priority: 88,
        taskTitle: `Review aktualisieren: ${document.name || "Dokument"}`,
        module: "Dokumentation",
        dueDays: 7
      });
    });

  addOwnerGap(gaps, "Asset Owner ergänzen", "assets", "Asset Management", state.assets, "name");
  addOwnerGap(gaps, "Risk Owner ergänzen", "risks", "Risiko Management", state.risks, "scenario");
  addOwnerGap(gaps, "Rechtsanforderung Owner ergänzen", "legal", "Rechtsregister", state.legal, "requirement");
  addOwnerGap(gaps, "Lieferanten-Owner ergänzen", "suppliers", "Vendor Management", state.suppliers, "name");
  addOwnerGap(gaps, "Policy Owner ergänzen", "policies", "Policy Management", state.policies, "title");
  addOwnerGap(gaps, "Incident Owner ergänzen", "incidents", "Incident Management", state.incidents, "title");
  addOwnerGap(gaps, "Contract Owner ergänzen", "contracts", "Contract Management", state.contracts, "title");
  addOwnerGap(gaps, "Aufgaben-Owner ergänzen", "tasks", "Task Management", state.tasks, "title");

  state.risks
    .filter((risk) => !["Akzeptiert", "Erledigt"].includes(risk.status))
    .filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10 || !risk.treatment || !risk.owner)
    .forEach((risk) => {
      const score = riskScore(risk.likelihood, risk.impact);
      gaps.push({
        kind: "risk-open",
        category: "Risiken",
        title: risk.riskId ? `${risk.riskId}: ${risk.scenario || risk.asset || "Risiko"}` : (risk.scenario || "Risiko prüfen"),
        meta: `Score ${score || "offen"} · Behandlung: ${risk.treatment ? "vorhanden" : "fehlt"} · Owner: ${risk.owner || "offen"}`,
        view: "risks",
        status: score >= 10 ? "Hoch" : (risk.status || "Offen"),
        priority: score >= 16 ? 95 : score >= 10 ? 88 : 72,
        taskTitle: `Risiko bearbeiten: ${risk.riskId || risk.asset || risk.scenario || "Risiko"}`,
        module: "Risiko Management",
        dueDays: score >= 10 ? 7 : 14,
        scoreLabel: score ? String(score) : "?"
      });
    });

  state.policies
    .filter((policy) => policy.status !== "Freigegeben" || !registerRowLinked("policies", policy))
    .forEach((policy) => {
      const artifact = resolvePolicyArtifact(policy);
      gaps.push({
        kind: "policy-open",
        category: "Policies",
        title: policy.title || "Policy prüfen",
        meta: `${policy.status || "Entwurf"} · ${artifact.document || artifact.draft || artifact.template ? "verknüpft" : "Dokument/Entwurf fehlt"}`,
        view: "policies",
        status: policy.status || "Entwurf",
        priority: artifact.document || artifact.draft || artifact.template ? 58 : 78,
        taskTitle: `Policy fertigstellen: ${policy.title || "Policy"}`,
        module: "Policy Management",
        dueDays: 14
      });
    });

  state.tasks
    .filter((task) => task.status !== "Erledigt" && task.due && task.due < todayValue)
    .forEach((task) => {
      gaps.push({
        kind: "task-overdue",
        category: "Aufgaben",
        title: task.title || "Aufgabe überfällig",
        meta: dueText(task.due, task.module || "Task Management"),
        view: moduleToView(task.module || "tasks"),
        status: "Überfällig",
        priority: 92,
        taskTitle: task.title || "Überfällige Aufgabe bearbeiten",
        module: task.module || "Task Management",
        dueDays: 3
      });
    });

  normalizeProjectPlan(state.projectPlan)
    .filter((item) => item.status === "Blockiert")
    .forEach((item) => {
      gaps.push({
        kind: "project-blocked",
        category: "Projekt",
        title: item.title,
        meta: `${item.stream} · ${item.phase} · Owner: ${item.owner || "offen"}`,
        view: "project",
        status: document.reviewStatus === "abgelehnt" || document.approval === "Abgelehnt" ? "Abgelehnt" : "Blockiert",
        priority: 90,
        taskTitle: `Blockade lösen: ${item.title}`,
        module: "Projektstrukturplan",
        dueDays: 5
      });
    });

  normalizeSocReports(state.socReports).forEach((report) => {
    const critical = numericValue(report.criticalAlerts);
    const high = numericValue(report.highAlerts);
    const findings = numericValue(report.openFindings);
    if (!critical && !high && !findings && report.status !== "Maßnahmen offen") return;
    gaps.push({
      kind: "soc-open",
      category: "SOC/SIEM",
      title: report.title || socReportTitle(report),
      meta: `${critical} kritisch · ${high} hoch · ${findings} offene Findings`,
      view: report.incidentAssessment === "Meldepflicht prüfen" ? "incidents" : "documents",
      status: report.status || "In Prüfung",
      priority: critical ? 94 : high ? 84 : 72,
      taskTitle: `SOC/SIEM-Finding bearbeiten: ${report.title || socReportTitle(report)}`,
      module: report.incidentAssessment === "Meldepflicht prüfen" ? "Incident Management" : "Dokumentation",
      dueDays: critical ? 3 : 10
    });
  });

  return deduplicateWorkspaceGaps(gaps)
    .sort((left, right) => right.priority - left.priority || String(left.title).localeCompare(String(right.title)));
}

function addOwnerGap(gaps, title, view, module, rows = [], labelKey = "title") {
  const missing = rows.filter((row) => !row.owner);
  if (!missing.length) return;
  const examples = missing.slice(0, 3).map((row) => row[labelKey] || row.name || row.title || row.requirement || "Eintrag").join(", ");
  gaps.push({
    kind: `${view}-owner`,
    category: "Verantwortung",
    title,
    meta: `${missing.length} Eintrag(e) ohne Owner · ${examples}`,
    view,
    status: "Owner offen",
    priority: missing.length >= 3 ? 76 : 64,
    taskTitle: title,
    module,
    dueDays: 10
  });
}

function workspaceGapGroups(gaps) {
  const groups = [
    ["Nachweise", "documents", "fehlende oder nicht verknüpfte Nachweise"],
    ["Dokumente", "documents", "Metadaten, Zuordnung und Dokumentenlenkung"],
    ["Verantwortung", "tasks", "Owner und Zuständigkeiten offen"],
    ["Reviews", "documents", "überfällige Dokumentenreviews"],
    ["Risiken", "risks", "offene oder hohe Risiken"],
    ["Policies", "policies", "Entwürfe, Freigaben, Verknüpfungen"],
    ["Aufgaben", "tasks", "überfällig oder blockiert"],
    ["Projekt", "project", "blockierte Arbeitspakete"],
    ["SOC/SIEM", "documents", "offene Findings oder Alerts"]
  ];
  return groups.map(([label, view, hint]) => ({
    label,
    view,
    hint,
    count: gaps.filter((gap) => gap.category === label).length
  }));
}

function deduplicateWorkspaceGaps(gaps) {
  const seen = new Set();
  return gaps.filter((gap) => {
    const key = normalizeImportKey(`${gap.kind} ${gap.title} ${gap.meta}`);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function viewToTaskModule(view) {
  const map = {
    documents: "Dokumentation",
    assets: "Asset Management",
    risks: "Risiko Management",
    legal: "Rechtsregister",
    suppliers: "Vendor Management",
    policies: "Policy Management",
    incidents: "Incident Management",
    contracts: "Contract Management",
    tasks: "Task Management",
    project: "Projektstrukturplan",
    audit: "Audit"
  };
  return map[view] || "Task Management";
}

function renderCustomerTodoItem(item, index) {
  const actions = Array.isArray(item.actions) && item.actions.length
    ? item.actions
    : [customerTodoDefaultAction(item)];
  return `
    <article class="customer-todo-item ${item.priority >= 85 ? "urgent" : ""}">
      <span class="customer-todo-rank">${index + 1}</span>
      <div class="customer-todo-copy">
        <small>${escapeHtml(item.category)}</small>
        <strong>${escapeHtml(item.title)}</strong>
        <span>${escapeHtml(item.meta || "")}</span>
        ${item.guidance ? renderCustomerReworkGuidance(item.guidance) : ""}
      </div>
      <div class="customer-todo-state">
        ${statusTag(item.status || "Offen")}
      </div>
      <div class="customer-todo-actions">
        ${actions.map((action, actionIndex) => renderCustomerTodoAction(action, item.priority >= 85 && actionIndex === 0)).join("")}
      </div>
    </article>
  `;
}

function customerTodoDefaultAction(item) {
  return item.scrollTarget
    ? { label: item.action || "Öffnen", type: "scroll", target: item.scrollTarget }
    : { label: item.action || "Öffnen", type: "view", target: item.view || "tasks" };
}

function renderCustomerTodoAction(action, primary = false) {
  const target = customerTodoActionTarget(action);
  if (!target) return "";
  const variant = action.variant || (primary ? "primary" : "quiet");
  const disabled = action.disabled ? "disabled" : "";
  return `<button class="${variant === "primary" ? "primary-button" : "quiet-button"}" type="button" ${target} ${disabled}>${escapeHtml(action.label || "Öffnen")}</button>`;
}

function customerTodoActionTarget(action) {
  if (action.type === "scroll") return `data-scroll-target="${escapeHtml(action.target || "")}"`;
  if (action.type === "view") return `data-jump="${escapeHtml(action.target || "tasks")}"`;
  if (action.type === "document") return `data-open-document="${escapeHtml(action.target || "")}"`;
  if (action.type === "documentSubmit") return `data-document-submit="${escapeHtml(action.target || "")}"`;
  if (action.type === "registerSubmit") return `data-register-submit="${escapeHtml(action.target || "")}"`;
  if (action.type === "openTemplateDraft") return `data-open-template-draft="${escapeHtml(action.target || "")}"`;
  if (action.type === "templateDraftSubmit") return `data-template-draft-submit="${escapeHtml(action.target || "")}"`;
  if (action.type === "openOnboardingDraft") return `data-open-onboarding-draft="${escapeHtml(action.target || "")}"`;
  if (action.type === "resubmitOnboardingDraft") return `data-onboarding-resubmit-draft="${escapeHtml(action.target || "")}"`;
  if (action.type === "templateDraftDocument") return `data-template-draft-document="${escapeHtml(action.target || "")}"`;
  return "";
}

