function customerCockpitData(stats) {
  const openTasks = taskEngine.sort(state.tasks).filter(taskEngine.isOpen);
  const overdueTasks = openTasks.filter((task) => taskEngine.isOverdue(task));
  const policyDrafts = state.policies.filter((policy) => policy.status !== "Freigegeben");
  const docsNeedingReview = state.documents
    .filter((document) => document.status !== "Quelle" && document.status !== "Archiviert")
    .filter((document) => document.review && document.review <= futureDate(30))
    .sort((left, right) => String(left.review).localeCompare(String(right.review)));
  const missingEvidence = customerEvidenceGaps();

  const next = overdueTasks[0]
    ? { title: overdueTasks[0].title || "Überfällige Aufgabe prüfen", text: dueText(overdueTasks[0].due, overdueTasks[0].module || "Task Management"), action: "Aufgabe öffnen", view: "tasks" }
    : missingEvidence[0]
      ? { title: missingEvidence[0].title, text: missingEvidence[0].meta, action: "Nachweise prüfen", view: missingEvidence[0].view }
      : policyDrafts[0]
        ? { title: policyDrafts[0].title || "Policy prüfen", text: `Status: ${policyDrafts[0].status || "Entwurf"} · Owner: ${policyDrafts[0].owner || "offen"}`, action: "Policy öffnen", view: "policies" }
        : openTasks[0]
          ? { title: openTasks[0].title || "Aufgabe bearbeiten", text: dueText(openTasks[0].due, openTasks[0].module || "Task Management"), action: "Aufgabe öffnen", view: "tasks" }
          : { title: "Arbeitsstand prüfen", text: "Projektplan, Policies und Nachweise sind aktuell ohne dringenden Blocker.", action: "Projektplan öffnen", view: "project" };

  return {
    next,
    tasks: openTasks.slice(0, 5).map((task) => ({
      title: task.title || "Unbenannte Aufgabe",
      meta: dueText(task.due, task.module || "Task Management"),
      view: moduleToView(task.module || "Task Management"),
      status: task.status || "Offen"
    })),
    evidence: missingEvidence.slice(0, 5),
    reviews: docsNeedingReview.slice(0, 5).map((document) => ({
      title: document.name || "Dokument reviewen",
      meta: `Review ${document.review} · ${document.owner || "Owner offen"}`,
      view: "documents",
      status: document.review < today() ? "Blockiert" : "In Arbeit"
    }))
  };
}

function customerEvidenceGaps() {
  const gaps = [];
  const nonSourceDocuments = state.documents.filter((document) => document.status !== "Quelle");
  if (!nonSourceDocuments.length) {
    gaps.push({ title: "Erste Nachweise hochladen", meta: "Noch keine Kundennachweise im Dokumentationsregister.", view: "documents", status: "Offen" });
  }
  if (!state.assets.length) {
    gaps.push({ title: "Asset-Liste starten", meta: "Kritische Systeme und Informationen fehlen noch.", view: "assets", status: "Offen" });
  }
  if (!state.risks.length) {
    gaps.push({ title: "Risikoregister starten", meta: "Noch keine Informationssicherheitsrisiken erfasst.", view: "risks", status: "Offen" });
  }
  if (!state.suppliers.length) {
    gaps.push({ title: "Lieferanten erfassen", meta: "Kritische Dienstleister und Cloud-Anbieter prüfen.", view: "suppliers", status: "Offen" });
  }
  const policiesWithoutArtifact = state.policies.filter((policy) => {
    const artifact = resolvePolicyArtifact(policy);
    return !artifact.draft && !artifact.document && !artifact.template;
  });
  if (policiesWithoutArtifact.length) {
    gaps.push({ title: "Policies verknüpfen", meta: `${policiesWithoutArtifact.length} Policy-Eintrag(e) ohne Dokument oder Vorlage.`, view: "policies", status: "In Arbeit" });
  }
  return gaps;
}

function cockpitListRow(item) {
  return `
    <button class="cockpit-list-row" type="button" data-jump="${escapeHtml(item.view || "tasks")}">
      <span>
        <strong>${escapeHtml(item.title)}</strong>
        <small>${escapeHtml(item.meta || "")}</small>
      </span>
      ${statusTag(item.status || "Offen")}
    </button>
  `;
}

function dueText(due, module = "") {
  if (!due) return module || "Keine Frist gesetzt";
  const prefix = due < today() ? "Überfällig" : "Fällig";
  return `${prefix} ${due}${module ? ` · ${module}` : ""}`;
}

