function backendSyncText() {
  if (!backendSessionChecked) return "Session wird geprüft";
  if (!backendSessionUser) return "Lokal, nicht angemeldet";
  if (backendSync.sessionExpired) return "Sitzung abgelaufen - lokal gesichert";
  if (backendSync.saving) return "Speichert ...";
  if (backendSync.conflict) return "Speicherkonflikt - neu laden und abgleichen";
  if (backendSync.online === false) return "Offline - lokal gesichert";
  if (backendSync.error) return `Speicherung prüfen: ${backendSync.error}`;
  if (backendSync.dirty) return "Änderungen ausstehend";
  if (backendSync.savedAt) return `Gespeichert ${formatBackendTime(backendSync.savedAt)}`;
  if (backendSync.loaded) return "Verbunden";
  return "Bereit";
}

function formatBackendTime(value) {
  if (!value) return "noch nicht";
  const date = typeof value === "number" ? new Date(value * 1000) : new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  });
}

function formatDateOnly(value) {
  if (!value) return "";
  const normalized = /^\d{4}-\d{2}-\d{2}$/.test(String(value))
    ? `${value}T00:00:00`
    : value;
  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric"
  });
}

