function renderIntegrationVisual() {
  const nodes = INTEGRATION_CATALOG.slice(0, 10);
  return `
    <div class="integration-visual" aria-hidden="true">
      <div class="integration-line line-a"></div>
      <div class="integration-line line-b"></div>
      <div class="integration-line line-c"></div>
      <div class="integration-hub">SFM</div>
      ${nodes.map((node, index) => `
        <span class="integration-node node-${index + 1}">${escapeHtml(integrationInitials(node.name))}</span>
      `).join("")}
    </div>
  `;
}

function integrationInitials(name) {
  const compact = String(name || "").replace(/[^A-Za-z0-9 ]/g, " ").trim();
  const words = compact.split(/\s+/).filter(Boolean);
  if (!words.length) return "API";
  if (words.length === 1) return words[0].slice(0, 3).toUpperCase();
  return words.slice(0, 2).map((word) => word[0]).join("").toUpperCase();
}

