function reviewRegisterItems(collection) {
  const rows = registerRows(collection);
  const typeLabels = {
    legal: "Rechtsregister",
    suppliers: "Lieferant",
    incidents: "Incident",
    contracts: "Vertrag"
  };
  return rows
    .map((row) => {
      const summary = registerRowSummary(collection, row);
      const reviewStatus = canonicalReviewStatus(row, collection);
      const overdue = registerRowOverdue(collection, row);
      const missing = [
        !row.owner ? "Owner fehlt" : "",
        !registerRowLinked(collection, row) ? "Nachweis fehlt" : "",
        collection === "legal" && !row.source ? "Quelle fehlt" : "",
        collection === "suppliers" && !row.service ? "Leistung fehlt" : "",
        collection === "incidents" && !row.note ? "Erstbewertung fehlt" : "",
        collection === "contracts" && !row.linkedTo ? "Zuordnung fehlt" : "",
        overdue ? "Termin überfällig" : ""
      ].filter(Boolean);
      const needsReview = missing.length
        || recordAuditRelevant(row)
        || ["vom_kunden_eingereicht", "in_beraterpruefung", "nacharbeit_noetig", "abgelehnt", "auditrelevant"].includes(reviewStatus);
      if (!needsReview) return null;
      return makeReviewItem({
        key: `${collection}:${row.id}`,
        id: row.id,
        rawType: collection,
        type: typeLabels[collection] || "Register",
        title: summary.title,
        owner: row.owner,
        reviewStatus,
        priority: overdue || recordAuditRelevant(row) || ["Hoch", "Sehr hoch", "Kritisch"].includes(row.criticality || row.severity) ? "Hoch" : "Mittel",
        module: registerFullModuleLabel(collection),
        modified: row.reviewUpdatedAt || row.updated || row.added || row.due || row.review || row.nextReview || "",
        resubmittedAfterReworkAt: row.resubmittedAfterReworkAt || "",
        resubmissionCount: row.resubmissionCount || 0,
        reason: missing.join(", ") || "Registereintrag fachlich prüfen.",
        customerInput: [summary.subtitle, summary.meta, row.note].filter(Boolean).join(" · "),
        linkedEvidence: findLinkedDocuments(rowReferenceValues(row), { limit: 1 })[0]?.name || row.evidence || row.linkedTo || "",
        mapping: row.framework || row.linkedTo || row.source || registerFullModuleLabel(collection),
        documentId: findLinkedDocuments(rowReferenceValues(row), { limit: 1 })[0]?.id || "",
        auditBlocker: isAuditRelevantOpen(row) || reviewStatus === "nacharbeit_noetig" || reviewStatus === "abgelehnt"
      });
    })
    .filter(Boolean);
}

function makeReviewItem(item) {
  const record = reviewRecordByKey(item.key) || {};
  const resubmitted = Boolean(item.resubmittedAfterReworkAt || Number(item.resubmissionCount || 0));
  return {
    ...item,
    reviewStatus: normalizeReviewStatus(item.reviewStatus),
    priority: item.priority || "Mittel",
    modified: item.modified || "-",
    reason: item.reason || "Zur Prüfung vormerken.",
    resubmitted,
    resubmittedAfterReworkAt: item.resubmittedAfterReworkAt || "",
    resubmissionCount: Number(item.resubmissionCount || 0),
    customerInput: item.customerInput || "",
    linkedEvidence: item.linkedEvidence || "",
    mapping: item.mapping || "",
    templateDraftId: item.templateDraftId || "",
    reviewAssignee: record.reviewAssignee || record.reviewer || "",
    reviewDue: reviewSafeDate(record.reviewDue || record.reworkDue || ""),
    auditBlocker: Boolean(item.auditBlocker)
  };
}

function reviewPriorityScore(item) {
  const priority = item.priority === "Kritisch" ? 90 : item.priority === "Hoch" ? 70 : item.priority === "Mittel" ? 45 : 25;
  const status = {
    nacharbeit_noetig: 35,
    abgelehnt: 35,
    vom_kunden_eingereicht: 30,
    in_beraterpruefung: 20,
    auditrelevant: 25,
    review_ueberfaellig: 35,
    spaeter_pruefen: 5,
    offen: 10,
    entwurf: 10,
    archiviert: 0,
    freigegeben: 0
  }[item.reviewStatus] || 0;
  return priority + status + (item.auditBlocker ? 40 : 0) + (item.resubmitted ? 12 : 0);
}

function normalizeReviewStatus(status) {
  return reviewWorkflow.normalize(status);
}

function reviewStatusLabel(status) {
  return reviewWorkflow.label(status);
}

function inferReviewStatusFromDocument(document = {}) {
  return reviewWorkflow.inferDocument(document);
}

function canonicalReviewStatus(record = {}, type = "") {
  return reviewWorkflow.canonical(record, type);
}

function recordAuditRelevant(record = {}) {
  return reviewWorkflow.isAuditRelevant(record);
}

function isAuditRelevantOpen(record = {}) {
  return reviewWorkflow.isAuditRelevantOpen(record);
}

function reviewRecordByKey(key) {
  const { type, id } = parseReviewKey(key);
  if (type === "document") return state.documents.find((item) => item.id === id) || null;
  if (type === "risk") return state.risks.find((item) => item.id === id) || null;
  if (type === "policy") return state.policies.find((item) => item.id === id) || null;
  if (type === "task") return state.tasks.find((item) => item.id === id) || null;
  if (type === "asset") return state.assets.find((item) => item.id === id) || null;
  if (type === "legal") return state.legal.find((item) => item.id === id) || null;
  if (type === "suppliers") return state.suppliers.find((item) => item.id === id) || null;
  if (type === "incidents") return state.incidents.find((item) => item.id === id) || null;
  if (type === "contracts") return state.contracts.find((item) => item.id === id) || null;
  if (type === "auditFinding") return state.auditFindings.find((item) => String(item.id) === String(id)) || null;
  if (type === "managementReview") return state.managementReview || null;
  if (type === "internalAuditPlan") return state.internalAuditPlan || null;
  if (type === "soa") return getMutableSoaRecord(id);
  return null;
}

function parseReviewKey(key = "") {
  const [type, ...rest] = String(key).split(":");
  return { type, id: rest.join(":") };
}

function getMutableSoaRecord(controlId) {
  let record = state.soa.find((item) => item.controlId === controlId);
  const control = ANNEX_CONTROLS.find((item) => item.id === controlId);
  if (!record && control) {
    record = defaultSoaRecord(control);
    state.soa.push(record);
  }
  return record || null;
}

function auditPackageGate(items = reviewCenterItems()) {
  const visibleDocuments = state.documents.filter((document) => document.status !== "Quelle");
  const bundle = auditEvidenceBundleData(visibleDocuments);
  const templateDraftOpen = auditPackageTemplateDraftOpenItems();
  return auditPackageGateEngine.evaluate({
    documents: visibleDocuments.map((document) => ({
      title: document.name || "Nachweis",
      auditRelevant: recordAuditRelevant(document),
      approved: document.status === "Freigegeben" || document.approval === "Freigegeben" || document.reviewStatus === "freigegeben"
    })),
    risks: state.risks.map((risk) => ({
      title: risk.riskId || risk.scenario || "Risiko",
      critical: riskScore(risk.likelihood, risk.impact) >= 10,
      treatment: Boolean(risk.treatment),
      approved: canonicalReviewStatus(risk, "risk") === "freigegeben"
    })),
    soa: normalizeSoaRegister(state.soa).map((record) => ({
      title: record.controlId,
      auditRelevant: recordAuditRelevant(record),
      approved: canonicalReviewStatus(record, "soa") === "freigegeben"
    })),
    policies: state.policies.map((policy) => ({
      title: policy.title || "Policy",
      auditRelevant: recordAuditRelevant(policy),
      approved: policy.status === "Freigegeben"
    })),
    drafts: templateDraftOpen.map((row) => ({
      title: templateDraftDisplayTitle(row.draft, "Arbeitsvorlage"),
      open: true,
      approved: false
    })),
    capa: capaAuditPackageGateItems(),
    reviewItems: items.map((item) => ({
      type: item.type,
      title: item.title,
      auditBlocker: item.auditBlocker,
      approved: item.reviewStatus === "freigegeben"
    })),
    bundle
  });
}

function auditPackageTemplateDraftOpenItems() {
  return (state.templateDrafts || [])
    .map((draft) => {
      const document = findDocumentForTemplateDraft(draft, draft.title);
      const status = canonicalReviewStatus(document || draft, document ? "document" : "templateDraft");
      const template = TEMPLATE_LIBRARY.find((item) => item.id === draft.templateId);
      const policyLike = isPolicyLikeTemplate(template || {
        id: draft.templateId || "",
        title: draft.templateTitle || draft.title || "",
        area: draft.area || draft.documentKind || ""
      });
      const auditRelevant = recordAuditRelevant(draft) || (document && recordAuditRelevant(document)) || policyLike;
      const openStatus = ["vom_kunden_eingereicht", "in_beraterpruefung", "nacharbeit_noetig", "abgelehnt", "auditrelevant"].includes(status);
      if (!openStatus && !auditRelevant) return null;
      if (status === "freigegeben" || draft.status === "Freigegeben" || draft.approval === "Freigegeben") return null;
      return { draft, document, status, auditRelevant, policyLike };
    })
    .filter(Boolean);
}

function canApproveAuditPackage() {
  return canReviewDocuments() || isBackendAdmin();
}

function auditPackageFingerprint(payload = {}) {
  return window.SFMVersioning.fingerprint(payload, "pkg");
}

function auditPackageFingerprintPayload(data = {}) {
  const documents = (data.documents || []).map((document) => [
    document.id || "",
    document.version || "",
    document.status || "",
    document.approval || "",
    document.reviewStatus || "",
    document.linkedTo || document.evidenceFor || "",
    recordAuditRelevant(document) ? "auditrelevant" : ""
  ]).sort();
  const risks = (data.risks || []).map((risk) => [
    risk.id || "",
    risk.riskId || "",
    risk.status || "",
    risk.treatment || "",
    canonicalReviewStatus(risk, "risk"),
    riskScore(risk.likelihood, risk.impact)
  ]).sort();
  const policies = state.policies.map((policy) => [
    policy.id || "",
    policy.title || "",
    policy.version || "",
    policy.status || "",
    canonicalReviewStatus(policy, "policy"),
    recordAuditRelevant(policy) ? "auditrelevant" : ""
  ]).sort();
  const soa = (data.soa || []).map((record) => [
    record.controlId || "",
    record.applicability || "",
    record.implementation || "",
    canonicalReviewStatus(record, "soa"),
    record.evidence || "",
    recordAuditRelevant(record) ? "auditrelevant" : ""
  ]).sort();
  const templateDrafts = (state.templateDrafts || []).map((draft) => [
    draft.id || "",
    draft.templateId || "",
    draft.title || draft.templateTitle || "",
    draft.version || draft.data?.version || "",
    draft.status || "",
    draft.approval || "",
    canonicalReviewStatus(findDocumentForTemplateDraft(draft, draft.title) || draft, findDocumentForTemplateDraft(draft, draft.title) ? "document" : "templateDraft"),
    recordAuditRelevant(draft) ? "auditrelevant" : ""
  ]).sort();

  return {
    progress: data.stats?.progress || {},
    gate: {
      blockers: data.gate?.blockers || [],
      criteria: (data.gate?.criteria || []).map((criterion) => [criterion.label, criterion.open])
    },
    bundle: {
      ready: data.bundle?.ready || 0,
      open: data.bundle?.open || 0,
      missing: data.bundle?.missing || 0,
      total: data.bundle?.total || 0
    },
    documents,
    risks,
    policies,
    soa,
    templateDrafts,
    review: {
      submitted: data.reviewMetrics?.submitted || 0,
      inReview: data.reviewMetrics?.inReview || 0,
      returns: data.reviewMetrics?.returns || 0,
      approved: data.reviewMetrics?.approved || 0
    }
  };
}

function auditPackageApprovals() {
  return normalizeAuditPackageState(state.auditPackage).approvals;
}

function currentAuditPackageApproval(fingerprint) {
  if (!fingerprint) return null;
  return auditPackageApprovals().find((approval) => approval.status === "beraterfreigegeben" && approval.fingerprint === fingerprint) || null;
}

function latestAuditPackageApproval() {
  return auditPackageApprovals()[0] || null;
}

function nextAuditPackageVersion() {
  const latest = latestAuditPackageApproval();
  return window.SFMVersioning.nextSequence(latest?.version || "0");
}

function auditPackageReportData() {
  const stats = dashboardStats();
  const reviewItems = reviewCenterItems();
  const reviewMetrics = reviewCenterMetrics(reviewItems);
  const gate = auditPackageGate(reviewItems);
  const documents = state.documents.filter((document) => document.status !== "Quelle");
  const docMetrics = documentWorkflowMetrics(documents);
  const traceRows = auditTraceabilityRows(documents);
  const bundle = auditEvidenceBundleData(documents);
  const soa = normalizeSoaRegister(state.soa);
  const risks = [...state.risks].sort((left, right) => riskScore(right.likelihood, right.impact) - riskScore(left.likelihood, left.impact));
  const highRisks = risks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10 || ["Hoch", "Sehr hoch", "Kritisch"].includes(risk.level || risk.status));
  const approvedDocuments = documents.filter((document) => document.status === "Freigegeben" || document.approval === "Freigegeben" || document.reviewStatus === "freigegeben");
  const submittedDocuments = documents.filter((document) => document.status === "In Prüfung" || document.approval === "Prüfung läuft" || document.reviewStatus === "vom_kunden_eingereicht");
  const auditRelevantDocuments = documents.filter(recordAuditRelevant);
  const openTasks = state.tasks.filter((task) => task.status !== "Erledigt");
  const overdueTasks = openTasks.filter((task) => task.due && task.due < today());
  const policyOpen = state.policies.filter((policy) => policy.status !== "Freigegeben");
  const templateDrafts = state.templateDrafts || [];
  const templateDraftOpen = auditPackageTemplateDraftOpenItems();
  const formalPercent = percentOf(bundle.ready, bundle.total);
  const baseData = {
    stats,
    reviewItems,
    reviewMetrics,
    gate,
    documents,
    docMetrics,
    traceRows,
    bundle,
    soa,
    risks
  };
  const packageFingerprint = auditPackageFingerprint(auditPackageFingerprintPayload(baseData));
  const packageApproval = currentAuditPackageApproval(packageFingerprint);
  const latestPackageApproval = latestAuditPackageApproval();
  const approvalStale = Boolean(latestPackageApproval && !packageApproval);
  const packageStatus = packageApproval
    ? "beraterfreigegeben und exportbereit"
    : gate.consultantApproved
      ? "Gate formal erfüllt, aber noch nicht explizit durch den Berater freigegeben"
      : "vorbereitet, aber noch nicht durch den Berater freigegeben";
  return {
    stats,
    reviewItems,
    reviewMetrics,
    gate,
    documents,
    docMetrics,
    traceRows,
    bundle,
    soa,
    risks,
    highRisks,
    approvedDocuments,
    submittedDocuments,
    auditRelevantDocuments,
    openTasks,
    overdueTasks,
    policyOpen,
    templateDrafts,
    templateDraftOpen,
    formalPercent,
    packageStatus,
    packageFingerprint,
    packageApproval,
    latestPackageApproval,
    approvalStale,
    latestAuditEvents: auditTrailEvents().slice(0, 12),
    latestVersions: auditVersionRows().slice(0, 10)
  };
}

function renderAuditPackageGenerator() {
  const data = auditPackageReportData();
  const contents = auditPackageContentCards(data);
  const nextSteps = auditPackageNextSteps(data);
  return `
    <div class="audit-package-generator-workspace">
      ${renderWorkspaceCommandPanel("auditpackage")}

      ${renderAuditPackageDecisionBoard(data)}

      <section class="panel audit-package-generator-next">
        <div>
          <span class="eyebrow">Nächster sinnvoller Schritt</span>
          <h3>${escapeHtml(nextSteps[0]?.title || "Auditpaket weiter vorbereiten")}</h3>
          <p>${escapeHtml(nextSteps[0]?.text || "Offene Gate-Punkte prüfen und danach den aktuellen Paketstand durch Berater/Admin freigeben.")}</p>
        </div>
        <div class="audit-package-generator-next-actions">
          ${data.gate.blockers.length ? `<button class="primary-button" type="button" data-audit-package-tasks>Blocker als Aufgaben</button>` : ""}
          <button class="quiet-button" type="button" data-jump="${escapeHtml(nextSteps[0]?.view || "review")}">${escapeHtml(nextSteps[0]?.label || "Bereich öffnen")}</button>
        </div>
      </section>

      <section class="panel audit-package-contents-panel">
        <div class="panel-header">
          <div>
            <span class="eyebrow">Paketbestandteile</span>
            <h3>Was in das Auditpaket einfließt</h3>
            <p>Die Plattform bündelt vorhandene Daten. Freigaben und fachliche Bewertung bleiben bewusst getrennt sichtbar.</p>
          </div>
        </div>
        <div class="audit-package-content-grid">
          ${contents.map(renderAuditPackageContentCard).join("")}
        </div>
      </section>

      ${renderAuditPackageReportPanel(data)}
      ${renderAuditPackageApprovalHistory(data)}
      ${renderAuditEvidenceBundle(data.documents)}
    </div>
  `;
}

function renderAuditPackageDecisionBoard(data = auditPackageReportData()) {
  const blockerCount = data.gate.blockers.length;
  const latestChange = data.latestAuditEvents[0] ? formatAuditTime(data.latestAuditEvents[0]) : "Noch kein Audit-Trail-Ereignis";
  const cards = [
    {
      eyebrow: "Automatisch vorbereitet",
      title: `${data.formalPercent}% formaler Arbeitsstand`,
      text: `${data.bundle.ready}/${data.bundle.total} Paketpunkte sind formal befüllt. Die Plattform zeigt damit nur Vorbereitung und Lücken, keine fachliche Erfüllung.`,
      status: data.bundle.missing ? `${data.bundle.missing} fehlen` : "formal vollständig",
      tone: data.bundle.missing ? "active" : "done"
    },
    {
      eyebrow: "Beraterentscheidung",
      title: data.packageApproval ? "Paketstand freigegeben" : blockerCount ? `${blockerCount} Blocker offen` : "Freigabe bewusst setzen",
      text: data.packageApproval
        ? "Der aktuelle Fingerprint wurde durch Berater/Admin freigegeben und im Audit Trail protokolliert."
        : blockerCount
          ? "Diese Punkte müssen fachlich geprüft, zurückgegeben oder geschlossen werden, bevor eine Freigabe möglich ist."
          : "Das Gate erkennt keine offenen Blocker. Berater/Admin muss den Paketstand trotzdem explizit freigeben.",
      status: data.packageApproval ? "beraterfreigegeben" : blockerCount ? "nicht freigabefähig" : "freigabefähig",
      tone: data.packageApproval ? "done" : blockerCount ? "warning" : "active"
    },
    {
      eyebrow: "Exportlogik",
      title: data.packageApproval ? "Freigegebener Export möglich" : "Export bleibt vorbereitet",
      text: data.packageApproval
        ? "Bericht und Evidence Bundle können als freigegebener Arbeitsstand exportiert werden. Eine externe Auditentscheidung wird nicht ersetzt."
        : "Berichte können erstellt werden; ein freigegebenes Evidence Bundle bleibt bis zur Beraterfreigabe gesperrt.",
      status: data.packageApproval ? "exportbereit" : "Freigabe fehlt",
      tone: data.packageApproval ? "done" : "active"
    }
  ];
  return `
    <section class="panel audit-package-decision-board">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Abschlusslogik</span>
          <h3>Vorbereitung, Beraterfreigabe und Export sauber trennen</h3>
          <p>Damit Kunden nicht denken, die Plattform habe automatisch „auditbereit“ entschieden: Das Paket wird vorbereitet, aber Freigabe und Bewertung bleiben beim Berater/Admin.</p>
        </div>
        <div class="audit-package-fingerprint-box">
          <span>Aktueller Paketstand</span>
          <strong>${escapeHtml(data.packageFingerprint)}</strong>
          <small>Letztes Ereignis: ${escapeHtml(latestChange)}</small>
        </div>
      </div>
      <div class="audit-package-decision-grid">
        ${cards.map((card) => `
          <article class="${escapeHtml(card.tone)}">
            <span>${escapeHtml(card.eyebrow)}</span>
            <strong>${escapeHtml(card.title)}</strong>
            <p>${escapeHtml(card.text)}</p>
            <em>${escapeHtml(card.status)}</em>
          </article>
        `).join("")}
      </div>
      <div class="audit-package-decision-actions">
        ${blockerCount ? `<button class="primary-button" type="button" data-audit-package-tasks>Blocker als Kundenaufgaben anlegen</button>` : ""}
        <button class="quiet-button" type="button" data-jump="review">Beraterprüfung öffnen</button>
        <button class="quiet-button" type="button" data-jump="audittrail">Audit Trail öffnen</button>
      </div>
    </section>
  `;
}

function auditPackageGeneratorStatus(data = auditPackageReportData()) {
  if (data.packageApproval) {
    return {
      title: "Auditpaket ist beraterfreigegeben",
      text: "Dieser konkrete Paketstand wurde durch Berater/Admin freigegeben und ist als Arbeitsstand exportbereit. Das ersetzt keine externe Auditentscheidung.",
      badge: "Freigegeben",
      tone: "done"
    };
  }
  if (data.gate.consultantApproved) {
    return {
      title: "Auditpaket ist formal vorbereitet",
      text: "Es sind keine offenen Gate-Blocker erkannt. Jetzt muss Berater/Admin den Paketstand bewusst freigeben.",
      badge: "Freigabe offen",
      tone: "active"
    };
  }
  return {
    title: "Auditpaket ist vorbereitet, aber noch blockiert",
    text: "Die Plattform hat offene Gate-Punkte gefunden. Diese müssen geprüft, nachgearbeitet oder fachlich entschieden werden.",
    badge: `${data.gate.blockers.length} Blocker`,
    tone: "warning"
  };
}

function auditPackageContentCards(data = auditPackageReportData()) {
  const soaCounts = auditPackageSoaCounts(data.soa);
  const templateApproved = data.templateDrafts.filter((draft) => {
    const document = findDocumentForTemplateDraft(draft, draft.title);
    const status = canonicalReviewStatus(document || draft, document ? "document" : "templateDraft");
    return status === "freigegeben" || draft.status === "Freigegeben" || draft.approval === "Freigegeben";
  }).length;
  return [
    {
      title: "Projektstrukturplan",
      value: `${data.stats.progress.done}/${data.stats.progress.total}`,
      text: "ISO, NIS-2 und gemeinsame Arbeitspakete mit Ownern und Status.",
      view: "project",
      status: `${data.stats.progress.percent}%`,
      tone: data.stats.progress.percent >= 80 ? "done" : "active"
    },
    {
      title: "Evidence Bundle",
      value: `${data.bundle.ready}/${data.bundle.total}`,
      text: "Nachweise nach ISO, NIS-2, Policies, Risiken und Betrieb gruppiert.",
      view: "documents",
      status: data.bundle.missing ? `${data.bundle.missing} fehlen` : "bereit",
      tone: data.bundle.missing ? "warning" : "done"
    },
    {
      title: "SoA Matrix",
      value: `${soaCounts.touched}/${soaCounts.total}`,
      text: "Annex-A-Entscheidungen, Umsetzung, Owner und Nachweise.",
      view: "soa",
      status: soaCounts.auditOpen ? `${soaCounts.auditOpen} auditrelevant offen` : "keine auditrelevante Lücke",
      tone: soaCounts.auditOpen ? "warning" : "done"
    },
    {
      title: "Risikoregister",
      value: data.risks.length,
      text: "Top-Risiken, Behandlung, Restrisiko und Review-Status.",
      view: "risks",
      status: data.highRisks.length ? `${data.highRisks.length} hoch/kritisch` : "keine Top-Lücke",
      tone: data.highRisks.length ? "warning" : "done"
    },
    {
      title: "Policy Register",
      value: `${state.policies.length - data.policyOpen.length}/${state.policies.length}`,
      text: "Policies, Versionen, Owner, Review-Datum und Freigabestand.",
      view: "policies",
      status: data.policyOpen.length ? `${data.policyOpen.length} offen` : "freigegeben",
      tone: data.policyOpen.length ? "warning" : "done"
    },
    {
      title: "Arbeitsvorlagen",
      value: `${templateApproved}/${data.templateDrafts.length}`,
      text: "Ausfüllbare Vorlagen, Policy-/Prozessentwürfe und Nacharbeit.",
      view: "templates",
      status: data.templateDraftOpen.length ? `${data.templateDraftOpen.length} offen` : "keine offene Vorlage",
      tone: data.templateDraftOpen.length ? "warning" : "done"
    },
    {
      title: "Beraterprüfung",
      value: data.reviewMetrics.approved,
      text: "Freigaben, Rückgaben, auditrelevante Punkte und interne Kommentare.",
      view: "review",
      status: data.reviewMetrics.returns ? `${data.reviewMetrics.returns} Rückgaben` : `${data.reviewMetrics.submitted + data.reviewMetrics.inReview} warten`,
      tone: data.reviewMetrics.returns || data.reviewMetrics.submitted || data.reviewMetrics.inReview ? "active" : "done"
    },
    {
      title: "Audit Trail",
      value: auditTrailEvents().length,
      text: "Wer hat was wann geändert, eingereicht, freigegeben oder zurückgegeben.",
      view: "audittrail",
      status: data.latestVersions.length ? `${data.latestVersions.length} Versionen` : "Historie",
      tone: "active"
    }
  ];
}

function renderAuditPackageContentCard(item = {}) {
  return `
    <button class="audit-package-content-card ${escapeHtml(item.tone || "")}" type="button" data-jump="${escapeHtml(item.view || "auditpackage")}">
      <span>${escapeHtml(item.title || "Paketbestandteil")}</span>
      <strong>${escapeHtml(String(item.value ?? "-"))}</strong>
      <small>${escapeHtml(item.text || "")}</small>
      <em>${escapeHtml(item.status || "öffnen")}</em>
    </button>
  `;
}

function auditPackageGeneratorStage(number, title, text, status, tone = "") {
  return `
    <article class="audit-package-generator-stage ${escapeHtml(tone)}">
      <span>${escapeHtml(number)}</span>
      <strong>${escapeHtml(title)}</strong>
      <small>${escapeHtml(text)}</small>
      <em>${escapeHtml(status)}</em>
    </article>
  `;
}

function auditPackageNextSteps(data = auditPackageReportData()) {
  if (data.gate.blockers.length) {
    return [{
      title: "Audit-Blocker zuerst schließen",
      text: data.gate.blockers[0] || "Offene Gate-Punkte fachlich prüfen und dem Kunden bei Bedarf als Nacharbeit zurückgeben.",
      view: "review",
      label: "Blocker prüfen"
    }];
  }
  if (!data.packageApproval) {
    return [{
      title: "Beraterfreigabe bewusst setzen",
      text: "Das formale Gate ist erfüllt. Berater/Admin muss den aktuellen Fingerprint prüfen und freigeben.",
      view: "auditpackage",
      label: "Freigabe prüfen"
    }];
  }
  return [{
    title: "Freigegebenes Paket exportieren",
    text: "Der Paketstand ist freigegeben. Exportiere Bericht und Evidence Bundle als Arbeitsunterlage.",
    view: "auditpackage",
    label: "Exportieren"
  }];
}

function renderAuditPackageApprovalHistory(data = auditPackageReportData()) {
  const approvals = auditPackageApprovals();
  return `
    <section class="panel audit-package-history-panel">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Freigabehistorie</span>
          <h3>Versionen und Paketstände nachvollziehen</h3>
          <p>Freigaben sind an den jeweiligen Paket-Fingerprint gebunden. Ändert sich der Inhalt, wird eine alte Freigabe als veraltet sichtbar.</p>
        </div>
        <div class="audit-package-history-status">
          <strong>${escapeHtml(approvals.length)}</strong>
          <span>Freigaben</span>
        </div>
      </div>
      <div class="audit-package-history-list">
        ${approvals.length ? approvals.map((approval) => `
          <article class="${approval.fingerprint === data.packageFingerprint ? "current" : ""}">
            <div>
              <strong>Version ${escapeHtml(approval.version || "-")}</strong>
              <span>${escapeHtml(formatAuditTime(approval))} · ${escapeHtml(approval.by || "SFM Compliance")}</span>
            </div>
            <div>
              <span>${approval.fingerprint === data.packageFingerprint ? "aktueller Stand" : "älterer Stand"}</span>
              <small>${escapeHtml(approval.fingerprint || "-")}</small>
            </div>
            <p>${escapeHtml(approval.comment || "Keine Freigabenotiz hinterlegt.")}</p>
          </article>
        `).join("") : renderEmptyState("Noch keine Auditpaket-Freigabe", "Sobald Berater/Admin einen Paketstand freigibt, erscheint die Freigabe hier mit Version, Fingerprint und Kommentar.", [], { compact: true, mark: "AP" })}
      </div>
    </section>
  `;
}

