function renderAuditPackageApprovalBox(data = auditPackageReportData()) {
  const canApprove = canApproveAuditPackage();
  const approval = data.packageApproval;
  const latest = data.latestPackageApproval;
  const readyForApproval = data.gate.consultantApproved;
  const approvalTitle = approval
    ? "Auditpaket durch Berater/Admin freigegeben"
    : readyForApproval
      ? "Formale Gate-Kriterien erfüllt, Freigabe noch offen"
      : "Freigabe noch blockiert";
  const approvalHint = approval
    ? `Version ${escapeHtml(approval.version)} · ${escapeHtml(formatAuditTime(approval))} · ${escapeHtml(approval.by || "SFM Compliance")}`
    : data.approvalStale
      ? `Letzte Freigabe ist veraltet: ${escapeHtml(formatAuditTime(latest))} · neuer Paketstand ${escapeHtml(data.packageFingerprint)}`
      : "Noch keine explizite Beraterfreigabe für diesen Paketstand vorhanden.";

  return `
    <div class="audit-package-approval ${approval ? "approved" : readyForApproval ? "ready" : "blocked"}">
      <div>
        <span class="eyebrow">Explizite Beraterfreigabe</span>
        <h4>${escapeHtml(approvalTitle)}</h4>
        <p>${approvalHint}</p>
        <div class="audit-package-approval-meta">
          <span>Fingerprint: <strong>${escapeHtml(data.packageFingerprint)}</strong></span>
          <span>Formaler Stand: <strong>${escapeHtml(data.formalPercent)}%</strong></span>
          <span>Blocker: <strong>${escapeHtml(data.gate.blockers.length)}</strong></span>
        </div>
        ${approval?.comment ? `<blockquote>${escapeHtml(approval.comment)}</blockquote>` : ""}
      </div>
      ${canApprove ? `
        <div class="audit-package-approval-form">
          <label>
            <span>Beraterkommentar zur Freigabe</span>
            <textarea rows="4" data-audit-package-comment placeholder="Kurze fachliche Notiz, zum Beispiel geprüfter Stand, Einschränkungen oder nächster Schritt.">${approval?.comment ? escapeHtml(approval.comment) : ""}</textarea>
          </label>
          <button class="primary-button" type="button" data-audit-package-approve ${readyForApproval ? "" : "disabled"}>Auditpaket freigeben</button>
          <small>${readyForApproval ? "Freigabe wird im Audit Trail protokolliert und an den aktuellen Fingerprint gebunden." : "Freigabe ist erst möglich, wenn alle Gate-Blocker geschlossen sind."}</small>
        </div>
      ` : `
        <div class="audit-package-approval-readonly">
          <strong>Kundenansicht</strong>
          <span>Du kannst das Paket vorbereiten und einreichen. Die fachliche Freigabe erfolgt durch Berater/Admin.</span>
        </div>
      `}
    </div>
  `;
}

function approveAuditPackage(button) {
  if (!canApproveAuditPackage()) {
    showPermissionToast("Auditpaket freigeben", "Berater-, Reviewer- oder Admin-Rechten");
    return;
  }
  const data = auditPackageReportData();
  if (!data.gate.consultantApproved) {
    showToast("Auditpaket kann noch nicht freigegeben werden: offene Gate-Blocker zuerst schließen.", "warning");
    return;
  }
  const panel = button?.closest("[data-audit-package-panel]");
  const comment = String(panel?.querySelector("[data-audit-package-comment]")?.value || "").trim()
    || "Auditpaket durch Berater/Admin für den aktuellen Paketstand freigegeben.";
  const approval = {
    id: crypto.randomUUID(),
    date: today(),
    dateTime: auditTimestamp(),
    by: workflowActor(),
    role: workflowActorRole(),
    status: "beraterfreigegeben",
    comment,
    fingerprint: data.packageFingerprint,
    version: nextAuditPackageVersion(),
    formalPercent: data.formalPercent,
    bundleReady: data.bundle.ready,
    bundleTotal: data.bundle.total,
    blockers: data.gate.blockers,
    criteria: data.gate.criteria.map((criterion) => ({
      label: criterion.label,
      open: criterion.open,
      hint: criterion.hint
    }))
  };
  state.auditPackage = normalizeAuditPackageState(state.auditPackage);
  state.auditPackage.approvals = [approval, ...state.auditPackage.approvals].slice(0, 30);
  recordAuditTrailEvent({
    action: "Auditpaket beraterfreigegeben",
    entityType: "Auditpaket",
    entityId: data.packageFingerprint,
    entityTitle: "Auditpaket-Bericht",
    module: "Auditpaket",
    status: "Beraterfreigegeben",
    note: comment,
    metadata: {
      version: approval.version,
      fingerprint: approval.fingerprint,
      formalPercent: approval.formalPercent,
      bundleReady: approval.bundleReady,
      bundleTotal: approval.bundleTotal
    }
  });
  saveState({ immediate: true });
  showToast("Auditpaket-Freigabe gespeichert und im Audit Trail protokolliert.");
  render();
}

function createAuditPackageBlockerTasks() {
  if (!canEditWorkspace()) {
    showPermissionToast("Auditpaket-Blocker als Aufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const data = auditPackageReportData();
  const blockers = data.gate.blockers || [];
  if (!blockers.length) {
    showToast("Keine offenen Auditpaket-Blocker vorhanden.");
    return;
  }
  let created = 0;
  blockers.slice(0, 25).forEach((blocker) => {
    const short = String(blocker || "Auditpaket-Blocker").slice(0, 120);
    const added = addTaskIfMissing({
      title: `Auditpaket-Blocker klären: ${short}`,
      module: "Beraterprüfung",
      owner: "Beratung / ISB",
      due: futureDate(7),
      status: "Offen",
      source: "Auditpaket-Gate",
      workflowType: "audit-package-blocker",
      linkedTo: data.packageFingerprint,
      note: `Was fehlt: ${blocker}. Warum reicht es noch nicht: Dieser Punkt blockiert die Beraterfreigabe des Auditpakets. Konkret tun: Nachweis, Review, Freigabe oder fachliche Entscheidung ergänzen.`
    });
    if (added) created += 1;
  });
  if (created) {
    recordAuditTrailEvent({
      action: "Auditpaket-Blocker als Aufgaben angelegt",
      entityType: "Auditpaket",
      entityId: data.packageFingerprint,
      entityTitle: "Auditpaket-Gate",
      module: "Auditpaket",
      status: "Aufgaben angelegt",
      note: `${created} Aufgabe(n) aus Auditpaket-Blockern erstellt.`,
      metadata: {
        blockers: blockers.slice(0, 25).join(" | ")
      }
    });
    saveState({ immediate: true });
    showToast(`${created} Auditpaket-Aufgabe(n) angelegt.`);
  } else {
    showToast("Auditpaket-Aufgaben waren bereits vorhanden.");
  }
  render();
}

