function consultantQuestionField(question, value = "") {
  const required = question.required ? "required" : "";
  const sourceText = SHOW_INTERNAL_REFERENCES ? (question.sources || []).join(" · ") : "";
  const helpText = question.help ? `<em class="question-help">${escapeHtml(question.help)}</em>` : "";
  const sourceNote = sourceText ? `<small class="question-source">${escapeHtml(sourceText)}</small>` : "";
  if (question.type === "textarea") {
    return `
      <label class="question-card">
        <span>${escapeHtml(question.label)}${question.required ? " *" : ""}</span>
        ${helpText}
        <textarea name="${escapeHtml(question.id)}" placeholder="${escapeHtml(question.placeholder || "")}" ${required}>${escapeHtml(value || "")}</textarea>
        ${sourceNote}
      </label>
    `;
  }
  if (question.type === "select") {
    return `
      <label class="question-card">
        <span>${escapeHtml(question.label)}${question.required ? " *" : ""}</span>
        ${helpText}
        <select name="${escapeHtml(question.id)}" ${required}>
          ${(question.options || []).map((option) => `<option value="${escapeHtml(option)}" ${value === option ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
        </select>
        ${sourceNote}
      </label>
    `;
  }
  return `
    <label class="question-card">
      <span>${escapeHtml(question.label)}${question.required ? " *" : ""}</span>
      ${helpText}
      <input name="${escapeHtml(question.id)}" type="text" value="${escapeHtml(value || "")}" placeholder="${escapeHtml(question.placeholder || "")}" ${required} />
      ${sourceNote}
    </label>
  `;
}

function collectConsultantAnswers(form) {
  return Object.fromEntries(CONSULTANT_QUESTIONS.map((question) => [question.id, String(new FormData(form).get(question.id) || "").trim()]));
}

function splitAnswerList(value) {
  return String(value || "")
    .split(/\n|,/)
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 20);
}

function addRecordIfMissing(collection, key, value, record) {
	  const normalized = String(value || "").trim().toLowerCase();
	  if (!normalized) return false;
	  const exists = state[collection].some((item) => String(item[key] || "").trim().toLowerCase() === normalized);
	  if (exists) return false;
	  const entry = { id: crypto.randomUUID(), ...record };
	  if (collection === "documents") {
	    const document = normalizeDocumentRecord(entry);
	    addDocumentHistory(document, "Dokument angelegt", "Eintrag wurde automatisch oder manuell im Dokumentenregister angelegt.");
	    addDocumentVersionHistory(document, "Erste Dokumentversion angelegt", {}, "Initialer Dokumentenstand protokolliert.");
	    state[collection].unshift(document);
	    return true;
	  }
	  if (collection === "policies") {
	    const policy = normalizePolicyRecord(entry);
	    addPolicyHistory(policy, "Policy angelegt", "Policy wurde im Register angelegt.");
	    addPolicyVersionHistory(policy, "Erste Policy-Version angelegt", {}, "Initialer Policystand protokolliert.");
	    state[collection].unshift(policy);
	    return true;
	  }
	  state[collection].unshift(entry);
	  return true;
	}

function collectCustomerOnboardingAnswers(form) {
  const formData = new FormData(form);
  return Object.fromEntries(CUSTOMER_ONBOARDING_FIELDS.map((field) => [
    field.id,
    String(formData.get(field.id) || "").trim()
  ]));
}

function collectProjectSetupAnswers(form) {
  const formData = new FormData(form);
  return Object.fromEntries(PROJECT_SETUP_FIELDS.map((field) => [
    field.id,
    String(formData.get(field.id) || "").trim()
  ]));
}

function syncProjectSetupToOnboardingAnswers(project, answers = {}) {
  return {
    ...answers,
    organizationName: project.organizationName || answers.organizationName || "",
    mainContact: project.mainContact || answers.mainContact || "",
    projectGoal: answers.projectGoal || project.projectIntent || project.projectMode || "",
    firstPriority: answers.firstPriority || "Startprofil ausfüllen, vorhandene Nachweise sammeln und offene Punkte für die Beraterprüfung vorbereiten."
  };
}

function handleProjectSetupSubmit(event) {
  event.preventDefault();
  if (!canSubmitDocuments()) {
    showPermissionToast("Grundprojekt anlegen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const current = normalizeOnboarding(state.onboarding);
  const project = normalizeProjectSetup({
    ...current.project,
    ...collectProjectSetupAnswers(event.currentTarget),
    created: true,
    lastUpdated: today()
  }, current.answers);
  if (!onboardingProjectSetupReady(project)) {
    showToast("Bitte fülle die Pflichtfelder für das Grundprojekt aus.", "warning");
    return;
  }
  state.onboarding = normalizeOnboarding({
    ...current,
    project,
    answers: syncProjectSetupToOnboardingAnswers(project, current.answers)
  });
  const created = applyProjectSetup(project);
  recordAuditTrailEvent({
    action: "Grundprojekt angelegt",
    entityType: "Kundenprojekt",
    entityTitle: project.organizationName,
    module: "Kunden-Onboarding",
    status: "formal vorbereitet",
    note: `Projektmodus: ${project.projectMode}. Fachliche Freigabe bleibt beim Berater/Admin.`,
    metadata: { projectMode: project.projectMode, targetDate: project.targetDate || "" }
  });
  saveState({ immediate: true });
  showToast(projectSetupToast(created));
  render();
}

function handleCustomerOnboardingSubmit(event) {
  event.preventDefault();
  if (!canSubmitDocuments()) {
    showPermissionToast("Onboarding-Angaben erfassen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const answers = collectCustomerOnboardingAnswers(event.currentTarget);
  state.onboarding = normalizeOnboarding({
    completed: true,
    lastUpdated: today(),
    answers
  });
  const created = applyCustomerOnboarding(answers);
  saveState({ immediate: true });
  showToast(onboardingToast(created));
  render();
}

function applyProjectSetup(project) {
  const organization = project.organizationName || "Kundenprojekt";
  const owner = project.mainContact || "Kunde / Projektleitung";
  const consultant = project.consultantOwner || "Berater/Admin";
  const created = { documents: 0, tasks: 0 };
  const projectName = `Grundprojekt - ${organization}`;
  const note = [
    `Projektmodus: ${project.projectMode || "offen"}`,
    project.industry ? `Kontext: ${project.industry}` : "",
    project.companySize ? `Größe: ${project.companySize}` : "",
    project.startDate ? `Start: ${project.startDate}` : "",
    project.targetDate ? `Zieltermin: ${project.targetDate}` : "",
    project.projectIntent ? `Ziel: ${project.projectIntent}` : "",
    `Fachliche Bewertung und Freigabe bleiben bei ${consultant}.`
  ].filter(Boolean).join(" · ");

  if (addRecordIfMissing("documents", "name", projectName, {
    name: projectName,
    area: "Projektstrukturplan",
    status: "Entwurf",
    approval: "Nicht gestartet",
    owner: consultant,
    linkedTo: "Grundprojekt",
    evidenceFor: "Projektvorbereitung",
    size: "",
    version: "0.1",
    classification: "Intern",
    review: project.targetDate || futureDate(30),
    note,
    added: today()
  })) created.documents += 1;

  [
    {
      title: `Startprofil ausfüllen: ${organization}`,
      module: "Dashboard",
      owner,
      due: project.startDate || futureDate(7),
      status: "Offen",
      linkedTo: projectName,
      note: "Kunde ergänzt Scope, kritische Assets, Lieferanten, vorhandene Nachweise und erste Priorität."
    },
    {
      title: `Projektstart fachlich einordnen: ${organization}`,
      module: "Beraterprüfung",
      owner: consultant,
      due: project.startDate || futureDate(7),
      status: "Offen",
      linkedTo: projectName,
      note: "Berater/Admin prüft Projektmodus, Rollen, Zeitrahmen und ob ISO 27001, NIS-2 oder beide Spuren relevant vorbereitet werden."
    },
    ...(String(project.projectMode || "").includes("ISO") ? [{
      title: `ISO-27001-Projektspur vorbereiten: ${organization}`,
      module: "Projektstrukturplan",
      owner: consultant,
      due: futureDate(14),
      status: "Offen",
      linkedTo: "ISO 27001 / Projektstrukturplan",
      note: "Scope, Clauses, Annex-A-Arbeitspakete und Nachweislogik als Projektspur vorbereiten."
    }] : []),
    ...(String(project.projectMode || "").includes("NIS-2") ? [{
      title: `NIS-2 Einordnung vorbereiten: ${organization}`,
      module: "NIS-2",
      owner: consultant,
      due: futureDate(14),
      status: "Offen",
      linkedTo: "NIS-2 Navigator",
      note: "Betroffenheit, offene Pflichten und Nachweise getrennt von ISO 27001 vorbereiten. Finale Einordnung erfolgt durch Berater/Admin."
    }] : [])
  ].forEach((task) => {
    if (addTaskIfMissing(task)) created.tasks += 1;
  });

  return created;
}

function projectSetupToast(created) {
  const total = created.documents + created.tasks;
  if (!total) return "Grundprojekt gespeichert. Projektanker und Aufgaben waren bereits vorhanden.";
  return `Grundprojekt gespeichert: ${created.documents} Projektanker, ${created.tasks} Aufgabe(n) angelegt.`;
}

function applyCustomerOnboarding(rawAnswers = {}) {
  const answers = normalizeOnboarding({ answers: rawAnswers }).answers;
  const owner = answers.mainContact || "Kunde / ISB";
  const organization = answers.organizationName || "Kunde";
  const created = { documents: 0, templateDrafts: 0, assets: 0, suppliers: 0, risks: 0, tasks: 0 };
  const assetNames = [...new Set([
    ...splitAnswerList(answers.criticalAssets),
    ...splitAnswerList(answers.scopeSummary)
  ])].slice(0, 12);
  const supplierNames = splitAnswerList(answers.criticalSuppliers).slice(0, 10);
  const evidenceNames = splitAnswerList(answers.existingEvidence).slice(0, 12);

  assetNames.forEach((name) => {
    if (addRecordIfMissing("assets", "name", name, {
      name,
      type: "Kritisches Asset",
      owner,
      criticality: "Hoch",
      protection: "CIA prüfen",
      status: "Offen",
      note: `Aus Kunden-Onboarding vom ${today()} übernommen.`
    })) created.assets += 1;
  });

  supplierNames.forEach((name) => {
    if (addRecordIfMissing("suppliers", "name", name, {
      name,
      service: "IKT / Cloud / Dienstleistung",
      criticality: "Zu prüfen",
      owner,
      review: "Nicht gestartet",
      nextReview: futureDate(30),
      note: `Aus Kunden-Onboarding vom ${today()} übernommen.`
    })) created.suppliers += 1;
  });

  const profileName = onboardingProfileDocumentName(organization);
  if (addRecordIfMissing("documents", "name", profileName, {
    name: profileName,
    area: "Projektstrukturplan",
    status: "Entwurf",
    approval: "Nicht gestartet",
    owner,
    linkedTo: "Kunden-Onboarding",
    evidenceFor: "Kunden-Onboarding",
    size: "",
    version: "0.1",
    classification: "Intern",
    review: futureDate(30),
    note: [
      `Organisation: ${organization}`,
      answers.projectGoal ? `Ziel: ${answers.projectGoal}` : "",
      answers.scopeSummary ? `Scope-Hinweis: ${answers.scopeSummary}` : "",
      answers.firstPriority ? `Erste Priorität: ${answers.firstPriority}` : ""
    ].filter(Boolean).join(" · "),
    added: today()
  })) created.documents += 1;

  evidenceNames.forEach((name) => {
    const documentName = `Nachweisverweis - ${name}`;
    if (addRecordIfMissing("documents", "name", documentName, {
      name: documentName,
      area: inferDocumentArea(name),
      status: "Entwurf",
      approval: "Nicht gestartet",
      owner,
      linkedTo: "Kunden-Onboarding",
      evidenceFor: "Kunden-Onboarding",
      size: "",
      version: "0.1",
      classification: "Intern",
      review: futureDate(DOCUMENT_REVIEW_DAYS),
      note: `Vom Kunden als vorhandener Nachweis genannt: ${name}`,
      added: today()
    })) created.documents += 1;
  });

  const templateResult = createOnboardingTemplateDrafts(answers, {
    owner,
    organization,
    assetNames,
    supplierNames,
    evidenceNames
  });
  created.templateDrafts += templateResult.templateDrafts;
  created.documents += templateResult.documents;

  const riskScenario = "Start-Risiko: Scope, Assets und Nachweise sind noch nicht vollständig bewertet";
  if (addRecordIfMissing("risks", "scenario", riskScenario, {
    riskId: nextRiskId(),
    scenario: riskScenario,
    asset: assetNames[0] || organization,
    impact: 3,
    likelihood: 3,
    owner,
    treatment: "Onboarding-Angaben prüfen, Scope bestätigen, Asset Register vervollständigen und Nachweise priorisieren.",
    status: "Offen",
    added: today(),
    source: "Kunden-Onboarding"
  })) created.risks += 1;

  [
    {
      title: "Onboarding-Angaben prüfen und bestätigen",
      module: "Projektstrukturplan",
      owner,
      due: futureDate(7),
      status: "Offen",
      note: `Startprofil für ${organization} fachlich prüfen.`
    },
    {
      title: "Scope-Arbeitsvorlage aus Startprofil finalisieren",
      module: "ISO 27001",
      owner,
      due: futureDate(14),
      status: "Offen",
      note: answers.scopeSummary || "Scope, Schnittstellen und Grenzen aus dem Startprofil konkretisieren."
    },
    {
      title: "Kritische Assets aus Onboarding bewerten",
      module: "Asset Management",
      owner,
      due: futureDate(14),
      status: "Offen",
      note: assetNames.length ? assetNames.join(", ") : "Kritische Assets mit Owner, Kritikalität und Schutzbedarf ergänzen."
    },
    {
      title: "Vorhandene Nachweise hochladen oder verknüpfen",
      module: "Dokumentation",
      owner,
      due: futureDate(21),
      status: "Offen",
      note: evidenceNames.length ? evidenceNames.join(", ") : "Bestehende Dokumente, Policies oder Listen als Nachweis einreichen."
    }
  ].forEach((task) => {
    if (addTaskIfMissing(task)) created.tasks += 1;
  });

  return created;
}

function createOnboardingTemplateDrafts(answers, context) {
  const { owner, organization, assetNames, supplierNames, evidenceNames } = context;
  const created = { templateDrafts: 0, documents: 0 };
  const scopeText = [
    answers.scopeSummary,
    assetNames.length ? `Kritische Assets / Informationswerte: ${assetNames.join(", ")}` : "",
    supplierNames.length ? `Kritische Lieferanten / IKT-Dienste: ${supplierNames.join(", ")}` : ""
  ].filter(Boolean).join("\n");
  const centralDocuments = [
    "ISMS Scope",
    "Asset Register",
    "Risikoregister",
    "Policy Register",
    "Projektstrukturplan",
    ...evidenceNames
  ].filter(Boolean).join("\n");

  [
    ["scope", {
      organization,
      scope: scopeText || "Anwendungsbereich im Scope-Workshop fachlich finalisieren.",
      interfaces: supplierNames.length ? `Kritische Lieferanten / IKT-Dienste: ${supplierNames.join(", ")}` : "Interne und externe Schnittstellen im Scope-Workshop ergänzen.",
      exclusions: "Noch offen - Ausschlüsse und Grenzen fachlich prüfen und begründen.",
      owner,
      review: futureDate(30)
    }, "ISMS Scope Arbeitsvorlage"],
    ["isms-manual", {
      organization,
      manualPurpose: answers.projectGoal || "ISMS-Startdokument für Projektsteuerung, Nachweise und spätere Freigabe.",
      scopeSummary: scopeText || "Scope aus Onboarding ergänzen und finalisieren.",
      coreDocuments: centralDocuments,
      owner,
      review: "Jährlich"
    }, "ISMS Manual Arbeitsvorlage"],
    ["asset-inventory", {
      asset: assetNames.length ? assetNames.join(", ") : "Kritische Assets aus Onboarding ergänzen",
      owner,
      classification: "Intern",
      location: "Ablage / Standort noch zu ergänzen",
      protection: "Schutzbedarf für Vertraulichkeit, Integrität und Verfügbarkeit je Asset prüfen.",
      dependencies: supplierNames.length ? supplierNames.join(", ") : "Abhängigkeiten und Schnittstellen noch ergänzen."
    }, "Asset-Inventar Arbeitsvorlage"],
    ...(supplierNames.length ? [["supplier-security", {
      supplier: supplierNames.join(", "),
      service: "IKT / Cloud / Dienstleistung aus Kunden-Onboarding",
      criticality: "Hoch",
      requirements: "Sicherheitsanforderungen, Vertragsgrundlagen und Nachweise je Lieferant prüfen.",
      evidence: evidenceNames.length ? evidenceNames.join(", ") : "Zertifikate, Verträge, Fragebögen oder Auditberichte anfordern.",
      decision: "Freigeben mit Maßnahmen"
    }, "Lieferanten-Sicherheitscheck Arbeitsvorlage"]] : [])
  ].forEach(([templateId, data, title]) => {
    const result = addOnboardingTemplateDraft(templateId, organization, data, { owner, title });
    created.templateDrafts += result.templateDrafts;
    created.documents += result.documents;
  });

  return created;
}

function addOnboardingTemplateDraft(templateId, organization, data, options = {}) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === templateId);
  if (!template) return { templateDrafts: 0, documents: 0 };
  const customerKey = normalizeImportKey(organization || "kunde");
  const generatedKey = `onboarding:${customerKey}:${templateId}`;
  const content = buildTemplateDocument(template, data);
  const title = `${organization} - ${options.title || template.outputName || template.title}`;
  const documentName = `${options.title || template.outputName || template.title} - ${organization}`;
  const existingDraft = state.templateDrafts.find((item) => item.generatedKey === generatedKey);
  const documentId = existingDraft?.documentId || crypto.randomUUID();
  const createdDraft = upsertGeneratedTemplateDraft({
    generatedKey,
    documentId,
    title,
    templateId,
    templateTitle: template.title,
    area: template.area,
    linkedTo: template.linkedTo,
    owner: data.owner || options.owner || "Kunde / ISB",
    status: "Entwurf",
    approval: "Nicht gestartet",
    version: "0.1",
    review: dateInputValue(data.review || data.reviewDate, futureDate(DOCUMENT_REVIEW_DAYS)),
    classification: "Intern",
    documentKind: isPolicyLikeTemplate(template) ? "Vollständiger Policy-/Prozessentwurf" : "Arbeitsvorlage",
    source: "Kunden-Onboarding",
    data,
    content,
    added: today(),
    updated: today()
  });

  const createdDocument = addRecordIfMissing("documents", "name", documentName, {
    id: documentId,
    name: documentName,
    area: template.area,
    status: "Entwurf",
    owner: data.owner || options.owner || "Kunde / ISB",
    linkedTo: template.linkedTo,
    evidenceFor: template.linkedTo,
    size: "",
    version: "0.1",
    review: dateInputValue(data.review || data.reviewDate, futureDate(DOCUMENT_REVIEW_DAYS)),
    approval: "Nicht gestartet",
    classification: "Intern",
    note: `Aus dem Startprofil als Arbeitsvorlage erzeugt: ${template.title}`,
    added: today()
  });

  const draft = state.templateDrafts.find((item) => item.generatedKey === generatedKey);
  if (draft) selectedTemplateDraftId = draft.id;
  return {
    templateDrafts: createdDraft ? 1 : 0,
    documents: createdDocument ? 1 : 0
  };
}

function onboardingProfileDocumentName(organization) {
  return `Onboarding-Profil - ${organization || "Kunde"}`;
}

function onboardingToast(created) {
  const total = Object.values(created).reduce((sum, value) => sum + value, 0);
  if (!total) return "Startprofil gespeichert. Alle Arbeitsunterlagen waren bereits vorhanden.";
  return `Startprofil gespeichert: ${created.documents} Dokumente, ${created.templateDrafts} Arbeitsvorlagen, ${created.assets} Assets, ${created.suppliers} Lieferanten, ${created.risks} Risiko, ${created.tasks} Aufgaben.`;
}

function openOnboardingTemplateDraft(id) {
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) {
    showToast("Arbeitsvorlage nicht gefunden.");
    return;
  }
  selectedTemplateDraftId = draft.id;
  if (draft.templateId) selectedTemplateId = draft.templateId;
  navigateToView("templates");
}

function createOnboardingGapTasks() {
  if (!canSubmitDocuments()) {
    showPermissionToast("Onboarding-Aufgaben anlegen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const rows = onboardingTemplateDrafts().map((draft) => ({ draft, quality: onboardingDraftQuality(draft) }));
  const created = createOnboardingGapTasksFromRows(rows);
  saveState({ immediate: true });
  showToast(created ? `${created} Nacharbeitsaufgabe(n) angelegt.` : "Für die offenen Felder bestehen bereits Aufgaben.");
  render();
}

function createOnboardingGapTasksFromRows(rows) {
  let created = 0;
  rows
    .filter((row) => row.quality.missing.length)
    .forEach((row) => {
      const title = row.draft.templateTitle || row.draft.title || "Arbeitsvorlage";
      const missingLabels = row.quality.missing.map((field) => field.label).join(", ");
      if (addTaskIfMissing({
        title: `Arbeitsvorlage vervollständigen: ${title}`,
        module: "Arbeitsvorlagen",
        owner: row.draft.owner || row.draft.data?.owner || "Kunde / ISB",
        due: futureDate(row.quality.requiredMissing.length ? 7 : 14),
        status: "Offen",
        note: `Folgende Felder in der Arbeitsvorlage nacharbeiten: ${missingLabels}`
      })) created += 1;
    });
  return created;
}

function downloadOnboardingStartPackageReport() {
  const onboarding = normalizeOnboarding(state.onboarding);
  const answers = onboarding.answers || {};
  const organization = answers.organizationName || "Kunde";
  const draftRows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    quality: onboardingDraftQuality(draft)
  }));
  const readiness = onboardingStartPackageReadiness(draftRows);
  const onboardingAssets = state.assets.filter((asset) => String(asset.note || "").includes("Kunden-Onboarding"));
  const onboardingSuppliers = state.suppliers.filter((supplier) => String(supplier.note || "").includes("Kunden-Onboarding"));
  const onboardingDocuments = state.documents.filter((document) => {
    const text = `${document.name || ""} ${document.linkedTo || ""} ${document.evidenceFor || ""} ${document.note || ""}`;
    return text.includes("Kunden-Onboarding") || text.includes("Onboarding-Profil") || text.includes("Nachweisanker -") || text.includes("Nachweisverweis -");
  });
  const onboardingTasks = state.tasks.filter((task) => {
    const text = `${task.title || ""} ${task.note || ""}`;
    return text.includes("Onboarding") || text.includes("Startpaket");
  });
  const lines = [
    "# SFM Compliance Arbeitsvorlagen-Report",
    "",
    `Datum: ${today()}`,
    `Organisation: ${organization}`,
    `Ansprechpartner: ${answers.mainContact || "offen"}`,
    `Projektziel: ${answers.projectGoal || "offen"}`,
    "",
    "## Kurzstatus",
    `- Onboarding abgeschlossen: ${onboarding.completed ? "Ja" : "Nein"}`,
    `- Letzte Aktualisierung: ${onboarding.lastUpdated || "offen"}`,
    `- Ausfüllgrad der Arbeitsvorlagen: ${readiness.percent}%`,
    `- Arbeitsvorlagen bereit: ${readiness.readyDrafts}/${readiness.totalDrafts}`,
    `- Pflichtfelder offen: ${readiness.requiredMissing}`,
    `- Felder nacharbeiten: ${readiness.missingFields}`,
    `- Dokumentverweis: ${readiness.documentsLinked}/${readiness.totalDrafts}`,
    "",
    "## Kundenantworten"
  ];

  appendMarkdownTable(lines, ["Frage", "Antwort"], CUSTOMER_ONBOARDING_FIELDS.map((field) => [
    field.label,
    answers[field.id] || "offen"
  ]));

  lines.push("", "## Vorbereitete Arbeitsvorlagen");
  appendMarkdownTable(lines, ["Arbeitsvorlage", "Vorlage", "Zuordnung", "Prüfstatus", "Ausfüllgrad", "Offene Pflichtfelder", "Offene Felder"], draftRows.map(({ draft, quality }) => {
    const document = findDocumentForTemplateDraft(draft, draft.title);
    const workflowStatus = onboardingDraftApproved(draft, document)
      ? "Freigegeben"
      : onboardingDraftNeedsRework(draft, document)
        ? "Nachbesserung"
        : onboardingDraftInReview(draft, document)
          ? "In Prüfung"
          : (draft.status || quality.status);
    return [
      draft.title || "Unbenannte Arbeitsvorlage",
      draft.templateTitle || draft.area || "Template",
      draft.linkedTo || "offen",
      workflowStatus,
      `${quality.percent}% (${quality.filled}/${quality.total})`,
      quality.requiredMissing.map((field) => field.label).join(", ") || "-",
      quality.missing.map((field) => field.label).join(", ") || "-"
    ];
  }));

  const activityEvents = onboardingActivityEvents(draftRows.map(({ draft, quality }) => ({
    draft,
    quality,
    document: findDocumentForTemplateDraft(draft, draft.title)
  })));
  if (activityEvents.length) {
    lines.push("", "## Prüf- und Nachbesserungshistorie");
    appendMarkdownTable(lines, ["Datum", "Arbeitsvorlage", "Aktion", "Person", "Hinweis"], activityEvents.slice(0, 12).map((event) => [
      event.date || "-",
      event.title || "Arbeitsvorlage",
      event.action || "-",
      event.by || "-",
      event.note || "-"
    ]));
  }

  if (readiness.topGaps.length) {
    lines.push("", "## Nächste Nacharbeiten");
    readiness.topGaps.forEach((gap) => lines.push(`- ${gap}`));
  }

  lines.push("", "## Aus Onboarding erzeugte Registereinträge");
  appendMarkdownTable(lines, ["Typ", "Name", "Owner", "Status / Review"], [
    ...onboardingAssets.map((asset) => ["Asset", asset.name, asset.owner || "offen", asset.status || "Offen"]),
    ...onboardingSuppliers.map((supplier) => ["Lieferant", supplier.name, supplier.owner || "offen", supplier.review || supplier.status || "Nicht gestartet"])
  ]);

  lines.push("", "## Dokumentverweise");
  appendMarkdownTable(lines, ["Dokument", "Bereich", "Zuordnung", "Status", "Review"], onboardingDocuments.map((document) => [
    document.name || "Unbenanntes Dokument",
    document.area || "Dokumentation",
    document.linkedTo || document.evidenceFor || "offen",
    document.status || "Entwurf",
    document.review || "offen"
  ]));

  lines.push("", "## Aufgaben aus Startprofil und Arbeitsvorlagen");
  appendMarkdownTable(lines, ["Aufgabe", "Modul", "Owner", "Fällig", "Status"], onboardingTasks.map((task) => [
    task.title || "Unbenannte Aufgabe",
    task.module || "Task Management",
    task.owner || "offen",
    task.due || "offen",
    task.status || "Offen"
  ]));

  lines.push(
    "",
    "## Empfohlene nächste Schritte",
    "- Offene Pflichtfelder in den Arbeitsvorlagen schließen.",
    "- Lücken als Aufgaben erzeugen und Verantwortliche mit Fristen bestätigen.",
    "- Dokumentverweise mit echten Kundennachweisen hochladen oder verknüpfen.",
    "- Scope, Asset Register und erstes Risiko fachlich prüfen.",
    "- Arbeitsvorlagen nach Nacharbeit erneut exportieren.",
    "",
    "## Grenzen",
    "- Dieser Report basiert nur auf dem aktuellen Plattformstand und den lokalen Onboarding-Angaben.",
    "- Externe Quellen wurden für diesen Export nicht verwendet.",
    "- ISO 27001 und NIS-2 bleiben in der Plattform fachlich getrennt; dieser Bericht ist eine praktische Arbeitsunterlage."
  );

  downloadTextFile(`sfm-compliance-startpaket-${slugify(organization)}-${today()}.md`, lines.join("\n"), "text/markdown");
  showToast("Arbeitsvorlagen-Report exportiert.");
}

function downloadOnboardingAcceptanceProtocol() {
  const onboarding = normalizeOnboarding(state.onboarding);
  const answers = onboarding.answers || {};
  const organization = answers.organizationName || "Kunde";
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    document: findDocumentForTemplateDraft(draft, draft.title),
    quality: onboardingDraftQuality(draft)
  }));
  if (!rows.length) {
    showToast("Noch keine Arbeitsvorlagen vorhanden.");
    return;
  }
  const notApproved = rows.filter((row) => !onboardingDraftApproved(row.draft, row.document));
  if (notApproved.length) {
    showToast("Abnahmeprotokoll ist erst verfügbar, wenn alle Arbeitsvorlagen freigegeben sind.");
    return;
  }

  const activityEvents = onboardingActivityEvents(rows);
  const approvedDates = rows.map((row) => row.draft.approvedAt || row.document?.approvedAt || "").filter(Boolean).sort();
  const approvedAt = approvedDates[approvedDates.length - 1] || today();
  const approvedBy = Array.from(new Set(rows.map((row) => row.draft.approvedBy || row.document?.approvedBy || "").filter(Boolean))).join(", ") || "SFM Compliance";
  const lines = [
    "# SFM Compliance Übergabeprotokoll",
    "",
    `Organisation: ${organization}`,
    `Exportdatum: ${today()}`,
    `Abnahmestatus: Arbeitsvorlagen vollständig freigegeben`,
    `Letzte Freigabe: ${approvedAt}`,
    `Freigegeben durch: ${approvedBy}`,
    "",
    "## Freigegebene Arbeitsvorlagen"
  ];

  appendMarkdownTable(lines, ["Arbeitsvorlage", "Vorlage", "Zuordnung", "Version", "Dokument", "Freigabe"], rows.map(({ draft, document }) => [
    draft.title || "Unbenannte Arbeitsvorlage",
    draft.templateTitle || draft.area || "Template",
    draft.linkedTo || document?.linkedTo || "offen",
    draft.version || document?.version || "1.0",
    document?.name || "Dokumentverweis offen",
    draft.approvedAt || document?.approvedAt || approvedAt
  ]));

  if (activityEvents.length) {
    lines.push("", "## Prüfverlauf");
    appendMarkdownTable(lines, ["Datum", "Arbeitsvorlage", "Aktion", "Person", "Hinweis"], activityEvents.slice(0, 16).map((event) => [
      event.date || "-",
      event.title || "Arbeitsvorlage",
      event.action || "-",
      event.by || "-",
      event.note || "-"
    ]));
  }

  lines.push(
    "",
    "## Abnahmevermerk",
    "- Die oben genannten Arbeitsvorlagen wurden im Plattform-Workflow freigegeben.",
    "- Dieses Protokoll dokumentiert die interne Projektübergabe aus den Arbeitsvorlagen in die weitere ISMS-/NIS-2-Umsetzung.",
    "- Das Protokoll ersetzt keine Zertifizierung, kein Auditurteil und keine rechtliche Einzelfallprüfung.",
    "",
    "## Empfohlene nächste Schritte",
    "- Projektstrukturplan für ISO 27001 und NIS-2 weiter abarbeiten.",
    "- Freigegebene Arbeitsvorlagen bei Bedarf in Policies, Register und Nachweisführung überführen.",
    "- Risiken, Assets, Lieferanten, Aufgaben und Nachweise regelmäßig reviewen.",
    "- Management Review und Audit-Paket vorbereiten, sobald die Umsetzungsnachweise belastbar sind.",
    "",
    "## Grenzen",
    "- Der Export basiert auf dem aktuellen Plattformstand.",
    "- Externe Quellen wurden für dieses Protokoll nicht verwendet.",
    "- ISO 27001 und NIS-2 bleiben fachlich getrennt; dieses Protokoll ist ein praktischer Übergabenachweis."
  );

  downloadTextFile(`sfm-compliance-arbeitsvorlagen-uebergabe-${slugify(organization)}-${today()}.md`, lines.join("\n"), "text/markdown");
  showToast("Übergabeprotokoll exportiert.");
}

function createOnboardingImplementationTaskPack() {
  if (!canEditWorkspace()) {
    showPermissionToast("Folgeaufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const onboarding = normalizeOnboarding(state.onboarding);
  const answers = onboarding.answers || {};
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    document: findDocumentForTemplateDraft(draft, draft.title),
    quality: onboardingDraftQuality(draft)
  }));
  if (!rows.length) {
    showToast("Noch keine Arbeitsvorlagen vorhanden.");
    return;
  }
  const notApproved = rows.filter((row) => !onboardingDraftApproved(row.draft, row.document));
  if (notApproved.length) {
    showToast("Folgeaufgaben werden erst angelegt, wenn die Arbeitsvorlagen vollständig freigegeben sind.");
    return;
  }

  const organization = answers.organizationName || "Kunde";
  const contact = answers.mainContact || "Kunde / Fachbereich";
  const firstPriority = answers.firstPriority || "Priorität aus Arbeitsvorlagen";
  const tasks = [
    {
      title: `Arbeitsvorlagen in Projektstrukturplan überführen: ${organization}`,
      module: "Projektstrukturplan",
      owner: "Berater / ISB",
      due: futureDate(7),
      status: "Offen",
      note: `Freigegebene Arbeitsvorlagen in konkrete ISO-27001-/NIS-2-Arbeitspakete überführen. Priorität: ${firstPriority}`
    },
    {
      title: `Scope und ISMS-Arbeitsstand bestätigen: ${organization}`,
      module: "Dokumentation",
      owner: contact,
      due: futureDate(7),
      status: "Offen",
      note: "Freigegebene Scope-/ISMS-Arbeitsstände fachlich bestätigen und als Grundlage für die Umsetzung nutzen."
    },
    {
      title: `Asset Register aus Arbeitsvorlagen fachlich prüfen: ${organization}`,
      module: "Asset Management",
      owner: contact || "Kunde / IT",
      due: futureDate(10),
      status: "Offen",
      note: "Kritische Assets, Owner und Schutzbedarf aus den Arbeitsvorlagen gegen echte System-/Prozesslandschaft prüfen."
    },
    {
      title: `Risiko-Workshop auf Basis der Arbeitsvorlagen durchführen: ${organization}`,
      module: "Risiko Management",
      owner: contact || "ISB / Risk Owner",
      due: futureDate(14),
      status: "Offen",
      note: "Start-Risiken aus dem Onboarding in Bewertung, Behandlung und Verantwortlichkeiten überführen."
    },
    {
      title: `Policy- und Prozesspaket gegen Arbeitsvorlagen abstimmen: ${organization}`,
      module: "Policy Management",
      owner: "Policy Owner / ISB",
      due: futureDate(21),
      status: "Offen",
      note: "Freigegebene Arbeitsvorlagen mit bestehenden Policies, Verfahren und Dokumentverweisen abgleichen."
    },
    {
      title: `Nachweisplan für ISO 27001 und NIS-2 erstellen: ${organization}`,
      module: "Dokumentation",
      owner: "ISB / Compliance",
      due: futureDate(21),
      status: "Offen",
      note: "Aus freigegebenen Arbeitsvorlagen ableiten, welche Nachweise zuerst hochgeladen, verknüpft oder geprüft werden."
    },
    {
      title: `Management-Review-Inputs aus Arbeitsvorlagen vormerken: ${organization}`,
      module: "Audit",
      owner: "Berater / ISB",
      due: futureDate(30),
      status: "Offen",
      note: "Ergebnisse aus den Arbeitsvorlagen als spätere Inputs für Management Review, Audit-Vorbereitung und offene Entscheidungen vormerken."
    }
  ].map((task) => ({
    ...task,
    source: ONBOARDING_IMPLEMENTATION_SOURCE,
    linkedTo: "Arbeitsvorlagen"
  }));

  let created = 0;
  tasks.forEach((task) => {
    if (addTaskIfMissing(task)) created += 1;
  });
  saveState({ immediate: true });
  showToast(created ? `${created} Folgeaufgabe(n) aus der Arbeitsvorlagen-Übergabe angelegt.` : "Folgeaufgaben aus der Arbeitsvorlagen-Übergabe sind bereits vorhanden.");
  render();
}

function downloadOnboardingImplementationPlanReport() {
  const tasks = onboardingImplementationTasks();
  if (!tasks.length) {
    showToast("Noch keine Folgeaufgaben aus der Arbeitsvorlagen-Übergabe vorhanden.");
    return;
  }
  const onboarding = normalizeOnboarding(state.onboarding);
  const answers = onboarding.answers || {};
  const organization = answers.organizationName || "Kunde";
  const done = tasks.filter((task) => task.status === "Erledigt").length;
  const overdue = tasks.filter((task) => task.status !== "Erledigt" && task.due && task.due < today()).length;
  const open = tasks.filter((task) => task.status !== "Erledigt").length;
  const evidenceCount = tasks.filter((task) => onboardingImplementationTaskEvidence(task)).length;
  const doneWithoutEvidence = tasks.filter((task) => onboardingImplementationTaskNeedsEvidence(task)).length;
  const progress = percentOf(done, tasks.length);
  const lines = [
    "# SFM Compliance Umsetzungsplan nach Arbeitsvorlagen-Übergabe",
    "",
    `Organisation: ${organization}`,
    `Exportdatum: ${today()}`,
    `Fortschritt: ${progress}%`,
    `Aufgaben gesamt: ${tasks.length}`,
    `Offen: ${open}`,
    `Erledigt: ${done}`,
    `Überfällig: ${overdue}`,
    `Nachweise verknüpft: ${evidenceCount}/${tasks.length}`,
    `Erledigt ohne Nachweis: ${doneWithoutEvidence}`,
    "",
    "## Aufgaben"
  ];

  appendMarkdownTable(lines, ["Aufgabe", "Modul", "Owner", "Fällig", "Status", "Nachweis", "Hinweis"], tasks.map((task) => {
    const evidence = onboardingImplementationTaskEvidence(task);
    return [
      task.title || "Folgeaufgabe",
      task.module || "Task Management",
      task.owner || "offen",
      task.due || "offen",
      task.status || "Offen",
      evidence ? `${evidence.name || "Nachweis"} (${evidence.status || "Status offen"})` : task.status === "Erledigt" ? "fehlt trotz erledigt" : "offen",
      task.note || "-"
    ];
  }));

  lines.push(
    "",
    "## Priorisierte Bearbeitung",
    "- Erledigte Aufgaben ohne Nachweisverweis zuerst nachdokumentieren.",
    "- Überfällige oder blockierte Aufgaben zuerst klären.",
    "- Aufgaben mit Kunden-Ownern in den nächsten Jour fixe übernehmen.",
    "- Ergebnisse mit Nachweisen, Dokumentverweisen oder Registereinträgen verknüpfen.",
    "- Erledigte Aufgaben als Input für Management Review und Audit-Vorbereitung vormerken.",
    "",
    "## Grenzen",
    "- Dieser Umsetzungsplan basiert auf den in SFM Compliance angelegten Folgeaufgaben.",
    "- Externe Quellen wurden für diesen Export nicht verwendet.",
    "- Der Plan ersetzt keine fachliche Freigabe, kein Audit und keine rechtliche Einzelfallprüfung."
  );

  downloadTextFile(`sfm-compliance-umsetzungsplan-${slugify(organization)}-${today()}.md`, lines.join("\n"), "text/markdown");
  showToast("Umsetzungsplan exportiert.");
}

function openOnboardingImplementationTaskEvidence(id) {
  if (!canSubmitDocuments()) {
    showPermissionToast("Nachweisverweis anlegen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const task = state.tasks.find((item) => item.id === id && isOnboardingImplementationTask(item));
  if (!task) {
    showToast("Folgeaufgabe nicht gefunden.");
    return;
  }
  const { document } = ensureOnboardingImplementationTaskEvidence(task);
  task.evidenceDocumentId = document.id;
  task.updated = today();
  selectedDocumentId = document.id;
  saveState({ immediate: true });
  showToast("Nachweisverweis geöffnet.");
  navigateToView("documents");
}

function ensureOnboardingImplementationTaskEvidence(task) {
  let document = onboardingImplementationTaskEvidence(task);
  if (document) {
    task.evidenceDocumentId = document.id;
    return { document, created: false };
  }
  document = normalizeDocumentRecord({
    id: crypto.randomUUID(),
    name: `Nachweis - ${task.title || "Folgeaufgabe"}`,
    area: task.module || ONBOARDING_IMPLEMENTATION_SOURCE,
    status: "Entwurf",
    owner: task.owner || "Kunde / ISB",
    linkedTo: task.title || ONBOARDING_IMPLEMENTATION_SOURCE,
    evidenceFor: task.title || ONBOARDING_IMPLEMENTATION_SOURCE,
    version: "0.1",
    review: futureDate(DOCUMENT_REVIEW_DAYS),
    approval: "Nicht gestartet",
    classification: "Intern",
    implementationTaskId: task.id,
    note: "Nachweisverweis zur Folgeaufgabe aus der Arbeitsvorlagen-Übergabe.",
    added: today()
  }, "Nachweisverweis angelegt");
  addDocumentHistory(document, "Nachweisverweis angelegt", `Zur Folgeaufgabe: ${task.title || "Arbeitsvorlagen-Übergabe"}`);
  state.documents.unshift(document);
  task.evidenceDocumentId = document.id;
  task.updated = today();
  return { document, created: true };
}

function createMissingOnboardingImplementationEvidenceAnchors() {
  if (!canSubmitDocuments()) {
    showPermissionToast("Nachweisverweis anlegen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const tasks = onboardingImplementationTasks().filter(onboardingImplementationTaskNeedsEvidence);
  if (!tasks.length) {
    showToast("Keine erledigten Folgeaufgaben ohne Nachweis gefunden.");
    return;
  }
  let created = 0;
  tasks.forEach((task) => {
    if (ensureOnboardingImplementationTaskEvidence(task).created) created += 1;
  });
  saveState({ immediate: true });
  showToast(created ? `${created} fehlende Nachweisverweise angelegt.` : "Nachweisverweise waren bereits vorhanden.");
  render();
}

function updateOnboardingImplementationTaskStatus(id, status) {
  if (!canEditWorkspace()) {
    showPermissionToast("Folgeaufgaben aktualisieren", "Bearbeitungsrechten");
    return;
  }
  const task = state.tasks.find((item) => item.id === id && isOnboardingImplementationTask(item));
  if (!task) {
    showToast("Folgeaufgabe nicht gefunden.");
    return;
  }
  task.status = status === "Erledigt" ? "Erledigt" : "Offen";
  task.updated = today();
  if (task.status === "Erledigt") {
    task.completedAt = today();
  } else {
    task.completedAt = "";
  }
  saveState({ immediate: true });
  showToast(task.status === "Erledigt" ? "Folgeaufgabe erledigt." : "Folgeaufgabe wieder geöffnet.");
  render();
}

function submitOnboardingStartPackageForReview() {
  if (!canSubmitDocuments()) {
    showPermissionToast("die Arbeitsvorlagen einreichen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const onboarding = normalizeOnboarding(state.onboarding);
  const organization = onboarding.answers.organizationName || "Kunde";
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    quality: onboardingDraftQuality(draft)
  }));
  if (!rows.length) {
    showToast("Noch keine Arbeitsvorlagen vorhanden. Bitte zuerst das Startprofil speichern.");
    return;
  }

  const submitRows = rows.filter((row) => !onboardingDraftApproved(row.draft, findDocumentForTemplateDraft(row.draft, row.draft.title)));
  if (!submitRows.length) {
    showToast("Alle Arbeitsvorlagen sind bereits freigegeben.");
    return;
  }

  const blockers = submitRows.filter((row) => row.quality.requiredMissing.length);
  if (blockers.length) {
    const created = createOnboardingGapTasksFromRows(rows);
    saveState({ immediate: true });
    showToast(created
      ? "Pflichtfelder offen. Nacharbeitsaufgaben wurden angelegt."
      : "Pflichtfelder offen. Bitte Arbeitsvorlagen vor Einreichung vervollständigen.");
    render();
    return;
  }

  submitRows.forEach(({ draft }) => {
    Object.assign(draft, {
      status: "In Prüfung",
      approval: "Prüfung läuft",
      submittedAt: today(),
      submittedBy: workflowActor(),
      updated: today()
    });
    const document = syncTemplateDraftDocument(draft, draft.title, "Arbeitsvorlage zur Prüfung eingereicht");
    Object.assign(document, normalizeDocumentRecord({
      ...document,
      status: "In Prüfung",
      approval: "Prüfung läuft",
      submittedAt: today(),
      submittedBy: workflowActor()
    }, "Arbeitsvorlage zur Prüfung eingereicht"));
    addDocumentHistory(document, "Zur Prüfung eingereicht", "Arbeitsvorlage wurde gesammelt zur Prüfung eingereicht.");
  });

  addTaskIfMissing({
    title: `Arbeitsvorlagen prüfen: ${organization}`,
    module: "Arbeitsvorlagen",
    owner: "Berater / ISB",
    due: futureDate(7),
    status: "Offen",
    note: `${submitRows.length} Arbeitsvorlage(n) wurden vom Kunden zur Prüfung eingereicht.`
  });

  saveState({ immediate: true });
  showToast(`${submitRows.length} Arbeitsvorlage(n) zur Prüfung eingereicht.`);
  render();
}

function resubmitOnboardingDraft(id, options = {}) {
  if (!canSubmitDocuments()) {
    showPermissionToast("Arbeitsvorlagen einreichen", "Kunden-, Contributor- oder Beraterrechten");
    return false;
  }
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) return false;
  const documentBeforeUpdate = findDocumentForTemplateDraft(draft, draft.title);
  if (!onboardingDraftNeedsRework(draft, documentBeforeUpdate)) {
    if (!options.silent) showToast("Diese Arbeitsvorlage ist aktuell nicht zur Nachbesserung zurückgegeben.");
    return false;
  }
  const quality = onboardingDraftQuality(draft);
  if (quality.requiredMissing.length) {
    if (!options.silent) showToast("Pflichtfelder sind noch offen. Die Arbeitsvorlage kann nicht erneut eingereicht werden.");
    return false;
  }
  const previousReason = draft.reworkReason || documentBeforeUpdate?.reworkReason || "";
  Object.assign(draft, {
    status: "In Prüfung",
    approval: "Prüfung läuft",
    reviewStatus: "vom_kunden_eingereicht",
    submittedAt: today(),
    submittedBy: workflowActor(),
    lastReworkReason: previousReason,
    reworkReason: "",
    reworkDue: "",
    updated: today()
  });
  const document = syncTemplateDraftDocument(draft, draft.title, "Arbeitsvorlagen-Nachbesserung erneut eingereicht");
  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "In Prüfung",
    approval: "Prüfung läuft",
    submittedAt: today(),
    submittedBy: workflowActor(),
    lastReworkReason: previousReason,
    reworkReason: "",
    reworkDue: ""
  }, "Arbeitsvorlagen-Nachbesserung erneut eingereicht"));
  addDocumentHistory(document, "Nachbesserung erneut eingereicht", previousReason || "Kunde hat die Arbeitsvorlage nachgebessert und erneut eingereicht.");
  completeDocumentWorkflowTasksByType(document, ["rework"], "Nachbesserung erneut eingereicht.");
  upsertDocumentWorkflowTask(document, "review");
  if (!options.silent) {
    saveState({ immediate: true });
    showToast("Arbeitsvorlage erneut zur Prüfung eingereicht.");
    render();
  }
  return true;
}

function resubmitOnboardingReworkPackage() {
  if (!canSubmitDocuments()) {
    showPermissionToast("Arbeitsvorlagen einreichen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const onboarding = normalizeOnboarding(state.onboarding);
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({
    draft,
    document: findDocumentForTemplateDraft(draft, draft.title),
    quality: onboardingDraftQuality(draft)
  }));
  const reworkRows = rows.filter((row) => onboardingDraftNeedsRework(row.draft, row.document));
  if (!reworkRows.length) {
    showToast("Es gibt aktuell keine Nachbesserungen an Arbeitsvorlagen.");
    return;
  }
  const blockers = reworkRows.filter((row) => row.quality.requiredMissing.length);
  if (blockers.length) {
    const created = createOnboardingGapTasksFromRows(reworkRows);
    saveState({ immediate: true });
    showToast(created
      ? "Pflichtfelder offen. Nacharbeitsaufgaben wurden angelegt."
      : "Pflichtfelder offen. Bitte Nachbesserungen vervollständigen.");
    render();
    return;
  }
  let submitted = 0;
  reworkRows.forEach((row) => {
    if (resubmitOnboardingDraft(row.draft.id, { silent: true })) submitted += 1;
  });
  saveState({ immediate: true });
  showToast(submitted ? `${submitted} Nachbesserung(en) erneut eingereicht.` : "Keine Nachbesserung wurde erneut eingereicht.");
  render();
}

function approveOnboardingDraft(id, options = {}) {
  if (!canReviewDocuments()) {
    showPermissionToast("Arbeitsvorlagen freigeben", "Reviewer-, Manager- oder Admin-Rechten");
    return false;
  }
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) return false;
  const documentBeforeUpdate = findDocumentForTemplateDraft(draft, draft.title);
  if (!onboardingDraftInReview(draft, documentBeforeUpdate)) {
    if (!options.silent) showToast("Nur eingereichte Arbeitsvorlagen können freigegeben werden.");
    return false;
  }
  const quality = onboardingDraftQuality(draft);
  if (quality.requiredMissing.length) {
    showToast("Pflichtfelder sind noch offen. Die Arbeitsvorlage kann nicht freigegeben werden.");
    return false;
  }
  const nextVersion = approvedDocumentVersion(draft.version || "0.1");
  Object.assign(draft, {
    status: "Freigegeben",
    approval: "Freigegeben",
    version: nextVersion,
    approvedAt: today(),
    approvedBy: workflowActor(),
    reworkReason: "",
    reworkDue: "",
    updated: today()
  });
  const document = syncTemplateDraftDocument(draft, draft.title, "Arbeitsvorlage freigegeben");
  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "Freigegeben",
    approval: "Freigegeben",
    version: approvedDocumentVersion(document.version || nextVersion),
    approvedAt: today(),
    approvedBy: workflowActor(),
    reworkReason: "",
    reworkDue: ""
  }, "Arbeitsvorlage freigegeben"));
  addDocumentHistory(document, "Freigegeben", "Arbeitsvorlage aus dem Startprofil wurde im Prüfcenter freigegeben.");
  completeDocumentWorkflowTasks(document, "Arbeitsvorlagen-Prüfung abgeschlossen.");
  if (!options.silent) {
    saveState({ immediate: true });
    showToast("Arbeitsvorlage freigegeben.");
    render();
  }
  return true;
}

function requestOnboardingDraftRework(id, row) {
  if (!canReviewDocuments()) {
    showPermissionToast("Nachbesserungen anfordern", "Reviewer-, Manager- oder Admin-Rechten");
    return false;
  }
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) return false;
  const documentBeforeUpdate = findDocumentForTemplateDraft(draft, draft.title);
  if (!onboardingDraftInReview(draft, documentBeforeUpdate)) {
    showToast("Nur eingereichte Arbeitsvorlagen können zur Nachbesserung zurückgegeben werden.");
    return false;
  }
  const note = String(row?.querySelector("[data-onboarding-review-note]")?.value || "").trim()
    || onboardingDraftReworkReason(draft);
  Object.assign(draft, {
    status: "Überarbeiten",
    approval: "Abgelehnt",
    reworkRequestedAt: today(),
    reworkRequestedBy: workflowActor(),
    reworkReason: note,
    reworkDue: futureDate(DOCUMENT_REWORK_DAYS),
    updated: today()
  });
  const document = syncTemplateDraftDocument(draft, draft.title, "Arbeitsvorlagen-Nachbesserung angefordert");
  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "Überarbeiten",
    approval: "Abgelehnt",
    reworkRequestedAt: today(),
    reworkRequestedBy: workflowActor(),
    reworkReason: note,
    reworkDue: futureDate(DOCUMENT_REWORK_DAYS)
  }, "Arbeitsvorlagen-Nachbesserung angefordert"));
  addDocumentHistory(document, "Nachbesserung angefordert", note);
  upsertDocumentWorkflowTask(document, "rework");
  saveState({ immediate: true });
  showToast("Nachbesserung für Arbeitsvorlage angefordert.");
  render();
  return true;
}

function onboardingDraftReworkReason(draft) {
  const quality = onboardingDraftQuality(draft);
  const missing = quality.requiredMissing.length ? quality.requiredMissing : quality.missing;
  if (missing.length) {
    return `Bitte folgende Felder in der Arbeitsvorlage nacharbeiten: ${missing.map((field) => field.label).join(", ")}`;
  }
  return "Bitte Arbeitsvorlage fachlich nachbessern und erneut einreichen.";
}

function approveOnboardingStartPackage() {
  if (!canReviewDocuments()) {
    showPermissionToast("die Arbeitsvorlagen freigeben", "Reviewer-, Manager- oder Admin-Rechten");
    return;
  }
  const onboarding = normalizeOnboarding(state.onboarding);
  const rows = onboardingTemplateDrafts(onboarding).map((draft) => ({ draft, quality: onboardingDraftQuality(draft) }));
  const blockers = rows.filter((row) => row.quality.requiredMissing.length);
  if (blockers.length) {
    showToast("Arbeitsvorlagen haben noch Pflichtfeld-Blocker.");
    return;
  }
  const rework = rows.filter((row) => onboardingDraftNeedsRework(row.draft, findDocumentForTemplateDraft(row.draft, row.draft.title)));
  if (rework.length) {
    showToast("Arbeitsvorlagen enthalten Nachbesserungen und können noch nicht gesammelt freigegeben werden.");
    return;
  }
  let approved = 0;
  rows.forEach(({ draft }) => {
    if (onboardingDraftApproved(draft, findDocumentForTemplateDraft(draft, draft.title))) return;
    if (!onboardingDraftInReview(draft, findDocumentForTemplateDraft(draft, draft.title))) return;
    if (approveOnboardingDraft(draft.id, { silent: true })) approved += 1;
  });
  saveState({ immediate: true });
  showToast(approved ? `${approved} Arbeitsvorlage(n) freigegeben.` : "Arbeitsvorlagen waren bereits freigegeben.");
  render();
}

function upsertGeneratedTemplateDraft(draft) {
  const generatedKey = draft.generatedKey;
  const existing = generatedKey
    ? state.templateDrafts.find((item) => item.generatedKey === generatedKey)
    : null;

  if (existing) {
    Object.assign(existing, {
      ...draft,
      id: existing.id,
      added: existing.added || today(),
      updated: today()
    });
    return false;
  }

  state.templateDrafts.unshift({
    id: crypto.randomUUID(),
    added: today(),
    ...draft
  });
  return true;
}

function addConsultantTemplateDraft(templateId, customer, data, options = {}) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === templateId);
  if (!template) return { templateDrafts: 0, documents: 0 };

  const generatedKey = `consultant:${normalizeImportKey(customer)}:${templateId}`;
  const content = buildTemplateDocument(template, data);
  const createdDraft = upsertGeneratedTemplateDraft({
    generatedKey,
    title: `${customer} - ${options.title || template.outputName || template.title}`,
    templateId,
    templateTitle: template.title,
    area: template.area,
    linkedTo: options.linkedTo || template.linkedTo,
    source: "Beratergenerator",
    data,
    content
  });

  const documentName = `${options.documentName || template.outputName || template.title} - ${customer}`;
  const createdDocument = addRecordIfMissing("documents", "name", documentName, {
    name: documentName,
    area: template.area,
    status: "Entwurf",
    owner: data.owner || options.owner || "ISB",
    linkedTo: options.linkedTo || template.linkedTo,
    size: "",
    note: `Aus Beratergenerator als ausfüllbare Vorlage erzeugt: ${template.title}`,
    added: today()
  });

  return {
    templateDrafts: createdDraft ? 1 : 0,
    documents: createdDocument ? 1 : 0
  };
}

function addConsultantTemplateCounts(created, counts) {
  created.templateDrafts += counts.templateDrafts || 0;
  created.documents += counts.documents || 0;
}

function createConsultantTemplateDrafts(answers, customer, owner, sponsor) {
  const created = { templateDrafts: 0, documents: 0 };
  const systems = splitAnswerList(`${answers.scopeSystems}\n${answers.criticalSystems}`);
  const assets = splitAnswerList(`${answers.informationAssets}\n${answers.criticalSystems}`);
  const threats = splitAnswerList(answers.topThreats);
  const vendors = splitAnswerList(`${answers.criticalVendors}\n${answers.cloudServices}`);
  const firstSystem = systems[0] || assets[0] || "Kritischer Prozess";
  const firstAsset = assets[0] || firstSystem;
  const firstThreat = threats[0] || "Ransomware";
  const firstVendor = vendors[0] || "Kritischer Dienstleister";
  const scopeText = [
    answers.scopeGoal,
    answers.scopeSystems ? `Systeme/Prozesse: ${answers.scopeSystems}` : "",
    answers.locations ? `Standorte/Länder: ${answers.locations}` : ""
  ].filter(Boolean).join("\n");

  [
    ["scope", {
      organization: customer,
      scope: scopeText || "Anwendungsbereich mit Kunde fachlich finalisieren.",
      interfaces: answers.interfaces || answers.cloudServices || "",
      exclusions: answers.exclusions || "Keine Ausschlüsse erfasst; fachlich prüfen.",
      owner,
      review: futureDate(90)
    }],
    ["interested-parties", {
      party: answers.interestedParties || "Kunden, Mitarbeitende, Lieferanten, Behörden, Geschäftsleitung",
      expectation: answers.legalRequirements || "Informationssicherheitsanforderungen und relevante Erwartungen konkretisieren.",
      relevance: "Hoch",
      evidence: "Scope, Rechtsregister, Verträge, Policy Management, Projektstrukturplan",
      owner
    }],
    ["risk-method", {
      scale: answers.riskMethod || "5x5 Likelihood/Impact",
      criteria: "Vertraulichkeit, Integrität, Verfügbarkeit, rechtliche/vertragliche Auswirkungen und Betriebsunterbrechung.",
      acceptance: answers.riskAcceptance || "Akzeptanzlogik durch Management festlegen.",
      treatment: "Reduzieren, vermeiden, übertragen oder akzeptieren; Entscheidung und Restrisiko dokumentieren.",
      cycle: "Quartalsweise"
    }],
    ["risk-assessment-report", {
      asset: firstAsset,
      scenario: `${firstThreat}: Auswirkung auf ${firstSystem}`,
      likelihood: "3",
      impact: "4",
      evaluation: answers.treatmentPriorities || "Im Risikoworkshop bewerten und Behandlungsentscheidung treffen.",
      owner
    }],
    ["risk-treatment-plan", {
      risk: `${firstThreat}: Auswirkung auf ${firstSystem}`,
      option: "Reduzieren",
      control: "Annex-A-Control passend nach SoA-Entscheidung zuordnen.",
      measure: answers.treatmentPriorities || "Maßnahmen priorisieren, Owner festlegen und Nachweise verknüpfen.",
      owner,
      due: futureDate(30)
    }],
    ["legal-register-entry", {
      requirement: answers.nisNotes || answers.legalRequirements || "NIS-2-Betroffenheit und weitere rechtliche/vertragliche Anforderungen prüfen.",
      source: "NIS-2-Dokument, §28 bis §39 / ISO 27001 EN, Annex A, A.5.31",
      applicability: answers.nisApplicability || "Zu prüfen",
      implementation: "Rechtsregister pflegen, Owner benennen, Fristen und Nachweise verknüpfen.",
      owner: "Legal / ISB",
      review: futureDate(45)
    }],
    ["supplier-security", {
      supplier: firstVendor,
      service: answers.cloudServices || "IKT / Cloud / Dienstleistung",
      criticality: "Hoch",
      requirements: answers.contractGaps || "Sicherheitsanforderungen, Incident-Meldung, Audit-/Nachweisrechte und Exit prüfen.",
      evidence: "Vertrag, Sicherheitsfragebogen, Zertifikat, Auditnachweis oder Lieferantenbewertung.",
      decision: "Nachbesserung"
    }],
    ["access-control-policy", {
      principles: answers.accessModel || "Need-to-know, Least Privilege, MFA und regelmäßige Rezertifizierung.",
      roles: answers.assetOwners || "Rollenmodell mit HR, IT und Fachbereichen finalisieren.",
      joinerMoverLeaver: "Anlage, Änderung und Entzug von Rechten über geregelten Prozess.",
      privileged: "Admin- und privilegierte Zugriffe separat genehmigen, protokollieren und reviewen.",
      review: "Quartalsweise"
    }],
    ["backup-restore-test", {
      system: firstSystem,
      backupType: answers.backupStatus || "Backup-Umfang und Frequenz erfassen.",
      testScope: "Restore kritischer Daten/Systeme praktisch prüfen.",
      result: "Nachtest erforderlich",
      issues: "Offene Punkte im Maßnahmenregister verfolgen.",
      nextTest: futureDate(60)
    }],
    ["business-continuity", {
      service: firstSystem,
      rto: "[ausfüllen]",
      rpo: "[ausfüllen]",
      scenarios: "Ausfall, Ransomware, Cloud-/Lieferantenausfall, Standortausfall.",
      recovery: answers.backupStatus || "Wiederanlaufprozess und Verantwortlichkeiten erfassen.",
      test: "Übung oder Tabletop-Test planen."
    }],
    ["vulnerability-management", {
      sources: "Scanner, Herstellerinformationen, Dienstleistermeldungen und interne Findings.",
      assessment: answers.vulnerabilityStatus || "Kritikalität, Exposition und betroffene Systeme bewerten.",
      sla: "Fristen je Kritikalität festlegen.",
      exceptions: "Ausnahmen risikobewerten, befristen und freigeben.",
      owner: "IT Security"
    }],
    ["logging-monitoring", {
      sources: answers.loggingStatus || "Kritische Systeme, Identitäten, Admin-Aktionen, Netzwerk- und Sicherheitsereignisse.",
      retention: "Aufbewahrung gemäß Rechtsregister und Betriebsanforderung festlegen.",
      protection: "Integrität, Zugriffsschutz und Manipulationsschutz sicherstellen.",
      monitoring: "Use Cases und Alarme für kritische Ereignisse definieren.",
      response: "Bewertung, Eskalation und Incident-Prozess verknüpfen."
    }],
    ["awareness-plan", {
      audience: "Alle Mitarbeitenden, IT, Management und relevante Dienstleister",
      content: answers.awarenessStatus || "Policies, Meldewege, Phishing, Rollenpflichten, NIS-2-Leitungsaufgaben.",
      frequency: "Jährlich",
      evidence: "Teilnahmelisten, LMS-Export, Quiz, Bestätigung.",
      effectiveness: "Teilnahmequote, Tests, Feedback und Incident-Trends."
    }],
    ["communication-plan", {
      audience: "Mitarbeitende, Management, Kunden, Lieferanten, Behörden",
      content: answers.incidentProcess || "Policy-Updates, Risiken, Incident-Status, Schulungen und Nachweise.",
      frequency: "Anlassbezogen",
      channel: "E-Mail, Portal, Meeting, Ticket oder gesicherter Kommunikationskanal.",
      responsible: owner,
      effectiveness: "Reichweite, Reaktionszeiten, Feedback und Review im Management Review."
    }],
    ["management-review", {
      date: futureDate(90),
      participants: `${sponsor}, ${owner}, IT, Fachbereiche, Legal`,
      inputs: "Risiken, Incidents, Auditstatus, Maßnahmen, Lieferanten, Ziele und NIS-2-Einordnung.",
      decisions: "Freigaben, Prioritäten, Ressourcen und Restrisikoentscheidungen dokumentieren.",
      actions: "Aufgaben mit Owner und Frist in SFM Compliance nachhalten.",
      training: answers.awarenessStatus || "Management- und Mitarbeiterschulungen planen."
    }],
    ["document-control", {
      documentType: "Policies, Register, Nachweise, Reports und Protokolle",
      owner,
      approval: "Prüfung durch Dokument-Owner, Freigabe durch zuständige Rolle.",
      versioning: "Version, Änderungshistorie, Review-Datum und Freigabestatus pflegen.",
      retention: answers.evidenceStorage || "Zentrale Ablage mit Zugriffsschutz, Backup und Aufbewahrungslogik."
    }]
  ].forEach(([templateId, data]) => {
    addConsultantTemplateCounts(created, addConsultantTemplateDraft(templateId, customer, data, { owner }));
  });

  if (answers.cloudServices) {
    addConsultantTemplateCounts(created, addConsultantTemplateDraft("cloud-policy", customer, {
      service: answers.cloudServices,
      approval: "Neue Cloud-Dienste vor Nutzung über Einkauf/IT/ISB prüfen und freigeben.",
      requirements: "Verschlüsselung, IAM/MFA, Logging, Backup, Standort, Vertrags- und Exit-Regelung prüfen.",
      data: answers.dataCategories || "Datenarten und Schutzbedarf erfassen.",
      exit: "Datenexport, Löschung, Übergabe und Vertragsende dokumentieren."
    }, { owner }));
  }

  if (answers.secureDevelopment && answers.secureDevelopment !== "Nicht relevant") {
    addConsultantTemplateCounts(created, addConsultantTemplateDraft("secure-development", customer, {
      requirements: "Security Requirements vor Entwicklung oder Beschaffung erfassen und freigeben.",
      architecture: "Sichere Architektur- und Engineering-Grundsätze dokumentieren.",
      coding: "Secure Coding, Code Review und Tooling festlegen.",
      testing: "Security Testing in Entwicklung und Abnahme planen.",
      environments: "Entwicklung, Test und Produktion trennen."
    }, { owner: "IT / Entwicklung" }));
  }

  return created;
}

function updateProjectPlanFromConsultant(answers, owner, sponsor) {
  const nisRelevant = answers.nisApplicability && !answers.nisApplicability.startsWith("Nicht betroffen");
  const updates = {
    "iso-01": { owner, due: futureDate(7), status: "In Arbeit" },
    "iso-02": { owner: sponsor, due: futureDate(14), status: "In Arbeit" },
    "iso-03": { owner, due: futureDate(21), status: "In Arbeit" },
    "iso-04": { owner, due: futureDate(35), status: "In Arbeit" },
    "iso-05": { owner, due: futureDate(28), status: "In Arbeit" },
    "shared-01": { owner, due: futureDate(21), status: "In Arbeit" },
    "shared-02": { owner: "Einkauf / ISB", due: futureDate(30), status: "In Arbeit" },
    "shared-03": { owner, due: futureDate(35), status: "In Arbeit" }
  };

  if (nisRelevant) {
    Object.assign(updates, {
      "nis-01": { owner: "Legal / Geschäftsleitung", due: futureDate(14), status: "In Arbeit" },
      "nis-02": { owner, due: futureDate(30), status: "In Arbeit" },
      "nis-03": { owner, due: futureDate(30), status: "In Arbeit" },
      "nis-04": { owner: "Legal / Geschäftsleitung", due: futureDate(45), status: "In Arbeit" },
      "nis-05": { owner: sponsor, due: futureDate(45), status: "In Arbeit" },
      "nis-06": { owner, due: futureDate(60), status: "In Arbeit" }
    });
  }

  let changed = 0;
  state.projectPlan = normalizeProjectPlan(state.projectPlan).map((item) => {
    const update = updates[item.id];
    if (!update || item.status === "Erledigt") return item;
    changed += 1;
    return {
      ...item,
      ...update,
      generatorLinked: today()
    };
  });
  return changed;
}

function consultantWorkspaceTotals() {
  return {
    documents: state.documents.length,
    templateDrafts: state.templateDrafts.length,
    assets: state.assets.length,
    risks: state.risks.length,
    suppliers: state.suppliers.length,
    policies: state.policies.length,
    tasks: state.tasks.length
  };
}

function applyConsultantGenerator(answers) {
  const customer = answers.customerName || "Kunde";
  const owner = answers.ismsOwner || "ISB";
  const sponsor = answers.managementSponsor || "Geschäftsleitung";
  const created = {
    documents: 0,
    templateDrafts: 0,
    assets: 0,
    risks: 0,
    suppliers: 0,
    contracts: 0,
    policies: 0,
    legal: 0,
    incidents: 0,
    tasks: 0,
    projectPlan: 0,
    policyPackage: {
      policies: 0,
      drafts: 0,
      documents: 0,
      tasks: 0
    }
  };
  const content = buildConsultantMarkdown(answers);

  state.consultantGenerator = {
    lastAnswers: answers,
    lastGeneratedAt: today()
  };

  const mainDraftCreated = upsertGeneratedTemplateDraft({
    generatedKey: `consultant:${normalizeImportKey(customer)}:startpaket`,
    title: `Beratergenerator ISMS/NIS-2 Arbeitsunterlagen ${customer} ${today()}`,
    templateId: "consultant-generator",
    templateTitle: "Beratergenerator",
    area: "Berater",
    linkedTo: "ISO 27001 / NIS-2",
    data: answers,
    content
  });
  if (mainDraftCreated) created.templateDrafts += 1;

  [
    ["ISMS Scope Entwurf", "Dokumentation", "Clause 4.3"],
    ["Kontext und interessierte Parteien", "Dokumentation", "Clause 4.1 / Clause 4.2"],
    ["Risikomethodik und Risiko-Startregister", "Risk", "Clause 6.1"],
    ["NIS-2 Erstnotiz", "Rechtsregister", "§28 / §30 / §32 / §38 / §39"],
    ["Nachweis-Mapping Arbeitsunterlagen", "Dokumentation", "Clause 7.5 / §39"]
  ].forEach(([name, area, linkedTo]) => {
    const added = addRecordIfMissing("documents", "name", `${name} - ${customer}`, {
      name: `${name} - ${customer}`,
      area,
      status: "Entwurf",
      owner,
      linkedTo,
      size: "",
      note: "Aus Beratergenerator erstellt",
      added: today()
    });
    if (added) created.documents += 1;
  });

  const generatedTemplates = createConsultantTemplateDrafts(answers, customer, owner, sponsor);
  created.templateDrafts += generatedTemplates.templateDrafts;
  created.documents += generatedTemplates.documents;

  splitAnswerList(`${answers.criticalSystems}\n${answers.informationAssets}`).forEach((asset) => {
    const added = addRecordIfMissing("assets", "name", asset, {
      name: asset,
      type: "Information / System",
      owner: answers.assetOwners || owner,
      criticality: "Hoch",
      protection: answers.dataCategories || "C/I/A prüfen",
      status: "In Prüfung"
    });
    if (added) created.assets += 1;
  });

  const threats = splitAnswerList(answers.topThreats);
  const defaultThreats = ["Ransomware", "Cloud-/IKT-Dienstleisterausfall", "Unklare Zugriffsrechte"];
  (threats.length ? threats : defaultThreats).forEach((threat) => {
    const scenario = `${threat}: Auswirkung auf ${splitAnswerList(answers.criticalSystems)[0] || "kritische Systeme oder Prozesse"}`;
    const added = addRecordIfMissing("risks", "scenario", scenario, {
      riskId: nextRiskId(),
      scenario,
      asset: splitAnswerList(answers.criticalSystems)[0] || "Kritischer Prozess",
      cia: "C/I/A kombiniert",
      impact: 4,
      likelihood: 3,
      owner,
      treatmentOption: "Reduzieren",
      controls: "Clause 6.1 / Annex A passend zuordnen",
      treatment: answers.treatmentPriorities || "Maßnahmen priorisieren und Verantwortliche festlegen.",
      status: "In Bewertung",
      review: futureDate(30),
      added: today()
    });
    if (added) created.risks += 1;
  });

  splitAnswerList(`${answers.criticalVendors}\n${answers.cloudServices}`).forEach((vendor) => {
    const supplierAdded = addRecordIfMissing("suppliers", "name", vendor, {
      name: vendor,
      service: "IKT / Cloud / Dienstleistung",
      criticality: "Hoch",
      owner: "Einkauf / ISB",
      review: "In Prüfung",
      nextReview: futureDate(60)
    });
    if (supplierAdded) created.suppliers += 1;

    const contractAdded = addRecordIfMissing("contracts", "title", `Sicherheitsanforderungen ${vendor}`, {
      title: `Sicherheitsanforderungen ${vendor}`,
      vendor,
      owner: "Einkauf / Legal",
      status: "Prüfen",
      review: futureDate(45),
      linkedTo: "A.5.20 / §30 Abs. 2 Nr. 4"
    });
    if (contractAdded) created.contracts += 1;
  });

  [
    ["Information Security Policy", sponsor, "Clause 5.2 / A.5.1"],
    ["Access Control Policy", owner, "A.5.15-A.5.18"],
    ["Incident Response Policy", owner, "A.5.24-A.5.28 / §32 / §35"],
    ["Supplier Security Policy", "Einkauf / ISB", "A.5.19-A.5.23 / §30 Abs. 2 Nr. 4"],
    ["Backup and Continuity Policy", "IT / Betrieb", "§30 / A.5.29-A.5.30"],
    ["Awareness and Training Plan", owner, "Clause 7 / §38"]
  ].forEach(([title, policyOwner]) => {
    const added = addRecordIfMissing("policies", "title", title, {
      title,
      owner: policyOwner,
      version: "0.1",
      status: "Entwurf",
      review: futureDate(90)
    });
    if (added) created.policies += 1;
  });

  if (answers.secureDevelopment && answers.secureDevelopment !== "Nicht relevant") {
    const added = addRecordIfMissing("policies", "title", "Secure Development Policy", {
      title: "Secure Development Policy",
      owner: owner,
      version: "0.1",
      status: "Entwurf",
      review: futureDate(90)
    });
    if (added) created.policies += 1;
  }

  created.policyPackage = createPolicyPackage({ save: false });

  if (answers.nisApplicability && !answers.nisApplicability.startsWith("Nicht betroffen")) {
    [
      ["NIS-2 Betroffenheit und Einrichtungsart prüfen", "NIS-2-Dokument, §28", "Legal / Geschäftsleitung"],
      ["NIS-2 Risikomanagementmaßnahmen strukturieren", "NIS-2-Dokument, §30", owner],
      ["NIS-2 Incident-Meldeprozess vorbereiten", "NIS-2-Dokument, §32 / §35", owner],
      ["NIS-2 Geschäftsleitungsaufgaben und Schulung planen", "NIS-2-Dokument, §38", sponsor],
      ["NIS-2 Nachweispflichten und Prüfung vorbereiten", "NIS-2-Dokument, §39", owner]
    ].forEach(([requirement, source, legalOwner]) => {
      const added = addRecordIfMissing("legal", "requirement", requirement, {
        requirement,
        source,
        owner: legalOwner,
        status: "Prüfen",
        due: futureDate(45)
      });
      if (added) created.legal += 1;
    });
  }

  const incidentAdded = addRecordIfMissing("incidents", "title", `Incident-Meldeprozess ${customer} testen`, {
    title: `Incident-Meldeprozess ${customer} testen`,
    severity: "Mittel",
    owner,
    status: "Offen",
    detected: "",
    due: futureDate(21),
    note: answers.incidentProcess || "Meldeweg, Erstbewertung, Eskalation und Lessons Learned testen."
  });
  if (incidentAdded) created.incidents += 1;

  [
    ["Scope-Entwurf fachlich mit Management freigeben", "Dokumentation", sponsor, 7],
    ["Risikoworkshop auf Basis des Startregisters durchführen", "Risiko Management", owner, 14],
    ["Lieferanten- und Vertragsreview priorisieren", "Vendor Management", "Einkauf / ISB", 21],
    ["Policy-Paket prüfen und Owner bestätigen", "Policy Management", owner, 21],
    ["NIS-2 Einordnung fachlich bestätigen", "Rechtsregister", "Legal / Geschäftsleitung", 14],
    ["Nachweisablage und Dokumentenlenkung festlegen", "Dokumentation", owner, 10]
  ].forEach(([title, module, taskOwner, days]) => {
    const added = addTaskIfMissing({
      title: `${customer}: ${title}`,
      module,
      owner: taskOwner,
      due: futureDate(days),
      status: "Offen"
    });
    if (added) created.tasks += 1;
  });

  created.projectPlan = updateProjectPlanFromConsultant(answers, owner, sponsor);

  state.consultantGenerator = {
    lastAnswers: answers,
    lastGeneratedAt: today(),
    lastCreated: {
      ...created,
      totals: consultantWorkspaceTotals()
    }
  };

  saveState();
  return created;
}

function buildConsultantMarkdown(answers) {
  const customer = answers.customerName || "[Kunde]";
  const lines = [
    `# ISMS/NIS-2 Arbeitsunterlagen - ${customer}`,
    "",
    `Datum: ${today()}`,
    "Typ: Berater-Entwurf",
    "",
    "## Grenze",
    "- Dieser Entwurf ist eine praxisnahe Umsetzungshilfe auf Basis der in SFM Compliance hinterlegten lokalen Dokumente.",
    "- ISO 27001 und NIS-2 werden getrennt betrachtet.",
    "- Der Entwurf ersetzt keine Zertifizierung, kein internes Audit und keine Rechtsprüfung.",
    "",
    "## Kurzprofil"
  ];

  [
    ["Organisation", answers.customerName],
    ["Ansprechpartner", answers.contactPerson],
    ["Geschäftsmodell", answers.businessModel],
    ["Größe", answers.employees],
    ["Standorte", answers.locations],
    ["Management Sponsor", answers.managementSponsor],
    ["ISMS Owner", answers.ismsOwner]
  ].forEach(([label, value]) => lines.push(`- ${label}: ${value || "[offen]"}`));

  lines.push("", "## Scope-Entwurf", `- Ziel: ${answers.scopeGoal || "[offen]"}`, `- Systeme / Prozesse: ${answers.scopeSystems || "[offen]"}`, `- Schnittstellen: ${answers.interfaces || "[offen]"}`, `- Ausschlüsse / Grenzen: ${answers.exclusions || "[offen]"}`, "Quelle: [ISO 27001 EN, Clause 4.3] / [Praxisbuch, Kapitel 4.4]");

  lines.push("", "## Kontext und Anforderungen", `- Interessierte Parteien: ${answers.interestedParties || "[offen]"}`, `- Anforderungen: ${answers.legalRequirements || "[offen]"}`, `- NIS-2 Status: ${answers.nisApplicability || "[offen]"}`, `- NIS-2 Notizen: ${answers.nisNotes || "[offen]"}`, "Quellen: [ISO 27001 EN, Clause 4.1 und Clause 4.2] / [NIS-2-Dokument, §28 bis §39]");

  lines.push("", "## Assets und Risiko", `- Informationswerte: ${answers.informationAssets || "[offen]"}`, `- Kritische Systeme: ${answers.criticalSystems || "[offen]"}`, `- Risikomethodik: ${answers.riskMethod || "[offen]"}`, `- Top-Bedrohungen: ${answers.topThreats || "[offen]"}`, `- Behandlungsprioritäten: ${answers.treatmentPriorities || "[offen]"}`, "Quellen: [ISO 27001 EN, Clause 6.1] / [ISO 27001 EN, Annex A, A.5.9] / [NIS-2-Dokument, §30]");

  lines.push("", "## Lieferanten, Policies und Betrieb", `- Cloud-/IKT-Dienste: ${answers.cloudServices || "[offen]"}`, `- Kritische Lieferanten: ${answers.criticalVendors || "[offen]"}`, `- Vertragslücken: ${answers.contractGaps || "[offen]"}`, `- Bestehende Policies: ${answers.existingPolicies || "[offen]"}`, `- Zugriff / MFA: ${answers.accessModel || "[offen]"} / ${answers.mfaStatus || "[offen]"}`, `- Backup: ${answers.backupStatus || "[offen]"}`, `- Logging: ${answers.loggingStatus || "[offen]"}`, `- Schwachstellen: ${answers.vulnerabilityStatus || "[offen]"}`, "Quellen: [ISO 27001 EN, Annex A, A.5.1, A.5.15 bis A.5.23, A.8.8, A.8.15 und A.8.16] / [NIS-2-Dokument, §30]");

  lines.push("", "## Incident, Awareness und Audit", `- Incident-Prozess: ${answers.incidentProcess || "[offen]"}`, `- Kontaktstelle: ${answers.reportingContact || "[offen]"}`, `- Awareness: ${answers.awarenessStatus || "[offen]"}`, `- Audit / Management Review: ${answers.auditReview || "[offen]"}`, `- Nachweisablage: ${answers.evidenceStorage || "[offen]"}`, "Quellen: [ISO 27001 EN, Clause 7, Clause 9, Annex A, A.5.24 bis A.5.28] / [NIS-2-Dokument, §32, §35, §38 und §39]");

  lines.push("", "## Nächste Schritte", "- Scope und Kontext fachlich bestätigen.", "- Risikoworkshop durchführen.", "- Policy-Arbeitsvorlagen prüfen und Owner festlegen.", "- Lieferanten- und Vertragsreview priorisieren.", "- NIS-2 Einordnung separat fachlich bewerten.", "- Nachweise in SFM Compliance verknüpfen.");
  return lines.join("\n");
}

function buildProductionReadiness() {
  const taskByTitle = new Map(state.tasks.map((task) => [String(task.title || ""), task]));
  const rows = PRODUCTION_CHECKS.map(([area, title, owner, must, doc], index) => {
    const task = taskByTitle.get(`Go-live: ${title}`);
    let status = "Offen";
    let signal = "Noch nicht nachgewiesen";

    if (task?.status === "Erledigt") {
      status = "Erledigt";
      signal = "Go-live-Aufgabe erledigt";
    } else if (task) {
      status = "In Arbeit";
      signal = `Aufgabe angelegt: ${task.status || "Offen"}`;
    } else if (title === "Backend-Modus statt file://" && location.protocol !== "file:") {
      status = backendHealth.ok ? "Erledigt" : "In Arbeit";
      signal = backendHealth.ok ? "Backend-Healthcheck erfolgreich" : "Servermodus geöffnet; Backend prüfen";
    } else if (title === "HTTPS und sichere Cookies" && location.protocol === "https:") {
      status = "In Arbeit";
      signal = "HTTPS im Browser aktiv; Cookie-/Proxy-Konfiguration prüfen";
    } else if (title === "Kundenprozess abgenommen" && state.documents.length > SOURCE_FILES.length && state.risks.length > 1) {
      status = "In Arbeit";
      signal = "Testdaten vorhanden; UX-Abnahme noch freigeben";
    } else if (title === "Rechts- und Datenschutzfreigabe" && state.legal.some((item) => String(item.status || "").includes("Umgesetzt"))) {
      status = "In Arbeit";
      signal = "Rechtsregister enthält umgesetzte Punkte; formale Freigabe ergänzen";
    }

    return { id: `prod-${index + 1}`, area, title, owner, must, doc, task, status, signal };
  });
  const done = rows.filter((row) => row.status === "Erledigt").length;
  const inProgress = rows.filter((row) => row.status === "In Arbeit").length;
  const percent = Math.round((done / Math.max(rows.length, 1)) * 100);
  return { rows, done, inProgress, percent };
}

function renderProductionReadiness() {
  const readiness = buildProductionReadiness();
  const open = PRODUCTION_CHECKS.length - readiness.done - readiness.inProgress;
  const backendClass = backendHealth.ok ? "practice" : backendHealth.checked ? "must" : "should";

  return `
    <section class="panel">
      <div class="panel-header">
        <div>
          <span class="eyebrow">Go-live Readiness</span>
          <h3>Produktivbetrieb, UX, Recht, Betrieb und Security-Härtung</h3>
          <p>Diese Sicht bewertet die technische Kundenfähigkeit der Plattform. ISO- und NIS-2-Nachweise bleiben fachlich getrennt in den jeweiligen Modulen.</p>
        </div>
        <div class="action-row">
          <button class="primary-button" type="button" data-production-task-pack>Go-live Aufgaben anlegen</button>
          <button class="quiet-button" type="button" data-production-report>Freigabebericht herunterladen</button>
          <button class="quiet-button" type="button" data-backend-health>Backend testen</button>
        </div>
      </div>

      <div class="metrics">
        ${metric("Go-live Readiness", `${readiness.percent}%`, `${readiness.done} von ${PRODUCTION_CHECKS.length} erledigt`)}
        ${metric("In Arbeit", readiness.inProgress, "teilweise vorbereitet")}
        ${metric("Offen", open, "noch ohne Nachweis")}
        ${metric("Backend", backendHealth.ok ? "OK" : "Prüfen", backendHealth.detail)}
      </div>
    </section>

    ${renderBackendAccessPanel("production")}
    ${renderProductionAdminCenter()}

    <section class="table-panel" style="margin-top:18px">
      <h3>Produktionscheckliste</h3>
      <div class="table-scroll">
        <table class="data-table project-table">
          <thead><tr><th>Bereich</th><th>Status</th><th>MUSS</th><th>Owner</th><th>Dokument</th></tr></thead>
          <tbody>
            ${readiness.rows.map((row) => `
              <tr>
                <td><strong>${escapeHtml(row.area)}</strong><br><span class="muted">${escapeHtml(row.title)}</span></td>
                <td><span class="tag ${productionStatusClass(row.status)}">${escapeHtml(row.status)}</span><br><span class="muted">${escapeHtml(row.signal)}</span></td>
                <td>${escapeHtml(row.must)}<br><span class="muted">Technische Plattformreife; keine ISO-/NIS-2-Fachquelle.</span></td>
                <td>${escapeHtml(row.owner)}</td>
                <td><a href="docs/${escapeHtml(row.doc)}" target="_blank" rel="noreferrer">${escapeHtml(row.doc)}</a></td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    </section>

    <div class="dashboard-grid" style="margin-top:18px">
      <section class="panel">
        <div class="panel-header">
          <div>
            <h3>Produktionsunterlagen</h3>
            <p>Lokale Unterlagen für Deployment, UX-Abnahme, Datenschutz-Freigabe, Betrieb und Hardening.</p>
          </div>
        </div>
        <div class="source-grid">
          ${PRODUCTION_DOCS.map(([title, href, purpose]) => `
            <div class="source-panel">
              <strong>${escapeHtml(title)}</strong>
              <p class="muted">${escapeHtml(purpose)}</p>
              <a href="${escapeHtml(href)}" target="_blank" rel="noreferrer">Öffnen</a>
            </div>
          `).join("")}
        </div>
      </section>

      <section class="panel">
        <div class="panel-header">
          <div>
            <h3>Backend-Status</h3>
            <p>Der Test prüft, ob der aktuelle Server die Backend-API bereitstellt.</p>
          </div>
        </div>
        <div class="source-list">
          <div><strong>Status:</strong> <span class="tag ${backendClass}">${escapeHtml(backendHealth.ok ? "OK" : backendHealth.checked ? "Fehler" : "Nicht geprüft")}</span></div>
          <div><strong>Detail:</strong> ${escapeHtml(backendHealth.detail)}</div>
          <div><strong>Grenze:</strong> Rechtstexte und konkrete Datenschutzklauseln sind in den vorliegenden Dokumenten nicht enthalten.</div>
        </div>
      </section>
    </div>
  `;
}

function teamInviteRoles() {
  if (backendSessionUser?.platformAdmin) return productionAdminData.security?.roles || ["admin", "consultant", "manager", "customer", "contributor", "auditor", "viewer"];
  return ["manager", "customer", "contributor", "auditor", "viewer"];
}

function renderFileQuarantine() {
  if (!backendSessionUser) {
    return `<section class="panel">${renderAccessState("Anmeldung erforderlich", "Die Datei-Quarantäne ist nur für berechtigte Admins verfügbar.", [{ label: "Mein Konto", view: "account" }], { mark: "DQ" })}</section>`;
  }
  if (!isBackendAdmin()) {
    return `<section class="panel">${renderAccessState("Adminzugriff erforderlich", "Isolierte Dateien enthalten interne Sicherheitsinformationen und können nur von Admins bearbeitet werden.", [{ label: "Dashboard", view: "dashboard" }], { mark: "DQ" })}</section>`;
  }
  if (productionAdminData.loading && !productionAdminData.loaded) {
    return `<section class="panel">${renderEmptyState("Quarantäne wird geladen", "Scannerstatus und isolierte Dateien werden sicher abgerufen.", [], { mark: "DQ" })}</section>`;
  }
  const quarantine = productionAdminData.quarantine || { scanner: {}, files: [] };
  const scanner = quarantine.scanner || {};
  const files = Array.isArray(quarantine.files) ? quarantine.files : [];
  return `
    <div class="quarantine-workspace">
      <section class="panel quarantine-hero">
        <div>
          <span class="eyebrow">Upload-Sicherheit</span>
          <h3>Datei-Quarantäne</h3>
          <p>Verdächtige oder bei verpflichtender Prüfung nicht prüfbare Uploads bleiben verschlüsselt isoliert. Sie erscheinen nicht im Kundenbestand und können nicht heruntergeladen werden.</p>
        </div>
        <div class="quarantine-kpis">
          <div class="${scanner.ready ? "ok" : "warn"}"><strong>${scanner.ready ? "Aktiv" : "Prüfen"}</strong><span>Scanner</span></div>
          <div class="${files.length ? "warn" : "ok"}"><strong>${files.length}</strong><span>isoliert</span></div>
          <div><strong>${escapeHtml(scanner.mode || "-")}</strong><span>Modus</span></div>
        </div>
      </section>

      <section class="panel quarantine-status-panel">
        <div>
          <span class="eyebrow">Scannerstatus</span>
          <h3>${scanner.ready ? "Upload-Prüfung ist erreichbar" : "Upload-Prüfung benötigt Aufmerksamkeit"}</h3>
          <p>${escapeHtml(scanner.detail || "Noch kein Scannerstatus verfügbar.")}</p>
        </div>
        <button class="quiet-button" type="button" data-admin-refresh>Aktualisieren</button>
      </section>

      <section class="table-panel quarantine-list-panel">
        <div class="table-panel-heading">
          <div>
            <span class="eyebrow">Isolierte Uploads</span>
            <h3>Administrativ prüfen oder löschen</h3>
            <p>Eine Freigabe erfolgt ausschließlich nach einem erneut erfolgreichen Malware-Scan. Manuelles Überspringen ist nicht vorgesehen.</p>
          </div>
        </div>
        <div class="quarantine-list">
          ${files.length ? files.map((file) => `
            <article class="quarantine-item">
              <div class="quarantine-item-main">
                <span class="status-pill ${file.scanStatus === "infected" ? "danger" : "warning"}">${file.scanStatus === "infected" ? "Fund erkannt" : "Scan fehlgeschlagen"}</span>
                <h4>${escapeHtml(file.name || "Datei")}</h4>
                <p>${escapeHtml(file.tenantName || "Kundenraum")} · ${escapeHtml(file.uploadedBy || "Unbekannt")} · ${formatBytes(file.size || 0)}</p>
                <small>SHA-256: ${escapeHtml(file.sha256 || "-")}</small>
              </div>
              <div class="quarantine-item-detail">
                <span>Scanner</span><strong>${escapeHtml(file.scanEngine || "-")}</strong>
                <span>Hinweis</span><strong>${escapeHtml(file.signature || file.detail || "Prüfung erforderlich")}</strong>
                <span>Zeitpunkt</span><strong>${escapeHtml(formatBackendTime(file.scannedAt || file.uploadedAt))}</strong>
              </div>
              <div class="quarantine-item-actions">
                <button class="primary-button" type="button" data-quarantine-rescan="${escapeHtml(file.id)}">Prüfjob starten</button>
                <button class="danger-button" type="button" data-quarantine-delete="${escapeHtml(file.id)}">Endgültig löschen</button>
              </div>
            </article>
          `).join("") : renderEmptyState("Keine Dateien isoliert", "Aktuell wartet kein Upload in der Quarantäne.", [], { mark: "OK", compact: true })}
        </div>
      </section>
    </div>
  `;
}

