function renderTeamInvitationRow(invite) {
  const canRevoke = invite.status === "pending";
  const deliveryLabel = invitationDeliveryLabel(invite.deliveryStatus);
  const resendLabel = productionAdminData.invitationDeliveryConfigured ? "Erneut senden" : "Neuen Link erzeugen";
  return `
    <article class="team-invitation-row ${escapeHtml(invite.status || "pending")}">
      <div>
        <strong>${escapeHtml(invite.displayName || invite.email)}</strong>
        <span>${escapeHtml(invite.email)}</span>
        <small>${escapeHtml(invite.tenantName || backendSessionUser?.tenant?.name || "Mandant")} · eingeladen von ${escapeHtml(invite.invitedBy || "-")}</small>
      </div>
      <div>
        ${statusTag(invite.roleLabel || invite.role)}
        ${statusTag(invitationStatusLabel(invite.status))}
        ${statusTag(deliveryLabel)}
      </div>
      <div>
        <span>Gültig bis</span>
        <strong>${escapeHtml(formatBackendTime(invite.expiresAt))}</strong>
        ${invite.lastSentAt ? `<small>Letzter Versand: ${escapeHtml(formatBackendTime(invite.lastSentAt))}</small>` : ""}
        ${invite.deliveryError ? `<small class="team-delivery-error">${escapeHtml(invite.deliveryError)}</small>` : ""}
      </div>
      <div class="team-row-actions">
        ${canRevoke ? `<button class="quiet-button" type="button" data-admin-resend-invitation="${escapeHtml(invite.id)}">${resendLabel}</button>` : ""}
        ${canRevoke ? `<button class="danger-button" type="button" data-admin-revoke-invitation="${escapeHtml(invite.id)}">Widerrufen</button>` : ""}
      </div>
    </article>
  `;
}

function invitationDeliveryLabel(status) {
  if (status === "delivered") return "E-Mail zugestellt";
  if (status === "failed") return "Zustellung fehlgeschlagen";
  return "Link manuell teilen";
}

function invitationStatusLabel(status) {
  if (status === "pending") return "offen";
  if (status === "accepted") return "angenommen";
  if (status === "revoked") return "widerrufen";
  if (status === "expired") return "abgelaufen";
  return status || "offen";
}

