async function persistAuditExecutionFinding(index) {
  const visibleDocuments = state.documents.filter((document) => document.status !== "Quelle");
  const rows = auditTraceabilityRows(visibleDocuments);
  const finding = auditExecutionData(rows, auditPackageReportData()).findings[index];
  if (!finding) return;
  const record = normalizeAuditFinding({
    title: finding.title,
    type: finding.type,
    severity: finding.tone === "warning" ? "Hoch" : "Mittel",
    status: "offen",
    owner: finding.owner,
    due: finding.due,
    mapping: finding.linkedTo,
    note: finding.text,
    sourceView: finding.view || "audit",
    sourceRow: `${finding.type}|${finding.title}|${finding.linkedTo}`
  });
  if (state.auditFindings.some((item) => item.sourceRow === record.sourceRow && !["geschlossen", "abgelehnt"].includes(item.status))) {
    showToast("Dieser Prüfpunkt ist bereits als offenes Finding dokumentiert.", "warning");
    return;
  }
  let saved = false;
  if (recordMutationApiEnabled()) {
    saved = await createAuditFindingViaApi(record);
  } else {
    state.auditFindings.unshift(record);
    persist("Audit-Finding dokumentiert");
    saved = true;
  }
  if (saved) {
    showToast("Audit-Finding wurde dokumentiert.");
    render();
  }
}

async function updateAuditFindingField(id, field, value) {
  const finding = state.auditFindings.find((item) => String(item.id) === String(id));
  if (!finding || !field) return;
  let saved = false;
  if (recordMutationApiEnabled()) {
    saved = await updateAuditFindingViaApi(id, { [field]: value });
  } else {
    finding[field] = value;
    persist("Audit-Finding aktualisiert");
    saved = true;
  }
  if (saved) render();
}

async function deleteAuditFindingRecord(id) {
  if (!canEditWorkspace() || !window.confirm("Dieses Audit-Finding wirklich löschen?")) return;
  let deleted = false;
  if (recordMutationApiEnabled()) {
    deleted = await deleteAuditFindingViaApi(id);
  } else {
    state.auditFindings = state.auditFindings.filter((finding) => String(finding.id) !== String(id));
    persist("Audit-Finding gelöscht");
    deleted = true;
  }
  if (deleted) {
    showToast("Audit-Finding wurde gelöscht.");
    render();
  }
}

