function renderAssets() {
  const rows = state.assets;

  return `
    <div class="asset-command-page">
      <div class="asset-command-main">
        ${renderAssetManagementHero(rows)}
        ${renderAssetManagementWorkflow(rows)}
        ${renderReferenceRegisterPanel("Asset Register", "assets", rows, "Assets, Owner, Kritikalität, Nachweise und Reviews auf einer Arbeitsfläche.")}
        <details class="register-detail-disclosure">
          <summary>
            <span>Geführte Kundenansicht</span>
            <strong>Heute zuerst, Wartestatus und Freigaben anzeigen</strong>
          </summary>
          ${renderAssetCustomerHub(rows)}
        </details>
        ${renderAssetQuickForm()}
      </div>
      ${renderAssetManagementSideRail(rows)}
      ${renderRegisterDetailDrawer("assets", rows)}
    </div>
  `;
}

function renderAssetManagementHero(rows = []) {
  const groups = registerCustomerHubGroups("assets", rows);
  const next = registerCustomerNextAction("assets", groups);
  const total = rows.length;
  const linked = rows.filter((row) => registerRowLinked("assets", row)).length;
  const submitted = rows.filter((row) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(canonicalReviewStatus(row, registerReviewType("assets")))).length;
  const approved = rows.filter((row) => canonicalReviewStatus(row, registerReviewType("assets")) === "freigegeben").length;
  const metrics = registerCommandMetrics("assets", rows, groups, { total, linked, submitted, approved });
  const actions = ["Alle Assets anzeigen", "Kritische Assets anzeigen", "Nachweise anzeigen", "Freigaben prüfen"];

  return `
    <section class="asset-hero-grid" aria-label="Asset Management Überblick">
      <article class="asset-overview-card">
        <div>
          <span class="eyebrow">Überblick</span>
          <h3>Asset Management</h3>
          <p>Zentraler Überblick über Assets, deren Kritikalität, Nachweise und aktuellen Freigabestatus.</p>
        </div>
        <div class="asset-next-callout">
          <span class="asset-callout-icon" aria-hidden="true">${renderModuleInlineIcon("shield")}</span>
          <div>
            <span>Nächster sinnvoller Schritt</span>
            <strong>${escapeHtml(next.title || "Kritische Systeme erfassen")}</strong>
            <p>${escapeHtml(next.text || "Ergänze fehlende kritische Assets für eine vollständige Abdeckung.")}</p>
            <button class="primary-button" type="button" data-scroll-target="assetQuickForm">${escapeHtml(next.label || "Kritische Systeme erfassen")}</button>
          </div>
        </div>
      </article>
      ${metrics.map((metric, index) => renderAssetMetricCard(metric, actions[index] || "Details anzeigen")).join("")}
    </section>
  `;
}

function renderAssetMetricCard(metric, actionLabel) {
  const target = actionLabel.includes("Nachweise") ? "documents" : actionLabel.includes("Freigaben") ? "review" : "assetsReferenceRegister";
  const attribute = target === "assetsReferenceRegister"
    ? `data-scroll-target="${target}"`
    : `data-jump="${target}"`;
  return `
    <article class="asset-metric-card ${escapeHtml(metric.tone || "")}">
      <span class="asset-metric-icon ${escapeHtml(metric.icon || "database")}" aria-hidden="true">${renderModuleInlineIcon(metric.icon || "database")}</span>
      <div>
        <span>${escapeHtml(metric.label)}</span>
        <strong>${escapeHtml(String(metric.value))}</strong>
        <small>${escapeHtml(metric.hint)}</small>
      </div>
      <button class="asset-text-link" type="button" ${attribute}>${escapeHtml(actionLabel)} →</button>
    </article>
  `;
}

function renderAssetManagementWorkflow(rows = []) {
  const total = rows.length;
  const linked = rows.filter((row) => registerRowLinked("assets", row)).length;
  const approved = rows.filter((row) => canonicalReviewStatus(row, registerReviewType("assets")) === "freigegeben").length;
  const missingOwner = rows.filter((row) => !row.owner).length;
  const steps = registerCommandSteps("assets", registerCommandConfig("assets"), { total, linked, missingOwner, approved });

  return `
    <section class="asset-workflow-card" aria-label="Asset Management Workflow">
      <h3>Ihr Asset-Management-Workflow</h3>
      <div class="asset-workflow-steps">
        ${steps.map(([number, label, text, done, icon]) => `
          <article class="${done ? "done" : ""}">
            <b>${escapeHtml(number)}</b>
            <span class="asset-step-icon" aria-hidden="true">${renderModuleInlineIcon(icon || "database")}</span>
            <div>
              <strong>${escapeHtml(label)}</strong>
              <p>${escapeHtml(text)}</p>
            </div>
          </article>
        `).join("")}
      </div>
      <p class="asset-workflow-note"><strong>Wichtig:</strong> Die fachliche Bewertung und Freigabe verbleibt beim Berater/Admin.</p>
    </section>
  `;
}

function renderAssetManagementSideRail(rows = []) {
  const groups = registerCustomerHubGroups("assets", rows);
  const next = registerCustomerNextAction("assets", groups);
  const missingEvidence = rows.filter((row) => !registerRowLinked("assets", row)).length;
  const missingOwner = rows.filter((row) => !row.owner).length;
  const submitted = rows.filter((row) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(canonicalReviewStatus(row, registerReviewType("assets")))).length;
  const activity = rows.slice(-3).reverse();
  const openTasks = [
    ["Kritische Assets ohne Nachweis", missingEvidence],
    ["Nachweise überfällig", rows.filter((row) => registerRowOverdue("assets", row)).length],
    ["Freigaben ausstehend", submitted],
    ["Assets ohne Owner", missingOwner]
  ].filter(([, count]) => count > 0);

  return `
    <aside class="asset-side-rail" aria-label="Asset Management Kontext">
      <section class="asset-rail-card asset-rail-next">
        <span class="asset-rail-icon" aria-hidden="true">${renderModuleInlineIcon("score")}</span>
        <span class="eyebrow">Nächster sinnvoller Schritt</span>
        <h3>${escapeHtml(next.title || "Kritische Systeme erfassen")}</h3>
        <p>${escapeHtml(next.text || "Bitte ergänzen Sie kritische Systeme, für die noch keine Bewertung und Nachweise vorliegen.")}</p>
        <button class="primary-button" type="button" data-scroll-target="assetQuickForm">${escapeHtml(next.label || "Kritische Systeme erfassen")}</button>
        <button class="quiet-button" type="button" data-scroll-target="assetQuickForm">+ Asset erfassen</button>
      </section>

      <section class="asset-rail-card">
        <div class="asset-rail-head">
          <span class="eyebrow">Offene Aufgaben</span>
          <strong>${escapeHtml(String(openTasks.reduce((sum, [, count]) => sum + count, 0)))}</strong>
        </div>
        <div class="asset-rail-list">
          ${openTasks.length ? openTasks.map(([label, count], index) => `
            <button class="asset-rail-row" type="button" data-jump="tasks">
              <span class="asset-dot tone-${index + 1}">${escapeHtml(String(count))}</span>
              <strong>${escapeHtml(label)}</strong>
            </button>
          `).join("") : `
            <div class="asset-rail-empty">
              <strong>Keine offenen Asset-Aufgaben</strong>
              <small>Formale Lücken werden hier angezeigt, sobald sie entstehen.</small>
            </div>
          `}
        </div>
        <button class="asset-text-link" type="button" data-jump="tasks">Alle Aufgaben anzeigen →</button>
      </section>

      <section class="asset-rail-card">
        <span class="eyebrow">Schnellaktionen</span>
        <div class="asset-rail-actions">
          <button class="quiet-button" type="button" data-scroll-target="assetQuickForm">Asset erfassen</button>
          <button class="quiet-button" type="button" data-jump="documents">Massenupload</button>
          <button class="quiet-button" type="button" data-jump="documents">Nachweis verknüpfen</button>
          <button class="quiet-button" type="button" data-jump="review">Beraterprüfung starten</button>
        </div>
      </section>

      <section class="asset-rail-card">
        <span class="eyebrow">Letzte Aktivität</span>
        <div class="asset-activity-list">
          ${activity.length ? activity.map((row) => `
            <button type="button" data-register-detail="assets:${escapeHtml(row.id || "")}">
              <span>${renderModuleInlineIcon("document")}</span>
              <strong>${escapeHtml(registerEntryTitle("assets", row))}</strong>
              <small>${escapeHtml(registerNextStep("assets", row))}</small>
            </button>
          `).join("") : `
            <div class="asset-rail-empty">
              <strong>Noch keine Aktivität</strong>
              <small>Neue Assets und Nachweise erscheinen hier automatisch.</small>
            </div>
          `}
        </div>
        <button class="asset-text-link" type="button" data-jump="audittrail">Alle Aktivitäten anzeigen →</button>
      </section>
    </aside>
  `;
}

function renderAssetQuickForm() {
  return `
    <section class="panel register-form-panel register-clean-panel asset-form-card" id="assetQuickForm">
      <div class="panel-header register-clean-header">
        <div>
          <span class="eyebrow">Einfach erfassen</span>
          <h3>Asset Management</h3>
          <p>Asset anlegen, Owner setzen und direkt zuordnen: ISO 27001, NIS-2 oder beides.</p>
        </div>
        ${renderRegisterScopeLegend()}
      </div>
      <form class="form-grid register-simple-form asset-simple-form" data-form="asset">
        <div class="field wide"><label>Asset *</label>${fieldHelp(["Was eintragen: wichtiges System, Information, Anwendung, Prozess oder Dienstleister.", "Beispiel: CRM-System, Kundenportal, Produktions-IT, Personaldaten."])}<input name="name" type="text" placeholder="z. B. CRM-System, Kundenportal, Produktions-IT" required /></div>
        ${selectField("Typ", "type", ["Information", "Anwendung", "System", "Infrastruktur", "Dienstleister", "To-do"], ["Was eintragen: Art des Assets.", "Beispiel: Anwendung für CRM, Information für Kundendaten, Infrastruktur für Netzwerk."])}
        ${frameworkSelectField("ISO 27001", ["Was eintragen: ob der Eintrag für ISO 27001, NIS-2 oder beides relevant ist.", "Beispiel: ISO 27001 für ISMS-Asset, Beides für kritisches Cloud-System."])}
        ${field("Owner", "owner", "text", "Fachbereich", ["Was eintragen: Rolle oder Person, die fachlich verantwortlich ist.", "Beispiel: IT-Leitung, Vertrieb, HR, System Owner."])}
        ${selectField("Kritikalität", "criticality", ["Niedrig", "Mittel", "Hoch", "Sehr hoch"], ["Was eintragen: Bedeutung für Betrieb, Vertraulichkeit, Integrität und Verfügbarkeit.", "Beispiel: Hoch bei Kundendaten oder kritischen Geschäftsprozessen."])}
        ${selectField("Status", "status", ["Offen", "In Prüfung", "Freigegeben", "Archiviert"], ["Was eintragen: Arbeitsstand des Asset-Eintrags.", "Beispiel: Offen bei Ersterfassung, In Prüfung vor Beraterreview."])}
        <div class="field wide"><label>Notiz / Schutzbedarf</label>${fieldHelp(["Was eintragen: warum das Asset wichtig ist und welcher Schutzbedarf besteht.", "Beispiel: personenbezogene Daten, kritischer Prozess, Vertraulichkeit hoch."])}<input name="protection" placeholder="z. B. personenbezogene Daten, kritischer Prozess, C/I/A hoch" /></div>
        <div class="field wide"><label>Nachweis</label>${fieldHelp(["Was eintragen: vorhandene Datei, Link oder Dokumentverweis.", "Beispiel: Assetliste.xlsx, Architekturdiagramm, CMDB-Link."])}<input name="evidence" placeholder="Dateiname, Datei-ID oder kurzer Hinweis" /></div>
        <div class="field asset-submit-field"><label>&nbsp;</label><button class="primary-button" type="submit">+ Asset</button></div>
      </form>
      ${internalReferenceNote(`<p class="muted"><strong>Quelle:</strong> [ISO 27001 EN, Annex A, A.5.9], [Praxisbuch, Kapitel 5.1.9]</p>`)}
    </section>
  `;
}

function renderRisks() {
  const preparedRisks = state.risks.map(enrichRisk);

  return `
    <div class="risk-command-page">
      <div class="risk-command-main">
        ${renderRiskManagementHero(preparedRisks)}
        ${renderRiskManagementWorkflow(preparedRisks)}
        ${renderRiskRegisterPanel(preparedRisks)}
        ${renderRiskQuickForm()}
        <details class="risk-collapsed-section register-detail-disclosure">
          <summary>Weitere Risiko-Werkzeuge anzeigen</summary>
          <div class="risk-tools-stack">
            ${renderRiskFocusPanel(preparedRisks)}
            ${renderRiskMethodologyPanel(preparedRisks)}
            ${renderRiskCustomerHub(preparedRisks)}
            ${renderRiskDecisionCenter(preparedRisks)}
            ${renderRiskTreatmentPlanPanel(preparedRisks)}
            ${renderRiskAcceptancePanel(preparedRisks)}
            ${renderRiskReviewPlanPanel(preparedRisks)}
            ${renderRiskTraceabilityPanel(preparedRisks)}
            ${renderRiskEffectivenessPanel(preparedRisks)}
            ${renderRiskBoardPanel(preparedRisks)}
            ${renderRiskWorkshopPanel()}
            ${renderSocRiskSuggestions()}
          </div>
        </details>
      </div>
      ${renderRiskManagementSideRail(preparedRisks)}
      ${renderRegisterDetailDrawer("risks", preparedRisks)}
    </div>
  `;
}

function renderRiskManagementHero(risks = []) {
  const groups = registerCustomerHubGroups("risks", risks);
  const next = registerCustomerNextAction("risks", groups);
  const metrics = riskManagementMetrics(risks);

  return `
    <section class="risk-hero-grid" aria-label="Risiko Management Übersicht">
      <article class="risk-overview-card">
        <div>
          <span class="eyebrow">Überblick</span>
          <h3>Was kann schiefgehen und was machen wir dagegen?</h3>
          <p>Risiken werden verständlich erfasst, bewertet und mit Behandlung, Owner, Nachweis und Review verbunden. Fachliche Bewertung und Akzeptanz bleiben beim Berater/Admin.</p>
        </div>
        <div class="risk-next-callout ${next.warning ? "warning" : ""}">
          <span class="risk-callout-icon">${renderModuleInlineIcon("risk")}</span>
          <div>
            <span>Nächster sinnvoller Schritt</span>
            <strong>${escapeHtml(next.title || "Risiko bearbeiten")}</strong>
            <p>${escapeHtml(next.text || "Bitte fehlende Angaben ergänzen und anschließend zur Beraterprüfung geben.")}</p>
            ${renderRegisterCustomerAction(next, true)}
          </div>
        </div>
      </article>
      ${metrics.map(renderRiskMetricCard).join("")}
    </section>
  `;
}

function riskManagementMetrics(risks = []) {
  const total = risks.length;
  const high = risks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10).length;
  const critical = risks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 16).length;
  const treatmentOpen = risks.filter((risk) => !String(risk.treatment || "").trim() && !registerRowClosed("risks", risk)).length;
  const waiting = risks.filter((risk) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(canonicalReviewStatus(risk, "risk"))).length;
  const linked = risks.filter((risk) => registerRowLinked("risks", risk)).length;
  return [
    { icon: "risk", label: "Risiken gesamt", value: total, hint: total ? "im Register" : "noch nicht angelegt", tone: "" },
    { icon: "warning", label: "High / Critical", value: high, hint: critical ? `${critical} kritisch` : "Score ab hoch", tone: high ? "warning" : "done" },
    { icon: "treatment", label: "Maßnahmen offen", value: treatmentOpen, hint: treatmentOpen ? "Behandlung ergänzen" : "formal ruhig", tone: treatmentOpen ? "active" : "done" },
    { icon: "review", label: "Beraterprüfung", value: waiting, hint: waiting ? "in Prüfung" : `${linked}/${total || 0} mit Nachweis`, tone: waiting ? "active" : linked < total ? "warning" : "done" }
  ];
}

function renderRiskMetricCard(metric = {}) {
  return `
    <button class="risk-metric-card ${escapeHtml(metric.tone || "")}" type="button" data-jump-section="risks:risksReferenceRegister">
      <span class="risk-metric-icon">${renderModuleInlineIcon(metric.icon || "risk")}</span>
      <span>${escapeHtml(metric.label)}</span>
      <strong>${escapeHtml(metric.value)}</strong>
      <small>${escapeHtml(metric.hint || "")}</small>
      <em>Details ansehen →</em>
    </button>
  `;
}

function renderRiskManagementWorkflow(risks = []) {
  const total = risks.length;
  const hasOwner = risks.some((risk) => String(risk.owner || "").trim());
  const hasTreatment = risks.some((risk) => String(risk.treatment || "").trim());
  const hasEvidence = risks.some((risk) => registerRowLinked("risks", risk));
  const hasReview = risks.some((risk) => canonicalReviewStatus(risk, "risk") === "freigegeben");
  const steps = [
    ["1", "Risiko erfassen", "Asset, Szenario und Ursache beschreiben.", total > 0, "risk"],
    ["2", "Bewertung", "Eintritt und Auswirkung einschätzen.", total > 0 && hasOwner, "score"],
    ["3", "Behandlung & Nachweis", "Maßnahme definieren und Wirksamkeit belegen.", hasTreatment && hasEvidence, "treatment"],
    ["4", "Review / Freigabe", "Berater/Admin prüft fachlich.", hasReview, "review"]
  ];

  return `
    <section class="risk-workflow-card">
      <h3>Ihr Risiko-Management-Workflow</h3>
      <div class="risk-workflow-steps">
        ${steps.map(([number, label, text, done, icon]) => `
          <article class="${done ? "done" : ""}">
            <b>${escapeHtml(number)}</b>
            <span class="risk-step-icon">${renderModuleInlineIcon(icon)}</span>
            <div>
              <strong>${escapeHtml(label)}</strong>
              <p>${escapeHtml(text)}</p>
            </div>
          </article>
        `).join("")}
      </div>
      <p class="risk-workflow-note"><strong>Wichtig:</strong> Die Plattform zeigt formale Lücken. Sie entscheidet nicht automatisch, ob ein Risiko akzeptabel ist oder ob eine Maßnahme ausreicht.</p>
    </section>
  `;
}

function renderRiskManagementSideRail(risks = []) {
  const groups = registerCustomerHubGroups("risks", risks);
  const next = registerCustomerNextAction("risks", groups);
  const high = risks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10).length;
  const missingTreatment = risks.filter((risk) => !String(risk.treatment || "").trim() && !registerRowClosed("risks", risk)).length;
  const missingEvidence = risks.filter((risk) => !registerRowLinked("risks", risk)).length;
  const reviewOpen = risks.filter((risk) => !String(risk.review || "").trim() && !registerRowClosed("risks", risk)).length;
  const gaps = [
    { value: high, label: "Top-Risiken", text: "Score ab hoch priorisieren", tone: "risk" },
    { value: missingTreatment, label: "Maßnahme fehlt", text: "Behandlung konkret ergänzen", tone: "warning" },
    { value: missingEvidence, label: "Nachweis fehlt", text: "Datei, Link oder Dokumentverweis ergänzen", tone: "warning" },
    { value: reviewOpen, label: "Review offen", text: "Wiedervorlage setzen", tone: "active" }
  ].filter((gap) => gap.value > 0);
  const activity = risks.slice(0, 4);

  return `
    <aside class="risk-mockup-rail" aria-label="Risiko Management Kontext">
      <section class="risk-rail-card risk-rail-next">
        <span class="risk-rail-icon">${renderModuleInlineIcon("score")}</span>
        <span class="eyebrow">Nächster sinnvoller Schritt</span>
        <h3>${escapeHtml(next.title || "Risiko bearbeiten")}</h3>
        <p>${escapeHtml(next.text || "Bitte Risiko, Behandlung oder Nachweis ergänzen.")}</p>
        ${renderRegisterCustomerAction(next, true)}
        <button class="quiet-button" type="button" data-jump-section="risks:riskQuickForm">+ Risiko erfassen</button>
      </section>

      <section class="risk-rail-card">
        <div class="risk-rail-head">
          <span class="eyebrow">Formale Lücken</span>
          <strong>${gaps.reduce((sum, gap) => sum + gap.value, 0)}</strong>
        </div>
        <div class="risk-rail-list">
          ${gaps.length ? gaps.slice(0, 4).map((gap) => `
            <button class="risk-rail-row" type="button" data-jump-section="risks:risksReferenceRegister">
              <span class="risk-dot ${escapeHtml(gap.tone)}">${escapeHtml(gap.value)}</span>
              <div>
                <strong>${escapeHtml(gap.label)}</strong>
                <small>${escapeHtml(gap.text)}</small>
              </div>
            </button>
          `).join("") : `<div class="risk-rail-empty"><strong>Keine formalen Lücken</strong><small>Bitte fachliche Reviews weiter einplanen.</small></div>`}
        </div>
      </section>

      <section class="risk-rail-card">
        <span class="eyebrow">Schnellaktionen</span>
        <div class="risk-rail-actions">
          <button class="primary-button" type="button" data-jump-section="risks:riskQuickForm">+ Risiko erfassen</button>
          <button class="quiet-button" type="button" data-jump="documents">Nachweise öffnen</button>
          <button class="quiet-button" type="button" data-jump="review">Beraterprüfung</button>
          <button class="quiet-button" type="button" data-jump-section="risks:riskBoard">Risikoboard</button>
        </div>
      </section>

      <section class="risk-rail-card">
        <div class="risk-rail-head">
          <span class="eyebrow">Letzte Aktivität</span>
          <strong>${activity.length}</strong>
        </div>
        <div class="risk-activity-list">
          ${activity.length ? activity.map((risk) => `
            <button type="button" data-register-detail="risks:${escapeHtml(risk.id || "")}">
              <span>${renderModuleInlineIcon("risk")}</span>
              <div>
                <strong>${escapeHtml(risk.riskId || risk.asset || "Risiko")}</strong>
                <small>${escapeHtml(risk.scenario || "Risikoszenario ergänzen")}</small>
              </div>
            </button>
          `).join("") : `<div class="risk-rail-empty"><strong>Noch keine Risiken</strong><small>Erfasse das erste Risiko über die Schnellaktion.</small></div>`}
        </div>
      </section>
    </aside>
  `;
}

function renderRiskQuickForm() {
  return `
    <section class="panel register-form-panel register-clean-panel risk-form-card" id="riskQuickForm">
      <div class="panel-header register-clean-header">
        <div>
          <span class="eyebrow">Einfach erfassen</span>
          <h3>Risiko Management</h3>
          <p>Risiko kurz beschreiben, bewerten, Behandlung festlegen und eindeutig ISO/NIS-2 zuordnen.</p>
        </div>
        ${renderRegisterScopeLegend()}
      </div>

      <form class="form-grid register-simple-form risk-form risk-simple-form" data-form="risk">
        ${field("Risiko-ID", "riskId", "text", nextRiskId(), ["Was eintragen: eindeutige Nummer oder Kennung für das Risiko.", "Beispiel: R-001, R-Cloud-01."])}
        ${field("Asset / Prozess", "asset", "text", "z. B. CRM-System", ["Was eintragen: betroffenes Asset, System, Prozess oder Dienstleister.", "Beispiel: CRM-System, M365, Zahlungsprozess, Cloud-Provider."])}
        ${frameworkSelectField("ISO 27001 + NIS-2", ["Was eintragen: ob das Risiko für ISO 27001, NIS-2 oder beides relevant ist.", "Beispiel: Beides bei kritischem Lieferketten- oder Incident-Risiko."])}
        ${field("Risk Owner", "owner", "text", "Verantwortliche Rolle", ["Was eintragen: wer das Risiko fachlich steuert.", "Beispiel: IT-Leitung, Prozessowner, CISO, Einkauf."])}

        <div class="field full"><label>Risiko / Szenario *</label>${fieldHelp(["Was eintragen: was passieren kann, welches Asset betroffen ist und welche Auswirkung entsteht.", "Beispiel: Phishing führt zu unbefugtem Zugriff auf M365 und möglichem Datenabfluss."])}<textarea name="scenario" placeholder="Was kann passieren, welches Asset ist betroffen und was wäre die Auswirkung?" required></textarea></div>

        ${selectField("Likelihood", "likelihood", ["1", "2", "3", "4", "5"], ["Was eintragen: geschätzte Eintrittswahrscheinlichkeit von 1 bis 5.", "Beispiel: 1 sehr selten, 3 möglich, 5 sehr wahrscheinlich."])}
        ${selectField("Impact", "impact", ["1", "2", "3", "4", "5"], ["Was eintragen: geschätzte Auswirkung von 1 bis 5.", "Beispiel: 1 gering, 3 deutlich, 5 kritisch."])}
        ${selectField("Restrisiko Likelihood", "residualLikelihood", ["", "1", "2", "3", "4", "5"], ["Was eintragen: erwartete Eintrittswahrscheinlichkeit nach Umsetzung der Maßnahme.", "Beispiel: Vorher 4, nach MFA vielleicht 2."])}
        ${selectField("Restrisiko Impact", "residualImpact", ["", "1", "2", "3", "4", "5"], ["Was eintragen: erwartete Auswirkung nach Umsetzung der Maßnahme.", "Beispiel: Datenabfluss bleibt kritisch, aber Ausbreitung wird begrenzt."])}
        ${selectField("Status", "status", ["Offen", "In Bewertung", "In Behandlung", "Restrisiko prüfen", "Akzeptiert", "Erledigt"], ["Was eintragen: aktueller Bearbeitungsstand.", "Beispiel: In Behandlung, wenn Maßnahmen laufen."])}
        ${selectField("Behandlung", "treatmentOption", ["Reduzieren", "Vermeiden", "Übertragen", "Akzeptieren"], ["Was eintragen: grundsätzliche Risikostrategie.", "Beispiel: Reduzieren durch MFA, Übertragen durch Versicherung, Akzeptieren nach Entscheidung."])}

        <div class="field wide"><label>Maßnahme / Behandlung</label>${fieldHelp(["Was eintragen: konkrete Maßnahme, Verantwortliche und Nachweisidee.", "Beispiel: MFA aktivieren, Backup-Test dokumentieren, Rechte quartalsweise prüfen."])}<input name="treatment" placeholder="Was wird getan? Wer macht was?" /></div>
        <div class="field wide"><label>Control / Anforderung</label>${fieldHelp(["Was eintragen: Bezug zu Control, Policy, Aufgabe oder NIS-2-Arbeitspunkt.", "Beispiel: A.5.15, Backup Policy, Incident Response, §30."])}<input name="controls" placeholder="z. B. Annex A Control, NIS-2-Arbeitspunkt oder Policy" /></div>
        ${field("Akzeptanz-Owner", "acceptanceOwner", "text", "z. B. Geschäftsleitung / Risk Owner", ["Was eintragen: wer ein Restrisiko fachlich akzeptieren oder entscheiden muss.", "Beispiel: Geschäftsleitung, Risk Owner, Fachbereichsleitung."])}
        ${field("Nachweis / Link", "evidence", "text", "z. B. Ticket, Protokoll, Datei, Link", ["Was eintragen: Nachweis zur Maßnahme oder Entscheidung.", "Beispiel: MFA-Rollout-Ticket, Backup-Testprotokoll, Managemententscheidung."])}
        ${field("Review-Datum", "review", "date", "", ["Was eintragen: wann Risiko, Maßnahme oder Restrisiko erneut geprüft werden soll.", "Beispiel: nach Maßnahmenabschluss oder monatlich bei hohem Risiko."])}
        <div class="field risk-submit-field"><label>&nbsp;</label><button class="primary-button" type="submit">+ Risiko speichern</button></div>
      </form>
      ${internalReferenceNote(`<p class="muted"><strong>Quellen:</strong> [ISO 27001 EN, Clause 6.1.2, Clause 6.1.3, Clause 8.2, Clause 8.3], [NIS-2-Dokument, §30], [Praxisbuch, Kapitel 4.6.1 und 4.8], [Manual, Section 10.1]</p>`)}
    </section>
  `;
}

function renderAssetCustomerHub(assets = []) {
  const groups = registerCustomerHubGroups("assets", assets);
  const action = registerCustomerNextAction("assets", groups);
  return renderRegisterCustomerHub({
    collection: "assets",
    eyebrow: "Assets einfach steuern",
    title: "Welche Werte sind wichtig und was fehlt noch?",
    text: "Kunden erfassen hier wichtige Systeme, Informationen, Prozesse oder Dienstleister. Die Plattform zeigt formale Lücken; Schutzbedarf und fachliche Bewertung bleiben in der Beraterprüfung.",
    groups,
    action,
    statuses: [
      ["Unvollständig", groups.todo.length, "Owner, Kritikalität oder Nachweis fehlt", groups.todo.length ? "warning" : "ready"],
      ["Wartet", groups.waiting.length, "Liegt beim Berater", groups.waiting.length ? "waiting" : "ready"],
      ["Freigegeben", groups.approved.length, "Berater/Admin", "approved"],
      ["Gesamt", assets.length, "angelegte Assets", ""]
    ],
    steps: [
      "Asset oder Information benennen",
      "Owner und Kritikalität ergänzen",
      "Nachweis verknüpfen oder zur Prüfung einreichen"
    ],
    lanes: [
      ["Heute zuerst", "Unvollständige Assets", groups.todo.slice(0, 5), "Aktuell keine Asset-Lücken offen.", "warning"],
      ["Wartet auf Berater", "Du musst hier gerade nichts tun", groups.waiting.slice(0, 5), "Noch keine Assets eingereicht.", "waiting"],
      ["Freigegeben", "Durch Berater/Admin geprüft", groups.approved.slice(0, 5), "Noch keine Assets freigegeben.", "approved"]
    ],
    hint: "Ein Asset mit Datei oder Link ist formal besser vorbereitet. Daraus folgt aber keine automatische Aussage, dass Schutzbedarf, Risiko oder Nachweis fachlich ausreichen."
  });
}

function renderRiskCustomerHub(risks = []) {
  const groups = registerCustomerHubGroups("risks", risks);
  const highRisks = risks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10);
  const action = registerCustomerNextAction("risks", groups);
  return renderRegisterCustomerHub({
    collection: "risks",
    eyebrow: "Risiken einfach bearbeiten",
    title: "Was kann schiefgehen und was macht ihr dagegen?",
    text: "Kunden beschreiben Risiken in Alltagssprache. Die Plattform strukturiert Owner, Maßnahme, Nachweis und Review-Status; Bewertung und Akzeptanz bleiben beim Berater/Admin.",
    groups,
    action,
    statuses: [
      ["Unvollständig", groups.todo.length, "Owner, Maßnahme oder Nachweis fehlt", groups.todo.length ? "warning" : "ready"],
      ["Top-Risiken", highRisks.length, "Score ab hoch", highRisks.length ? "warning" : "ready"],
      ["Wartet", groups.waiting.length, "Liegt beim Berater", groups.waiting.length ? "waiting" : "ready"],
      ["Freigegeben", groups.approved.length, "Berater/Admin", "approved"]
    ],
    steps: [
      "Was ist wichtig?",
      "Was kann schiefgehen?",
      "Was macht ihr dagegen und wer ist verantwortlich?"
    ],
    lanes: [
      ["Heute zuerst", "Hohe oder unvollständige Risiken", groups.todo.slice(0, 5), "Aktuell keine Risikolücken offen.", "warning"],
      ["Wartet auf Berater", "Du musst hier gerade nichts tun", groups.waiting.slice(0, 5), "Noch keine Risiken eingereicht.", "waiting"],
      ["Freigegeben", "Durch Berater/Admin geprüft", groups.approved.slice(0, 5), "Noch keine Risiken freigegeben.", "approved"]
    ],
    hint: "Die Plattform kann formale Lücken sichtbar machen. Sie entscheidet nicht automatisch, ob ein Risiko akzeptabel ist oder ob eine Maßnahme ausreicht."
  });
}

function renderRegisterCommandPanel(collection) {
  const rows = registerRows(collection);
  const groups = registerCustomerHubGroups(collection, rows);
  const next = registerCustomerNextAction(collection, groups);
  const config = registerCommandConfig(collection);
  const total = rows.length;
  const linked = rows.filter((row) => registerRowLinked(collection, row)).length;
  const missingOwner = rows.filter((row) => !row.owner).length;
  const submitted = rows.filter((row) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(canonicalReviewStatus(row, registerReviewType(collection)))).length;
  const approved = rows.filter((row) => canonicalReviewStatus(row, registerReviewType(collection)) === "freigegeben").length;
  const metrics = registerCommandMetrics(collection, rows, groups, { total, linked, submitted, approved });
  const steps = registerCommandSteps(collection, config, { total, linked, missingOwner, approved });

  return `
    <section class="panel register-command-panel register-command-${escapeHtml(collection)}">
      <div class="register-command-head">
        <div class="register-command-title">
          <div class="register-command-mark">${escapeHtml(config.mark)}</div>
          <div>
            <span class="eyebrow">${escapeHtml(config.eyebrow)}</span>
            <h3>${escapeHtml(config.title)}</h3>
            <p>${escapeHtml(config.text)}</p>
          </div>
        </div>
        <div class="register-command-next ${next.warning ? "warning" : ""}">
          <span>Nächster sinnvoller Schritt</span>
          <strong>${escapeHtml(next.title || "Weiter bearbeiten")}</strong>
          <p>${escapeHtml(next.text || "Ergänze die fehlenden Angaben und reiche sie bei Bedarf zur Beraterprüfung ein.")}</p>
          <div class="register-command-next-actions">
            ${renderRegisterCustomerAction(next, true)}
            <button class="quiet-button" type="button" data-jump-section="${escapeHtml(config.quickTarget)}">${escapeHtml(config.quickLabel)}</button>
          </div>
        </div>
      </div>

      <div class="register-command-grid">
        ${metrics.map((metric) => `
          <article class="register-command-metric ${escapeHtml(metric.tone || "")}">
            <span class="register-command-metric-icon ${escapeHtml(metric.icon || "")}" aria-hidden="true">${renderModuleInlineIcon(metric.icon || collection)}</span>
            <strong>${escapeHtml(metric.value)}</strong>
            <span>${escapeHtml(metric.label)}</span>
            <small>${escapeHtml(metric.hint)}</small>
          </article>
        `).join("")}
      </div>

      <div class="register-command-flow">
        ${steps.map(([number, label, text, done, icon]) => `
          <div class="${done ? "done" : ""}">
            <b>${renderModuleInlineIcon(icon || "review")}${escapeHtml(number)}</b>
            <span><strong>${escapeHtml(label)}</strong>${escapeHtml(text)}</span>
          </div>
        `).join("")}
      </div>

      <div class="register-command-footer">
        <div class="register-command-scope">
          ${renderRegisterScopeLegend()}
        </div>
        <div class="register-command-actions">
          <button class="quiet-button" type="button" data-jump="documents">Nachweise</button>
          <button class="quiet-button" type="button" data-jump="review">Beraterprüfung</button>
          <button class="quiet-button" type="button" data-register-gap-tasks="${escapeHtml(collection)}" ${total ? "" : "disabled"}>Lücken als Aufgaben</button>
        </div>
      </div>

      <p class="register-command-note"><strong>Wichtig:</strong> Diese Ansicht zeigt formale Vorbereitung und Review-Status. Freigabe, Ablehnung, Audit-Relevanz und fachliche Bewertung bleiben beim Berater/Admin.</p>
    </section>
  `;
}

function renderModuleInlineIcon(name = "") {
  const icons = {
    assets: ["M4 7h16", "M4 12h16", "M4 17h16"],
    asset: ["M4 7h16", "M4 12h16", "M4 17h16"],
    database: ["M6 8c0-2 12-2 12 0s-12 2-12 0", "M6 8v8c0 2 12 2 12 0V8", "M6 12c0 2 12 2 12 0"],
    shield: ["M12 3l7 3v5c0 5-3.2 8.4-7 10-3.8-1.6-7-5-7-10V6l7-3z"],
    document: ["M7 3h7l4 4v14H7V3z", "M14 3v5h5", "M9 13h6", "M9 17h5"],
    people: ["M8.5 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6z", "M15.5 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6z", "M3 20c.7-3 3-5 5.5-5s4.8 2 5.5 5", "M10 20c.7-2.6 2.8-4.3 5.5-4.3S20.3 17.4 21 20"],
    warning: ["M12 3l9 16H3L12 3z", "M12 8v5", "M12 17h.01"],
    review: ["M9 11l2 2 4-5", "M4 12a8 8 0 1 0 8-8"],
    risk: ["M12 3l7 4v5c0 4.6-2.8 7.6-7 9-4.2-1.4-7-4.4-7-9V7l7-4z", "M12 8v5", "M12 16h.01"],
    contract: ["M7 3h10v18H7z", "M10 8h4", "M10 12h4", "M10 16h3"],
    calendar: ["M6 5h12v15H6z", "M6 9h12", "M9 3v4", "M15 3v4"],
    score: ["M12 19a7 7 0 1 0-7-7", "M12 12l4-4"],
    treatment: ["M5 7h14", "M5 12h14", "M5 17h14", "M8 7v10", "M16 7v10"],
    legal: ["M4 19h16", "M7 19V9l5-4 5 4v10", "M9 12h6", "M10 15h4"],
    incidents: ["M12 3l9 16H3L12 3z", "M12 8v5", "M12 17h.01"],
    contracts: ["M7 3h10v18H7z", "M10 8h4", "M10 12h4", "M10 16h3"]
  };
  const paths = icons[name] || icons.assets;
  return `<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true">${paths.map((path) => `<path d="${path}"></path>`).join("")}</svg>`;
}

function registerCommandMetrics(collection, rows, groups, base) {
  const total = base.total || 0;
  const linked = base.linked || 0;
  const submitted = base.submitted || 0;
  const approved = base.approved || 0;
  if (collection === "assets") {
    const critical = rows.filter((row) => ["Hoch", "Sehr hoch", "Kritisch", "Critical"].includes(row.criticality)).length;
    return [
      { label: "Assets gesamt", value: total, hint: "angelegt", icon: "database" },
      { label: "Kritische Assets", value: critical, hint: critical ? "priorisiert prüfen" : "keine markiert", tone: critical ? "warning" : "done", icon: "shield" },
      { label: "Nachweise", value: linked, hint: total ? `${Math.round((linked / total) * 100)} % vollständig` : "noch keine Assets", tone: linked < total ? "warning" : "done", icon: "document" },
      { label: "Offene Freigaben", value: submitted || approved, hint: submitted ? `${submitted} in Prüfung` : `${approved} freigegeben`, tone: submitted ? "active" : approved ? "done" : "", icon: "people" }
    ];
  }
  if (collection === "risks") {
    const high = rows.filter((row) => riskScore(row.likelihood, row.impact) >= 10).length;
    const openTreatment = rows.filter((row) => !String(row.treatment || "").trim() && !registerRowClosed("risks", row)).length;
    return [
      { label: "Risiken gesamt", value: total, hint: "im Register", icon: "risk" },
      { label: "High / Critical", value: high, hint: high ? "Managementbedarf" : "keine Top-Risiken", tone: high ? "warning" : "done", icon: "warning" },
      { label: "Maßnahmen offen", value: openTreatment, hint: openTreatment ? "Behandlung ergänzen" : "formal ruhig", tone: openTreatment ? "warning" : "done", icon: "treatment" },
      { label: "Beraterprüfung", value: submitted || approved, hint: submitted ? `${submitted} in Prüfung` : `${approved} freigegeben`, tone: submitted ? "active" : approved ? "done" : "", icon: "review" }
    ];
  }
  if (collection === "suppliers") {
    const metrics = supplierMetrics();
    return [
      { label: "Lieferanten gesamt", value: metrics.total, hint: "im Register", icon: "people" },
      { label: "Kritische Lieferanten", value: metrics.critical, hint: metrics.critical ? "priorisiert prüfen" : "keine markiert", tone: metrics.critical ? "warning" : "done", icon: "shield" },
      { label: "Verträge & Nachweise", value: Math.max(0, metrics.total - metrics.missingEvidence), hint: metrics.missingEvidence ? `${metrics.missingEvidence} offen` : "vollständig verknüpft", tone: metrics.missingEvidence ? "warning" : "done", icon: "contract" },
      { label: "Offene Reviews", value: metrics.reviewOpen, hint: metrics.reviewOpen ? "prüfen" : "keine offenen Reviews", tone: metrics.reviewOpen ? "warning" : "done", icon: "review" }
    ];
  }
  return [
    { label: "Einträge", value: total, hint: "angelegt", icon: collection },
    { label: "Offene Punkte", value: groups.todo.length, hint: groups.todo.length ? "formal zu ergänzen" : "formal ruhig", tone: groups.todo.length ? "warning" : "done", icon: "warning" },
    { label: "Nachweise", value: `${linked}/${total || 0}`, hint: "Datei, Link oder Anker", tone: linked < total ? "warning" : "done", icon: "document" },
    { label: "Beraterfreigabe", value: approved, hint: `${submitted} in Prüfung`, tone: submitted ? "active" : approved ? "done" : "", icon: "review" }
  ];
}

function registerCommandSteps(collection, config, stateFlags) {
  const total = stateFlags.total || 0;
  const linked = stateFlags.linked || 0;
  const missingOwner = stateFlags.missingOwner || 0;
  const approved = stateFlags.approved || 0;
  const steps = {
    assets: [
      ["01", "Erfassen", "Assets, Typ, Zugehörigkeit und Schutzbedarf erfassen.", total > 0, "database"],
      ["02", "Verantwortung", "Owner, Zuständigkeiten und Rollen zuordnen.", total > 0 && missingOwner === 0, "people"],
      ["03", "Schutzbedarf & Nachweis", "Schutzbedarf definieren und Nachweise verknüpfen.", total > 0 && linked === total, "shield"],
      ["04", "Beraterprüfung", "Fachliche Entscheidung dokumentieren und freigeben.", approved > 0, "review"]
    ],
    risks: [
      ["01", "Risiko erfassen", "Risiken und Szenarien identifizieren und erfassen.", total > 0, "risk"],
      ["02", "Bewertung", "Eintrittswahrscheinlichkeit und Auswirkung bewerten.", total > 0, "score"],
      ["03", "Behandlung & Nachweis", "Maßnahmen definieren und Wirksamkeit nachweisen.", total > 0 && linked === total, "treatment"],
      ["04", "Review / Freigabe", "Fachliche Prüfung und Freigabe durch Berater/Admin.", approved > 0, "review"]
    ],
    suppliers: [
      ["01", "Lieferant erfassen", "Basisdaten, Leistung und Zugriff erfassen.", total > 0, "people"],
      ["02", "Kritikalität & Zugriff", "Owner, Kritikalität und Datenzugriff klären.", total > 0 && missingOwner === 0, "shield"],
      ["03", "Vertrag / Nachweis", "Vertrag und Nachweise verknüpfen und prüfen.", total > 0 && linked === total, "contract"],
      ["04", "Review / Freigabe", "Fachliche Bewertung dokumentieren und freigeben.", approved > 0, "review"]
    ]
  }[collection] || [
    ["01", "Erfassen", config.stepOne, total > 0, "document"],
    ["02", "Verantwortung", "Owner und Zuständigkeit klären.", total > 0 && missingOwner === 0, "people"],
    ["03", "Nachweis", "Datei, Link oder Dokumentverweis ergänzen.", total > 0 && linked === total, "document"],
    ["04", "Beraterprüfung", "Fachliche Entscheidung dokumentieren.", approved > 0, "review"]
  ];
  return steps;
}

