function policyWorkspaceCommandConfig() {
  const summary = policyControlCenterSummary();
  const packageStatus = policyPackageStatus();
  const missingPackageItems = Math.max(0, packageStatus.total - packageStatus.policyCount);
  const missingArtifacts = Math.max(0, summary.total - summary.withArtifact);
  const needsReview = summary.draft + summary.inReview;
  const next = missingPackageItems
    ? {
        title: "Policy-/Prozesspaket vervollständigen",
        text: `${missingPackageItems} Paketpunkt(e) fehlen noch im Register. Lege zuerst die zentralen Policies und Verfahren an.`,
        warning: true,
        action: { kind: "policyPackage", label: "Paket anlegen" }
      }
    : missingArtifacts
      ? {
          title: "Policy-Dokumente verknüpfen",
          text: `${missingArtifacts} Policy-Eintrag(e) brauchen noch Entwurf, Dokumentverweis oder Vorlage.`,
          warning: true,
          action: { kind: "section", label: "Policy öffnen", target: "policies:policyManualForm" }
        }
      : needsReview
        ? {
            title: "Policies prüfen lassen",
            text: "Einige Policies sind noch Entwurf oder warten auf Beraterprüfung.",
            warning: summary.draft > 0,
            action: { kind: "view", label: "Review Center", target: canAccessView("review") ? "review" : "policies" }
          }
        : {
            title: "Policy-Stand beobachten",
            text: "Policy-Paket und Dokumentverweis sind formal gut vorbereitet. Reviews weiterhin einplanen.",
            warning: false,
            action: { kind: "view", label: "Policy Register", target: "policies" }
          };

  return {
    mark: "PM",
    eyebrow: "Policy-Zentrale",
    title: "Policies öffnen, ausfüllen und freigeben lassen",
    text: "Kunden sollen nicht suchen müssen: Policy auswählen, Vorlage oder Arbeitsvorlage öffnen, Owner und Review pflegen und anschließend zur Beraterprüfung geben.",
    next,
    quickAction: { kind: "section", label: "+ Policy erfassen", target: "policies:policyManualForm" },
    metrics: [
      { value: `${packageStatus.percent}%`, label: "Paketstand", hint: "Policy, Arbeitsvorlage und Dokumentverweis", tone: packageStatus.percent < 100 ? "warning" : "done" },
      { value: `${packageStatus.policyCount}/${packageStatus.total}`, label: "Register", hint: "Policy-Paketpunkte" },
      { value: `${summary.withArtifact}/${summary.total || 0}`, label: "Dokumente", hint: "Arbeitsvorlage, Vorlage oder Nachweis", tone: missingArtifacts ? "warning" : "done" },
      { value: summary.published, label: "Freigegeben", hint: "durch Berater/Admin", tone: summary.published ? "done" : "" }
    ],
    steps: [
      { number: "01", title: "Auswählen", text: "Policy oder Verfahren aus dem Paket öffnen.", done: packageStatus.policyCount > 0 },
      { number: "02", title: "Ausfüllen", text: "Owner, Version, Review und Inhalt ergänzen.", done: summary.withArtifact > 0 },
      { number: "03", title: "Prüfen lassen", text: "Arbeitsvorlage zur Beraterprüfung geben.", done: summary.inReview > 0 || summary.published > 0 },
      { number: "04", title: "Freigabe", text: "Berater/Admin gibt fachlich frei.", done: summary.published > 0 }
    ],
    actions: [
      { kind: "view", label: "Arbeitsvorlagen", target: "templates" },
      { kind: "view", label: "Dokumente", target: "documents" },
      { kind: "view", label: "Review Center", target: canAccessView("review") ? "review" : "policies" }
    ],
    note: "Eine erstellte Policy ist nur ein vorbereiteter Arbeitsstand. Fachliche Freigabe, Ablehnung oder Audit-Relevanz setzt Berater/Admin."
  };
}

function auditPackageWorkspaceCommandConfig() {
  const data = auditPackageReportData();
  const nextSteps = auditPackageNextSteps(data);
  const next = nextSteps[0] || {
    title: "Auditpaket weiter vorbereiten",
    text: "Offene Gate-Punkte prüfen und danach den Paketstand durch Berater/Admin freigeben lassen.",
    label: "Review Center",
    view: canAccessView("review") ? "review" : "documents"
  };
  const primaryAction = data.gate.blockers.length
    ? { kind: "auditTasks", label: "Blocker als Aufgaben" }
    : data.packageApproval
      ? { kind: "auditBundle", label: "Evidence Bundle" }
      : { kind: "view", label: next.label || "Beraterprüfung", target: next.view || (canAccessView("review") ? "review" : "documents") };
  return {
    mark: "AP",
    eyebrow: "Auditpaket-Zentrale",
    title: data.packageApproval ? "Auditpaket beraterfreigegeben" : "Auditpaket vorbereitet, Freigabe offen",
    text: "Die Plattform bündelt Nachweise, Risiken, Policies, SoA und Aufgaben. Export und Status bleiben klar getrennt von der fachlichen Beraterfreigabe.",
    next: {
      title: next.title,
      text: next.text,
      warning: Boolean(data.gate.blockers.length),
      action: primaryAction
    },
    quickAction: { kind: "auditReport", label: "Bericht exportieren" },
    metrics: [
      { value: `${data.formalPercent}%`, label: "Formaler Stand", hint: "automatisch vorbereitet", tone: data.formalPercent < 100 ? "warning" : "done" },
      { value: data.gate.blockers.length, label: "Blocker", hint: "Gate-Punkte offen", tone: data.gate.blockers.length ? "warning" : "done" },
      { value: `${data.bundle.ready}/${data.bundle.total}`, label: "Paketpunkte", hint: "formal befüllt", tone: data.bundle.missing ? "warning" : "done" },
      { value: data.packageApproval ? "Ja" : "Nein", label: "Beraterfreigabe", hint: data.packageApproval ? "Paketstand freigegeben" : "bewusst offen", tone: data.packageApproval ? "done" : "active" }
    ],
    steps: [
      { number: "01", title: "Sammeln", text: "Nachweise und Registerdaten bündeln.", done: data.bundle.total > 0 },
      { number: "02", title: "Formal prüfen", text: "Gate zeigt nur Lücken und Review-Punkte.", done: data.gate.blockers.length === 0 },
      { number: "03", title: "Freigeben", text: "Berater/Admin gibt Paketstand frei.", done: Boolean(data.packageApproval) },
      { number: "04", title: "Export", text: "Freigegebenen Arbeitsstand exportieren.", done: Boolean(data.packageApproval) }
    ],
    scopeHtml: `<div class="register-scope-legend"><span class="scope-badge review">Keine automatische Auditbereitschaft</span><span class="scope-badge shared">Beraterfreigabe erforderlich</span></div>`,
    actions: [
      { kind: "view", label: "Review Center", target: canAccessView("review") ? "review" : "auditpackage" },
      { kind: "view", label: "Nachweise", target: "documents" },
      { kind: "auditBundle", label: data.packageApproval ? "Evidence Bundle" : "Export gesperrt", disabled: !data.packageApproval }
    ],
    note: "Das Auditpaket darf vorbereitet wirken, aber nicht automatisch auditbereit. Berater/Admin muss den konkreten Paketstand ausdrücklich freigeben."
  };
}

function renderWorkspaceCommandAction(action = {}, primary = false) {
  if (!action) return "";
  const buttonClass = primary ? "primary-button" : "quiet-button";
  const disabled = action.disabled ? "disabled" : "";
  if (action.kind === "document") {
    return `<button class="${buttonClass}" type="button" data-open-document="${escapeHtml(action.target || "")}" ${disabled}>${escapeHtml(action.label || "Dokument öffnen")}</button>`;
  }
  if (action.kind === "upload") {
    return `<button class="${buttonClass}" type="button" data-document-upload-ref="${escapeHtml(action.ref || "")}" data-document-upload-area="${escapeHtml(action.area || "Dokumentation")}" ${disabled}>${escapeHtml(action.label || "Nachweis anlegen")}</button>`;
  }
  if (action.kind === "section") {
    return `<button class="${buttonClass}" type="button" data-jump-section="${escapeHtml(action.target || "")}" ${disabled}>${escapeHtml(action.label || "Öffnen")}</button>`;
  }
  if (action.kind === "policyPackage") {
    return `<button class="${buttonClass}" type="button" data-policy-package ${disabled}>${escapeHtml(action.label || "Policy-Paket anlegen")}</button>`;
  }
  if (action.kind === "auditReport") {
    return `<button class="${buttonClass}" type="button" data-audit-package-report ${disabled}>${escapeHtml(action.label || "Auditpaket-Bericht")}</button>`;
  }
  if (action.kind === "auditBundle") {
    return `<button class="${buttonClass}" type="button" data-audit-evidence-bundle ${disabled}>${escapeHtml(action.label || "Evidence Bundle")}</button>`;
  }
  if (action.kind === "auditTasks") {
    return `<button class="${buttonClass}" type="button" data-audit-package-tasks ${disabled}>${escapeHtml(action.label || "Blocker als Aufgaben")}</button>`;
  }
  return `<button class="${buttonClass}" type="button" data-jump="${escapeHtml(action.target || "dashboard")}" ${disabled}>${escapeHtml(action.label || "Öffnen")}</button>`;
}

function renderRiskFocusPanel(risks = state.risks.map(enrichRisk)) {
  const focus = riskFocusData(risks);
  return `
    <section class="panel risk-focus-panel" id="riskFocus">
      <div class="risk-focus-head">
        <div>
          <span class="eyebrow">Risiko-Fokus</span>
          <h3>Was ist jetzt der nächste sinnvolle Schritt?</h3>
          <p>Diese Startzone bündelt die wichtigsten Lücken aus Methodik, Behandlung, Nachweisen, Review und Wirksamkeitscheck. Die Plattform priorisiert formal, die fachliche Entscheidung bleibt beim Berater/Admin.</p>
        </div>
        <div class="risk-focus-primary">
          <span>${escapeHtml(focus.next.eyebrow)}</span>
          <strong>${escapeHtml(focus.next.title)}</strong>
          <p>${escapeHtml(focus.next.text)}</p>
          <button class="primary-button" type="button" data-jump-section="${escapeHtml(focus.next.target)}">${escapeHtml(focus.next.action)}</button>
        </div>
      </div>

      <div class="risk-focus-grid">
        ${focus.cards.map(renderRiskFocusCard).join("")}
      </div>

      <div class="risk-focus-shortcuts" aria-label="Risiko-Schnellnavigation">
        ${[
          ["riskMethodology", "Methodik"],
          ["riskTreatmentPlan", "Behandlung"],
          ["riskTraceability", "Nachweise"],
          ["riskReviewPlan", "Reviews"],
          ["riskEffectiveness", "Wirksamkeit"],
          ["riskBoard", "Risikoboard"]
        ].map(([target, label]) => `<button class="quiet-button" type="button" data-jump-section="risks:${target}">${escapeHtml(label)}</button>`).join("")}
      </div>
    </section>
  `;
}

function riskFocusData(risks = state.risks.map(enrichRisk)) {
  const treatment = riskTreatmentPlanData(risks);
  const acceptance = riskAcceptanceData(risks);
  const review = riskReviewPlanData(risks);
  const traceability = riskTraceabilityData(risks);
  const effectiveness = riskEffectivenessData(risks);
  const highRisks = risks.filter((risk) => !riskClosed(risk) && riskScore(risk.likelihood, risk.impact) >= 10);
  const waitingReview = risks.filter((risk) => ["vom_kunden_eingereicht", "in_beraterpruefung"].includes(canonicalReviewStatus(risk, "risk")));
  const next = riskFocusNextAction({ risks, treatment, acceptance, review, traceability, effectiveness });
  return {
    next,
    cards: [
      {
        label: "Top-Risiken",
        value: highRisks.length,
        hint: "Score ab hoch",
        tone: highRisks.length ? "warning" : "done",
        target: "risks:riskBoard"
      },
      {
        label: "Maßnahmen offen",
        value: treatment.missingTreatment.length + treatment.missingResidual.length,
        hint: "Behandlung oder Restrisiko fehlt",
        tone: treatment.missingTreatment.length + treatment.missingResidual.length ? "warning" : "done",
        target: "risks:riskTreatmentPlan"
      },
      {
        label: "Nachweise offen",
        value: traceability.missingEvidence.length,
        hint: "Datei, Link oder Dokumentverweis fehlt",
        tone: traceability.missingEvidence.length ? "warning" : "done",
        target: "risks:riskTraceability"
      },
      {
        label: "Reviewbedarf",
        value: review.overdue.length + review.missingReview.length + review.next30.length,
        hint: "überfällig, offen oder bald fällig",
        tone: review.overdue.length ? "danger" : review.missingReview.length + review.next30.length ? "active" : "done",
        target: "risks:riskReviewPlan"
      },
      {
        label: "Wirksamkeit prüfen",
        value: effectiveness.taskCandidates.length,
        hint: "formal noch nicht prüfbereit",
        tone: effectiveness.taskCandidates.length ? "warning" : "done",
        target: "risks:riskEffectiveness"
      },
      {
        label: "Beraterprüfung",
        value: waitingReview.length + acceptance.decisionRisks.length,
        hint: "wartet oder Entscheidung offen",
        tone: waitingReview.length + acceptance.decisionRisks.length ? "active" : "done",
        target: "risks:riskAcceptance"
      }
    ]
  };
}

function riskFocusNextAction({ risks, treatment, acceptance, review, traceability, effectiveness } = {}) {
  if (!risks?.length) {
    return {
      eyebrow: "Start",
      title: "Erstes Risiko erfassen",
      text: "Nutze den Risikoworkshop, damit Asset, Szenario, Owner, Bewertung und Behandlung strukturiert entstehen.",
      action: "Risiko erfassen",
      target: "risks:riskWorkshop"
    };
  }
  if (treatment?.missingTreatment?.length || treatment?.missingResidual?.length) {
    return {
      eyebrow: "Priorität",
      title: "Risikobehandlung vervollständigen",
      text: "Für einige Risiken fehlen Maßnahme oder Restrisikobewertung. Ohne diese Angaben kann der Berater nicht sauber prüfen.",
      action: "Behandlungsplan öffnen",
      target: "risks:riskTreatmentPlan"
    };
  }
  if (traceability?.highWithoutEvidence?.length || traceability?.missingEvidence?.length) {
    return {
      eyebrow: "Nachweise",
      title: "Nachweise verknüpfen",
      text: "Risiken müssen mit Datei, Link oder Dokumentverweis nachvollziehbar belegt werden. Die Plattform zeigt nur formale Lücken.",
      action: "Mapping öffnen",
      target: "risks:riskTraceability"
    };
  }
  if (effectiveness?.taskCandidates?.length) {
    return {
      eyebrow: "Wirksamkeit",
      title: "Maßnahmen prüfbar machen",
      text: "Restrisiko, Nachweis oder Review fehlen noch für eine fachliche Wirksamkeitsprüfung.",
      action: "Wirksamkeitscheck öffnen",
      target: "risks:riskEffectiveness"
    };
  }
  if (review?.overdue?.length || review?.missingReview?.length || review?.next30?.length) {
    return {
      eyebrow: "Wiedervorlage",
      title: "Reviews planen",
      text: "Einige Risiken brauchen ein Review-Datum oder stehen zur Wiedervorlage an.",
      action: "Reviewplan öffnen",
      target: "risks:riskReviewPlan"
    };
  }
  if (acceptance?.decisionRisks?.length) {
    return {
      eyebrow: "Entscheidung",
      title: "Managemententscheidung vorbereiten",
      text: "Hohe Restrisiken oder bewusst akzeptierte Risiken brauchen dokumentierte Entscheidung und Beraterprüfung.",
      action: "Entscheidungen öffnen",
      target: "risks:riskAcceptance"
    };
  }
  return {
    eyebrow: "Gut vorbereitet",
    title: "Risikoboard prüfen",
    text: "Die formalen Kernlücken sind aktuell niedrig. Nutze das Risikoboard für Überblick und Filter.",
    action: "Risikoboard öffnen",
    target: "risks:riskBoard"
  };
}

function renderRiskFocusCard(card) {
  return `
    <button class="risk-focus-card ${escapeHtml(card.tone || "")}" type="button" data-jump-section="${escapeHtml(card.target || "risks:riskBoard")}">
      <strong>${escapeHtml(card.value)}</strong>
      <span>${escapeHtml(card.label)}</span>
      <small>${escapeHtml(card.hint)}</small>
    </button>
  `;
}

function renderRiskMethodologyPanel(risks = state.risks.map(enrichRisk)) {
  const methodology = normalizeRiskMethodology(state.riskMethodology);
  const thresholds = riskMethodologyThresholds(methodology);
  const scaleLikelihood = splitRiskScale(methodology.likelihoodLabels);
  const scaleImpact = splitRiskScale(methodology.impactLabels);
  const openRisks = risks.filter((risk) => !riskClosed(risk));
  const treatmentNeeded = openRisks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= thresholds.treatmentFrom).length;
  const managementNeeded = openRisks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= thresholds.managementFrom || riskScore(risk.residualLikelihood, risk.residualImpact) >= thresholds.managementFrom).length;
  const critical = openRisks.filter((risk) => riskScore(risk.likelihood, risk.impact) >= thresholds.criticalFrom).length;
  const disabled = canEditWorkspace() ? "" : "disabled";

  return `
    <section class="panel risk-methodology-panel" id="riskMethodology">
      <div class="risk-methodology-head">
        <div>
          <span class="eyebrow">Risikomethodik</span>
          <h3>Bewertungsskala und Akzeptanzlogik verständlich festlegen</h3>
          <p>Diese Methodik erklärt, wie Risiken bewertet und ab wann sie behandelt oder zur Managemententscheidung vorbereitet werden. Fachliche Freigaben bleiben beim Berater/Admin.</p>
        </div>
        <div class="risk-methodology-actions">
          <button class="quiet-button" type="button" data-risk-methodology-export>Methodik exportieren</button>
        </div>
      </div>

      <div class="risk-methodology-kpis">
        ${renderRiskMethodologyKpi("Methodik", methodology.methodName, methodology.updated ? `Stand ${methodology.updated}` : "Arbeitsstand")}
        ${renderRiskMethodologyKpi("Behandlung ab", `Score ${thresholds.treatmentFrom}`, `${treatmentNeeded} offene Risiko(s)`, treatmentNeeded ? "warning" : "done")}
        ${renderRiskMethodologyKpi("Management ab", `Score ${thresholds.managementFrom}`, `${managementNeeded} Entscheidung(en)`, managementNeeded ? "danger" : "done")}
        ${renderRiskMethodologyKpi("Kritisch ab", `Score ${thresholds.criticalFrom}`, `${critical} kritisch`, critical ? "danger" : "done")}
      </div>

      <div class="risk-methodology-layout">
        <div class="risk-methodology-scale">
          <article>
            <strong>Wahrscheinlichkeit</strong>
            <div class="risk-methodology-scale-list">
              ${scaleLikelihood.map((item) => renderRiskScaleItem(item)).join("")}
            </div>
          </article>
          <article>
            <strong>Auswirkung</strong>
            <div class="risk-methodology-scale-list">
              ${scaleImpact.map((item) => renderRiskScaleItem(item)).join("")}
            </div>
          </article>
          <article class="risk-methodology-rules">
            <strong>Entscheidungsregeln</strong>
            <ul>
              <li><b>1-4</b><span>beobachten oder regulär behandeln</span></li>
              <li><b>5-${Math.max(thresholds.treatmentFrom - 1, 5)}</b><span>prüfen und bei Bedarf Maßnahme planen</span></li>
              <li><b>ab ${thresholds.treatmentFrom}</b><span>Behandlung, Owner und Nachweis vorbereiten</span></li>
              <li><b>ab ${thresholds.managementFrom}</b><span>Managemententscheidung oder Akzeptanz vorbereiten</span></li>
              <li><b>ab ${thresholds.criticalFrom}</b><span>priorisiert durch Berater/Admin prüfen lassen</span></li>
            </ul>
          </article>
        </div>

        <form class="risk-methodology-form" data-risk-methodology-form>
          <div class="field wide">
            <label>Methodik</label>
            <input name="methodName" value="${escapeHtml(methodology.methodName)}" ${disabled} />
          </div>
          <div class="field">
            <label>Behandlung ab Score</label>
            <input name="treatmentFrom" type="number" min="1" max="25" value="${escapeHtml(methodology.treatmentFrom)}" ${disabled} />
          </div>
          <div class="field">
            <label>Management ab Score</label>
            <input name="managementFrom" type="number" min="1" max="25" value="${escapeHtml(methodology.managementFrom)}" ${disabled} />
          </div>
          <div class="field">
            <label>Kritisch ab Score</label>
            <input name="criticalFrom" type="number" min="1" max="25" value="${escapeHtml(methodology.criticalFrom)}" ${disabled} />
          </div>
          <div class="field wide">
            <label>Wahrscheinlichkeitsskala</label>
            <textarea name="likelihoodLabels" ${disabled}>${escapeHtml(methodology.likelihoodLabels)}</textarea>
          </div>
          <div class="field wide">
            <label>Auswirkungsskala</label>
            <textarea name="impactLabels" ${disabled}>${escapeHtml(methodology.impactLabels)}</textarea>
          </div>
          <div class="field full">
            <label>Akzeptanzlogik</label>
            <textarea name="acceptanceRule" ${disabled}>${escapeHtml(methodology.acceptanceRule)}</textarea>
          </div>
          <div class="field wide">
            <label>Review-Zyklus</label>
            <input name="reviewCycle" value="${escapeHtml(methodology.reviewCycle)}" ${disabled} />
          </div>
          <div class="field">
            <label>Owner</label>
            <input name="owner" value="${escapeHtml(methodology.owner)}" ${disabled} />
          </div>
          <div class="field risk-methodology-submit">
            <label>&nbsp;</label>
            <button class="primary-button" type="submit" ${disabled}>Methodik speichern</button>
          </div>
        </form>
      </div>

      <p class="risk-methodology-boundary">Grenze: Die Methodik schafft Transparenz und Konsistenz. Sie entscheidet nicht automatisch, ob ein Risiko akzeptiert, ISO-konform, NIS-2-erfüllt oder auditbereit ist.</p>
    </section>
  `;
}

function riskMethodologyThresholds(methodology = state.riskMethodology) {
  return riskEngine.thresholds(methodology);
}

function splitRiskScale(text = "") {
  return riskEngine.splitScale(text);
}

function renderRiskScaleItem(item) {
  return `
    <span>
      <b>${escapeHtml(item.value)}</b>
      <small>${escapeHtml(item.label || "-")}</small>
    </span>
  `;
}

function renderRiskMethodologyKpi(label, value, hint, tone = "") {
  return `
    <article class="${escapeHtml(tone)}">
      <strong>${escapeHtml(value)}</strong>
      <span>${escapeHtml(label)}</span>
      <small>${escapeHtml(hint)}</small>
    </article>
  `;
}

function handleRiskMethodologySubmit(event) {
  event.preventDefault();
  if (!canEditWorkspace()) {
    showPermissionToast("Risikomethodik speichern", "Berater-/Adminrechten");
    return;
  }
  const data = Object.fromEntries(new FormData(event.currentTarget).entries());
  state.riskMethodology = normalizeRiskMethodology({
    ...state.riskMethodology,
    ...data,
    updated: today()
  });
  recordAuditTrailEvent({
    action: "Risikomethodik aktualisiert",
    entityType: "Risikomethodik",
    entityId: "risk-methodology",
    entityTitle: state.riskMethodology.methodName,
    module: "Risiko Management",
    status: "aktualisiert",
    note: "Bewertungsskala, Schwellenwerte oder Akzeptanzlogik wurden aktualisiert."
  });
  saveState({ immediate: true });
  showToast("Risikomethodik gespeichert.");
  render();
}

function downloadRiskMethodologyReport() {
  const methodology = normalizeRiskMethodology(state.riskMethodology);
  const thresholds = riskMethodologyThresholds(methodology);
  const lines = [
    "# SFM Compliance Risikomethodik",
    "",
    `Datum: ${today()}`,
    `Methodik: ${methodology.methodName}`,
    `Owner: ${methodology.owner}`,
    `Stand: ${methodology.updated || "Arbeitsstand"}`,
    "",
    "Grenze: Diese Methodik ist eine formale Arbeitsgrundlage. Sie ersetzt keine fachliche Freigabe, keine automatische Risikoakzeptanz und keine Aussage zu ISO-Konformität, NIS-2-Erfüllung oder Auditbereitschaft.",
    "",
    "## Schwellenwerte",
    `- Behandlung ab Score: ${thresholds.treatmentFrom}`,
    `- Managemententscheidung ab Score: ${thresholds.managementFrom}`,
    `- Kritisch ab Score: ${thresholds.criticalFrom}`,
    "",
    "## Wahrscheinlichkeitsskala"
  ];
  splitRiskScale(methodology.likelihoodLabels).forEach((item) => {
    lines.push(`- ${item.value}: ${item.label}`);
  });
  lines.push("", "## Auswirkungsskala");
  splitRiskScale(methodology.impactLabels).forEach((item) => {
    lines.push(`- ${item.value}: ${item.label}`);
  });
  lines.push(
    "",
    "## Akzeptanzlogik",
    methodology.acceptanceRule || "-",
    "",
    "## Review-Zyklus",
    methodology.reviewCycle || "-"
  );
  downloadTextFile(`sfm-compliance-risikomethodik-${today()}.md`, lines.join("\n"), "text/markdown");
  showToast("Risikomethodik exportiert.");
}

