function riskAcceptanceData(risks = state.risks.map(enrichRisk)) {
  const open = dedupeRisks(risks).filter((risk) => !riskClosed(risk));
  const decisionRisks = open
    .filter(riskNeedsManagementDecision)
    .sort((left, right) => {
      const leftResidual = riskScore(left.residualLikelihood, left.residualImpact);
      const rightResidual = riskScore(right.residualLikelihood, right.residualImpact);
      return Math.max(riskScore(right.likelihood, right.impact), rightResidual) - Math.max(riskScore(left.likelihood, left.impact), leftResidual);
    });
  const ownerMissing = decisionRisks.filter((risk) => !String(risk.acceptanceOwner || "").trim());
  const highResidual = decisionRisks.filter((risk) => riskScore(risk.residualLikelihood, risk.residualImpact) >= 10);
  const readyForReview = decisionRisks.filter((risk) => {
    const hasTreatment = Boolean(String(risk.treatment || "").trim());
    const hasResidual = Boolean(risk.residualLikelihood && risk.residualImpact);
    const hasOwner = Boolean(String(risk.acceptanceOwner || "").trim());
    const hasEvidence = Boolean(String(risk.evidence || "").trim()) || riskLinkedDocuments(risk).length > 0;
    return hasTreatment && hasResidual && hasOwner && hasEvidence;
  });
  return { open, decisionRisks, ownerMissing, highResidual, readyForReview };
}

function riskNeedsManagementDecision(risk = {}) {
  const inherentScore = riskScore(risk.likelihood, risk.impact);
  const residualScore = riskScore(risk.residualLikelihood, risk.residualImpact);
  const status = String(risk.status || "");
  const acceptanceRelevant = inherentScore >= 10
    || residualScore >= 10
    || String(risk.treatmentOption || "") === "Akzeptieren"
    || status === "Restrisiko prüfen";
  return inherentScore >= 10
    || residualScore >= 10
    || String(risk.treatmentOption || "") === "Akzeptieren"
    || status === "Restrisiko prüfen"
    || (acceptanceRelevant && !String(risk.acceptanceOwner || "").trim());
}

function renderRiskAcceptanceKpi(label, value, hint, tone = "") {
  return `
    <article class="${escapeHtml(tone)}">
      <strong>${escapeHtml(value)}</strong>
      <span>${escapeHtml(label)}</span>
      <small>${escapeHtml(hint)}</small>
    </article>
  `;
}

function renderRiskAcceptanceCard(risk) {
  const inherentScore = riskScore(risk.likelihood, risk.impact);
  const residualScore = riskScore(risk.residualLikelihood, risk.residualImpact);
  const status = canonicalReviewStatus(risk, "risk");
  const reason = riskAcceptanceReason(risk);
  const tone = residualScore >= 10 || inherentScore >= 16 ? "danger" : inherentScore >= 10 ? "warning" : "active";
  const submitButton = (canEditWorkspace() || canSubmitDocuments()) && status !== "freigegeben"
    ? `<button class="quiet-button" type="button" data-register-submit="risks:${escapeHtml(risk.id || "")}">Zur Prüfung</button>`
    : "";
  const taskButton = canEditWorkspace()
    ? `<button class="quiet-button" type="button" data-risk-acceptance-task="${escapeHtml(risk.id || "")}">Entscheidungsaufgabe</button>`
    : "";
  return `
    <article class="risk-acceptance-card ${escapeHtml(tone)}">
      <div class="risk-acceptance-main">
        <span class="risk-treatment-id">${escapeHtml(risk.riskId || "Risiko")}</span>
        <strong>${escapeHtml(risk.asset || "Asset offen")}</strong>
        <p>${escapeHtml(risk.scenario || "Risikoszenario noch ergänzen.")}</p>
        <div class="risk-acceptance-tags">
          ${statusTag(`${inherentScore || "-"} inhärent`)}
          ${statusTag(residualScore ? `${residualScore} Restrisiko` : "Restrisiko offen")}
          ${statusTag(reviewStatusLabel(status))}
        </div>
      </div>
      <div class="risk-acceptance-decision">
        <strong>${escapeHtml(reason)}</strong>
        <span>Entscheider: ${escapeHtml(risk.acceptanceOwner || "offen")}</span>
        <span>Owner: ${escapeHtml(risk.owner || "offen")}</span>
        <span>Review: ${escapeHtml(risk.review || "offen")}</span>
      </div>
      <div class="risk-acceptance-card-actions">
        <button class="quiet-button" type="button" data-document-upload-ref="${escapeHtml(registerEvidenceReference("risks", risk))}" data-document-upload-area="Risiko Management">Nachweis</button>
        ${submitButton}
        ${taskButton}
      </div>
    </article>
  `;
}

function riskAcceptanceReason(risk = {}) {
  const inherentScore = riskScore(risk.likelihood, risk.impact);
  const residualScore = riskScore(risk.residualLikelihood, risk.residualImpact);
  if (!String(risk.acceptanceOwner || "").trim()) return "Akzeptanz-Owner fehlt";
  if (residualScore >= 10) return "Hohes Restrisiko entscheiden";
  if (String(risk.treatmentOption || "") === "Akzeptieren") return "Risikoakzeptanz dokumentieren";
  if (String(risk.status || "") === "Restrisiko prüfen") return "Restrisiko prüfen";
  if (inherentScore >= 16) return "Sehr hohes Ausgangsrisiko";
  if (inherentScore >= 10) return "Hohes Risiko im Blick behalten";
  return "Entscheidungsbedarf prüfen";
}

function createRiskAcceptanceTasks(riskId = "") {
  if (!canEditWorkspace()) {
    showPermissionToast("Management-Entscheidungsaufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const risks = riskId
    ? state.risks.filter((risk) => risk.id === riskId)
    : riskAcceptanceData(state.risks.map(enrichRisk)).decisionRisks;
  let created = 0;
  risks.forEach((risk) => {
    const reason = riskAcceptanceReason(risk);
    const title = `Managemententscheidung vorbereiten: ${risk.riskId || risk.asset || risk.scenario || "Risiko"}`;
    const ok = addTaskIfMissing({
      title,
      module: "Risiko Management",
      owner: risk.acceptanceOwner || risk.owner || "Geschäftsleitung / Risk Owner",
      due: futureDate(riskScore(risk.likelihood, risk.impact) >= 16 ? 7 : 14),
      status: "Offen",
      linkedTo: risk.riskId || risk.id || "",
      workflowType: "risk-acceptance",
      note: [
        `Entscheidungsgrund: ${reason}.`,
        risk.scenario ? `Risiko: ${risk.scenario}` : "",
        risk.treatment ? `Maßnahme: ${risk.treatment}` : "Bitte Maßnahme vor der Entscheidung ergänzen.",
        "Bitte Restrisiko, Entscheider/Gremium und Entscheidungsnachweis vorbereiten. Finale fachliche Freigabe bleibt beim Berater/Admin."
      ].filter(Boolean).join(" ")
    });
    if (ok) created += 1;
  });
  saveState({ immediate: true });
  showToast(created ? `${created} Management-Entscheidungsaufgabe(n) angelegt.` : "Passende Entscheidungsaufgaben waren bereits vorhanden.");
  render();
}

