function riskReviewPlanData(risks = state.risks.map(enrichRisk)) {
  const open = dedupeRisks(risks).filter((risk) => !riskClosed(risk));
  const next30Date = futureDate(30);
  const missingReview = open
    .filter((risk) => !String(risk.review || "").trim())
    .sort(riskReviewSort);
  const overdue = open
    .filter((risk) => risk.review && risk.review < today())
    .sort(riskReviewSort);
  const next30 = open
    .filter((risk) => risk.review && risk.review >= today() && risk.review <= next30Date)
    .sort((left, right) => String(left.review || "").localeCompare(String(right.review || "")) || riskReviewSort(left, right));
  const highOpen = open
    .filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10 || riskScore(risk.residualLikelihood, risk.residualImpact) >= 10)
    .sort(riskReviewSort);
  const taskCandidates = dedupeRisks([...overdue, ...missingReview, ...next30.filter((risk) => riskScore(risk.likelihood, risk.impact) >= 10)]);
  return { open, missingReview, overdue, next30, highOpen, taskCandidates };
}

function riskReviewSort(left, right) {
  return riskScore(right.likelihood, right.impact) - riskScore(left.likelihood, left.impact)
    || String(left.review || "9999-12-31").localeCompare(String(right.review || "9999-12-31"));
}

