function renderRegisterDetailDrawer(collection, rows = registerRows(collection)) {
  const row = registerDetailRow(collection, rows);
  if (!row) return "";
  const summary = registerRowSummary(collection, row);
  const reviewStatus = canonicalReviewStatus(row, registerReviewType(collection));
  const documents = findLinkedDocuments(rowReferenceValues(row), { limit: 3 });
  const hasEvidence = Boolean(documents.length || row.evidence || row.documentId || row.sourceSocReportId);
  const nextStep = registerNextStep(collection, row);
  const facts = [
    ["Owner", row.owner || "Owner offen"],
    ["Status", registerRowStatusValue(collection, row)],
    ["Zuordnung", registerComplianceScope(row, collection)],
    ["Nachweis", hasEvidence ? `${documents.length || 1} vorhanden` : "fehlt"],
    ["Review", reviewStatusLabel(reviewStatus)],
    ["Termin", row.due || row.review || row.nextReview || "nicht gesetzt"]
  ];
  const contextActions = registerContextActions(collection);
  const evidenceRef = registerEvidenceReference(collection, row);
  return `
    <aside class="register-detail-drawer" data-register-detail-panel="${escapeHtml(collection)}:${escapeHtml(row.id || "")}" tabindex="-1" aria-label="${escapeHtml(registerFullModuleLabel(collection))} Detail">
      <div class="register-detail-head">
        <div>
          <span>${escapeHtml(registerFullModuleLabel(collection))}</span>
          <h3>${escapeHtml(summary.title)}</h3>
          <p>${escapeHtml(summary.subtitle || "Details und nächsten Schritt prüfen.")}</p>
        </div>
        <button class="quiet-button register-detail-close" type="button" data-register-detail-close aria-label="Detail schließen">Schließen</button>
      </div>

      <div class="register-detail-facts">
        ${facts.map(([label, value]) => `
          <div>
            <span>${escapeHtml(label)}</span>
            <strong>${escapeHtml(value)}</strong>
          </div>
        `).join("")}
      </div>

      <section class="register-detail-section">
        <span>Nächster sinnvoller Schritt</span>
        <p>${escapeHtml(nextStep)}</p>
      </section>

      <section class="register-detail-section">
        <span>Warum relevant?</span>
        <p>${escapeHtml(registerDetailWhy(collection, row))}</p>
      </section>

      <section class="register-detail-section">
        <span>Nachweis / Bezug</span>
        ${documents.length ? `
          <div class="register-detail-doc-list">
            ${documents.map((document) => `
              <button class="quiet-button" type="button" data-open-document="${escapeHtml(document.id)}">${escapeHtml(document.name || "Nachweis öffnen")}</button>
            `).join("")}
          </div>
        ` : `<p>${escapeHtml(row.evidence || "Noch kein Nachweis verknüpft. Datei, Link oder Dokumentverweis ergänzen.")}</p>`}
      </section>

      ${collection === "assets" ? renderAssetDetailEditForm(row) : ""}
      ${collection === "risks" ? renderRiskDetailEditForm(row) : ""}
      ${collection === "suppliers" ? renderSupplierDetailEditForm(row) : ""}
      ${collection === "legal" ? renderLegalDetailEditForm(row) : ""}
      ${collection === "incidents" ? renderIncidentDetailEditForm(row) : ""}
      ${collection === "contracts" ? renderContractDetailEditForm(row) : ""}
      ${collection === "tasks" ? renderTaskDetailEditForm(row) : ""}

      <div class="register-detail-actions">
        ${documents[0]
          ? `<button class="primary-button" type="button" data-open-document="${escapeHtml(documents[0].id)}">Nachweis öffnen</button>`
          : `<button class="primary-button" type="button" data-document-upload-ref="${escapeHtml(evidenceRef)}" data-document-upload-area="${escapeHtml(registerFullModuleLabel(collection))}">Nachweis anlegen</button>`}
        ${(canEditWorkspace() || canSubmitWorkspace()) && reviewStatus !== "freigegeben" ? `<button class="quiet-button" type="button" data-register-submit="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">Zur Beraterprüfung</button>` : ""}
        <button class="quiet-button" type="button" data-register-documents="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">Nachweise suchen</button>
        ${contextActions.map((action) => `<button class="quiet-button" type="button" data-jump="${escapeHtml(action.view)}">${escapeHtml(action.label)}</button>`).join("")}
        ${collection === "suppliers" ? `<button class="quiet-button" type="button" data-supplier-contract="${escapeHtml(row.id || "")}">Vertrag prüfen</button><button class="quiet-button" type="button" data-supplier-risk="${escapeHtml(row.id || "")}">Risiko prüfen</button>` : ""}
      </div>
    </aside>
  `;
}

function registerDetailWhy(collection, row = {}) {
  if (collection === "assets") {
    return "Assets sind die Grundlage für Schutzbedarf, Risiken, Zuständigkeiten und Nachweise. Der Eintrag sollte so klar sein, dass der Berater ihn fachlich prüfen kann.";
  }
  if (collection === "risks") {
    const score = riskScore(row.likelihood, row.impact);
    return `Risiken brauchen nachvollziehbare Bewertung, Behandlung, Owner und Nachweis. ${score ? `Der aktuelle Score liegt bei ${score} (${riskLevel(score)}).` : "Die Bewertung ist noch nicht vollständig."}`;
  }
  if (collection === "suppliers") {
    return "Lieferanten sollten mit Kritikalität, Zugriff/Daten, Vertrag, Nachweisen und Reviewstatus steuerbar sein. Die fachliche Bewertung bleibt beim Berater/Admin.";
  }
  return "Dieser Eintrag sollte formal vollständig, nachvollziehbar und mit passenden Nachweisen verbunden sein.";
}

function renderReferenceRegisterPanel(title, collection, rows = [], description = "") {
  const editable = canEditWorkspace();
  const tabs = referenceRegisterTabs(collection);
  const columns = referenceRegisterColumns(collection);
  const registerState = referenceRegisterViewState(collection);
  const filteredRows = referenceRegisterFilteredRows(collection, rows, registerState);
  const totalPages = Math.max(1, Math.ceil(filteredRows.length / REFERENCE_REGISTER_PAGE_SIZE));
  const currentPage = Math.min(Math.max(1, registerState.page), totalPages);
  const startIndex = (currentPage - 1) * REFERENCE_REGISTER_PAGE_SIZE;
  const visibleRows = filteredRows.slice(startIndex, startIndex + REFERENCE_REGISTER_PAGE_SIZE);
  const resultLabel = filteredRows.length
    ? `${startIndex + 1}-${startIndex + visibleRows.length} von ${filteredRows.length} ${referenceRegisterPlural(collection)}`
    : `0 ${referenceRegisterPlural(collection)}`;

  return `
    <section class="table-panel register-panel reference-register-panel reference-register-${escapeHtml(collection)} ${escapeHtml(collection || "general")} ${registerState.compactColumns ? "reference-columns-compact" : ""}" id="${escapeHtml(collection)}ReferenceRegister">
      <div class="reference-register-tabs" role="tablist" aria-label="${escapeHtml(title)} Ansichten">
        ${tabs.map((tab, index) => `<button class="${registerState.tab === tab || (!registerState.tab && index === 0) ? "active" : ""}" type="button" data-reference-tab="${escapeHtml(collection)}:${escapeHtml(tab)}" aria-selected="${registerState.tab === tab || (!registerState.tab && index === 0) ? "true" : "false"}">${escapeHtml(tab)}</button>`).join("")}
      </div>

      <div class="reference-register-toolbar">
        <div class="reference-scope-pills">
          ${["ISO 27001", "NIS-2", "Beides"].map((scope) => `<button class="quiet-button ${registerState.scope === scope ? "active" : ""}" type="button" data-reference-scope="${escapeHtml(collection)}:${escapeHtml(scope)}" aria-pressed="${registerState.scope === scope ? "true" : "false"}">${escapeHtml(scope)}</button>`).join("")}
        </div>
        <div class="reference-search-tools">
          <label class="reference-search">
            <input type="search" value="${escapeHtml(registerState.query)}" placeholder="${escapeHtml(referenceRegisterSearchPlaceholder(collection))}" aria-label="${escapeHtml(title)} durchsuchen" data-reference-search="${escapeHtml(collection)}" />
            <span aria-hidden="true">${renderModuleInlineIcon("review")}</span>
          </label>
          <button class="quiet-button" type="button" data-reference-filter-reset="${escapeHtml(collection)}">${renderModuleInlineIcon("review")} Filter zurücksetzen</button>
          <button class="quiet-button" type="button" data-reference-columns-toggle="${escapeHtml(collection)}" aria-pressed="${registerState.compactColumns ? "true" : "false"}">${renderModuleInlineIcon("database")} ${registerState.compactColumns ? "Alle Spalten" : "Weniger Spalten"}</button>
        </div>
      </div>

      <div class="reference-table-wrap">
        <table class="reference-table">
          <caption>
            <span>${escapeHtml(title)}</span>
            <small>${escapeHtml(description || tableRegisterHint(collection))}</small>
          </caption>
          <thead>
            <tr>
              ${columns.map((column) => `<th>${escapeHtml(column)}</th>`).join("")}
              <th aria-label="Aktionen"></th>
            </tr>
          </thead>
          <tbody>
            ${visibleRows.length ? visibleRows.map((row) => renderReferenceRegisterRow(collection, row, editable)).join("") : `
              <tr>
                <td colspan="${columns.length + 1}">
                  ${renderEmptyState("Noch keine Einträge vorhanden", emptyRegisterAction(collection), emptyRegisterActions(collection).map((action, index) => ({ ...action, primary: index === 0 })), { compact: true, mark: registerModuleLabel(collection).slice(0, 2).toUpperCase() })}
                </td>
              </tr>
            `}
          </tbody>
        </table>
      </div>

      <div class="reference-pagination">
        <span>${escapeHtml(resultLabel)}</span>
        ${renderReferencePagination(collection, currentPage, totalPages)}
      </div>
    </section>
  `;
}

function referenceRegisterViewState(collection) {
  const fallback = { scope: "Beides", query: "", page: 1, compactColumns: false, tab: "Übersicht" };
  const current = referenceRegisterState[collection] || fallback;
  return {
    scope: ["ISO 27001", "NIS-2", "Beides"].includes(current.scope) ? current.scope : fallback.scope,
    query: String(current.query || ""),
    page: Math.max(1, Number(current.page) || 1),
    compactColumns: Boolean(current.compactColumns),
    tab: referenceRegisterTabs(collection).includes(current.tab) ? current.tab : fallback.tab
  };
}

function updateReferenceRegisterState(collection, changes = {}) {
  const current = referenceRegisterViewState(collection);
  referenceRegisterState = {
    ...referenceRegisterState,
    [collection]: { ...current, ...changes }
  };
}

function referenceRegisterFilteredRows(collection, rows = [], viewState = referenceRegisterViewState(collection)) {
  const query = viewState.query.trim().toLocaleLowerCase("de-DE");
  return rows.filter((row) => {
    const framework = String(registerComplianceScope(row, collection) || "").toLocaleLowerCase("de-DE");
    const matchesScope = viewState.scope === "Beides"
      || (viewState.scope === "ISO 27001" && framework.includes("iso"))
      || (viewState.scope === "NIS-2" && framework.includes("nis"));
    if (!matchesScope) return false;
    if (!query) return true;
    const summary = registerRowSummary(collection, row);
    const searchable = [
      summary.title,
      summary.subtitle,
      row.owner,
      row.framework,
      row.status,
      row.evidence,
      row.linkedTo,
      row.service,
      row.asset,
      row.riskId,
      row.scenario
    ].filter(Boolean).join(" ").toLocaleLowerCase("de-DE");
    return searchable.includes(query);
  });
}

function referenceRegisterPageNumbers(currentPage, totalPages) {
  if (totalPages <= 5) return Array.from({ length: totalPages }, (_, index) => index + 1);
  const values = new Set([1, totalPages, currentPage - 1, currentPage, currentPage + 1]);
  return [...values].filter((value) => value >= 1 && value <= totalPages).sort((left, right) => left - right);
}

function renderReferencePagination(collection, currentPage, totalPages) {
  const pages = referenceRegisterPageNumbers(currentPage, totalPages);
  const buttons = pages.map((page, index) => {
    const previous = pages[index - 1];
    const gap = previous && page - previous > 1 ? `<span aria-hidden="true">…</span>` : "";
    return `${gap}<button class="quiet-button ${page === currentPage ? "active" : ""}" type="button" data-reference-page="${escapeHtml(collection)}" data-reference-page-value="${page}" aria-current="${page === currentPage ? "page" : "false"}">${page}</button>`;
  }).join("");
  return `
    <div>
      <button class="quiet-button" type="button" data-reference-page="${escapeHtml(collection)}" data-reference-page-value="${Math.max(1, currentPage - 1)}" ${currentPage === 1 ? "disabled" : ""} aria-label="Vorherige Seite">‹</button>
      ${buttons}
      <button class="quiet-button" type="button" data-reference-page="${escapeHtml(collection)}" data-reference-page-value="${Math.min(totalPages, currentPage + 1)}" ${currentPage === totalPages ? "disabled" : ""} aria-label="Nächste Seite">›</button>
    </div>
  `;
}

function referenceRegisterTabTarget(collection, tab) {
  const targets = {
    assets: {
      Nachweise: "documents",
      Freigaben: "review",
      Änderungshistorie: "audittrail"
    },
    risks: {
      Maßnahmen: "tasks",
      Nachweise: "documents",
      Entscheidungen: "review",
      Änderungshistorie: "audittrail"
    },
    suppliers: {
      Verträge: "contracts",
      Nachweise: "documents",
      Reviews: "review"
    }
  };
  return targets[collection]?.[tab] || "";
}

function referenceRegisterTabs(collection) {
  return {
    assets: ["Übersicht", "Register", "Nachweise", "Freigaben", "Änderungshistorie"],
    risks: ["Übersicht", "Register", "Maßnahmen", "Nachweise", "Entscheidungen", "Änderungshistorie"],
    suppliers: ["Übersicht", "Register", "Verträge", "Nachweise", "Reviews"]
  }[collection] || ["Übersicht", "Register", "Nachweise"];
}

function referenceRegisterColumns(collection) {
  return {
    assets: ["Asset", "Typ", "Owner", "Kritikalität", "Schutzbedarf", "Nachweisstatus", "Review"],
    risks: ["Risiko", "Bereich", "Owner", "Eintritt", "Auswirkung", "Score", "Maßnahmenstatus", "Review"],
    suppliers: ["Lieferant", "Kategorie", "Kritikalität", "Datenzugriff", "Vertrag", "Nachweisstatus", "Review", "Owner"]
  }[collection] || ["Eintrag", "Owner", "Status", "Nachweis", "Review"];
}

function referenceRegisterPlural(collection) {
  return {
    assets: "Assets",
    risks: "Risiken",
    suppliers: "Lieferanten"
  }[collection] || "Einträge";
}

function referenceRegisterSearchPlaceholder(collection) {
  return {
    assets: "Suche nach Asset, Owner, Typ ...",
    risks: "Suche nach Risiko, Bereich, Owner ...",
    suppliers: "Suche nach Lieferant, Owner, Tag ..."
  }[collection] || "Suche";
}

function renderReferenceRegisterRow(collection, row = {}, editable = false) {
  if (collection === "assets") return renderReferenceAssetRow(row, editable);
  if (collection === "risks") return renderReferenceRiskRow(row, editable);
  if (collection === "suppliers") return renderReferenceSupplierRow(row, editable);
  const summary = registerRowSummary(collection, row);
  return `
    <tr class="${registerRowStateClass(collection, row)}" data-register-detail="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">
      <td>${referencePrimaryCell(registerModuleLabel(collection), summary.title, summary.subtitle)}</td>
      <td>${escapeHtml(row.owner || "Owner offen")}</td>
      <td>${statusTag(registerRowStatusValue(collection, row))}</td>
      <td>${renderReferenceEvidenceStatus(collection, row)}</td>
      <td>${renderRegisterDateCell(collection, row)}</td>
      <td>${renderReferenceRowAction(collection, row, editable)}</td>
    </tr>
  `;
}

function renderReferenceAssetRow(row = {}, editable = false) {
  const summary = registerRowSummary("assets", row);
  return `
    <tr class="${registerRowStateClass("assets", row)}" data-register-detail="assets:${escapeHtml(row.id || "")}">
      <td>${referencePrimaryCell("asset", summary.title, summary.subtitle)}</td>
      <td>${escapeHtml(row.type || "Asset")}</td>
      <td>${referenceOwnerCell(row.owner || "Owner offen", summary.ownerContext)}</td>
      <td>${statusTag(row.criticality || "Offen")}</td>
      <td>${escapeHtml(row.protection || "Noch offen")}</td>
      <td>${renderReferenceEvidenceStatus("assets", row)}</td>
      <td>${renderReferenceReviewCell("assets", row)}</td>
      <td>${renderReferenceRowAction("assets", row, editable)}</td>
    </tr>
  `;
}

function renderReferenceRiskRow(row = {}, editable = false) {
  const score = riskScore(row.likelihood, row.impact);
  const summary = registerRowSummary("risks", row);
  return `
    <tr class="${registerRowStateClass("risks", row)}" data-register-detail="risks:${escapeHtml(row.id || "")}">
      <td>${referencePrimaryCell("risk", summary.title, summary.subtitle)}</td>
      <td>${escapeHtml(row.asset || row.controls || "Bereich offen")}</td>
      <td>${referenceOwnerCell(row.owner || "Owner offen", "Risk Owner")}</td>
      <td>${statusTag(row.likelihood ? `${row.likelihood}` : "Offen")}</td>
      <td>${statusTag(row.impact ? `${row.impact}` : "Offen")}</td>
      <td>${renderReferenceScore(score)}</td>
      <td>${renderReferenceTreatmentStatus(row)}</td>
      <td>${renderReferenceReviewCell("risks", row)}</td>
      <td>${renderReferenceRowAction("risks", row, editable)}</td>
    </tr>
  `;
}

function renderReferenceSupplierRow(row = {}, editable = false) {
  const documents = supplierLinkedDocuments(row);
  const contract = supplierLinkedContracts(row)[0];
  return `
    <tr class="${registerRowStateClass("suppliers", row)}" data-register-detail="suppliers:${escapeHtml(row.id || "")}">
      <td>${referencePrimaryCell("people", row.name || "Unbenannter Lieferant", row.service || "Leistung noch beschreiben")}</td>
      <td>${escapeHtml(row.service || "IT-Dienstleistung")}</td>
      <td>${statusTag(row.criticality || "Offen")}</td>
      <td>${statusTag(row.dataAccess ? "Hoch" : "Offen")}</td>
      <td>${statusTag(contract || ["Vorhanden", "Freigegeben"].includes(row.contractStatus) ? "Aktiv" : (row.contractStatus || "Prüfen"))}</td>
      <td>${renderReferenceEvidenceStatus("suppliers", row, documents)}</td>
      <td>${renderRegisterDateCell("suppliers", row)}</td>
      <td>${referenceOwnerCell(row.owner || "Owner offen", "Vendor Owner")}</td>
      <td>${renderReferenceRowAction("suppliers", row, editable)}</td>
    </tr>
  `;
}

function referencePrimaryCell(icon, title, subtitle) {
  return `
    <div class="reference-primary-cell">
      <span class="reference-row-icon" aria-hidden="true">${renderModuleInlineIcon(icon)}</span>
      <span>
        <strong>${escapeHtml(title || "Eintrag")}</strong>
        <small>${escapeHtml(subtitle || "Details ergänzen")}</small>
      </span>
    </div>
  `;
}

function referenceOwnerCell(owner, context) {
  return `
    <div class="reference-owner-cell">
      <strong>${escapeHtml(owner)}</strong>
      <small>${escapeHtml(context || "Verantwortung")}</small>
    </div>
  `;
}

function renderReferenceEvidenceStatus(collection, row = {}, documents = null) {
  const docs = documents || findLinkedDocuments(rowReferenceValues(row), { limit: 2 });
  const explicitEvidence = row.evidence || row.documentId || row.sourceSocReportId;
  const count = docs.length + (explicitEvidence && !docs.length ? 1 : 0);
  const label = count ? "Vollständig" : "Nachweis fehlt";
  const hint = count ? `${count}/${Math.max(count, collection === "risks" ? 3 : 5)} Nachweise` : "Datei oder Link ergänzen";
  const first = docs[0];
  return `
    <div class="reference-evidence-status ${count ? "ready" : "missing"}">
      <span class="reference-progress-dot"></span>
      <span>
        ${first ? `<button class="evidence-mini-link" type="button" data-open-document="${escapeHtml(first.id)}">${escapeHtml(label)}</button>` : `<strong>${escapeHtml(label)}</strong>`}
        <small>${escapeHtml(hint)}</small>
      </span>
    </div>
  `;
}

function renderReferenceReviewCell(collection, row = {}) {
  const date = row.review || row.nextReview || row.due || "";
  const status = canonicalReviewStatus(row, registerReviewType(collection));
  return `
    <div class="reference-review-cell">
      <strong>${escapeHtml(date || "Nicht geplant")}</strong>
      <small>${escapeHtml(reviewStatusLabel(status))}</small>
    </div>
  `;
}

function renderReferenceScore(score) {
  const level = riskLevel(score);
  return `
    <div class="reference-score ${riskBoardTone(score)}">
      <strong>${escapeHtml(score || "-")}</strong>
      <small>${escapeHtml(score ? level : "offen")}</small>
    </div>
  `;
}

function renderReferenceTreatmentStatus(row = {}) {
  const hasTreatment = Boolean(String(row.treatment || "").trim());
  const evidenceCount = riskLinkedDocuments(row).length;
  return `
    <div class="reference-treatment-status ${hasTreatment ? "ready" : "missing"}">
      <span class="reference-progress-dot"></span>
      <span>
        <strong>${escapeHtml(hasTreatment ? (row.treatmentOption || "In Arbeit") : "Offen")}</strong>
        <small>${escapeHtml(hasTreatment ? `${evidenceCount}/${Math.max(evidenceCount, 1)} Nachweise` : "Maßnahme ergänzen")}</small>
      </span>
    </div>
  `;
}

function renderReferenceRowAction(collection, row = {}, editable = false) {
  return `<button class="reference-row-menu" type="button" data-register-detail="${escapeHtml(collection)}:${escapeHtml(row.id || "")}" title="Details öffnen" aria-label="Details öffnen">Öffnen</button>`;
}

function renderTablePanel(title, rows, columns, collection) {
  const editable = canEditWorkspace() || canSubmitWorkspace();
  if (["assets"].includes(collection)) {
    return renderReferenceRegisterPanel(title, collection, rows, tableRegisterHint(collection));
  }
  if (!rows.length) {
    return `
      <section class="table-panel register-panel ${escapeHtml(collection || "general")}" style="margin-top:18px">
        ${renderRegisterPanelHeading(title, collection, rows, emptyRegisterHint(collection))}
        ${renderEmptyState("Noch keine Einträge vorhanden", emptyRegisterAction(collection), emptyRegisterActions(collection).map((action, index) => ({ ...action, primary: index === 0 })), { mark: "RE" })}
      </section>
    `;
  }

  return `
    <section class="table-panel register-panel ${escapeHtml(collection || "general")}" style="margin-top:18px">
      ${renderRegisterPanelHeading(title, collection, rows, tableRegisterHint(collection))}
      <div class="register-card-list">
        ${rows.map((row) => renderRegisterFriendlyCard(collection, row, editable)).join("")}
      </div>
      ${renderRegisterDetailDrawer(collection, rows)}
    </section>
  `;
}

function renderRegisterFriendlyRow(collection, row, editable) {
  const summary = registerRowSummary(collection, row);
  return `
    <tr class="${registerRowStateClass(collection, row)}" data-register-detail="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">
      <td class="register-title-cell">
        <strong>${escapeHtml(summary.title)}</strong>
        <span>${escapeHtml(summary.subtitle)}</span>
        ${summary.meta ? `<small>${escapeHtml(summary.meta)}</small>` : ""}
      </td>
      <td class="register-owner-cell">
        <strong>${escapeHtml(row.owner || "Owner offen")}</strong>
        <span>${escapeHtml(summary.ownerContext)}</span>
      </td>
      <td>
        <div class="register-status-stack">
          ${statusTag(registerRowStatusValue(collection, row))}
          ${registerRowOverdue(collection, row) ? `<small>Überfällig</small>` : ""}
        </div>
      </td>
      <td>${renderRegisterDateCell(collection, row)}</td>
      <td>${renderRegisterEvidenceCell(collection, row)}</td>
      <td><span class="register-next-step">${escapeHtml(registerNextStep(collection, row))}</span></td>
      <td>${registerRowActions(collection, row, editable)}</td>
    </tr>
  `;
}

function renderRegisterFriendlyCard(collection, row, editable) {
  const summary = registerRowSummary(collection, row);
  const status = registerRowStatusValue(collection, row);
  return `
    <article class="register-work-card ${registerRowStateClass(collection, row)}" data-register-detail="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">
      <div class="register-work-card-main">
        <div class="register-card-badges">
          <span class="register-card-module">${escapeHtml(registerModuleLabel(collection))}</span>
          ${renderComplianceScopeBadge(row, collection)}
        </div>
        <strong>${escapeHtml(summary.title)}</strong>
        <p>${escapeHtml(summary.subtitle)}</p>
        ${summary.meta ? `<small>${escapeHtml(summary.meta)}</small>` : ""}
      </div>
      <div class="register-work-card-grid">
        <div>
          <span>Verantwortung</span>
          <strong>${escapeHtml(row.owner || "Owner offen")}</strong>
          <small>${escapeHtml(summary.ownerContext)}</small>
        </div>
        <div>
          <span>Status</span>
          ${statusTag(status)}
          ${registerRowOverdue(collection, row) ? `<small class="warning-text">Überfällig</small>` : ""}
        </div>
        <div>
          <span>Termin</span>
          ${renderRegisterDateCell(collection, row)}
        </div>
        <div>
          <span>Nachweis</span>
          ${renderRegisterEvidenceCell(collection, row)}
        </div>
        <div>
          <span>Beraterprüfung</span>
          ${renderRegisterReviewCell(collection, row)}
        </div>
      </div>
      ${collection === "risks" ? renderRiskRegisterDecisionStrip(row) : ""}
      ${renderRegisterMiniPath(collection, row)}
      <div class="register-card-footer">
        <span class="register-next-step">${escapeHtml(registerNextStep(collection, row))}</span>
        ${registerRowActions(collection, row, editable)}
      </div>
    </article>
  `;
}

function renderRiskRegisterDecisionStrip(risk = {}) {
  const initialScore = riskScore(risk.likelihood, risk.impact);
  const residualScore = riskScore(risk.residualLikelihood, risk.residualImpact);
  const evidence = riskLinkedDocuments(risk);
  const treatmentReady = Boolean(String(risk.treatment || "").trim());
  const residualReady = Boolean(risk.residualLikelihood && risk.residualImpact);
  const acceptanceOwner = String(risk.acceptanceOwner || "").trim();
  const explicitEvidence = String(risk.evidence || "").trim();
  const evidenceReady = Boolean(evidence.length || explicitEvidence);
  return `
    <div class="risk-register-decision-strip" aria-label="Risikobewertung und Entscheidungsstand">
      <div class="${initialScore ? "ready" : "warning"}">
        <span>Ausgangsrisiko</span>
        <strong>${initialScore || "-"}</strong>
        <small>${escapeHtml(initialScore ? riskLevel(initialScore) : "Bewertung offen")}</small>
      </div>
      <div class="${residualReady ? "ready" : "warning"}">
        <span>Restrisiko</span>
        <strong>${residualScore || "-"}</strong>
        <small>${escapeHtml(residualReady ? riskLevel(residualScore) : "nach Maßnahme offen")}</small>
      </div>
      <div class="${treatmentReady ? "ready" : "warning"}">
        <span>Behandlung</span>
        <strong>${escapeHtml(risk.treatmentOption || "Offen")}</strong>
        <small>${escapeHtml(treatmentReady ? risk.treatment : "Maßnahme ergänzen")}</small>
      </div>
      <div class="${acceptanceOwner ? "ready" : "warning"}">
        <span>Akzeptanz</span>
        <strong>${escapeHtml(acceptanceOwner || "offen")}</strong>
        <small>Entscheidung bleibt bei Berater/Admin</small>
      </div>
      <div class="${evidenceReady ? "ready" : "warning"}">
        <span>Nachweis</span>
        <strong>${escapeHtml(evidence.length ? `${evidence.length} verknüpft` : explicitEvidence || "fehlt")}</strong>
        <small>${escapeHtml(evidence[0]?.name || explicitEvidence || "Datei, Link oder Entscheidung ergänzen")}</small>
      </div>
    </div>
  `;
}

function renderRegisterMiniPath(collection, row = {}, options = {}) {
  const steps = registerMiniPathSteps(collection, row);
  return `
    <div class="register-mini-path ${options.compact ? "compact" : ""}" aria-label="${escapeHtml(registerFullModuleLabel(collection))} Arbeitsstrecke">
      ${steps.map((step, index) => `
        <div class="${escapeHtml(step.state)}">
          <b>${String(index + 1).padStart(2, "0")}</b>
          <span>
            <strong>${escapeHtml(step.label)}</strong>
            <small>${escapeHtml(step.text)}</small>
          </span>
        </div>
      `).join("")}
    </div>
  `;
}

function registerMiniPathSteps(collection, row = {}) {
  const reviewStatus = canonicalReviewStatus(row, registerReviewType(collection));
  const entryDone = Boolean(registerEntryTitle(collection, row)) && Boolean(row.owner || collection === "tasks");
  const evidenceDone = registerRowLinked(collection, row);
  const reviewStarted = ["vom_kunden_eingereicht", "in_beraterpruefung", "nacharbeit_noetig", "abgelehnt", "auditrelevant", "freigegeben"].includes(reviewStatus);
  const approved = reviewStatus === "freigegeben" || registerRowClosed(collection, row);
  const labels = {
    policies: ["Erfasst", "Dokument", "Prüfung", "Freigabe"],
    suppliers: ["Erfasst", "Nachweis", "Prüfung", "Freigabe"],
    risks: ["Erfasst", "Maßnahme", "Prüfung", "Freigabe"],
    incidents: ["Erfasst", "Bewertet", "Prüfung", "Abschluss"],
    contracts: ["Erfasst", "Vertrag", "Prüfung", "Freigabe"],
    tasks: ["Erfasst", "Bearbeiten", "Ergebnis", "Abschluss"]
  }[collection] || ["Erfasst", "Nachweis", "Prüfung", "Freigabe"];
  const texts = {
    policies: ["Name, Owner, Zuordnung", "Vorlage oder Dokument", "Berater prüft", "Berater/Admin"],
    suppliers: ["Name, Owner, Kritikalität", "Vertrag oder Nachweis", "Berater prüft", "Berater/Admin"],
    risks: ["Szenario und Owner", "Behandlung/Nachweis", "Berater prüft", "Berater/Admin"],
    incidents: ["Ereignis und Owner", "Erstbewertung/Nachweis", "Berater prüft", "Geschlossen/Freigabe"],
    contracts: ["Partner und Owner", "AVV/SLA/Nachweis", "Berater prüft", "Berater/Admin"],
    tasks: ["Titel, Owner, Frist", "Konkrete Arbeit", "Nachweis/Notiz", "Erledigt/Review"]
  }[collection] || ["Name, Owner, Zuordnung", "Datei oder Link", "Berater prüft", "Berater/Admin"];
  const done = [entryDone, evidenceDone, reviewStarted, approved];
  const activeIndex = Math.max(0, done.findIndex((value) => !value));
  return labels.map((label, index) => {
    let state = done[index] ? "done" : index === activeIndex ? "active" : "open";
    if (reviewStatus === "nacharbeit_noetig" && index === 2) state = "warning";
    if (reviewStatus === "abgelehnt" && index === 2) state = "warning";
    return {
      label,
      text: texts[index],
      state
    };
  });
}

function registerModuleLabel(collection) {
  const labels = {
    assets: "Asset",
    risks: "Risiko",
    legal: "Recht",
    suppliers: "Vendor",
    incidents: "Incident",
    contracts: "Vertrag",
    tasks: "Task"
  };
  return labels[collection] || "Register";
}

function registerFullModuleLabel(collection) {
  const labels = {
    assets: "Asset Management",
    risks: "Risiko Management",
    legal: "Rechtsregister",
    suppliers: "Vendor Management",
    policies: "Policy Management",
    incidents: "Incident Management",
    contracts: "Contract Management",
    tasks: "Task Management"
  };
  return labels[collection] || registerModuleLabel(collection);
}

function registerRows(collection) {
  const map = {
    assets: state.assets,
    risks: state.risks,
    legal: state.legal,
    suppliers: state.suppliers,
    policies: state.policies,
    incidents: state.incidents,
    contracts: state.contracts,
    tasks: state.tasks
  };
  return Array.isArray(map[collection]) ? map[collection] : [];
}

function registerReviewType(collection) {
  return {
    risks: "risk",
    policies: "policy",
    assets: "asset",
    tasks: "task"
  }[collection] || collection || "";
}

function registerEntryTitle(collection, row = {}) {
  return registerRowSummary(collection, row).title || row.name || row.title || row.requirement || "Eintrag";
}

function registerEvidenceReference(collection, row = {}) {
  return [
    registerEntryTitle(collection, row),
    row.framework,
    row.linkedTo,
    row.source,
    row.riskId
  ].filter(Boolean).join(" · ");
}

function renderRegisterReviewCell(collection, row = {}) {
  const status = canonicalReviewStatus(row, registerReviewType(collection));
  const helper = {
    offen: "Noch nicht fachlich geprüft",
    entwurf: "Policy wird vorbereitet",
    vom_kunden_eingereicht: "Wartet auf Beraterprüfung",
    in_beraterpruefung: "Berater prüft",
    nacharbeit_noetig: "Kunde muss ergänzen",
    freigegeben: "Durch Berater/Admin freigegeben",
    abgelehnt: "Abgelehnt oder neu einreichen",
    review_ueberfaellig: "Review erneut durchführen",
    spaeter_pruefen: "Für später vorgemerkt",
    auditrelevant: "Für Auditpaket markiert",
    archiviert: "Archiviert"
  }[status] || "Prüfstatus offen";
  return `
    <div class="register-review-cell">
      ${statusTag(reviewStatusLabel(status))}
      <small>${escapeHtml(helper)}</small>
    </div>
  `;
}

function renderComplianceScopeBadge(row = {}, collection = "") {
  const scope = registerComplianceScope(row, collection);
  return `<span class="scope-badge ${complianceScopeClass(scope)}">${escapeHtml(scope)}</span>`;
}

function registerComplianceScope(row = {}, collection = "") {
  if (row.framework) return String(row.framework);
  const text = [
    row.requirement,
    row.source,
    row.controls,
    row.linkedTo,
    row.evidenceFor,
    row.note,
    row.scenario,
    row.treatment
  ].filter(Boolean).join(" ").toLowerCase();
  const hasNis = text.includes("nis") || text.includes("§");
  const hasIso = text.includes("iso") || text.includes("annex") || text.includes("clause") || /\ba\.\d/.test(text);
  if (hasIso && hasNis) return "ISO 27001 + NIS-2";
  if (hasNis) return "NIS-2";
  if (hasIso) return "ISO 27001";
  if (collection === "legal") return "NIS-2";
  if (collection === "risks") return "ISO 27001 + NIS-2";
  if (collection === "assets") return "ISO 27001";
  return "Prüfen";
}

function complianceScopeClass(scope = "") {
  const value = String(scope).toLowerCase();
  if (value.includes("nis") && value.includes("iso")) return "shared";
  if (value.includes("nis")) return "nis";
  if (value.includes("iso")) return "iso";
  return "review";
}

function registerRowSummary(collection, row = {}) {
  const fallbackTitle = row.name || row.title || row.requirement || row.service || "Unbenannter Eintrag";
  const map = {
    assets: {
      title: row.name || fallbackTitle,
      subtitle: [row.type || "Asset", row.protection ? `Schutzbedarf ${row.protection}` : ""].filter(Boolean).join(" · "),
      meta: row.criticality ? `Kritikalität: ${row.criticality}` : "",
      ownerContext: row.type || "Asset Management"
    },
    risks: {
      title: row.riskId ? `${row.riskId} · ${row.asset || "Asset offen"}` : (row.asset || row.scenario || fallbackTitle),
      subtitle: row.scenario || "Risikoszenario noch ergänzen",
      meta: [row.inherent ? `Score: ${row.inherent}` : "", row.treatmentOption ? `Behandlung: ${row.treatmentOption}` : "", row.controls || ""].filter(Boolean).join(" · "),
      ownerContext: "Risiko Management"
    },
    legal: {
      title: row.requirement || fallbackTitle,
      subtitle: row.source || "Quelle offen",
      meta: row.due ? `Fällig: ${row.due}` : "",
      ownerContext: "Rechtsregister"
    },
    suppliers: {
      title: row.name || fallbackTitle,
      subtitle: row.service || "Leistung noch beschreiben",
      meta: row.criticality ? `Kritikalität: ${row.criticality}` : "",
      ownerContext: "Vendor Management"
    },
    policies: {
      title: row.title || fallbackTitle,
      subtitle: row.linkedTo || row.note || "Zuordnung oder Zweck noch ergänzen",
      meta: [row.version ? `Version: ${row.version}` : "", row.review ? `Review: ${row.review}` : ""].filter(Boolean).join(" · "),
      ownerContext: "Policy Management"
    },
    incidents: {
      title: row.title || fallbackTitle,
      subtitle: row.note || "Erstbewertung noch ergänzen",
      meta: row.severity ? `Schweregrad: ${row.severity}` : "",
      ownerContext: "Incident Management"
    },
    contracts: {
      title: row.title || fallbackTitle,
      subtitle: row.vendor || "Vertragspartner offen",
      meta: row.linkedTo ? `Zuordnung: ${row.linkedTo}` : "",
      ownerContext: "Contract Management"
    },
    tasks: {
      title: row.title || fallbackTitle,
      subtitle: row.module || "Modul offen",
      meta: row.due ? `Fällig: ${row.due}` : "",
      ownerContext: row.module || "Task Management"
    }
  };
  return map[collection] || {
    title: fallbackTitle,
    subtitle: row.note || row.source || row.linkedTo || "Details im Eintrag prüfen",
    meta: "",
    ownerContext: collection || "Register"
  };
}

function registerRowStatusValue(collection, row = {}) {
  if (collection === "suppliers") return row.review || row.status || "Nicht gestartet";
  if (collection === "assets") return row.status || row.criticality || "Offen";
  if (collection === "tasks") return row.status || "Offen";
  return row.status || row.review || "Offen";
}

function renderRegisterDateCell(collection, row = {}) {
  const date = row.due || row.review || row.nextReview || row.detected || "";
  const label = row.due ? "Fällig" : row.review ? "Review" : row.nextReview ? "Nächstes Review" : row.detected ? "Erkannt" : "Termin";
  if (!date) return `<span class="muted">Kein Termin</span>`;
  return `
    <div class="register-date-cell ${registerRowOverdue(collection, row) ? "warning" : ""}">
      <strong>${escapeHtml(date)}</strong>
      <span>${escapeHtml(label)}</span>
    </div>
  `;
}

function renderRegisterEvidenceCell(collection, row = {}) {
  const docs = findLinkedDocuments(rowReferenceValues(row), { limit: 4 });
  const explicitEvidence = row.evidence || row.documentId || row.sourceSocReportId;
  const count = docs.length + (explicitEvidence && !docs.length ? 1 : 0);
  if (!count) return `<span class="tag should">Nachweis fehlt</span>`;
  const first = docs[0];
  return `
    <div class="register-evidence-cell">
      <span class="tag practice">${count} verknüpft</span>
      ${first ? `<button class="evidence-mini-link" type="button" data-open-document="${escapeHtml(first.id)}">${escapeHtml(first.name)}</button>` : `<small>${escapeHtml(String(row.evidence || "Nachweis hinterlegt"))}</small>`}
    </div>
  `;
}

function registerNextStep(collection, row = {}) {
  if (collection === "tasks") {
    if (registerRowOverdue("tasks", row)) return "Termin prüfen oder Aufgabe neu planen";
    if (!row.owner) return "Owner zuordnen";
    if (!row.due) return "Frist setzen";
    if (row.status === "Blockiert") return "Blocker klären";
    if (!registerRowClosed("tasks", row)) return "Aufgabe bearbeiten und Status aktualisieren";
    if (!registerRowLinked("tasks", row)) return "Ergebnis oder Nachweis ergänzen";
    return "Beim nächsten Review prüfen";
  }
  if (registerRowOverdue(collection, row)) return "Termin prüfen und Entscheidung dokumentieren";
  if (!row.owner) return "Owner zuordnen";
  if (!registerRowLinked(collection, row)) return "Nachweis verknüpfen";
  if (registerRowClosed(collection, row)) return "Beim nächsten Review prüfen";
  const next = {
    assets: "Risiko- oder Schutzbedarfsbezug prüfen",
    legal: "Anwendbarkeit und Umsetzung bestätigen",
    suppliers: "Review abschließen oder Vertrag prüfen",
    incidents: "Maßnahmen und Lessons Learned ergänzen",
    contracts: "Sicherheitsklauseln und Review dokumentieren",
    tasks: "Status aktualisieren"
  };
  return next[collection] || "Eintrag fachlich prüfen";
}

function createRegisterGapTasks(collection) {
  if (!canEditWorkspace()) {
    showPermissionToast("Register-Lücken als Aufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const rows = registerRows(collection);
  if (!rows.length) {
    showToast("Noch keine Registereinträge vorhanden.");
    return;
  }
  let created = 0;
  registerGapTaskCandidates(collection, rows).forEach((task) => {
    if (addTaskIfMissing(task)) created += 1;
  });
  if (created) {
    saveState({ immediate: true });
    navigateToView("tasks");
  }
  showToast(created ? `${created} Aufgabe${created === 1 ? "" : "n"} aus ${registerFullModuleLabel(collection)} angelegt.` : "Für diese Register-Lücken bestehen bereits Aufgaben.");
}

function registerGapTaskCandidates(collection, rows = registerRows(collection)) {
  const tasks = [];
  const module = registerFullModuleLabel(collection);
  const pushTask = (row, suffix, note, dueDays = 7) => {
    const title = `${suffix}: ${registerEntryTitle(collection, row)}`;
    tasks.push({
      title,
      module,
      owner: row.owner || "Owner offen",
      due: futureDate(dueDays),
      status: "Offen",
      source: "Register-Lückencheck",
      workflowType: "register-gap",
      linkedTo: registerEvidenceReference(collection, row),
      registerCollection: collection,
      registerItemId: row.id || "",
      note
    });
  };

  rows.forEach((row) => {
    if (!row.owner && collection !== "tasks") {
      pushTask(row, "Owner ergänzen", "Bitte verantwortliche Rolle oder Person ergänzen, damit der Eintrag prüfbar wird.", 5);
    }
    if (!registerRowLinked(collection, row)) {
      pushTask(row, "Nachweis verknüpfen", "Bitte Datei, Link oder Dokumentverweis ergänzen. Die Plattform prüft nur formal, der Berater bewertet fachlich.", 7);
    }
    const reviewStatus = canonicalReviewStatus(row, registerReviewType(collection));
    if (reviewStatus === "nacharbeit_noetig" || reviewStatus === "abgelehnt") {
      pushTask(row, "Nacharbeit beantworten", "Bitte Beraterkommentar prüfen, fehlende Angaben ergänzen und den Eintrag erneut einreichen.", 3);
    }
    if (registerRowOverdue(collection, row)) {
      pushTask(row, "Termin prüfen", "Bitte Fälligkeit oder Review-Termin prüfen und den aktuellen Stand dokumentieren.", 2);
    }
  });

  return tasks;
}

function renderRegisterPanelHeading(title, collection, rows, description) {
  const metrics = registerPanelMetrics(collection, rows);
  return `
    <div class="table-panel-heading register-panel-heading">
      <div>
        <span class="eyebrow">Register</span>
        <h3>${escapeHtml(title)}</h3>
        <p>${escapeHtml(description || tableRegisterHint(collection))}</p>
      </div>
      <div class="register-panel-kpis" aria-label="Register-Kennzahlen">
        ${metrics.map((metric) => `
          <div class="${metric.warning ? "warning" : ""}">
            <strong>${escapeHtml(metric.value)}</strong>
            <span>${escapeHtml(metric.label)}</span>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function registerPanelMetrics(collection, rows = []) {
  const total = rows.length;
  const open = rows.filter((row) => !registerRowClosed(collection, row)).length;
  const overdue = rows.filter((row) => registerRowOverdue(collection, row)).length;
  const linked = rows.filter((row) => registerRowLinked(collection, row)).length;
  const labels = {
    assets: ["Einträge", "offen", "mit Nachweis"],
    risks: ["Risiken", "offen", "mit Nachweis"],
    legal: ["Einträge", "zu prüfen", "mit Nachweis"],
    suppliers: ["Lieferanten", "Review offen", "mit Nachweis"],
    policies: ["Policies", "zu prüfen", "verknüpft"],
    incidents: ["Incidents", "offen", "mit Nachweis"],
    contracts: ["Verträge", "zu prüfen", "mit Nachweis"],
    tasks: ["Aufgaben", "offen", "überfällig"]
  }[collection] || ["Einträge", "offen", "mit Nachweis"];
  if (collection === "tasks") {
    return [
      { value: String(total), label: labels[0] },
      { value: String(open), label: labels[1], warning: open > 0 },
      { value: String(overdue), label: labels[2], warning: overdue > 0 }
    ];
  }
  return [
    { value: String(total), label: labels[0] },
    { value: String(open), label: labels[1], warning: open > 0 },
    { value: String(linked), label: labels[2], warning: linked < total && total > 0 }
  ];
}

function registerRowClosed(collection, row = {}) {
  const status = String(row.status || row.review || "").toLowerCase();
  const closed = {
    assets: ["freigegeben", "archiviert"],
    risks: ["akzeptiert", "erledigt"],
    legal: ["umgesetzt", "nicht anwendbar"],
    suppliers: ["freigegeben", "erledigt", "geprüft"],
    policies: ["freigegeben", "archiviert"],
    incidents: ["geschlossen", "erledigt"],
    contracts: ["geprüft", "aktiv", "archiviert"],
    tasks: ["erledigt"]
  }[collection] || ["erledigt", "freigegeben", "geschlossen", "archiviert"];
  return closed.includes(status);
}

function registerRowOverdue(collection, row = {}) {
  if (registerRowClosed(collection, row)) return false;
  const due = row.due || row.review || row.nextReview;
  return Boolean(due && due < today());
}

function registerRowLinked(collection, row = {}) {
  if (collection === "policies") {
    const artifact = resolvePolicyArtifact(row);
    return Boolean(artifact.document || artifact.draft || artifact.template);
  }
  if (collection === "risks") return riskLinkedDocuments(row).length > 0;
  if (row.evidence || row.documentId || row.sourceSocReportId) return true;
  return findLinkedDocuments(rowReferenceValues(row), { limit: 1 }).length > 0;
}

function registerRowStateClass(collection, row = {}) {
  if (registerRowOverdue(collection, row)) return "register-row-overdue";
  if (registerRowClosed(collection, row)) return "register-row-ready";
  return "register-row-open";
}

