function emptyRegisterActions(collection) {
  const actions = {
    assets: [{ label: "Projektplan öffnen", view: "project" }, { label: "Nachweise öffnen", view: "documents" }],
    risks: [{ label: "Asset Management öffnen", view: "assets" }, { label: "Nachweise öffnen", view: "documents" }],
    legal: [{ label: "NIS-2 öffnen", view: "nis2" }, { label: "Aufgaben öffnen", view: "tasks" }],
    suppliers: [{ label: "Verträge öffnen", view: "contracts" }, { label: "Nachweise öffnen", view: "documents" }],
    policies: [{ label: "Arbeitsvorlagen öffnen", view: "templates" }, { label: "Nachweise öffnen", view: "documents" }],
    incidents: [{ label: "Aufgaben öffnen", view: "tasks" }, { label: "NIS-2 öffnen", view: "nis2" }],
    contracts: [{ label: "Lieferanten öffnen", view: "suppliers" }, { label: "Rechtsregister öffnen", view: "legal" }],
    tasks: [{ label: "Projektplan öffnen", view: "project" }, { label: "Dashboard öffnen", view: "dashboard" }]
  };
  return actions[collection] || [{ label: "Nachweise öffnen", view: "documents" }];
}

function tableRegisterHint(collection) {
  const hints = {
    assets: "Assets können direkt mit Nachweisen und Risiken weiterbearbeitet werden.",
    risks: "Risiken sollten Bewertung, Behandlung, Owner, Review und Nachweise enthalten.",
    legal: "Rechtsanforderungen sollten Owner, Status, Frist und Nachweis haben.",
    suppliers: "Lieferanten sollten mit Vertragsprüfung, Nachweisen und Review verbunden sein.",
    policies: "Policies sollten mit Entwurf, Dokument, Owner, Version und Review verknüpft sein.",
    incidents: "Incidents sollten mit Aufgaben, Nachweisen und Lessons Learned abgeschlossen werden.",
    contracts: "Verträge sollten mit Lieferanten, Sicherheitsanforderungen und Review-Nachweisen verbunden sein.",
    tasks: "Aufgaben sollten Owner, Fälligkeit und Status haben."
  };
  return hints[collection] || "Einträge können mit Nachweisen und Folgeaktionen verbunden werden.";
}

function registerRowActions(collection, row, editable) {
  const document = findLinkedDocuments(rowReferenceValues(row), { limit: 1 })[0];
  const actions = [];
  if (document) {
    actions.push(`<button class="quiet-button register-primary-action" type="button" data-open-document="${escapeHtml(document.id)}">Nachweis öffnen</button>`);
  } else {
    if (row.evidence || row.documentId || row.sourceSocReportId) {
      actions.push(`<button class="quiet-button register-primary-action" type="button" data-register-documents="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">Nachweise suchen</button>`);
    }
    actions.push(`<button class="quiet-button" type="button" data-document-upload-ref="${escapeHtml(registerEvidenceReference(collection, row))}" data-document-upload-area="${escapeHtml(registerFullModuleLabel(collection))}">Nachweis anlegen</button>`);
  }
  registerContextActions(collection).forEach((action) => {
    actions.push(`<button class="quiet-button" type="button" data-jump="${escapeHtml(action.view)}">${escapeHtml(action.label)}</button>`);
  });
  if (editable) {
    if (canonicalReviewStatus(row, registerReviewType(collection)) !== "freigegeben") {
      actions.push(`<button class="quiet-button" type="button" data-register-submit="${escapeHtml(collection)}:${escapeHtml(row.id || "")}">Zur Prüfung</button>`);
    }
  }
  if (canEditWorkspace()) {
    actions.push(`<button class="danger-button" type="button" data-delete="${escapeHtml(collection)}:${escapeHtml(row.id || "")}" title="Eintrag löschen" aria-label="Eintrag löschen">×</button>`);
  }
  return `<div class="document-actions register-actions">${actions.join("")}</div>`;
}

function findRegisterRowById(collection, id) {
  const rows = registerRows(collection);
  return rows.find((row) => String(row.id || "") === String(id || "")) || null;
}

function openRegisterDocuments(collection, id) {
  const row = findRegisterRowById(collection, id);
  if (!row) return;
  const search = registerEvidenceReference(collection, row) || registerEntryTitle(collection, row);
  documentFilters = {
    status: "Alle",
    area: "Alle",
    quality: "Alle",
    search
  };
  const match = findLinkedDocuments(rowReferenceValues(row), { limit: 1 })[0];
  if (match) selectedDocumentId = match.id;
  showToast("Dokumentation nach passendem Nachweis gefiltert.");
  navigateToView("documents");
}

function rowReferenceValues(row) {
  return [
    row.name,
    row.title,
    row.requirement,
    row.service,
    row.framework,
    row.riskId,
    row.asset,
    row.scenario,
    row.controls,
    row.treatment,
    row.vendor,
    row.linkedTo,
    row.source,
    row.note,
    row.evidence
  ].filter(Boolean);
}

function registerContextActions(collection) {
  const actions = {
    assets: [{ label: "Risiko", view: "risks" }],
    legal: [{ label: "Aufgabe", view: "tasks" }],
    suppliers: [{ label: "Vertrag", view: "contracts" }],
    policies: [{ label: "Arbeitsvorlage", view: "templates" }],
    incidents: [{ label: "Aufgabe", view: "tasks" }],
    contracts: [{ label: "Lieferant", view: "suppliers" }],
    tasks: [{ label: "Projektplan", view: "project" }]
  };
  return actions[collection] || [];
}

function fieldHelp(copy) {
  if (!copy) return "";
  const lines = Array.isArray(copy) ? copy : [copy];
  return `<small class="field-help">${lines.map((line) => escapeHtml(line)).join("<br>")}</small>`;
}

function field(label, name, type, placeholder, help = "") {
  return `<div class="field"><label>${label}</label>${fieldHelp(help)}<input name="${name}" type="${type}" placeholder="${escapeHtml(placeholder)}" /></div>`;
}

function selectField(label, name, options, help = "") {
  return `
    <div class="field">
      <label>${label}</label>
      ${fieldHelp(help)}
      <select name="${name}">
        ${options.map((option) => `<option value="${escapeHtml(option)}">${escapeHtml(option || "Noch offen")}</option>`).join("")}
      </select>
    </div>
  `;
}

function frameworkSelectField(defaultValue = "ISO 27001 + NIS-2", help = "") {
  const options = [defaultValue, "ISO 27001", "NIS-2", "ISO 27001 + NIS-2", "Prüfen"]
    .filter((option, index, all) => all.indexOf(option) === index);
  return selectField("Zuordnung", "framework", options, help);
}

function renderRegisterScopeLegend() {
  return `
    <div class="register-scope-legend" aria-label="Zuordnung">
      <span class="scope-badge iso">ISO 27001</span>
      <span class="scope-badge nis">NIS-2</span>
      <span class="scope-badge shared">Beides</span>
    </div>
  `;
}

function templateField(field, initialData = {}) {
  const required = field.required ? "required" : "";
  const value = String(initialData[field.name] || "");
  const guidance = templateFieldGuidanceBlock(field);
  if (field.type === "textarea") {
    return `
      <div class="field full">
        <label>${escapeHtml(field.label)}${field.required ? " *" : ""}</label>
        ${guidance}
        <textarea name="${escapeHtml(field.name)}" placeholder="${escapeHtml(field.placeholder || "")}" ${required}>${escapeHtml(value)}</textarea>
      </div>
    `;
  }
  if (field.type === "select") {
    return `
      <div class="field">
        <label>${escapeHtml(field.label)}${field.required ? " *" : ""}</label>
        ${guidance}
        <select name="${escapeHtml(field.name)}" ${required}>
          ${(field.options || []).map((option) => `<option value="${escapeHtml(option)}" ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
        </select>
      </div>
    `;
  }
  return `
    <div class="field">
      <label>${escapeHtml(field.label)}${field.required ? " *" : ""}</label>
      ${guidance}
      <input name="${escapeHtml(field.name)}" type="${escapeHtml(field.type || "text")}" placeholder="${escapeHtml(field.placeholder || "")}" value="${escapeHtml(value)}" ${required} />
    </div>
  `;
}

function templateFieldGuidanceBlock(field = {}) {
  const guidance = templateFieldGuidance(field);
  if (!guidance.help && !guidance.example) return "";
  return `
    <div class="template-field-guidance">
      ${guidance.help ? `<span><strong>Was eintragen?</strong> ${escapeHtml(guidance.help)}</span>` : ""}
      ${guidance.example ? `<span><strong>Beispiel:</strong> ${escapeHtml(guidance.example)}</span>` : ""}
    </div>
  `;
}

function templateFieldGuidance(field = {}) {
  const name = String(field.name || "");
  const label = String(field.label || "Feld");
  const placeholder = String(field.placeholder || "");
  const normalized = normalizeImportKey(`${name} ${label}`);
  const defaults = {
    organization: ["Name der Organisation oder Einheit, für die die Arbeitsvorlage gilt.", "Muster GmbH"],
    title: ["Eindeutiger Dokument- oder Policy-Titel.", "Access Control Policy"],
    owner: ["Rolle oder Person, die fachlich verantwortlich ist und Reviews koordiniert.", "ISB / IT-Leitung"],
    responsible: ["Rolle oder Team, das die Umsetzung praktisch verantwortet.", "IT Security / Fachbereich"],
    review: ["Datum, an dem Inhalt, Status und Nachweise erneut geprüft werden sollen.", "2026-12-31"],
    evidence: ["Dokumente, Links, Register, Tickets oder Protokolle nennen, die als Nachweis dienen.", "Policy-Link, Ticket-ID, Auditbericht oder SharePoint-Pfad"],
    scope: ["Beschreiben, für wen, welche Standorte, Prozesse, Systeme oder Informationen die Vorlage gilt.", "Kundenportal, Microsoft 365, IT-Betrieb und Support am Standort Deutschland"],
    interfaces: ["Wichtige interne und externe Schnittstellen oder Abhängigkeiten nennen.", "Cloud-Provider, MSP, Datenschutzbeauftragter, zentrale Kunden"],
    exclusions: ["Bewusst ausgeschlossene Bereiche nennen und kurz begründen.", "Privatgeräte sind ausgeschlossen, weil sie nicht für Unternehmensdaten freigegeben sind."],
    purpose: ["Kurz beschreiben, warum das Dokument gebraucht wird und welches Ziel es hat.", "Regelt Mindestanforderungen für sichere Nutzung und Prüfung von Zugriffen."],
    requirements: ["Konkrete Mindestregeln oder Anforderungen aufnehmen, die später prüfbar sind.", "MFA für Admin-Konten, jährlicher Access Review, Protokollierung privilegierter Aktionen"],
    processsteps: ["Ablauf vom Auslöser bis zum Nachweis beschreiben.", "Antrag, Prüfung, Freigabe, Umsetzung, Dokumentation, Review"],
    responsibilities: ["Rollen, Mitwirkende, Freigabe- und Eskalationswege festhalten.", "Owner: ISB; Umsetzung: IT; Freigabe: Geschäftsleitung"],
    exceptions: ["Regeln für Abweichungen, Genehmigungen und spätere Überprüfung beschreiben.", "Ausnahme nur befristet, durch ISB genehmigt und mit Review-Datum versehen."],
    decision: ["Auswählen oder beschreiben, welche Entscheidung aktuell getroffen wurde.", "Freigeben mit Maßnahmen"],
    criticality: ["Einschätzen, wie wichtig der Dienst, Prozess oder Nachweis für Betrieb und Sicherheit ist.", "Hoch"],
    control: ["Clause, Annex-A-Control oder regulatorischen Bezug eintragen, sofern bekannt.", "A.5.19 oder Clause 6.1.3"],
    controlreference: ["Clause, Annex-A-Control, NIS-2-Paragraph oder internen Abschnitt eintragen.", "A.8.8 / §30 Abs. 2 Nr. 5"],
    implementation: ["Beschreiben, wie die Anforderung tatsächlich umgesetzt ist oder umgesetzt werden soll.", "Patch-Prozess monatlich, kritische Schwachstellen innerhalb von 7 Tagen."],
    reason: ["Kurz begründen, warum etwas anwendbar, nicht anwendbar oder noch zu prüfen ist.", "Control ist anwendbar, weil externe Dienstleister Zugriff auf Kundendaten haben."],
    service: ["Leistung oder Dienst nennen, die/der bewertet oder dokumentiert wird.", "Cloud-Hosting, SaaS, Managed Service Provider"],
    supplier: ["Name des Lieferanten oder Dienstleisters eintragen.", "Dienstleister GmbH"],
    party: ["Stakeholder oder Partei nennen, deren Erwartungen relevant sein können.", "Kunde, Behörde, Geschäftsleitung, Lieferant"],
    expectation: ["Erwartung, Verpflichtung oder Anforderung der Partei beschreiben.", "Vertraglich geforderte Informationssicherheitsnachweise jährlich bereitstellen."],
    source: ["Quelle der Anforderung oder des Nachweises nennen.", "Kundenvertrag, NIS-2-Dokument §30, interne Policy"],
    applicability: ["Status auswählen, ob die Anforderung aktuell relevant ist.", "Anwendbar"],
    summary: ["Sachverhalt kurz und verständlich beschreiben.", "Phishing-Mail wurde gemeldet, keine Zugangsdaten eingegeben."],
    impact: ["Mögliche oder tatsächliche Auswirkung auf Verfügbarkeit, Integrität oder Vertraulichkeit nennen.", "Kein Datenabfluss bekannt, betroffene Mailbox geprüft."],
    actions: ["Konkrete Maßnahmen, Owner und nächste Schritte festhalten.", "Passwort zurückgesetzt, IOC geprüft, Awareness-Hinweis versendet."],
    participants: ["Beteiligte Rollen oder Personen nennen.", "Geschäftsleitung, ISB, IT-Leitung, Datenschutz"],
    inputs: ["Grundlagen nennen, die in Review oder Bewertung einfließen.", "Risiken, Incidents, Audit-Findings, KPI, Maßnahmenstatus"],
    decisions: ["Beschlüsse und offene Entscheidungsbedarfe festhalten.", "Budget für MFA-Rollout freigegeben."],
    training: ["Schulungs- oder Awareness-Bezug beschreiben.", "Management-Briefing zu NIS-2 und Incident-Eskalation geplant."],
    audience: ["Zielgruppe der Kommunikation oder Policy nennen.", "Alle Mitarbeitenden, Admins, Lieferanten oder Management"],
    content: ["Kernaussage oder Inhalt der Kommunikation beschreiben.", "Neue Passwortregeln und Meldeweg für Sicherheitsereignisse"],
    channel: ["Kommunikationskanal oder Ablageort nennen.", "Intranet, E-Mail, Teams, SFM Compliance"],
    effectiveness: ["Wie geprüft wird, ob die Maßnahme angekommen oder wirksam ist.", "Teilnahmequote, Quiz, Feedback, Review-Ergebnis"],
    asset: ["Betroffenes Asset, System, Information oder Prozess nennen.", "ERP-System, Kundenportal, HR-Daten"],
    scenario: ["Bedrohung, Schwachstelle und mögliche Auswirkung als Szenario beschreiben.", "Ransomware verschlüsselt File-Server wegen fehlender Patch-Routine."],
    evaluation: ["Bewertung, Entscheidung oder weiteren Prüfbedarf knapp festhalten.", "Behandeln; Backup-Test und Patch-Frist priorisieren."],
    risk: ["Risiko oder Risikoreferenz nennen, auf die sich die Maßnahme bezieht.", "R-001 Ransomware auf kritischem Server"],
    measure: ["Konkrete Maßnahme beschreiben, nicht nur ein Schlagwort.", "EDR ausrollen, Backup testen, Admin-MFA verpflichtend machen."]
  };
  const exact = defaults[normalizeImportKey(name).replace(/-/g, "")] || defaults[normalizeImportKey(name)];
  if (exact) return { help: exact[0], example: exact[1] };
  if (field.type === "select") return { help: `Bitte den passenden Wert für "${label}" auswählen.`, example: (field.options || [])[0] || "" };
  if (placeholder && !placeholder.endsWith("?")) return { help: `Bitte "${label}" so konkret ausfüllen, dass ein Berater den Inhalt prüfen kann.`, example: placeholder.replace(/^z\.\s?B\.\s*/i, "").replace(/^Beispiel:\s*/i, "") };
  return { help: `Bitte "${label}" kurz, konkret und prüfbar beschreiben.`, example: "" };
}

function templateDefaultData(template) {
  if (!isPolicyLikeTemplate(template)) return {};
  const item = POLICY_PACKAGE.find((candidate) => candidate.templateId === template.id
    || normalizeImportKey(candidate.title) === normalizeImportKey(template.outputName || template.title));
  const review = futureDate(DOCUMENT_REVIEW_DAYS);
  const seed = item ? policyTemplateSeedData(item, template, review) : policyTemplateSeedData({
    id: template.id,
    title: template.outputName || template.title,
    owner: "ISB / Policy Owner",
    linkedTo: template.linkedTo || "",
    group: template.area || "Policy",
    source: "Lokale Arbeitsvorlagen-Bibliothek",
    purpose: template.purpose || ""
  }, template, review);
  return expandPolicyFieldDefaults(template, seed, item);
}

function expandPolicyFieldDefaults(template, data, item) {
  const preset = policyTextPreset({
    title: item?.title || template.outputName || template.title,
    linkedTo: item?.linkedTo || template.linkedTo || "",
    group: item?.group || template.area || "",
    purpose: item?.purpose || template.purpose || ""
  });
  const richDefaults = {
    purpose: preset.purpose,
    scope: preset.scope,
    principles: preset.requirements,
    requirements: preset.requirements,
    roles: preset.responsibilities,
    responsibilities: preset.responsibilities,
    joinerMoverLeaver: preset.processSteps,
    processSteps: preset.processSteps,
    evidence: preset.evidence,
    records: preset.evidence,
    storage: preset.evidence,
    logs: preset.evidence,
    exceptions: preset.exceptions,
    communication: preset.communication,
    content: preset.communication,
    audience: preset.communication,
    effectiveness: preset.effectiveness,
    evaluation: preset.effectiveness,
    decision: preset.effectiveness,
    approval: "Die Freigabe dieser Richtlinie erfolgt durch die benannte Freigaberolle. Vor Freigabe sind Geltungsbereich, Verantwortlichkeiten, Mindestregeln, Nachweise und bekannte Ausnahmen fachlich zu prüfen.",
    privileged: "Privilegierte Zugriffe werden nur nach fachlicher Freigabe eingerichtet. Sie sind getrennt von Standardbenutzerkonten zu behandeln, angemessen zu protokollieren und regelmäßig auf Notwendigkeit, Umfang und Missbrauchsrisiken zu prüfen.",
    access: preset.requirements,
    allowed: "Die Nutzung von Informationen, Geräten, Anwendungen und Diensten ist nur für freigegebene geschäftliche Zwecke zulässig. Nutzer müssen Informationen entsprechend Klassifizierung, Berechtigung und Schutzbedarf behandeln.",
    prohibited: "Nicht zulässig sind die Umgehung von Sicherheitsmaßnahmen, die unfreigegebene Weitergabe vertraulicher Informationen, private Schattenablagen sensibler Daten sowie jede Nutzung, die Vertraulichkeit, Integrität oder Verfügbarkeit gefährdet.",
    handling: preset.requirements,
    methods: preset.processSteps,
    monitoring: preset.effectiveness,
    remediation: preset.processSteps,
    secureDevelopment: preset.requirements,
    versioning: "Jede Änderung erhält eine nachvollziehbare Version, einen Owner, ein Freigabedatum, ein Review-Datum und eine kurze Änderungshistorie.",
    reviewCycle: "Jährlich",
    frequency: "Jährlich"
  };
  return { ...data, ...richDefaults };
}

function collectTemplateData(form) {
  const raw = Object.fromEntries(new FormData(form).entries());
  const data = {};
  Object.entries(raw).forEach(([key, value]) => {
    data[key] = String(value || "").trim();
  });
  return data;
}

function buildTemplateDocument(template, data) {
  data = data || {};
  if (isPolicyLikeTemplate(template)) {
    return buildFullPolicyDocument(template, data);
  }

  const lines = [
    `# ${template.outputName}`,
    "",
    `Template: ${template.title}`,
    `Typ: ${template.type}`,
    `Zuordnung: ${template.linkedTo}`,
    "",
    "## Zweck",
    template.purpose,
    "",
    "## Ausgefüllte Felder"
  ];

  template.fields.forEach((field) => {
    const value = data[field.name] || "[ausfüllen]";
    lines.push(`- ${field.label}: ${value}`);
  });

  appendInternalSources(lines, template.sources);

  lines.push("", "## Hinweis");
  lines.push("Dieser Entwurf ist eine praxisnahe Umsetzungshilfe auf Basis der hinterlegten Dokumente und muss fachlich freigegeben werden.");

  return lines.join("\n");
}

function templateCompletionStats(template = {}, data = {}) {
  const fields = Array.isArray(template.fields) ? template.fields : [];
  const required = fields.filter((field) => field.required);
  const filledRequired = required.filter((field) => String(data[field.name] || "").trim()).length;
  const filledTotal = fields.filter((field) => String(data[field.name] || "").trim()).length;
  const missing = required.filter((field) => !String(data[field.name] || "").trim());
  const complete = required.length === 0 || filledRequired >= required.length;
  return {
    total: fields.length,
    filledTotal,
    required: required.length,
    filledRequired,
    missing,
    complete,
    percent: percentOf(filledTotal, fields.length || 1)
  };
}

function renderTemplateCompletionCheck(template, data = {}) {
  const stats = templateCompletionStats(template, data);
  return `
    <section class="template-completion-check ${stats.complete ? "complete" : "missing"}" id="templateCompletionCheck" aria-live="polite">
      ${renderTemplateCompletionCheckContent(template, stats)}
    </section>
  `;
}

function renderTemplateCompletionCheckContent(template, stats) {
  const nextStep = stats.complete
    ? "Arbeitsvorlage speichern und anschließend in der Beraterprüfung fachlich prüfen lassen."
    : `${stats.missing.length} Pflichtangabe(n) ergänzen, bevor die Arbeitsvorlage formal vollständig ist.`;
  return `
    <div>
      <span class="eyebrow">Formaler Vorlagen-Check</span>
      <strong>${stats.complete ? "Formal vollständig" : "Pflichtangaben fehlen"}</strong>
      <p>${escapeHtml(nextStep)}</p>
    </div>
    <div class="template-completion-metrics">
      <span><b>${stats.filledRequired}/${stats.required || 0}</b> Pflichtfelder</span>
      <span><b>${stats.filledTotal}/${stats.total}</b> Felder gefüllt</span>
      <span><b>${stats.percent}%</b> ausgefüllt</span>
    </div>
    ${stats.missing.length ? `
      <div class="template-missing-fields">
        ${stats.missing.slice(0, 4).map((field) => `<span>${escapeHtml(field.label)}</span>`).join("")}
      </div>
      <button class="quiet-button compact-button" type="button" data-template-focus-missing>Erstes fehlendes Feld öffnen</button>
    ` : `
      <span class="template-completion-note">Hinweis: Das ist nur ein formaler Check. Fachliche Freigabe erfolgt durch Berater/Admin.</span>
    `}
  `;
}

function isPolicyLikeTemplate(template) {
  const text = `${template.id || ""} ${template.title || ""} ${template.outputName || ""} ${template.area || ""}`.toLowerCase();
  return template.area === "Policy"
    || text.includes("policy")
    || text.includes("procedure")
    || text.includes("richtlinie")
    || text.includes("prozessvorlage");
}

function buildFullPolicyDocument(template, data) {
  data = data || {};
  const preset = policyTextPreset({
    title: template.outputName || template.title,
    linkedTo: template.linkedTo || "",
    group: template.area || "",
    purpose: template.purpose || ""
  });
  const title = policyValue(data, ["title", "documentTitle"], template.outputName || template.title);
  const owner = policyValue(data, ["owner", "responsible"], "[ausfüllen]");
  const review = policyValue(data, ["review", "reviewCycle", "frequency"], "[ausfüllen]");
  const scope = policyValue(data, ["scope"], preset.scope);
  const purpose = policyValue(data, ["purpose", "manualPurpose"], preset.purpose);
  const requirements = policyValue(data, [
    "requirements",
    "principles",
    "allowed",
    "prohibited",
    "handling",
    "access",
    "sources",
    "methods",
    "secureDevelopment",
    "approval"
  ], preset.requirements);
  const processSteps = policyValue(data, [
    "processSteps",
    "joinerMoverLeaver",
    "change",
    "assessment",
    "remediation",
    "monitoring",
    "recovery",
    "test"
  ], preset.processSteps);
  const responsibilities = policyValue(data, ["responsibilities", "roles", "privileged"], preset.responsibilities);
  const evidence = policyValue(data, ["evidence", "records", "storage", "logs"], preset.evidence);
  const exceptions = policyValue(data, ["exceptions"], preset.exceptions);
  const communication = policyValue(data, ["communication", "content", "audience"], preset.communication);
  const effectiveness = policyValue(data, ["effectiveness", "evaluation", "decision", "result"], preset.effectiveness);
  const controlReference = policyValue(data, ["controlReference", "control"], template.linkedTo || "[ausfüllen]");
  const classification = policyValue(data, ["classification"], "Intern");
  const version = policyValue(data, ["version"], "0.1");
  const approver = policyValue(data, ["approver"], "Geschäftsleitung / zuständige Freigaberolle");

  const lines = [
    `# ${title}`,
    "",
    "## Dokumentensteuerung",
    `- Dokumenttyp: Policy / Prozessvorlage`,
    `- Status: Entwurf`,
    `- Version: ${version}`,
    `- Klassifizierung: ${classification}`,
    `- Owner: ${owner}`,
    `- Freigabe durch: ${approver}`,
    `- Review: ${review}`,
    `- Zuordnung: ${controlReference}`,
    "",
    "## 1. Zweck",
    purpose,
    "",
    "## 2. Geltungsbereich",
    scope,
    "",
    "## 3. Verbindlichkeit und Abgrenzung",
    "- MUSS: Verbindliche Vorgaben aus dieser Policy sind umzusetzen oder als Ausnahme zu dokumentieren.",
    "- SOLLTE: Empfohlene Umsetzungen sind zu berücksichtigen, wenn sie für Größe, Risiko und Betriebsmodell angemessen sind.",
    "- PRAXISNAHE UMSETZUNGSHILFE: Konkrete Verfahren, Nachweise und Arbeitsschritte können pragmatisch an die Organisation angepasst werden.",
    "- Diese Vorlage ersetzt keine fachliche Freigabe und keine rechtliche Bewertung.",
    "",
    "## 4. Rollen und Verantwortlichkeiten",
    responsibilities,
    "",
    "## 5. Anforderungen und Mindestregeln",
    requirements,
    "",
    "## 6. Umsetzung / Prozess",
    processSteps,
    "",
    "## 7. Nachweise und Aufzeichnungen",
    evidence,
    "",
    "## 8. Ausnahmen und Risikoakzeptanz",
    exceptions,
    "",
    "## 9. Kommunikation und Schulung",
    communication,
    "",
    "## 10. Review, Wirksamkeit und Verbesserung",
    effectiveness,
    "",
    "## 11. Ausgefüllte Felder"
  ];

  template.fields.forEach((field) => {
    const value = data[field.name] || "[ausfüllen]";
    lines.push(`- ${field.label}: ${value}`);
  });

  appendInternalSources(lines, template.sources, "## 12. Quellen");

  lines.push("", "## Hinweis");
  lines.push("Dieser Entwurf ist eine praxisnahe Umsetzungshilfe auf Basis der hinterlegten lokalen Dokumente und muss fachlich geprüft sowie freigegeben werden.");

  return lines.join("\n");
}

function buildPolicyPackageDocument(item, template, data) {
  const sources = Array.from(new Set([
    ...(template?.sources || []),
    item.source ? `[${item.source}]` : "",
    item.manualSection ? `[${item.source}, ${item.manualSection}]` : ""
  ].filter(Boolean)));
  return buildFullPolicyDocument({
    ...(template || {}),
    id: item.id,
    title: item.title,
    outputName: item.title,
    area: "Policy",
    type: template?.type || "ISO 27001",
    linkedTo: item.linkedTo,
    purpose: item.purpose,
    sources,
    fields: template?.fields || TEMPLATE_LIBRARY.find((candidate) => candidate.id === "policy-procedure")?.fields || [],
    sections: template?.sections || []
  }, data);
}

function policyValue(data, keys, fallback) {
  const value = keys.map((key) => data[key]).find((entry) => String(entry || "").trim());
  return String(value || fallback || "[ausfüllen]");
}

function updateTemplatePreview(form) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === form.dataset.templateForm);
  const preview = document.getElementById("templatePreview");
  if (!template || !preview) return;
  const data = collectTemplateData(form);
  preview.textContent = buildTemplateDocument(template, data);
  updateTemplateCompletionCheck(template, data);
}

function updateTemplateCompletionCheck(template, data) {
  const panel = document.getElementById("templateCompletionCheck");
  if (!panel) return;
  const stats = templateCompletionStats(template, data);
  panel.classList.toggle("complete", stats.complete);
  panel.classList.toggle("missing", !stats.complete);
  panel.innerHTML = renderTemplateCompletionCheckContent(template, stats);
}

function focusFirstMissingTemplateField() {
  const form = appView.querySelector("[data-template-form]");
  const template = TEMPLATE_LIBRARY.find((item) => item.id === form?.dataset.templateForm);
  if (!form || !template) return;
  const data = collectTemplateData(form);
  const missing = templateCompletionStats(template, data).missing[0];
  if (!missing) return;
  const field = form.querySelector(`[name="${CSS.escape(missing.name)}"]`);
  if (!field) return;
  field.scrollIntoView({ behavior: "smooth", block: "center" });
  field.focus();
}

