      showToast(`Arbeitsunterlagen erstellt: ${created.documents} Dokumente, ${created.templateDrafts} Arbeitsvorlagen, ${created.assets} Assets, ${created.risks} Risiken, ${policyItems} Policy-Einträge.`);
