function documentUploadContextFromElement(element) {
  const container = element?.closest?.("[data-document-upload-context]");
  if (!container) return {};
  const value = (name) => String(container.querySelector(`[name="${name}"]`)?.value || "").trim();
  return {
    area: value("area") || "Dokumentation",
    owner: value("owner") || "Offen",
    linkedTo: value("linkedTo"),
    evidenceFor: value("linkedTo"),
    classification: value("classification") || "Intern",
    review: value("review") || futureDate(DOCUMENT_REVIEW_DAYS),
    status: container.dataset.uploadStatus || "In Prüfung",
    approval: container.dataset.uploadApproval || "Prüfung läuft",
    note: container.dataset.uploadNote || (value("linkedTo") ? `Upload-Zuordnung: ${value("linkedTo")}` : "Upload über Dokumenten-Center")
  };
}

function prepareProjectDocumentUpload(projectId) {
  const context = projectEvidenceContext(projectId);
  if (!context.linkedTo && !context.note) return;
  pendingDocumentUploadContext = {
    ...context,
    area: inferDocumentArea(context.area || context.linkedTo),
    review: context.review || futureDate(DOCUMENT_REVIEW_DAYS),
    classification: context.classification || "Intern"
  };
  if (currentView === "documents") {
    applyPendingDocumentUploadContext();
  } else {
    navigateToView("documents");
  }
}

function applyPendingDocumentUploadContext() {
  if (currentView !== "documents" || !pendingDocumentUploadContext) return;
  const context = pendingDocumentUploadContext;
  pendingDocumentUploadContext = null;
  fillDocumentUploadContext(context);
  showToast("Upload-Zuordnung vorbereitet.");
}

function setDocumentUploadContext(ref, area = "") {
  const container = appView.querySelector("[data-document-upload-context]");
  if (!container) {
    pendingDocumentUploadContext = {
      linkedTo: ref || "",
      area: inferDocumentArea(area || ref),
      owner: "Offen",
      review: futureDate(DOCUMENT_REVIEW_DAYS),
      classification: "Intern"
    };
    navigateToView("documents");
    return;
  }
  fillDocumentUploadContext({
    linkedTo: ref || "",
    area: inferDocumentArea(area || ref),
    owner: "Offen",
    review: futureDate(DOCUMENT_REVIEW_DAYS),
    classification: "Intern"
  });
  container.scrollIntoView({ behavior: "smooth", block: "center" });
  showToast("Upload-Zuordnung vorbereitet.");
}

function fillDocumentUploadContext(context = {}) {
  const container = appView.querySelector("[data-document-upload-context]");
  if (!container) return false;
  const setValue = (name, value) => {
    const fieldElement = container.querySelector(`[name="${name}"]`);
    if (!fieldElement || value === undefined || value === null) return;
    if (fieldElement.tagName === "SELECT") {
      const values = [...fieldElement.options].map((option) => option.value);
      fieldElement.value = values.includes(value) ? value : inferDocumentArea(value);
    } else {
      fieldElement.value = value;
    }
  };
  setValue("area", context.area || inferDocumentArea(context.linkedTo || context.note));
  setValue("owner", context.owner || "Offen");
  setValue("linkedTo", context.linkedTo || context.evidenceFor || "");
  setValue("classification", context.classification || "Intern");
  setValue("review", context.review || futureDate(DOCUMENT_REVIEW_DAYS));
  container.dataset.uploadNote = context.note || "";
  container.dataset.uploadStatus = context.status || "In Prüfung";
  container.dataset.uploadApproval = context.approval || "Prüfung läuft";
  container.scrollIntoView({ behavior: "smooth", block: "center" });
  return true;
}

function inferDocumentArea(value) {
  const text = String(value || "").toLowerCase();
  if (text.includes("soc") || text.includes("siem") || text.includes("security operations")) return "SOC/SIEM";
  if (text.includes("capa") || text.includes("korrektur") || text.includes("audit")) return "Audit";
  if (text.includes("nis")) return "NIS-2";
  if (text.includes("risk") || text.includes("risiko")) return "Risk";
  if (text.includes("policy")) return "Policy";
  if (text.includes("liefer") || text.includes("vendor")) return "Lieferanten";
  if (text.includes("projekt")) return "Projektstrukturplan";
  return "ISO 27001";
}

function applyRoleModeToView() {
  if (canEditWorkspace()) return;
  const role = backendSessionUser?.role || "viewer";
  const documentSubmissionAllowed = currentView === "documents" && canSubmitDocuments();
  const banner = document.createElement("section");
  banner.className = "panel role-banner";
  banner.innerHTML = `
    <div>
      <span class="eyebrow">${documentSubmissionAllowed ? "Kundenzugriff" : "Kunden-/Auditansicht"}</span>
      <h3>${documentSubmissionAllowed ? "Nachweise einreichen" : "Nur Lesen"}</h3>
      <p>Angemeldet als <strong>${escapeHtml(backendSessionUser?.username || "Benutzer")}</strong> mit Rolle <strong>${escapeHtml(role)}</strong>. ${documentSubmissionAllowed ? "Du kannst Nachweise einreichen und die Historie ansehen. Freigaben, Reviews, Löschungen und administrative Änderungen bleiben bei berechtigten Rollen." : "Du kannst Inhalte prüfen und exportieren. Änderungen, Uploads, Löschungen, Beratergenerator und Betriebsverwaltung benötigen zusätzliche Rechte."}</p>
    </div>
  `;
  appView.prepend(banner);

  appView.querySelectorAll([
    "form[data-form] input",
    "form[data-form] select",
    "form[data-form] textarea",
    "form[data-form] button",
    "form[data-template-form] input",
    "form[data-template-form] select",
    "form[data-template-form] textarea",
    "form[data-template-form] button[type='submit']",
    "form[data-template-draft-editor] input",
    "form[data-template-draft-editor] select",
    "form[data-template-draft-editor] textarea",
    "form[data-template-draft-editor] button[type='submit']",
    "[data-template-draft-version]",
    "input[type='file']",
    "[data-delete]",
    "[data-project-owner]",
    "[data-project-due]",
    "[data-project-status]",
    "[data-project-save]",
    "[data-project-status-choice]",
    "[data-project-task]",
    "[data-project-task-pack]",
    "[data-production-task-pack]",
    "[data-integration-status]",
    "[data-integration-task]",
    "[data-integration-pack]",
    "[data-audit-execution-report]",
    "[data-audit-execution-tasks]",
    "[data-audit-finding-create]",
    "[data-audit-finding-field]",
    "[data-audit-finding-delete]",
    "[data-document-field]",
    "[data-document-save]",
    "[data-document-approve]",
    "[data-document-rework]",
    "[data-document-review]"
  ].join(",")).forEach((node) => {
    node.disabled = true;
    node.setAttribute("aria-disabled", "true");
  });

  if (documentSubmissionAllowed) {
    appView.querySelectorAll("form[data-form='manual-document'] input, form[data-form='manual-document'] select, form[data-form='manual-document'] textarea, form[data-form='manual-document'] button, form[data-form='soc-report'] input, form[data-form='soc-report'] select, form[data-form='soc-report'] textarea, form[data-form='soc-report'] button, #documentsUpload, #socReportUpload, [data-document-submit], [data-document-version-upload]").forEach((node) => {
      node.disabled = false;
      node.removeAttribute("aria-disabled");
    });
  }

  appView.querySelectorAll("[data-dropzone]").forEach((zone) => {
    if (documentSubmissionAllowed && zone.querySelector("#documentsUpload")) return;
    if (documentSubmissionAllowed && zone.querySelector("#socReportUpload")) return;
    zone.classList.add("disabled");
  });
}

function collectDocumentWorkflowValues(row) {
  const data = {};
  row?.querySelectorAll("[data-document-field]").forEach((fieldElement) => {
    data[fieldElement.dataset.documentField] = String(fieldElement.value || "").trim();
  });
  data.evidenceFor = data.linkedTo || "";
  return data;
}

	function addDocumentHistory(document, action, note = "", options = {}) {
	  const history = Array.isArray(document.workflowHistory) ? document.workflowHistory : [];
	  document.workflowHistory = [{
	    date: today(),
	    dateTime: auditTimestamp(),
	    action,
	    by: workflowActor(),
	    note
	  }, ...history].slice(0, 40);
	  if (!options.silent) {
	    recordAuditTrailEvent({
	      action,
	      entityType: "Nachweis",
	      entityId: document.id || "",
	      entityTitle: document.name || "Dokument",
	      module: document.area || "Dokumentation",
	      status: document.status || document.approval || "",
	      note,
	      metadata: {
	        version: document.version || "",
	        linkedTo: document.linkedTo || document.evidenceFor || "",
	        approval: document.approval || ""
	      }
	    });
	  }
	}

	function auditTimestamp() {
	  return new Date().toISOString();
	}

	function workflowActorRole() {
	  return backendSessionUser?.role || (backendSessionUser ? "user" : "local");
	}

	function recordAuditTrailEvent(event = {}) {
	  if (!state || !Array.isArray(state.auditTrail)) return;
	  state.auditTrail = [{
	    id: event.id || crypto.randomUUID(),
	    date: event.date || today(),
	    dateTime: event.dateTime || auditTimestamp(),
	    by: event.by || workflowActor(),
	    role: event.role || workflowActorRole(),
	    action: event.action || "Aktualisiert",
	    entityType: event.entityType || "Workspace",
	    entityId: event.entityId || "",
	    entityTitle: event.entityTitle || "",
	    module: event.module || "",
	    status: event.status || "",
	    note: event.note || "",
	    source: event.source || "local",
	    metadata: event.metadata && typeof event.metadata === "object" ? event.metadata : {}
	  }, ...state.auditTrail].slice(0, 500);
	}

	function normalizeVersionChanges(changes) {
	  return (Array.isArray(changes) ? changes : [])
	    .filter(Boolean)
	    .map((change) => ({
	      field: change.field || "",
	      label: change.label || change.field || "Feld",
	      before: normalizeChangeValue(change.before),
	      after: normalizeChangeValue(change.after)
	    }))
	    .filter((change) => change.label && change.before !== change.after)
	    .slice(0, 16);
	}

	function normalizeChangeValue(value) {
	  if (value === undefined || value === null || value === "") return "leer";
	  if (Array.isArray(value)) return value.map(normalizeChangeValue).join(", ");
	  if (typeof value === "object") {
	    try {
	      return JSON.stringify(value);
	    } catch {
	      return String(value);
	    }
	  }
	  const text = String(value).trim();
	  if (!text) return "leer";
	  return text.length > 180 ? `${text.slice(0, 177)}...` : text;
	}

	function buildVersionChanges(previous = {}, current = {}, fields = []) {
	  return normalizeVersionChanges(fields.map((field) => {
	    const before = field.before ? field.before(previous, current) : previous[field.key];
	    const after = field.after ? field.after(current, previous) : current[field.key];
	    return {
	      field: field.key,
	      label: field.label,
	      before,
	      after
	    };
	  }));
	}

	function documentVersionChanges(document = {}, previous = {}) {
	  return buildVersionChanges(previous, document, [
	    { key: "name", label: "Titel" },
	    { key: "area", label: "Bereich" },
	    { key: "status", label: "Status" },
	    { key: "approval", label: "Freigabe" },
	    { key: "reviewStatus", label: "Review-Status" },
	    { key: "owner", label: "Owner" },
	    { key: "review", label: "Review-Datum" },
	    { key: "version", label: "Version" },
	    { key: "classification", label: "Klassifizierung" },
	    { key: "linkedTo", label: "Zuordnung", after: (current) => current.linkedTo || current.evidenceFor },
	    { key: "fileId", label: "Datei-ID" },
	    { key: "sha256", label: "Datei-Hash" }
	  ]);
	}

	function policyVersionChanges(policy = {}, previous = {}) {
	  return buildVersionChanges(previous, policy, [
	    { key: "title", label: "Policy" },
	    { key: "owner", label: "Owner" },
	    { key: "version", label: "Version" },
	    { key: "status", label: "Status" },
	    { key: "reviewStatus", label: "Review-Status" },
	    { key: "review", label: "Review-Datum" },
	    { key: "priority", label: "Priorität" },
	    { key: "linkedTo", label: "Zuordnung" },
	    { key: "scope", label: "Geltungsbereich" },
	    { key: "note", label: "Notiz" }
	  ]);
	}

	function templateDraftVersionChanges(draft = {}, previous = {}) {
	  return buildVersionChanges(previous, draft, [
	    { key: "title", label: "Titel" },
	    { key: "templateTitle", label: "Vorlage" },
	    { key: "owner", label: "Owner" },
	    { key: "version", label: "Version", after: (current) => current.version || current.data?.version },
	    { key: "status", label: "Status" },
	    { key: "review", label: "Review-Datum" },
	    { key: "linkedTo", label: "Zuordnung" },
	    {
	      key: "content",
	      label: "Textumfang",
	      before: (previousValue) => `${String(previousValue.content || "").length} Zeichen`,
	      after: (current) => `${String(current.content || "").length} Zeichen`
	    }
	  ]);
	}

	function documentVersionSnapshot(document = {}, previous = {}) {
	  return {
	    id: crypto.randomUUID(),
	    date: today(),
	    dateTime: auditTimestamp(),
	    by: workflowActor(),
	    action: "",
	    version: document.version || "",
	    previousVersion: previous.version || "",
	    status: document.status || "",
	    previousStatus: previous.status || "",
	    approval: document.approval || "",
	    review: document.review || "",
	    linkedTo: document.linkedTo || document.evidenceFor || "",
	    fileId: document.fileId || "",
	    previousFileId: previous.fileId || document.previousFileId || "",
	    sha256: document.sha256 || "",
	    note: document.note || "",
	    snapshot: {
	      name: document.name || "",
	      area: document.area || "",
	      owner: document.owner || "",
	      classification: document.classification || "",
	      evidenceFor: document.evidenceFor || document.linkedTo || ""
	    }
	  };
	}

	function addDocumentVersionHistory(document, action, previous = {}, note = "") {
	  if (!document || document.status === "Quelle") return;
	  const history = Array.isArray(document.versionHistory) ? document.versionHistory : [];
	  const snapshot = {
	    ...documentVersionSnapshot(document, previous),
	    action,
	    note: note || document.note || "",
	    changes: documentVersionChanges(document, previous)
	  };
	  document.versionHistory = [snapshot, ...history].slice(0, 40);
	  recordAuditTrailEvent({
	    action,
	    entityType: "Nachweis-Version",
	    entityId: document.id || "",
	    entityTitle: document.name || "Dokument",
	    module: document.area || "Dokumentation",
	    status: document.status || "",
	    note: note || `Version ${document.version || "-"} protokolliert.`,
	    metadata: {
	      version: document.version || "",
	      previousVersion: previous.version || "",
	      fileId: document.fileId || "",
	      previousFileId: previous.fileId || "",
	      changedFields: snapshot.changes.map((change) => change.label).join(", ")
	    }
	  });
	}

	function policyVersionSnapshot(policy = {}, previous = {}) {
	  return {
	    id: crypto.randomUUID(),
	    date: today(),
	    dateTime: auditTimestamp(),
	    by: workflowActor(),
	    action: "",
	    version: policy.version || "",
	    previousVersion: previous.version || "",
	    status: policy.status || "",
	    previousStatus: previous.status || "",
	    approval: policy.approval || "",
	    review: policy.review || "",
	    linkedTo: policy.linkedTo || "",
	    note: policy.note || "",
	    snapshot: {
	      title: policy.title || "",
	      owner: policy.owner || "",
	      priority: policy.priority || "",
	      scope: policy.scope || "",
	      group: policy.group || "",
	      source: policy.source || ""
	    }
	  };
	}

	function addPolicyHistory(policy, action, note = "", previous = {}) {
	  if (!policy) return;
	  const history = Array.isArray(policy.workflowHistory) ? policy.workflowHistory : [];
	  policy.workflowHistory = [{
	    date: today(),
	    dateTime: auditTimestamp(),
	    action,
	    by: workflowActor(),
	    note
	  }, ...history].slice(0, 40);
	  recordAuditTrailEvent({
	    action,
	    entityType: "Policy",
	    entityId: policy.id || "",
	    entityTitle: policy.title || "Policy",
	    module: "Policy Management",
	    status: policy.status || policy.reviewStatus || "",
	    note,
	    metadata: {
	      version: policy.version || "",
	      previousVersion: previous.version || "",
	      linkedTo: policy.linkedTo || ""
	    }
	  });
	}

	function addPolicyVersionHistory(policy, action, previous = {}, note = "") {
	  if (!policy) return;
	  const history = Array.isArray(policy.versionHistory) ? policy.versionHistory : [];
	  const snapshot = {
	    ...policyVersionSnapshot(policy, previous),
	    action,
	    note: note || policy.note || "",
	    changes: policyVersionChanges(policy, previous)
	  };
	  policy.versionHistory = [snapshot, ...history].slice(0, 40);
	  recordAuditTrailEvent({
	    action,
	    entityType: "Policy-Version",
	    entityId: policy.id || "",
	    entityTitle: policy.title || "Policy",
	    module: "Policy Management",
	    status: policy.status || "",
	    note: note || `Policy-Version ${policy.version || "-"} protokolliert.`,
	    metadata: {
	      version: policy.version || "",
	      previousVersion: previous.version || "",
	      linkedTo: policy.linkedTo || "",
	      changedFields: snapshot.changes.map((change) => change.label).join(", ")
	    }
	  });
	}

	function addTemplateDraftVersionHistory(draft, action, previous = {}, note = "") {
	  if (!draft) return;
	  const history = Array.isArray(draft.versionHistory) ? draft.versionHistory : [];
	  const content = String(draft.content || "");
	  const changes = templateDraftVersionChanges(draft, previous);
	  draft.versionHistory = [{
	    id: crypto.randomUUID(),
	    date: today(),
	    dateTime: auditTimestamp(),
	    by: workflowActor(),
	    action,
	    version: draft.version || draft.data?.version || "",
	    previousVersion: previous.version || "",
	    status: draft.status || "",
	    previousStatus: previous.status || "",
	    review: draft.review || "",
	    linkedTo: draft.linkedTo || "",
	    note,
	    changes,
	    snapshot: {
	      title: draft.title || "",
	      templateTitle: draft.templateTitle || "",
	      owner: draft.owner || "",
	      contentLength: content.length,
	      content: content.slice(0, 40000)
	    }
	  }, ...history].slice(0, 40);
	  recordAuditTrailEvent({
	    action,
	    entityType: templateDraftAuditEntityType(draft, "-Version"),
	    entityId: draft.id || "",
	    entityTitle: draft.title || draft.templateTitle || "Arbeitsvorlage",
	    module: "Arbeitsvorlagen",
	    status: draft.status || "",
	    note: note || `Entwurfsversion ${draft.version || draft.data?.version || "-"} protokolliert.`,
	    metadata: {
	      version: draft.version || draft.data?.version || "",
	      previousVersion: previous.version || "",
	      linkedTo: draft.linkedTo || "",
	      contentLength: content.length,
	      changedFields: changes.map((change) => change.label).join(", ")
	    }
	  });
	}

	function compactRecordSnapshot(record = {}, keys = []) {
	  return Object.fromEntries(keys.map((key) => [key, record[key] || ""]));
	}

	function importantDocumentFieldsChanged(previous = {}, current = {}) {
	  return ["name", "area", "status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "classification", "fileId", "sha256"]
	    .some((key) => String(previous[key] || "") !== String(current[key] || ""));
	}

	function importantPolicyFieldsChanged(previous = {}, current = {}) {
	  return ["title", "owner", "version", "status", "review", "priority", "linkedTo", "scope", "note"]
	    .some((key) => String(previous[key] || "") !== String(current[key] || ""));
	}

	function workflowActor() {
	  return backendSessionUser?.username || "SFM Compliance";
	}

function saveDocumentWorkflow(id, row) {
  if (!canReviewDocuments()) {
    showPermissionToast("Dokumenten-Workflows speichern", "Reviewer-, Manager- oder Admin-Rechten");
    return;
  }
	  const document = state.documents.find((item) => item.id === id);
	  if (!document || document.status === "Quelle") return;
	  const previous = compactRecordSnapshot(document, ["name", "area", "status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "classification", "fileId", "sha256"]);
	  Object.assign(document, normalizeDocumentRecord({ ...document, ...collectDocumentWorkflowValues(row) }));
	  addDocumentHistory(document, "Workflow aktualisiert", "Version, Status, Freigabe, Owner, Review oder Zuordnung wurden gespeichert.");
	  if (importantDocumentFieldsChanged(previous, document)) {
	    addDocumentVersionHistory(document, "Dokumenten-Metadaten geändert", previous, "Metadatenstand nach Workflow-Speicherung protokolliert.");
	  }
	  selectedDocumentId = id;
  saveState();
  showToast("Dokumenten-Workflow gespeichert.");
  render();
}

function submitDocumentForReview(id) {
  if (!canSubmitDocuments()) {
    showPermissionToast("Dokumente einreichen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
	  const document = state.documents.find((item) => item.id === id);
	  if (!document || document.status === "Quelle" || ["Freigegeben", "Archiviert"].includes(document.status)) return;
	  const previous = compactRecordSnapshot(document, ["status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "fileId", "sha256"]);
	  const wasRework = document.reviewStatus === "nacharbeit_noetig" || document.status === "Überarbeiten" || document.approval === "Abgelehnt" || Boolean(document.reworkReason);
  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "In Prüfung",
    approval: "Prüfung läuft",
    reviewStatus: "vom_kunden_eingereicht",
    submittedAt: today(),
    submittedBy: document.submittedBy || workflowActor(),
    resubmittedAfterReworkAt: wasRework ? today() : (document.resubmittedAfterReworkAt || ""),
    resubmissionCount: wasRework ? Number(document.resubmissionCount || 0) + 1 : Number(document.resubmissionCount || 0),
    customerComment: "",
    reworkReason: "",
    reworkDue: "",
    reworkMissing: "",
    reworkWhy: "",
    reworkAction: "",
    reworkReference: ""
  }));
	  addDocumentHistory(document, wasRework ? "Nacharbeit erneut eingereicht" : "Zur Prüfung eingereicht", wasRework ? "Nachweis wurde nach Kunden-Nacharbeit erneut zur Beraterprüfung eingereicht." : "Nachweis wurde für Berater-/Managerprüfung eingereicht.");
	  addDocumentVersionHistory(document, wasRework ? "Nachweis erneut eingereicht" : "Nachweis eingereicht", previous, "Einreichungsstand dokumentiert.");
  if (wasRework) {
    addReviewHistoryEntry(document, {
      action: reviewDecisionLabel("resubmit"),
      status: reviewStatusLabel("vom_kunden_eingereicht"),
      type: "Nachweis",
      title: document.name || "Nachweis",
      customerComment: "Kunde hat die Nacharbeit erneut eingereicht.",
      note: "Wartet wieder auf Beraterprüfung."
    });
  }
  completeDocumentWorkflowTasksByType(document, ["rework"], "Nacharbeit erneut eingereicht.");
  upsertDocumentWorkflowTask(document, "review");
  selectedDocumentId = id;
  saveState();
  showToast("Dokument zur Prüfung eingereicht.");
  render();
}

function approveDocumentWorkflow(id) {
  if (!canReviewDocuments()) {
    showPermissionToast("Dokumente freigeben", "Reviewer-, Manager- oder Admin-Rechten");
    return;
  }
	  const document = state.documents.find((item) => item.id === id);
	  if (!document || document.status === "Quelle") return;
	  const previous = compactRecordSnapshot(document, ["status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "fileId", "sha256"]);
	  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "Freigegeben",
    approval: "Freigegeben",
    reviewStatus: "freigegeben",
    version: approvedDocumentVersion(document.version),
    review: document.review || futureDate(DOCUMENT_REVIEW_DAYS),
    approvedAt: today(),
    approvedBy: workflowActor(),
    reworkReason: "",
    reworkDue: ""
  }));
	  addDocumentHistory(document, "Freigegeben", "Dokument wurde fachlich freigegeben.");
	  addDocumentVersionHistory(document, "Freigabestand protokolliert", previous, "Fachliche Dokumentenfreigabe durch Berater/Admin.");
  completeDocumentWorkflowTasks(document, "Dokumentenprüfung abgeschlossen.");
  selectedDocumentId = id;
  saveState();
  showToast("Dokument freigegeben.");
  render();
}

function requestDocumentRework(id, scope) {
  if (!canReviewDocuments()) {
    showPermissionToast("Nachbesserungen anfordern", "Reviewer-, Manager- oder Admin-Rechten");
    return;
  }
	  const document = state.documents.find((item) => item.id === id);
	  if (!document || document.status === "Quelle" || document.status === "Archiviert") return;
	  const previous = compactRecordSnapshot(document, ["status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "fileId", "sha256"]);
	  const reworkReason = collectDocumentReworkReason(scope, document);
  if (!reworkReason) {
    selectedDocumentId = id;
    showToast("Bitte zuerst einen Nachbesserungshinweis für den Kunden eintragen.");
    return;
  }
  const guidance = reviewReworkGuidance({
    rawType: "document",
    type: "Nachweis",
    title: document.name,
    reason: reworkReason,
    linkedEvidence: document.evidenceFor || document.linkedTo || document.name
  }, reworkReason);
  Object.assign(document, normalizeDocumentRecord({
    ...document,
    status: "Überarbeiten",
    approval: "Abgelehnt",
    reviewStatus: "nacharbeit_noetig",
    customerComment: reworkReason,
    reworkMissing: guidance.missing,
    reworkWhy: guidance.why,
    reworkAction: guidance.action,
    reworkReference: guidance.reference,
    reworkRequestedAt: today(),
    reworkRequestedBy: workflowActor(),
    reworkReason,
    reworkDue: futureDate(DOCUMENT_REWORK_DAYS)
  }));
	  addDocumentHistory(document, "Nachbesserung angefordert", reworkReason);
	  addDocumentVersionHistory(document, "Nachbesserung protokolliert", previous, "Nachweis wurde an den Kunden zurückgegeben.");
  upsertDocumentWorkflowTask(document, "rework");
  selectedDocumentId = id;
  saveState();
  showToast("Nachbesserung angefordert.");
  render();
}

function collectDocumentReworkReason(scope, document) {
  const note = scope?.querySelector("[data-document-rework-note]");
  return String(note?.value || document?.reworkReason || "").trim();
}

function scheduleDocumentReview(id) {
  if (!canReviewDocuments()) {
    showPermissionToast("Review-Termine setzen", "Reviewer-, Manager- oder Admin-Rechten");
    return;
  }
	  const document = state.documents.find((item) => item.id === id);
	  if (!document || document.status === "Quelle") return;
	  const previous = compactRecordSnapshot(document, ["status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "fileId", "sha256"]);
	  Object.assign(document, normalizeDocumentRecord({
    ...document,
    review: futureDate(DOCUMENT_REVIEW_DAYS)
  }));
	  addDocumentHistory(document, "Review terminiert", `Nächstes Review auf ${document.review} gesetzt.`);
	  addDocumentVersionHistory(document, "Review-Datum geändert", previous, `Nächstes Review auf ${document.review} gesetzt.`);
  selectedDocumentId = id;
  saveState();
  showToast("Review-Datum aktualisiert.");
  render();
}

async function saveReviewPlanning(button) {
  if (!canReviewDocuments()) {
    showPermissionToast("Review-Planung speichern", "Berater-, Reviewer- oder Admin-Rechten");
    return;
  }
  const key = button?.dataset.reviewPlanningSave || selectedReviewItemKey;
  const scope = button?.closest("[data-review-detail]");
  const record = reviewRecordByKey(key);
  const item = reviewCenterItems().find((candidate) => candidate.key === key);
  if (!record || !item || !scope) {
    showToast("Review-Planung konnte nicht gespeichert werden.", "warning");
    return;
  }

  const assignee = String(scope.querySelector("[data-review-assignee]")?.value || "").trim();
  const rawDue = String(scope.querySelector("[data-review-due]")?.value || "").trim();
  const due = rawDue ? reviewSafeDate(rawDue) : "";
  if (rawDue && !due) {
    showToast("Bitte ein gültiges Review-Datum auswählen.", "warning");
    return;
  }

  const previousAssignee = String(record.reviewAssignee || record.reviewer || "").trim();
  const previousDue = reviewSafeDate(record.reviewDue || record.reworkDue || "");
  if (item.rawType === "managementReview" && recordMutationApiEnabled()) {
    const saved = await updateManagementReviewViaApi({ reviewAssignee: assignee, reviewDue: due });
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast(assignee || due ? "Review-Planung gespeichert." : "Review-Zuordnung entfernt.");
    render();
    return;
  }
  if (item.rawType === "internalAuditPlan" && recordMutationApiEnabled()) {
    const saved = await updateInternalAuditPlanViaApi({ reviewAssignee: assignee, reviewDue: due });
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast(assignee || due ? "Review-Planung gespeichert." : "Review-Zuordnung entfernt.");
    render();
    return;
  }
  record.reviewAssignee = assignee;
  record.reviewDue = due;
  record.reviewUpdatedAt = today();
  const note = [
    `Prüfer: ${previousAssignee || "offen"} → ${assignee || "offen"}`,
    `Termin: ${previousDue || "offen"} → ${due || "offen"}`
  ].join(" · ");
  addReviewHistoryEntry(record, {
    action: "Review geplant",
    status: reviewStatusLabel(record.reviewStatus),
    type: item.type,
    title: item.title,
    internalComment: note,
    note: "Interne Review-Zuordnung aktualisiert."
  });
  selectedReviewItemKey = key;
  saveState({ immediate: true });
  showToast(assignee || due ? "Review-Planung gespeichert." : "Review-Zuordnung entfernt.");
  render();
}

async function saveReviewCommentDrafts(button) {
  if (!canReviewDocuments()) {
    showPermissionToast("Review-Kommentare speichern", "Berater-, Reviewer- oder Admin-Rechten");
    return;
  }
  const key = button?.dataset.reviewCommentsSave || selectedReviewItemKey;
  const scope = button?.closest("[data-review-detail]");
  const record = reviewRecordByKey(key);
  const item = reviewCenterItems().find((candidate) => candidate.key === key);
  if (!record || !item || !scope) {
    showToast("Kommentarentwurf konnte nicht gespeichert werden.", "warning");
    return;
  }

  const internalComment = String(scope.querySelector("[data-review-internal-comment]")?.value || "").trim();
  const customerCommentDraft = String(scope.querySelector("[data-review-customer-comment]")?.value || "").trim();
  const unchanged = internalComment === String(record.consultantInternalComment || "").trim()
    && customerCommentDraft === String(record.customerCommentDraft || record.customerComment || record.reworkReason || "").trim();
  if (unchanged) {
    showToast("Keine neuen Kommentaränderungen vorhanden.");
    return;
  }

  if (item.rawType === "managementReview" && recordMutationApiEnabled()) {
    const saved = await updateManagementReviewViaApi({
      consultantInternalComment: internalComment,
      customerComment: customerCommentDraft
    });
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast("Kommentarentwürfe gespeichert. Prüfstatus bleibt unverändert.");
    render();
    return;
  }
  if (item.rawType === "internalAuditPlan" && recordMutationApiEnabled()) {
    const saved = await updateInternalAuditPlanViaApi({
      consultantInternalComment: internalComment,
      customerComment: customerCommentDraft
    });
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast("Kommentarentwürfe gespeichert. Prüfstatus bleibt unverändert.");
    render();
    return;
  }

  record.consultantInternalComment = internalComment;
  record.customerCommentDraft = customerCommentDraft;
  record.reviewUpdatedAt = today();
  addReviewHistoryEntry(record, {
    action: "Kommentarentwurf gespeichert",
    status: reviewStatusLabel(record.reviewStatus),
    type: item.type,
    title: item.title,
    internalComment: internalComment ? "Interner Beraterkommentar aktualisiert." : "Interner Beraterkommentar geleert.",
    note: customerCommentDraft ? "Kundenkommentar als Entwurf gespeichert; noch nicht versendet." : "Kein Kundenkommentar-Entwurf vorhanden."
  });
  selectedReviewItemKey = key;
  saveState({ immediate: true });
  showToast("Kommentarentwürfe gespeichert. Prüfstatus bleibt unverändert.");
  render();
}

function handleReviewDecisionClick(button) {
  const key = button?.dataset.reviewKey || selectedReviewItemKey;
  const decision = button?.dataset.reviewDecision || "";
  const scope = button?.closest("[data-review-detail], [data-review-item]");
  if (reviewDecisionNeedsDetailConfirmation(decision, scope)) {
    openReviewDetailForDecision(key, decision);
    return;
  }
  updateReviewItemDecision(key, decision, scope);
}

function reviewDecisionNeedsDetailConfirmation(decision, scope) {
  const fromDetailPanel = Boolean(scope?.matches("[data-review-detail]"));
  return !fromDetailPanel && ["approve", "rework", "reject", "audit"].includes(decision);
}

function openReviewDetailForDecision(key, decision) {
  if (!key) {
    showToast("Bitte zuerst einen Prüfeintrag auswählen.", "warning");
    return;
  }
  selectedReviewItemKey = key;
  render();
  setTimeout(() => {
    const detailPanel = document.querySelector(`[data-review-detail="${CSS.escape(key)}"]`);
    if (!detailPanel) return;
    detailPanel.scrollIntoView({ behavior: "smooth", block: "start" });
    detailPanel.classList.add("focus-pulse");
    setTimeout(() => detailPanel.classList.remove("focus-pulse"), 1200);
  }, 0);
  showToast(`Eintrag geöffnet. Bitte "${reviewDecisionLabel(decision)}" im Detailpanel bestätigen.`);
}

async function updateReviewItemDecision(key, decision, scope) {
  if (!canReviewDocuments()) {
    showPermissionToast("Prüfentscheidungen setzen", "Berater-, Reviewer- oder Admin-Rechten");
    return;
  }
  const record = reviewRecordByKey(key);
  const item = reviewCenterItems().find((candidate) => candidate.key === key);
	  if (!record || !item) {
	    showToast("Prüfeintrag nicht gefunden.", "warning");
	    return;
	  }
	  const previous = item.rawType === "document"
	    ? compactRecordSnapshot(record, ["name", "area", "status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "classification", "fileId", "sha256"])
	    : item.rawType === "policy"
	      ? compactRecordSnapshot(record, ["title", "owner", "version", "status", "review", "priority", "linkedTo", "scope", "note"])
	      : compactRecordSnapshot(record, ["title", "name", "status", "reviewStatus", "owner", "review", "linkedTo", "evidence"]);

  const internalCommentField = scope?.querySelector("[data-review-internal-comment]");
  const customerCommentField = scope?.querySelector("[data-review-customer-comment]");
  const internalComment = String(internalCommentField?.value || record.consultantInternalComment || "").trim();
  const typedCustomerComment = String(customerCommentField?.value || "").trim();
  const storedCustomerComment = String(record.customerCommentDraft || record.customerComment || record.reworkReason || "").trim();
  if (reviewDecisionRequiresCustomerComment(decision) && !typedCustomerComment && !storedCustomerComment) {
    highlightReviewCustomerComment(customerCommentField);
    showToast("Bitte vor der Rückgabe einen konkreten Kommentar an den Kunden eintragen.", "warning");
    return;
  }
  const customerComment = typedCustomerComment || storedCustomerComment || String(item.reason || "").trim();
  const nextStatus = reviewDecisionStatus(decision);
  if (item.rawType === "internalAuditPlan") {
    const status = {
      approve: "freigegeben",
      rework: "nacharbeit_noetig",
      reject: "abgelehnt",
      audit: "auditrelevant",
      check: "in_beraterpruefung",
      later: "spaeter_pruefen"
    }[decision] || record.status || "offen";
    const changes = {
      status,
      reviewStatus: nextStatus,
      consultantInternalComment: internalComment,
      customerComment,
      consultantDecision: reviewDecisionLabel(decision),
      auditRelevant: decision === "audit" ? true : Boolean(record.auditRelevant)
    };
    const saved = recordMutationApiEnabled()
      ? await updateInternalAuditPlanViaApi(changes)
      : (() => {
          state.internalAuditPlan = normalizeInternalAuditPlan({
            ...record,
            ...changes,
            serverUpdatedAt: auditTimestamp(),
            serverUpdatedBy: workflowActor()
          });
          persist(`Auditplanung: ${reviewDecisionLabel(decision)}`);
          return true;
        })();
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast(reviewDecisionMessage(decision, item));
    render();
    return;
  }
  if (item.rawType === "managementReview") {
    const status = {
      approve: "freigegeben",
      rework: "nacharbeit_noetig",
      reject: "abgelehnt",
      audit: "auditrelevant",
      check: "in_beraterpruefung",
      later: "spaeter_pruefen"
    }[decision] || record.status || "offen";
    const changes = {
      status,
      reviewStatus: nextStatus,
      consultantInternalComment: internalComment,
      customerComment,
      consultantDecision: reviewDecisionLabel(decision),
      auditRelevant: decision === "audit" ? true : Boolean(record.auditRelevant)
    };
    const saved = recordMutationApiEnabled()
      ? await updateManagementReviewViaApi(changes)
      : (() => {
          state.managementReview = normalizeManagementReview({
            ...record,
            ...changes,
            serverUpdatedAt: auditTimestamp(),
            serverUpdatedBy: workflowActor()
          });
          persist(`Managementbewertung: ${reviewDecisionLabel(decision)}`);
          return true;
        })();
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast(reviewDecisionMessage(decision, item));
    render();
    return;
  }
  if (item.rawType === "auditFinding") {
    const isCapa = String(record.type || "").toUpperCase() === "CAPA";
    if (isCapa && decision === "approve") {
      const candidate = {
        ...record,
        effectivenessAssessment: String(record.effectivenessAssessment || internalComment || "").trim()
      };
      const blockers = capaApprovalBlockers(candidate);
      if (blockers.length) {
        showToast(`CAPA-Freigabe noch nicht möglich: ${blockers.join(", ")}.`, "warning");
        return;
      }
    }
    const status = {
      approve: "freigegeben",
      rework: "nacharbeit_noetig",
      reject: "abgelehnt",
      audit: "auditrelevant",
      check: "in_pruefung",
      later: "offen"
    }[decision] || record.status || "offen";
    const changes = {
      status,
      reviewStatus: nextStatus,
      consultantInternalComment: internalComment,
      customerComment,
      consultantDecision: reviewDecisionLabel(decision),
      auditRelevant: decision === "audit" ? true : Boolean(record.auditRelevant)
    };
    if (isCapa && decision === "approve" && !String(record.effectivenessAssessment || "").trim()) {
      changes.effectivenessAssessment = internalComment;
    }
    const saved = recordMutationApiEnabled()
      ? await updateAuditFindingViaApi(record.id, changes)
      : (() => {
          Object.assign(record, changes, { reviewUpdatedAt: today(), reviewer: workflowActor() });
          persist(`Audit-Finding: ${reviewDecisionLabel(decision)}`);
          return true;
        })();
    if (!saved) return;
    selectedReviewItemKey = key;
    showToast(reviewDecisionMessage(decision, item));
    render();
    return;
  }
  applyReviewMetadata(record, nextStatus, { internalComment, customerComment });
  record.customerCommentDraft = "";

  if (decision === "approve") {
    applyReviewApproval(record, item);
  } else if (decision === "rework") {
    applyReviewRework(record, item, customerComment);
  } else if (decision === "reject") {
    applyReviewRejection(record, item, customerComment);
  } else if (decision === "audit") {
    record.auditRelevant = true;
	  }
	  addReviewDecisionHistory(record, item, decision, { internalComment, customerComment });
	  syncTemplateDraftReviewState(record, item, decision, { internalComment, customerComment });
	  if (item.rawType === "policy") {
	    addPolicyHistory(record, reviewDecisionLabel(decision), customerComment || internalComment || item.reason, previous);
	    addPolicyVersionHistory(record, `Review-Entscheidung: ${reviewDecisionLabel(decision)}`, previous, customerComment || item.reason);
	  } else if (item.rawType === "document" && ["check", "audit", "later"].includes(decision)) {
	    addDocumentHistory(record, reviewDecisionLabel(decision), customerComment || internalComment || item.reason);
	    addDocumentVersionHistory(record, `Review-Entscheidung: ${reviewDecisionLabel(decision)}`, previous, customerComment || item.reason);
	  }

	  selectedReviewItemKey = key;
  saveState({ immediate: true });
  showToast(reviewDecisionMessage(decision, item));
  render();
}

function reviewDecisionRequiresCustomerComment(decision) {
  return ["rework", "reject"].includes(decision);
}

function highlightReviewCustomerComment(field) {
  if (!field) return;
  field.setAttribute("aria-invalid", "true");
  field.classList.add("review-comment-required");
  field.focus();
  setTimeout(() => field.classList.remove("review-comment-required"), 1400);
}

function reviewDecisionStatus(decision) {
  if (decision === "approve") return "freigegeben";
  if (decision === "rework") return "nacharbeit_noetig";
  if (decision === "reject") return "abgelehnt";
  if (decision === "audit") return "auditrelevant";
  if (decision === "check") return "in_beraterpruefung";
  if (decision === "later") return "spaeter_pruefen";
  return "offen";
}

function reviewDecisionMessage(decision, item) {
  if (decision === "approve") return `${item.type} freigegeben.`;
  if (decision === "rework") return "Nacharbeit an den Kunden zurückgegeben.";
  if (decision === "reject") return `${item.type} abgelehnt.`;
  if (decision === "audit") return `${item.type} als auditrelevant markiert.`;
  if (decision === "check") return `${item.type} ist jetzt in Beraterprüfung.`;
  return `${item.type} für spätere Prüfung vorgemerkt.`;
}

function reviewDecisionLabel(decision) {
  return {
    approve: "Freigegeben",
    rework: "Nacharbeit angefordert",
    reject: "Abgelehnt",
    audit: "Auditrelevant markiert",
    check: "In Beraterprüfung genommen",
    later: "Später prüfen",
    resubmit: "Erneut eingereicht"
  }[decision] || "Review aktualisiert";
}

function addReviewHistoryEntry(record, entry = {}) {
  if (!record) return;
  const history = Array.isArray(record.reviewDecisionHistory) ? record.reviewDecisionHistory : [];
	  record.reviewDecisionHistory = [{
	    date: entry.date || today(),
	    dateTime: entry.dateTime || auditTimestamp(),
	    by: entry.by || workflowActor(),
	    action: entry.action || "Review aktualisiert",
	    status: entry.status || (record.reviewStatus ? reviewStatusLabel(record.reviewStatus) : ""),
    type: entry.type || "",
    title: entry.title || "",
    internalComment: entry.internalComment || "",
	    customerComment: entry.customerComment || "",
	    note: entry.note || ""
	  }, ...history].slice(0, 40);
	  recordAuditTrailEvent({
	    action: entry.action || "Review aktualisiert",
	    entityType: entry.type || "Review",
	    entityId: record.id || record.controlId || "",
	    entityTitle: entry.title || record.title || record.name || record.riskId || record.scenario || record.controlId || "",
	    module: entry.type || "",
	    status: entry.status || (record.reviewStatus ? reviewStatusLabel(record.reviewStatus) : ""),
	    note: entry.customerComment || entry.internalComment || entry.note || "",
	    metadata: {
	      reviewStatus: record.reviewStatus || "",
	      customerComment: entry.customerComment || "",
	      internalComment: entry.internalComment || ""
	    }
	  });
	}

function addReviewDecisionHistory(record, item, decision, { internalComment = "", customerComment = "" } = {}) {
  addReviewHistoryEntry(record, {
    action: reviewDecisionLabel(decision),
    status: reviewStatusLabel(record?.reviewStatus),
    type: item?.type || "",
    title: item?.title || "",
    internalComment,
    customerComment,
    note: item?.reason || ""
  });
}

function syncTemplateDraftReviewState(documentRecord, item = {}, decision = "", { internalComment = "", customerComment = "" } = {}) {
  if (!documentRecord || item.rawType !== "document") return;
  const draft = item.templateDraftId
    ? state.templateDrafts.find((entry) => entry.id === item.templateDraftId)
    : templateDraftForDocument(documentRecord);
  if (!draft) return;

  const previous = compactRecordSnapshot(draft, [
    "title",
    "templateTitle",
    "owner",
    "version",
    "status",
    "approval",
    "reviewStatus",
    "review",
    "linkedTo",
    "content"
  ]);
  const reviewStatus = normalizeReviewStatus(documentRecord.reviewStatus || reviewDecisionStatus(decision));
  const reviewFields = {
    status: documentRecord.status || draft.status || "Entwurf",
    approval: documentRecord.approval || draft.approval || "Nicht gestartet",
    reviewStatus,
    reviewUpdatedAt: today(),
    reviewer: documentRecord.reviewer || workflowActor(),
    consultantInternalComment: internalComment || draft.consultantInternalComment || "",
    customerComment: customerComment || documentRecord.customerComment || draft.customerComment || "",
    auditRelevant: Boolean(documentRecord.auditRelevant || draft.auditRelevant)
  };

  if (decision === "approve" || reviewStatus === "freigegeben") {
    Object.assign(reviewFields, {
      status: "Freigegeben",
      approval: "Freigegeben",
      version: approvedDocumentVersion(draft.version || documentRecord.version || "0.1"),
      approvedAt: documentRecord.approvedAt || today(),
      approvedBy: documentRecord.approvedBy || workflowActor(),
      reworkReason: "",
      reworkDue: "",
      reworkMissing: "",
      reworkWhy: "",
      reworkAction: "",
      reworkReference: ""
    });
  } else if (decision === "rework" || reviewStatus === "nacharbeit_noetig") {
    Object.assign(reviewFields, {
      status: "Überarbeiten",
      approval: "Abgelehnt",
      reworkRequestedAt: documentRecord.reworkRequestedAt || today(),
      reworkRequestedBy: documentRecord.reworkRequestedBy || workflowActor(),
      reworkReason: documentRecord.reworkReason || customerComment || item.reason || "",
      reworkDue: documentRecord.reworkDue || futureDate(DOCUMENT_REWORK_DAYS),
      reworkMissing: documentRecord.reworkMissing || "",
      reworkWhy: documentRecord.reworkWhy || "",
      reworkAction: documentRecord.reworkAction || "",
      reworkReference: documentRecord.reworkReference || ""
    });
  } else if (decision === "reject" || reviewStatus === "abgelehnt") {
    Object.assign(reviewFields, {
      status: "Überarbeiten",
      approval: "Abgelehnt",
      reworkRequestedAt: documentRecord.reworkRequestedAt || today(),
      reworkRequestedBy: documentRecord.reworkRequestedBy || workflowActor(),
      reworkReason: documentRecord.reworkReason || customerComment || item.reason || "",
      reworkDue: documentRecord.reworkDue || futureDate(DOCUMENT_REWORK_DAYS),
      reworkMissing: documentRecord.reworkMissing || "",
      reworkWhy: documentRecord.reworkWhy || "",
      reworkAction: documentRecord.reworkAction || "",
      reworkReference: documentRecord.reworkReference || ""
    });
  } else if (decision === "check" || reviewStatus === "in_beraterpruefung") {
    Object.assign(reviewFields, {
      status: "In Prüfung",
      approval: "Prüfung läuft"
    });
  } else if (decision === "audit" || reviewStatus === "auditrelevant") {
    Object.assign(reviewFields, {
      auditRelevant: true
    });
  }

  Object.assign(draft, reviewFields, { updated: today() });
  if (reviewFields.version) {
    draft.data = {
      ...(draft.data || {}),
      version: reviewFields.version,
      review: draft.review || draft.data?.review || "",
      reviewDate: draft.review || draft.data?.reviewDate || ""
    };
  }
  addTemplateDraftVersionHistory(
    draft,
    `Review-Entscheidung: ${reviewDecisionLabel(decision)}`,
    previous,
    customerComment || internalComment || item.reason || "Beraterprüfung wurde auf die Arbeitsvorlage synchronisiert."
  );
  addReviewHistoryEntry(draft, {
    action: reviewDecisionLabel(decision),
    status: reviewStatusLabel(draft.reviewStatus),
    type: item.type || "Arbeitsvorlage",
    title: draft.title || item.title || "Arbeitsvorlage",
    internalComment,
    customerComment,
    note: item.reason || ""
  });
}

function applyReviewMetadata(record, reviewStatus, { internalComment = "", customerComment = "" } = {}) {
  record.reviewStatus = normalizeReviewStatus(reviewStatus);
  record.consultantInternalComment = internalComment;
  record.customerComment = customerComment;
  record.reviewUpdatedAt = today();
  record.reviewer = workflowActor();
  if (!record.reviewAssignee) record.reviewAssignee = workflowActor();
}

function applyReviewApproval(record, item) {
  if (item.rawType === "document") {
    Object.assign(record, normalizeDocumentRecord({
      ...record,
      status: "Freigegeben",
      approval: "Freigegeben",
      reviewStatus: "freigegeben",
      version: approvedDocumentVersion(record.version),
      review: record.review || futureDate(DOCUMENT_REVIEW_DAYS),
      approvedAt: today(),
      approvedBy: workflowActor(),
      reworkReason: "",
      reworkDue: ""
    }));
    addDocumentHistory(record, "Beraterfreigabe", "Nachweis wurde im Review Center freigegeben.");
    completeDocumentWorkflowTasks(record, "Review Center: Nachweis freigegeben.");
    return;
  }
  if (item.rawType === "policy") {
    record.status = "Freigegeben";
    const artifact = resolvePolicyArtifact(record);
    if (artifact.document) {
      Object.assign(artifact.document, normalizeDocumentRecord({
        ...artifact.document,
        status: "Freigegeben",
        approval: "Freigegeben",
        reviewStatus: "freigegeben",
        approvedAt: today(),
        approvedBy: workflowActor()
      }, "Policy im Review Center freigegeben"));
      addDocumentHistory(artifact.document, "Policy freigegeben", "Policy wurde im Review Center freigegeben.");
    }
  }
  if (item.rawType === "asset") record.status = "Freigegeben";
  if (item.rawType === "task") record.status = "Erledigt";
  completeReviewItemTasks(item, "Review Center: Punkt freigegeben.");
}

function applyReviewRework(record, item, customerComment) {
  const guidance = reviewReworkGuidance(item, customerComment);
  Object.assign(record, {
    reworkMissing: guidance.missing,
    reworkWhy: guidance.why,
    reworkAction: guidance.action,
    reworkReference: guidance.reference
  });
  let customerTaskHandled = false;
  if (item.rawType === "document") {
    Object.assign(record, normalizeDocumentRecord({
      ...record,
      status: "Überarbeiten",
      approval: "Abgelehnt",
      reviewStatus: "nacharbeit_noetig",
      reworkRequestedAt: today(),
      reworkRequestedBy: workflowActor(),
      reworkReason: guidance.missing,
      customerComment: guidance.missing,
      reworkMissing: guidance.missing,
      reworkWhy: guidance.why,
      reworkAction: guidance.action,
      reworkReference: guidance.reference,
      reworkDue: futureDate(DOCUMENT_REWORK_DAYS)
    }));
    addDocumentHistory(record, "Nacharbeit über Review Center angefordert", record.reworkReason);
    upsertDocumentWorkflowTask(record, "rework");
    enhanceDocumentReworkTask(record, item, customerComment || item.reason);
    customerTaskHandled = true;
  }
  if (item.rawType === "policy") record.status = "Überarbeiten";
  if (item.rawType === "task") record.status = "Blockiert";
  if (!customerTaskHandled) createReviewReworkTask(item, record, customerComment || item.reason);
}

function applyReviewRejection(record, item, customerComment) {
  const rejectionItem = {
    ...item,
    reviewReturnStatus: "abgelehnt",
    reworkWhy: "Der Punkt wurde fachlich abgelehnt und kann in dieser Form nicht freigegeben werden.",
    reworkAction: "Bitte korrigiere die Angaben oder den Nachweis grundlegend und reiche den Punkt danach erneut ein."
  };
  const guidance = reviewReworkGuidance(rejectionItem, customerComment);
  Object.assign(record, {
    reworkMissing: guidance.missing,
    reworkWhy: guidance.why,
    reworkAction: guidance.action,
    reworkReference: guidance.reference
  });
  let customerTaskHandled = false;
  if (item.rawType === "document") {
    Object.assign(record, normalizeDocumentRecord({
      ...record,
      status: "Überarbeiten",
      approval: "Abgelehnt",
      reviewStatus: "abgelehnt",
      reworkRequestedAt: today(),
      reworkRequestedBy: workflowActor(),
      reworkReason: guidance.missing,
      customerComment: guidance.missing,
      reworkMissing: guidance.missing,
      reworkWhy: guidance.why,
      reworkAction: guidance.action,
      reworkReference: guidance.reference,
      reworkDue: futureDate(DOCUMENT_REWORK_DAYS)
    }));
    addDocumentHistory(record, "Über Review Center abgelehnt", record.reworkReason);
    upsertDocumentWorkflowTask(record, "rework");
    enhanceDocumentReworkTask(record, rejectionItem, customerComment || item.reason);
    customerTaskHandled = true;
  }
  if (item.rawType === "policy") record.status = "Überarbeiten";
  if (item.rawType === "task") record.status = "Blockiert";
  if (!customerTaskHandled) createReviewReworkTask(rejectionItem, record, customerComment || item.reason);
}

function createReviewReworkTask(item, record, customerComment) {
  const guidance = reviewReworkGuidance(item, customerComment);
  const title = `Nacharbeit: ${item.title}`;
  const existing = state.tasks.find((task) => task.reviewItemKey === item.key && task.workflowType === "review-rework" && task.status !== "Erledigt");
  const task = {
    title,
    module: item.module || "Review Center",
    owner: item.owner || "Kunde / Projektteam",
    due: futureDate(DOCUMENT_REWORK_DAYS),
    status: "Offen",
    workflowType: "review-rework",
    source: "Berater-Rückgabe",
    reviewReturnStatus: item.reviewReturnStatus || "",
    reviewItemKey: item.key,
    documentId: item.rawType === "document" ? item.id : item.documentId || "",
    linkedTo: item.mapping || item.linkedEvidence || item.title,
    reworkMissing: guidance.missing,
    reworkWhy: guidance.why,
    reworkAction: guidance.action,
    reworkReference: guidance.reference,
    note: formatReviewReworkNote(guidance)
  };
  if (existing) {
    Object.assign(existing, task, { id: existing.id });
    return false;
  }
  state.tasks.unshift({ id: crypto.randomUUID(), ...task });
  return true;
}

function enhanceDocumentReworkTask(document, item, customerComment) {
  const guidance = reviewReworkGuidance(item, customerComment);
  const task = state.tasks.find((candidate) => candidate.id === document.reviewTaskId)
    || state.tasks.find((candidate) => candidate.documentId === document.id && candidate.workflowType === "rework" && candidate.status !== "Erledigt");
  if (!task) return;
  Object.assign(task, {
    source: "Berater-Rückgabe",
    reviewItemKey: item.key,
    reviewReturnStatus: item.reviewReturnStatus || "",
    reworkMissing: guidance.missing,
    reworkWhy: guidance.why,
    reworkAction: guidance.action,
    reworkReference: guidance.reference,
    note: formatReviewReworkNote(guidance)
  });
}

function completeReviewItemTasks(item, note) {
  state.tasks = state.tasks.map((task) => {
    if (task.reviewItemKey !== item.key) return task;
    return { ...task, status: "Erledigt", note: note || task.note };
  });
}

function openReviewItemSource(key) {
  const item = reviewCenterItems().find((candidate) => candidate.key === key);
  if (!item) return;
  selectedReviewItemKey = key;
  if (item.templateDraftId) {
    const draft = state.templateDrafts.find((entry) => entry.id === item.templateDraftId);
    selectedTemplateDraftId = item.templateDraftId;
    if (draft?.templateId) selectedTemplateId = draft.templateId;
    navigateToView("templates");
    return;
  }
  if (item.rawType === "document" && item.id) {
    openDocumentFromAnywhere(item.id);
    return;
  }
  if (item.rawType === "policy" && item.id) {
    openPolicyArtifact(item.id, "best");
    return;
  }
  if (item.rawType === "soa" && item.id) {
    selectedSoaWizardControlId = item.id;
    navigateToView("soa");
    return;
  }
  if (item.rawType === "auditFinding" && item.type === "CAPA") {
    selectedCapaId = item.id;
  }
  navigateToView({
    risk: "risks",
    task: "tasks",
    asset: "assets",
    managementReview: "managementreview",
    internalAuditPlan: "audit",
    auditFinding: item.type === "CAPA" ? "capa" : "audit",
    legal: "legal",
    suppliers: "suppliers",
    incidents: "incidents",
    contracts: "contracts"
  }[item.rawType] || "review");
}

function supplierById(id) {
  return state.suppliers.find((supplier) => supplier.id === id) || null;
}

async function openOrCreateSupplierContract(supplierId) {
  const supplier = supplierById(supplierId);
  if (!supplier) return;
  const existing = supplierLinkedContracts(supplier)[0];
  if (existing) {
    showToast("Verknüpften Vertrag geöffnet.");
    navigateToView("contracts");
    return;
  }
  if (!canEditWorkspace() && !canSubmitWorkspace()) {
    showPermissionToast("Vertragsprüfung anlegen", "Bearbeitungsrechten");
    return;
  }
  const contract = normalizeRegisterComplianceEntry("contracts", {
    id: crypto.randomUUID(),
    title: `Lieferantenvertrag prüfen: ${supplier.name || "Lieferant"}`,
    vendor: supplier.name || "",
    framework: supplier.framework || "ISO 27001 + NIS-2",
    owner: supplier.owner || "Einkauf / ISB",
    status: "Prüfen",
    review: supplier.nextReview || futureDate(30),
    linkedTo: "A.5.20 / §30 Abs. 2 Nr. 4",
    evidence: supplier.evidence || "",
    supplierId: supplier.id || "",
    note: `Aus Vendor Management angelegt. Leistung: ${supplier.service || "offen"}.`
  });
  if (recordMutationApiEnabled()) {
    const created = await createContractRecordViaApi(contract);
    if (!created) return;
  } else {
    state.contracts.unshift(contract);
    supplier.contractStatus = supplier.contractStatus || "Prüfen";
    saveState();
  }
  showToast("Vertragsprüfung angelegt.");
  navigateToView("contracts");
}

function openOrCreateSupplierRisk(supplierId) {
  const supplier = supplierById(supplierId);
  if (!supplier) return;
  const existing = supplierLinkedRisks(supplier)[0];
  if (existing) {
    showToast("Verknüpftes Lieferantenrisiko geöffnet.");
    navigateToView("risks");
    return;
  }
  if (!canEditWorkspace()) {
    showPermissionToast("Lieferantenrisiko anlegen", "Bearbeitungsrechten");
    return;
  }
  const risk = normalizeRegisterComplianceEntry("risks", {
    id: crypto.randomUUID(),
    riskId: nextRiskId(),
    asset: supplier.name || "Lieferant",
    owner: supplier.owner || "Einkauf / ISB",
    framework: supplier.framework || "ISO 27001 + NIS-2",
    scenario: `Ausfall, Sicherheitsmangel oder unklare Vertragsanforderungen beim Lieferanten ${supplier.name || "Lieferant"} können Verfügbarkeit, Vertraulichkeit oder Compliance beeinträchtigen.`,
    likelihood: supplier.criticality === "Sehr hoch" ? "4" : "3",
    impact: ["Hoch", "Sehr hoch"].includes(supplier.criticality) ? "4" : "3",
    treatmentOption: "Reduzieren",
    treatment: "Lieferantenreview, Sicherheitsanforderungen, Vertragsprüfung und Nachweise durchführen.",
    controls: "A.5.19-A.5.23 / §30 Abs. 2 Nr. 4",
    status: "In Bewertung",
    review: supplier.nextReview || futureDate(30),
    evidence: supplier.evidence || ""
  });
  state.risks.unshift(risk);
  saveState();
  showToast("Lieferantenrisiko angelegt.");
  navigateToView("risks");
}

function approvedDocumentVersion(version) {
  return window.SFMVersioning.approvedVersion(version);
}

function prepareDocumentSubmissionOnUpload(document) {
  if (document.status !== "In Prüfung") return document;
  document.approval = "Prüfung läuft";
  document.reviewStatus = "vom_kunden_eingereicht";
  document.submittedAt = document.submittedAt || today();
  document.submittedBy = document.submittedBy || workflowActor();
  addDocumentHistory(document, "Zur Prüfung eingereicht", "Upload wurde automatisch als Nachweis zur Prüfung eingereicht.");
  upsertDocumentWorkflowTask(document, "review");
  return document;
}

function upsertDocumentWorkflowTask(document, type) {
  const title = type === "rework"
    ? `Nachweis nachbessern: ${document.name}`
    : `Dokument prüfen: ${document.name}`;
  const existing = state.tasks.find((task) => task.documentId === document.id && task.workflowType === type)
    || state.tasks.find((task) => String(task.title || "").toLowerCase() === title.toLowerCase());
  const guidance = type === "rework" ? parseCustomerReworkGuidance(document, {
    missing: document.reworkReason || "Nachweis wurde zurückgegeben und muss überarbeitet werden.",
    action: "Bitte ergänze den Nachweis, die Beschreibung oder den Link und reiche ihn danach erneut ein.",
    reference: document.evidenceFor || document.linkedTo || document.name || "Nachweis"
  }) : null;
  const task = {
    title,
    module: "Dokumentation",
    owner: type === "rework" ? (document.owner || document.submittedBy || "Kunde") : "Berater / ISB",
    due: type === "rework" ? (document.reworkDue || futureDate(DOCUMENT_REWORK_DAYS)) : futureDate(7),
    status: "Offen",
    documentId: document.id,
    workflowType: type,
    reviewReturnStatus: type === "rework" && document.reviewStatus === "abgelehnt" ? "abgelehnt" : "",
    linkedTo: document.linkedTo || document.evidenceFor || "",
    reworkMissing: guidance?.missing || "",
    reworkWhy: guidance?.why || "",
    reworkAction: guidance?.action || "",
    reworkReference: guidance?.reference || "",
    note: type === "rework"
      ? formatReviewReworkNote(guidance)
      : "Eingereichter Nachweis wartet auf fachliche Prüfung und Freigabe."
  };

  if (existing) {
    Object.assign(existing, task, { id: existing.id, status: existing.status === "Erledigt" ? "Offen" : existing.status });
    document.reviewTaskId = existing.id;
    return false;
  }

  const id = crypto.randomUUID();
  state.tasks.unshift({ id, ...task });
  document.reviewTaskId = id;
  return true;
}

function completeDocumentWorkflowTasks(document, note) {
  completeDocumentWorkflowTasksByType(document, ["review", "rework"], note);
}

function completeDocumentWorkflowTasksByType(document, workflowTypes, note) {
  const allowedTypes = new Set(workflowTypes);
  state.tasks = state.tasks.map((task) => {
    const sameDocument = task.documentId === document.id || (document.name && String(task.title || "").includes(document.name));
    if (!sameDocument) return task;
    if (!allowedTypes.has(task.workflowType)) return task;
    return {
      ...task,
      status: "Erledigt",
      note: note || task.note
    };
  });
}

async function handleFormSubmit(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const formType = form.dataset.form;
  const customerSubmitForms = ["manual-document", "soc-report", "asset", "risk", "legal", "supplier", "policy", "incident", "contract", "task"];
  if (!canEditWorkspace() && !(customerSubmitForms.includes(formType) && canSubmitDocuments())) {
    showPermissionToast("Einträge bearbeiten", "Bearbeitungsrechten");
    return;
  }
  const data = Object.fromEntries(new FormData(form).entries());
  const id = crypto.randomUUID();

  if (formType === "asset" && recordMutationApiEnabled()) {
    const asset = normalizeRegisterComplianceEntry("assets", { id, ...data });
    const created = await createAssetRecordViaApi(asset);
    if (!created) return;
    form.reset();
    showToast("Asset erfasst und sicher gespeichert.");
    render();
    return;
  }

  if (formType === "risk" && recordMutationApiEnabled()) {
    const risk = normalizeRegisterComplianceEntry("risks", {
      id,
      ...data,
      riskId: data.riskId || nextRiskId(),
      added: today(),
      reviewStatus: data.reviewStatus || (data.source === "Kundenmodus" ? "vom_kunden_eingereicht" : ""),
      submittedAt: data.source === "Kundenmodus" ? today() : data.submittedAt,
      submittedBy: data.source === "Kundenmodus" ? workflowActor() : data.submittedBy,
      reviewUpdatedAt: data.source === "Kundenmodus" ? today() : data.reviewUpdatedAt
    });
    const created = await createRiskRecordViaApi(risk);
    if (!created) return;
    form.reset();
    showToast("Risiko erfasst und sicher gespeichert.");
    render();
    return;
  }

  if (formType === "legal" && recordMutationApiEnabled()) {
    const legalEntry = normalizeRegisterComplianceEntry("legal", { id, ...data, added: today() });
    const created = await createLegalRecordViaApi(legalEntry);
    if (!created) return;
    form.reset();
    showToast("Rechtsregister-Eintrag erfasst und revisionssicher gespeichert.");
    render();
    return;
  }

  if (formType === "supplier" && recordMutationApiEnabled()) {
    const supplier = normalizeRegisterComplianceEntry("suppliers", { id, ...data });
    const created = await createSupplierRecordViaApi(supplier);
    if (!created) return;
    form.reset();
    showToast("Lieferant erfasst und sicher gespeichert.");
    render();
    return;
  }

  if (formType === "policy" && recordMutationApiEnabled()) {
    const policy = normalizePolicyRecord(enrichPolicyRecord({ id, ...data, added: today() }));
    const created = await createPolicyRecordViaApi(policy);
    if (!created) return;
    form.reset();
    showToast("Policy erfasst und revisionssicher gespeichert.");
    render();
    return;
  }

  if (formType === "incident" && recordMutationApiEnabled()) {
    const incident = normalizeRegisterComplianceEntry("incidents", { id, ...data, added: today() });
    const created = await createIncidentRecordViaApi(incident);
    if (!created) return;
    form.reset();
    showToast("Incident erfasst und sicher gespeichert.");
    render();
    return;
  }

  if (formType === "contract" && recordMutationApiEnabled()) {
    const contract = normalizeRegisterComplianceEntry("contracts", { id, ...data, added: today() });
    const created = await createContractRecordViaApi(contract);
    if (!created) return;
    form.reset();
    showToast("Vertrag erfasst und revisionssicher gespeichert.");
    render();
    return;
  }

  if (formType === "task" && recordMutationApiEnabled()) {
    const task = { id, ...data, added: today() };
    const created = await createTaskRecordViaApi(task);
    if (!created) return;
    form.reset();
    showToast("Aufgabe erfasst und revisionssicher gespeichert.");
    render();
    return;
  }

  const map = {
	    "manual-document": () => {
	      const document = normalizeDocumentRecord({ id, ...data, size: "", added: today(), evidenceFor: data.linkedTo || "" }, "Manuell erfasst");
	      addDocumentHistory(document, "Manuell erfasst", "Dokument- oder Nachweisverweis wurde manuell angelegt.");
	      addDocumentVersionHistory(document, "Erste Dokumentversion manuell erfasst", {}, "Initialer Metadatenstand protokolliert.");
	      state.documents.unshift(document);
	    },
    asset: () => state.assets.unshift(normalizeRegisterComplianceEntry("assets", { id, ...data })),
    risk: () => {
      const risk = normalizeRegisterComplianceEntry("risks", {
        id,
        ...data,
        riskId: data.riskId || nextRiskId(),
        added: today(),
        reviewStatus: data.reviewStatus || (data.source === "Kundenmodus" ? "vom_kunden_eingereicht" : ""),
        submittedAt: data.source === "Kundenmodus" ? today() : data.submittedAt,
        submittedBy: data.source === "Kundenmodus" ? workflowActor() : data.submittedBy,
        reviewUpdatedAt: data.source === "Kundenmodus" ? today() : data.reviewUpdatedAt
      });
      state.risks.unshift(risk);
      if (data.source === "Kundenmodus") {
        recordAuditTrailEvent({
          action: "Risiko vom Kunden eingereicht",
          entityType: "Risiko",
          entityId: risk.id,
          entityTitle: risk.riskId || risk.scenario,
          module: "Risiko Management",
          status: "vom_kunden_eingereicht",
          note: "Risiko wurde im Kundenmodus formal erfasst. Fachliche Bewertung bleibt beim Berater/Admin."
        });
      }
    },
    legal: () => state.legal.unshift(normalizeRegisterComplianceEntry("legal", { id, ...data })),
    supplier: () => state.suppliers.unshift(normalizeRegisterComplianceEntry("suppliers", { id, ...data })),
	    policy: () => {
	      const policy = normalizePolicyRecord(enrichPolicyRecord({ id, ...data, added: today() }));
	      addPolicyHistory(policy, "Policy manuell erfasst", "Policy wurde über das Registerformular angelegt.");
	      addPolicyVersionHistory(policy, "Erste Policy-Version manuell erfasst", {}, "Initialer Policystand protokolliert.");
	      state.policies.unshift(policy);
	    },
    incident: () => state.incidents.unshift(normalizeRegisterComplianceEntry("incidents", { id, ...data, added: today() })),
    contract: () => state.contracts.unshift(normalizeRegisterComplianceEntry("contracts", { id, ...data, added: today() })),
    "soc-report": () => createSocReportArtifacts({ id, ...data }),
    task: () => state.tasks.unshift({ id, ...data })
  };

  map[form.dataset.form]?.();
  saveState();
  form.reset();
  showToast("Eintrag erfasst.");
  render();
}

async function handleRiskWorkshopSubmit(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (!canEditWorkspace() && !canSubmitDocuments()) {
    showPermissionToast("Risiken einreichen", "Kunden-, Berater- oder Bearbeitungszugriff");
    return;
  }

  const data = Object.fromEntries(new FormData(form).entries());
  const asset = String(data.asset || "").trim() || "Asset / Prozess offen";
  const scenarioInput = String(data.scenario || "").trim();
  const effect = String(data.effect || "").trim();
  const treatment = String(data.treatment || "").trim();
  const scenario = [
    scenarioInput || `Risiko zu ${asset} fachlich beschreiben.`,
    effect ? `Auswirkung: ${effect}` : ""
  ].filter(Boolean).join(" ");
  const risk = normalizeRegisterComplianceEntry("risks", {
    id: crypto.randomUUID(),
    riskId: nextRiskId(),
    asset,
    scenario,
    owner: String(data.owner || "").trim() || "Owner offen",
    likelihood: data.likelihood || "3",
    impact: data.impact || "3",
    residualLikelihood: data.residualLikelihood || "",
    residualImpact: data.residualImpact || "",
    treatmentOption: data.treatmentOption || "Reduzieren",
    treatment,
    controls: String(data.controls || "").trim() || "Zuordnung und Nachweis durch Berater/Admin prüfen",
    acceptanceOwner: String(data.acceptanceOwner || "").trim(),
    evidence: String(data.evidence || "").trim(),
    review: data.review || futureDate(30),
    framework: data.framework || "ISO 27001 + NIS-2",
    status: treatment ? "In Behandlung" : "In Bewertung",
    reviewStatus: "vom_kunden_eingereicht",
    submittedAt: today(),
    submittedBy: workflowActor(),
    reviewUpdatedAt: today(),
    source: "Risikoworkshop",
    customerInput: {
      important: asset,
      whatCanGoWrong: scenarioInput,
      effect,
      whatWeDo: treatment,
      residualLikelihood: data.residualLikelihood || "",
      residualImpact: data.residualImpact || "",
      acceptanceOwner: String(data.acceptanceOwner || "").trim(),
      evidence: String(data.evidence || "").trim()
    },
    added: today()
  });

  if (recordMutationApiEnabled()) {
    const created = await createRiskRecordViaApi(risk);
    if (!created) return;
    const persistedRisk = state.risks.find((item) => String(item.id || "") === String(risk.id || "")) || risk;
    upsertRegisterReviewTask("risks", persistedRisk);
    saveState({ immediate: true });
    await Promise.resolve(saveWorkspaceToBackend());
  } else {
    state.risks.unshift(risk);
    upsertRegisterReviewTask("risks", risk);
    saveState({ immediate: true });
  }
  form.reset();
  showToast(`Risiko ${risk.riskId} erfasst und zur Beraterprüfung vorgemerkt.`);
  render();
}

async function submitRegisterItemForReview(collection, id) {
  if (!canEditWorkspace() && !canSubmitDocuments()) {
    showPermissionToast("Einträge zur Prüfung einreichen", "Bearbeitungs- oder Kundenzugriff");
    return;
  }
  let row = registerRows(collection).find((item) => item.id === id);
  if (!row) {
    showToast("Registereintrag nicht gefunden.", "warning");
    return;
  }
  const wasRework = row.reviewStatus === "nacharbeit_noetig" || row.status === "Überarbeiten" || row.approval === "Abgelehnt" || Boolean(row.reworkReason);
  let recordSavedViaApi = false;
  if (["risks", "legal", "suppliers", "policies", "incidents", "contracts", "tasks"].includes(collection) && recordMutationApiEnabled()) {
    const resubmissionCount = wasRework ? Number(row.resubmissionCount || 0) + 1 : Number(row.resubmissionCount || 0);
    const reviewChanges = {
      reviewStatus: "vom_kunden_eingereicht",
      submittedAt: today(),
      submittedBy: row.submittedBy || workflowActor(),
      reviewUpdatedAt: today(),
      resubmittedAfterReworkAt: wasRework ? today() : (row.resubmittedAfterReworkAt || ""),
      resubmissionCount,
      customerComment: "",
      reworkReason: "",
      reworkDue: "",
      reworkMissing: "",
      reworkWhy: "",
      reworkAction: "",
      reworkReference: ""
    };
    const updateViaApi = {
      risks: updateRiskRecordViaApi,
      legal: updateLegalRecordViaApi,
      suppliers: updateSupplierRecordViaApi,
      policies: updatePolicyRecordViaApi,
      incidents: updateIncidentRecordViaApi,
      contracts: updateContractRecordViaApi,
      tasks: updateTaskRecordViaApi
    }[collection];
    const updated = await updateViaApi(id, reviewChanges);
    if (!updated) return;
    row = registerRows(collection).find((item) => item.id === id);
    if (!row) return;
    recordSavedViaApi = true;
  }
  row.reviewStatus = "vom_kunden_eingereicht";
  row.submittedAt = today();
  row.submittedBy = row.submittedBy || workflowActor();
  row.reviewUpdatedAt = today();
  row.resubmittedAfterReworkAt = wasRework ? today() : (row.resubmittedAfterReworkAt || "");
  if (!recordSavedViaApi) {
    row.resubmissionCount = wasRework ? Number(row.resubmissionCount || 0) + 1 : Number(row.resubmissionCount || 0);
  }
  clearRecordReworkState(row);
  if (wasRework) {
    addReviewHistoryEntry(row, {
      action: reviewDecisionLabel("resubmit"),
      status: reviewStatusLabel("vom_kunden_eingereicht"),
      type: registerFullModuleLabel(collection),
      title: registerEntryTitle(collection, row),
      customerComment: "Kunde hat die Nacharbeit erneut eingereicht.",
      note: "Wartet wieder auf Beraterprüfung."
    });
  }
  completeReviewReworkTasksByKey(registerReviewKey(collection, row.id), "Nacharbeit erneut eingereicht.");
  upsertRegisterReviewTask(collection, row);
  saveState({ immediate: true });
  showToast(`${registerEntryTitle(collection, row)} zur Beraterprüfung vorgemerkt.`);
  render();
}

function clearRecordReworkState(record) {
  if (!record) return;
  Object.assign(record, {
    customerComment: "",
    reworkReason: "",
    reworkDue: "",
    reworkMissing: "",
    reworkWhy: "",
    reworkAction: "",
    reworkReference: ""
  });
}

function completeReviewReworkTasksByKey(key, note) {
  if (!key) return;
  state.tasks = state.tasks.map((task) => {
    if (task.reviewItemKey !== key) return task;
    if (!(task.workflowType === "review-rework" || task.source === "Berater-Rückgabe")) return task;
    return {
      ...task,
      status: "Erledigt",
      note: note || task.note
    };
  });
}

function upsertRegisterReviewTask(collection, row) {
  const key = registerReviewKey(collection, row.id);
  const title = `Prüfen: ${registerEntryTitle(collection, row)}`;
  const existing = state.tasks.find((task) => task.reviewItemKey === key && task.workflowType === "review");
  const task = {
    title,
    module: registerFullModuleLabel(collection),
    owner: "Berater / ISB",
    due: futureDate(7),
    status: "Offen",
    workflowType: "review",
    reviewItemKey: key,
    linkedTo: registerEvidenceReference(collection, row),
    note: "Registereintrag wurde zur Beraterprüfung vorgemerkt. Die Plattform zeigt nur formale Vollständigkeit; fachliche Freigabe erfolgt durch Berater/Admin."
  };
  if (existing) {
    Object.assign(existing, task, { id: existing.id, status: existing.status === "Erledigt" ? "Offen" : existing.status });
    return false;
  }
  state.tasks.unshift({ id: crypto.randomUUID(), ...task });
  return true;
}

function registerReviewKey(collection, id) {
  return {
    risks: `risk:${id}`,
    policies: `policy:${id}`,
    assets: `asset:${id}`,
    tasks: `task:${id}`
  }[collection] || `${collection}:${id}`;
}

function normalizeRegisterComplianceEntry(collection, entry) {
  return {
    ...entry,
    framework: entry.framework || registerComplianceScope(entry, collection)
  };
}

function createSocReportArtifacts(data) {
  const report = normalizeSocReportRecord({
    ...data,
    title: data.title || socReportTitle(data),
    added: today()
  });
  const period = socReportPeriod(report);
  const linkedTo = "SOC/SIEM Betriebsnachweis";
  const totalAlerts = numericValue(report.alertsTotal);
  const criticalAlerts = numericValue(report.criticalAlerts);
  const highAlerts = numericValue(report.highAlerts);
  const openFindings = numericValue(report.openFindings);

  state.socReports.unshift(report);
  state.documents.unshift(normalizeDocumentRecord({
    id: crypto.randomUUID(),
    name: report.title,
    area: "SOC/SIEM",
    status: "In Prüfung",
    approval: "Prüfung läuft",
    owner: report.owner,
    linkedTo,
    evidenceFor: linkedTo,
    size: "",
    version: "0.1",
    review: futureDate(DOCUMENT_REVIEW_DAYS),
    classification: "Vertraulich",
    note: [
      `${report.reportType} aus ${report.source}`,
      period ? `Zeitraum: ${period}` : "",
      `Alerts: ${totalAlerts} gesamt, ${criticalAlerts} kritisch, ${highAlerts} hoch`,
      `Offene Findings: ${openFindings}`,
      report.summary || "",
      report.actions ? `Maßnahmen: ${report.actions}` : ""
    ].filter(Boolean).join(" · "),
    added: today()
  }, "SOC/SIEM-Auswertung erfasst"));

  if (openFindings > 0 || criticalAlerts > 0 || highAlerts > 0 || report.actions) {
    state.tasks.unshift({
      id: crypto.randomUUID(),
      title: `SOC/SIEM Findings bearbeiten: ${report.title}`,
      module: "Incident Management",
      owner: report.owner || "IT / SOC",
      due: futureDate(14),
      status: "Offen",
      linkedTo,
      note: report.actions || report.summary || "SOC/SIEM-Auswertung enthält offene Findings oder erhöhte Alerts."
    });
  }

  if (report.incidentAssessment !== "Keine Incident-Indikation") {
    state.incidents.unshift({
      id: crypto.randomUUID(),
      title: `${report.incidentAssessment}: ${report.title}`,
      severity: criticalAlerts > 0 ? "Kritisch" : highAlerts > 0 ? "Hoch" : "Mittel",
      owner: report.owner || "IT / SOC",
      status: report.incidentAssessment === "Meldepflicht prüfen" ? "Meldepflicht prüfen" : "In Bewertung",
      detected: report.periodEnd || today(),
      due: futureDate(3),
      note: report.summary || "Aus SOC/SIEM-Auswertung erzeugte Incident-Vorprüfung.",
      linkedTo
    });
  }
}

function createRiskFromSocReport(reportId) {
  if (!canEditWorkspace()) {
    showPermissionToast("Risiken anlegen", "Bearbeitungsrechten");
    return;
  }
  const report = normalizeSocReports(state.socReports).find((item) => item.id === reportId);
  if (!report) {
    showToast("SOC/SIEM-Report nicht gefunden.");
    return;
  }
  if (state.risks.some((risk) => risk.sourceSocReportId === report.id)) {
    showToast("Risiko wurde für diesen SOC/SIEM-Report bereits übernommen.");
    return;
  }
  const suggestion = buildSocRiskSuggestion(report);
  const risk = {
    id: crypto.randomUUID(),
    riskId: nextRiskId(),
    asset: report.assetScope || report.source || "SOC/SIEM Scope",
    scenario: suggestion.scenario,
    owner: report.owner || "IT / SOC",
    cia: "C/I/A kombiniert",
    threat: "Erhöhte Sicherheitsereignisse oder Angriffsindikatoren aus SOC/SIEM-Auswertung",
    vulnerability: report.summary || "Offene Findings oder wiederkehrende Alerts müssen bewertet und behandelt werden.",
    likelihood: suggestion.likelihood,
    impact: suggestion.impact,
    treatmentOption: "Reduzieren",
    controls: "A.8.15 / A.8.16 / A.8.8 / A.5.24-A.5.28",
    treatment: report.actions || "SOC/SIEM-Findings analysieren, technische Maßnahmen priorisieren, offene Findings nachverfolgen und Wirksamkeit prüfen.",
    residualLikelihood: "-",
    residualImpact: "-",
    acceptanceOwner: "Risk Owner / Management",
    review: futureDate(90),
    status: "In Bewertung",
    sourceSocReportId: report.id,
    sourceSocReportTitle: report.title,
    added: today()
  };
  state.risks.unshift(risk);
  state.tasks.unshift({
    id: crypto.randomUUID(),
    title: `Risikobehandlung aus SOC/SIEM planen: ${risk.riskId}`,
    module: "Risiko Management",
    owner: risk.owner,
    due: futureDate(14),
    status: "Offen",
    linkedTo: risk.riskId,
    note: `Aus SOC/SIEM-Report übernommen: ${report.title || socReportTitle(report)}`
  });
  saveState();
  showToast(`Risiko ${risk.riskId} aus SOC/SIEM-Report übernommen.`);
  render();
}

function socReportTitle(report = {}) {
  const source = report.source || "SOC/SIEM";
  const type = report.reportType || "Report";
  const period = socReportPeriod(report);
  return `${source} ${type}${period ? ` ${period}` : ""}`.trim();
}

function socReportPeriod(report = {}) {
  if (report.periodStart && report.periodEnd) return `${report.periodStart} bis ${report.periodEnd}`;
  return report.periodEnd || report.periodStart || "";
}

function numericValue(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : 0;
}

function handleTemplateSubmit(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const template = TEMPLATE_LIBRARY.find((item) => item.id === form.dataset.templateForm);
  if (!template) return;

  const data = collectTemplateData(form);
  const id = crypto.randomUUID();
  const title = `${template.outputName} ${today()}`;
  const content = buildTemplateDocument(template, data);
  const documentId = crypto.randomUUID();

	  const draft = {
	    id,
	    documentId,
	    title,
    templateId: template.id,
    templateTitle: template.title,
    area: template.area,
    linkedTo: template.linkedTo,
    owner: data.owner || "ISB / Policy Owner",
    status: "Entwurf",
    approval: "Nicht gestartet",
    version: data.version || "0.1",
    review: dateInputValue(data.reviewDate || data.review, futureDate(DOCUMENT_REVIEW_DAYS)),
    classification: "Intern",
    documentKind: isPolicyLikeTemplate(template) ? "Vollständiger Policy-/Prozessentwurf" : "Arbeitsvorlage",
    generatorVersion: isPolicyLikeTemplate(template) ? POLICY_GENERATOR_VERSION : "",
    data,
	    content,
	    added: today()
	  };
	  addTemplateDraftVersionHistory(draft, "Erste Entwurfsversion erzeugt", {}, `Aus Template erstellt: ${template.title}`);
	  state.templateDrafts.unshift(draft);

  state.documents.unshift(normalizeDocumentRecord({
    id: documentId,
    name: title,
    area: template.area,
    status: "Entwurf",
    owner: data.owner || "Offen",
    linkedTo: template.linkedTo,
    version: data.version || "0.1",
    review: dateInputValue(data.reviewDate || data.review, futureDate(DOCUMENT_REVIEW_DAYS)),
    approval: "Nicht gestartet",
    classification: "Intern",
    evidenceFor: template.linkedTo,
    size: "",
    note: `Aus Template erstellt: ${template.title}`,
    added: today()
  }, "Arbeitsvorlage erzeugt"));

  selectedTemplateDraftId = id;
  saveState();
  showToast("Arbeitsvorlage gespeichert und als Dokument vermerkt.");
  render();
}

function downloadTemplateDraft(form) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === form.dataset.templateForm);
  if (!template) return;
  const content = buildTemplateDocument(template, collectTemplateData(form));
  downloadTextFile(`${slugify(template.outputName)}-${today()}.md`, content, "text/markdown");
  showToast("Markdown-Entwurf erstellt.");
}

function handleTemplateDraftEditorSubmit(event) {
  event.preventDefault();
  saveTemplateDraftFromEditor(event.currentTarget);
}

function saveTemplateDraftFromEditor(form, options = {}) {
  if (!form) return;
  if (!canEditWorkspace()) {
    showPermissionToast("Arbeitsvorlagen speichern", "Bearbeitungsrechten");
    return;
  }
	  const draft = state.templateDrafts.find((item) => item.id === form.dataset.templateDraftEditor);
	  if (!draft) return;

	  const previousTitle = draft.title;
	  const previous = {
	    title: draft.title || "",
	    version: draft.version || draft.data?.version || "",
	    status: draft.status || "",
	    review: draft.review || "",
	    linkedTo: draft.linkedTo || "",
	    content: draft.content || ""
	  };
	  const field = (name) => form.querySelector(`[data-draft-field="${name}"]`)?.value?.trim() || "";
  const content = form.querySelector("[data-draft-content]")?.value || draft.content || "";
  const nextVersion = options.bumpVersion ? nextDraftVersion(field("version") || draft.version) : field("version");

  Object.assign(draft, {
    title: field("title") || draft.title || "Unbenannte Arbeitsvorlage",
    owner: field("owner") || "ISB / Policy Owner",
    version: nextVersion || "0.1",
    status: field("status") || "Entwurf",
    approval: field("approval") || "Nicht gestartet",
    review: field("review") || futureDate(DOCUMENT_REVIEW_DAYS),
    classification: field("classification") || "Intern",
    linkedTo: field("linkedTo") || draft.linkedTo || "",
    content,
    updated: today()
  });

  draft.data = {
    ...(draft.data || {}),
    title: draft.title,
    documentTitle: draft.title,
    owner: draft.owner,
    version: draft.version,
    review: draft.data?.review || draft.review,
    reviewDate: draft.review,
    classification: draft.classification,
    controlReference: draft.linkedTo
  };

	  syncTemplateDraftDocument(draft, previousTitle, options.bumpVersion ? "Neue Version gespeichert" : "Entwurf aktualisiert");
	  addTemplateDraftVersionHistory(
	    draft,
	    options.bumpVersion ? "Neue Entwurfsversion gespeichert" : "Entwurf aktualisiert",
	    previous,
	    options.bumpVersion ? `Neue Version ${draft.version} gespeichert.` : "Bearbeitungsstand des Entwurfs gespeichert."
	  );
	  selectedTemplateDraftId = draft.id;
  saveState({ immediate: true });
  showToast(options.bumpVersion ? `Neue Version ${draft.version} gespeichert.` : "Entwurf gespeichert.");
  render();
}

function nextDraftVersion(version) {
  return window.SFMVersioning.nextDraftVersion(version);
}

function syncTemplateDraftDocument(draft, previousTitle = "", action = "Entwurf aktualisiert") {
  const document = findDocumentForTemplateDraft(draft, previousTitle);
  const payload = normalizeDocumentRecord({
    ...(document || {}),
    id: document?.id || draft.documentId || crypto.randomUUID(),
    name: draft.title,
    area: draft.area || "Policy",
    status: draft.status || "Entwurf",
    owner: draft.owner || draft.data?.owner || "ISB / Policy Owner",
    linkedTo: draft.linkedTo || draft.data?.controlReference || "",
    version: draft.version || "0.1",
    review: dateInputValue(draft.review || draft.reviewDate || draft.data?.reviewDate || draft.data?.review, futureDate(DOCUMENT_REVIEW_DAYS)),
    approval: draft.approval || "Nicht gestartet",
    classification: draft.classification || "Intern",
    evidenceFor: draft.linkedTo || draft.data?.controlReference || "",
    size: draft.content ? formatBytes(new Blob([draft.content]).size) : "",
    note: `Gespeicherte Arbeitsvorlage: ${draft.templateTitle || draft.documentKind || "Policy-Arbeitsvorlage"}`,
    added: document?.added || draft.added || today()
  }, "Arbeitsvorlage verknüpft");

  if (document) {
    Object.assign(document, payload);
    addDocumentHistory(document, action, "Policy-Arbeitsvorlage und Dokumentenregister wurden synchronisiert.");
    draft.documentId = document.id;
    return document;
  }

  state.documents.unshift(payload);
  addDocumentHistory(payload, action, "Policy-Arbeitsvorlage wurde im Dokumentenregister angelegt.");
  draft.documentId = payload.id;
  return payload;
}

function findDocumentForTemplateDraft(draft, previousTitle = "") {
  const keys = [
    draft.documentId,
    draft.title,
    previousTitle
  ].filter(Boolean).map((value) => normalizeImportKey(value));
  return state.documents.find((document) => keys.includes(normalizeImportKey(document.id))
    || keys.includes(normalizeImportKey(document.name)));
}

function downloadSavedTemplateDraft(id) {
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) return;
  downloadTextFile(`${slugify(draft.title || "arbeitsvorlage")}-${today()}.md`, presentationDocumentContent(draft.content || ""), "text/markdown");
  showToast("Gespeicherte Arbeitsvorlage exportiert.");
}

function openTemplateDraftDocument(id) {
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) return;
  let document = findDocumentForTemplateDraft(draft, draft.title);
  if (!document) {
    if (!canEditWorkspace()) {
      showToast("Dokumentverweis ist noch nicht vorhanden.");
      return;
    }
    document = syncTemplateDraftDocument(draft, draft.title, "Dokumentverweis geprüft");
  } else if (canEditWorkspace()) {
    document = syncTemplateDraftDocument(draft, draft.title, "Dokumentverweis geprüft");
  }
  selectedDocumentId = document.id;
  if (canEditWorkspace()) saveState();
  navigateToView("documents");
}

function submitTemplateDraftForReview(id) {
  if (!canSubmitDocuments()) {
    showPermissionToast("Arbeitsvorlagen einreichen", "Kunden-, Contributor- oder Beraterrechten");
    return;
  }
  const draft = state.templateDrafts.find((item) => item.id === id);
  if (!draft) {
    showToast("Arbeitsvorlage nicht gefunden.", "warning");
    return;
  }
  const document = findDocumentForTemplateDraft(draft, draft.title);
  const currentStatus = canonicalReviewStatus(document || draft, "document");
  if (["freigegeben", "archiviert", "vom_kunden_eingereicht", "in_beraterpruefung"].includes(currentStatus)) {
    showToast("Diese Arbeitsvorlage ist bereits eingereicht oder freigegeben.");
    return;
  }

  const previousDraftTitle = draft.title;
  const previousDraft = compactRecordSnapshot(draft, ["title", "templateTitle", "owner", "version", "status", "approval", "review", "linkedTo", "content"]);
  const wasRework = currentStatus === "nacharbeit_noetig" || draft.status === "Überarbeiten" || draft.approval === "Abgelehnt" || Boolean(draft.reworkReason || document?.reworkReason);

  Object.assign(draft, {
    status: "In Prüfung",
    approval: "Prüfung läuft",
    reviewStatus: "vom_kunden_eingereicht",
    submittedAt: today(),
    submittedBy: draft.submittedBy || workflowActor(),
    reviewUpdatedAt: today(),
    customerComment: "",
    reworkReason: "",
    reworkDue: "",
    reworkMissing: "",
    reworkWhy: "",
    reworkAction: "",
    reworkReference: "",
    resubmittedAfterReworkAt: wasRework ? today() : (draft.resubmittedAfterReworkAt || ""),
    resubmissionCount: wasRework ? Number(draft.resubmissionCount || 0) + 1 : Number(draft.resubmissionCount || 0)
  });
  addTemplateDraftVersionHistory(
    draft,
    wasRework ? "Arbeitsvorlage erneut eingereicht" : "Arbeitsvorlage eingereicht",
    previousDraft,
    "Einreichungsstand für Beraterprüfung dokumentiert."
  );

  const syncedDocument = syncTemplateDraftDocument(draft, previousDraftTitle, wasRework ? "Arbeitsvorlage erneut eingereicht" : "Arbeitsvorlage eingereicht");
  const previousDocument = compactRecordSnapshot(syncedDocument, ["status", "approval", "owner", "review", "linkedTo", "evidenceFor", "version", "classification", "fileId", "sha256"]);
  Object.assign(syncedDocument, normalizeDocumentRecord({
    ...syncedDocument,
    status: "In Prüfung",
    approval: "Prüfung läuft",
    reviewStatus: "vom_kunden_eingereicht",
    submittedAt: today(),
    submittedBy: syncedDocument.submittedBy || workflowActor(),
    reviewUpdatedAt: today(),
    customerComment: "",
    reworkReason: "",
    reworkDue: "",
    reworkMissing: "",
    reworkWhy: "",
    reworkAction: "",
    reworkReference: "",
    resubmittedAfterReworkAt: wasRework ? today() : (syncedDocument.resubmittedAfterReworkAt || ""),
    resubmissionCount: wasRework ? Number(syncedDocument.resubmissionCount || 0) + 1 : Number(syncedDocument.resubmissionCount || 0)
  }));
  addDocumentVersionHistory(
    syncedDocument,
    wasRework ? "Arbeitsvorlage erneut eingereicht" : "Arbeitsvorlage eingereicht",
    previousDocument,
    "Arbeitsvorlage wurde als Nachweis zur Beraterprüfung eingereicht."
  );
  addReviewHistoryEntry(syncedDocument, {
    action: wasRework ? reviewDecisionLabel("resubmit") : "Zur Beraterprüfung eingereicht",
    status: reviewStatusLabel("vom_kunden_eingereicht"),
    type: "Nachweis",
    title: syncedDocument.name || draft.title || "Arbeitsvorlage",
    customerComment: wasRework ? "Kunde hat die Arbeitsvorlage nach Nacharbeit erneut eingereicht." : "Kunde hat die Arbeitsvorlage zur Prüfung eingereicht.",
    note: "Wartet auf fachliche Prüfung durch Berater/Admin."
  });
  completeDocumentWorkflowTasksByType(syncedDocument, ["rework"], "Arbeitsvorlage erneut eingereicht.");
  upsertDocumentWorkflowTask(syncedDocument, "review");
  selectedTemplateDraftId = draft.id;
  saveState({ immediate: true });
  showToast("Arbeitsvorlage zur Beraterprüfung eingereicht.");
  render();
}

function updateProjectPlanItem(id) {
  const row = appView.querySelector(`[data-project-row="${id}"]`);
  if (!row) return;
  state.projectPlan = normalizeProjectPlan(state.projectPlan).map((item) => {
    if (item.id !== id) return item;
    return {
      ...item,
      owner: row.querySelector("[data-project-owner]")?.value || item.owner,
      due: row.querySelector("[data-project-due]")?.value || "",
      status: row.querySelector("[data-project-status]")?.value || item.status
    };
  });
  saveState();
  showToast("Projektpaket aktualisiert.");
  render();
}

function createTaskForProjectPlanItem(id) {
  const item = normalizeProjectPlan(state.projectPlan).find((row) => row.id === id);
  if (!item) return false;
  const created = addTaskIfMissing({
    title: `${item.stream}: ${item.phase} - ${item.title}`,
    module: "Projektstrukturplan",
    owner: item.owner || "ISB",
    due: item.due || "",
    status: item.status === "Erledigt" ? "Erledigt" : "Offen"
  });
  if (created && item.status === "Offen") {
    state.projectPlan = normalizeProjectPlan(state.projectPlan).map((row) => row.id === id ? { ...row, status: "In Arbeit" } : row);
  }
  saveState();
  showToast(created ? "Projektaufgabe angelegt." : "Aufgabe ist bereits vorhanden.");
  render();
  return created;
}

function createProjectTaskPack() {
  let created = 0;
  normalizeProjectPlan(state.projectPlan).forEach((item, index) => {
    const added = addTaskIfMissing({
      title: `${item.stream}: ${item.phase} - ${item.title}`,
      module: "Projektstrukturplan",
      owner: item.owner || "ISB",
      due: item.due || futureDate(7 + index * 4),
      status: item.status === "Erledigt" ? "Erledigt" : "Offen"
    });
    if (added) created += 1;
  });
  return created;
}

function createPolicyPackage(options = {}) {
  const created = { policies: 0, drafts: 0, updatedDrafts: 0, documents: 0, tasks: 0 };

  POLICY_PACKAGE.forEach((item, index) => {
    const template = TEMPLATE_LIBRARY.find((candidate) => candidate.id === item.templateId);
    const review = futureDate(90 + index * 7);
    const policyAdded = addRecordIfMissing("policies", "title", item.title, {
      title: item.title,
      owner: item.owner,
      version: "0.1",
      status: "Entwurf",
      review,
      linkedTo: item.linkedTo,
      templateId: item.templateId,
      group: item.group,
      source: item.source
    });
    if (policyAdded) created.policies += 1;

    if (template) {
      const data = policyTemplateSeedData(item, template, review);
      const existingDraft = findPolicyDraft(item);
	      if (existingDraft) {
	        const previousDraft = {
	          title: existingDraft.title || "",
	          version: existingDraft.version || existingDraft.data?.version || "",
	          status: existingDraft.status || "",
	          review: existingDraft.review || "",
	          linkedTo: existingDraft.linkedTo || "",
	          content: existingDraft.content || ""
	        };
	        const mergedData = mergePolicyDraftData(data, existingDraft.data, existingDraft.generatorVersion !== POLICY_GENERATOR_VERSION);
	        const content = buildPolicyPackageDocument(item, template, mergedData);
	        if (policyDraftNeedsRefresh(existingDraft, content)) {
          Object.assign(existingDraft, {
            policyPackageId: item.id,
            templateId: item.templateId,
            templateTitle: template.title,
            area: template.area,
            linkedTo: item.linkedTo,
            source: item.source,
            manualSection: item.manualSection,
            documentKind: "Vollständiger Policy-/Prozessentwurf",
            generatorVersion: POLICY_GENERATOR_VERSION,
            data: mergedData,
            content,
	            updated: today()
	          });
	          addTemplateDraftVersionHistory(existingDraft, "Policy-Paket-Entwurf aktualisiert", previousDraft, "Generator hat den Entwurf mit aktueller Struktur erweitert.");
	          created.updatedDrafts += 1;
	        }
	      } else {
	        const content = buildPolicyPackageDocument(item, template, data);
	        const draft = {
	          id: crypto.randomUUID(),
	          policyPackageId: item.id,
	          title: `${item.title} Entwurf ${today()}`,
          templateId: item.templateId,
          templateTitle: template.title,
          area: template.area,
          linkedTo: item.linkedTo,
          source: item.source,
          manualSection: item.manualSection,
          documentKind: "Vollständiger Policy-/Prozessentwurf",
          generatorVersion: POLICY_GENERATOR_VERSION,
	          data,
	          content,
	          added: today()
	        };
	        addTemplateDraftVersionHistory(draft, "Policy-Paket-Entwurf erzeugt", {}, "Automatisch aus Policy-/Prozesspaket angelegt.");
	        state.templateDrafts.unshift(draft);
	        created.drafts += 1;
	      }
    }

    const documentName = `${item.title} Entwurf`;
    const existsDoc = state.documents.some((doc) => normalizeImportKey(doc.name) === normalizeImportKey(documentName));
    if (!existsDoc) {
      state.documents.unshift(normalizeDocumentRecord({
        id: crypto.randomUUID(),
        name: documentName,
        area: "Policy",
        status: "Entwurf",
        owner: item.owner,
        linkedTo: item.linkedTo,
        version: "0.1",
        review,
        approval: "Nicht gestartet",
        classification: "Intern",
        evidenceFor: item.linkedTo,
        size: "",
        note: `Vollständiger Policy-/Prozessentwurf automatisch erzeugt${template ? `: ${template.title}` : ""}. Quelle: ${item.source}${item.manualSection ? `, ${item.manualSection}` : ""}. ${item.purpose}`,
        added: today()
      }, "Policy-Paket erzeugt"));
      created.documents += 1;
    }

    const taskAdded = addTaskIfMissing({
      title: `Policy finalisieren: ${item.title}`,
      module: "Policy Management",
      owner: item.owner,
      due: futureDate(14 + index * 4),
      status: "Offen"
    });
    if (taskAdded) created.tasks += 1;
  });

  if (options.save !== false) saveState();
  return created;
}

