function createAuditGapTasks() {
  if (!canEditWorkspace()) {
    showPermissionToast("Audit-Aufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const rows = auditTraceabilityRows(state.documents.filter((document) => document.status !== "Quelle"))
    .filter((row) => !row.task && (row.status === "Fehlt" || row.status === "Review überfällig" || row.riskScore >= 12))
    .slice(0, 20);
  if (!rows.length) {
    showToast("Keine neuen Audit-Lücken ohne Aufgabe gefunden.");
    return;
  }
  let created = 0;
  rows.forEach((row) => {
    const title = auditGapTaskTitle(row);
    if (addTaskIfMissing({
      title,
      module: row.module || row.stream || "Auditmatrix",
      owner: row.owner || "ISB",
      due: futureDate(row.status === "Review überfällig" ? 7 : 14),
      status: "Offen",
      linkedTo: row.mapping || row.title || "Audit-/Nachweismatrix",
      note: `Aus Audit-/Nachweismatrix erzeugt. Status: ${row.status}; Nachweis: ${row.evidence || "offen"}.`
    })) {
      created += 1;
    }
  });
  saveState();
  showToast(created ? `${created} Audit-Aufgabe(n) angelegt.` : "Passende Audit-Aufgaben waren bereits vorhanden.");
  render();
}

function auditGapTaskTitle(row) {
  if (row.status === "Review überfällig") return `Review aktualisieren: ${row.mapping || row.title || "Nachweis"}`;
  if (row.status === "Fehlt") return `Nachweis ergänzen: ${row.mapping || row.title || "Audit-Zeile"}`;
  return `Audit-Zeile prüfen: ${row.mapping || row.title || "Traceability"}`;
}

function createAuditExecutionFindingTasks() {
  if (!canEditWorkspace()) {
    showPermissionToast("Audit-Finding-Aufgaben anlegen", "Bearbeitungsrechten");
    return;
  }
  const rows = auditTraceabilityRows(state.documents.filter((document) => document.status !== "Quelle"));
  const findings = auditExecutionFindings(rows, auditPackageReportData()).slice(0, 20);
  if (!findings.length) {
    showToast("Keine priorisierten Audit-Findings gefunden.");
    return;
  }

  let created = 0;
  findings.forEach((finding) => {
    const added = addTaskIfMissing({
      title: `Audit-Finding klären: ${finding.title}`,
      module: finding.view ? viewToTaskModule(finding.view) : "Auditmatrix",
      owner: finding.owner || "ISB",
      due: finding.due || futureDate(14),
      status: "Offen",
      linkedTo: finding.linkedTo || "Audit Execution Center",
      note: `${finding.type || "Finding"}: ${finding.text || "Bitte fachlich prüfen und Maßnahme dokumentieren."}`
    });
    if (added) created += 1;
  });

  saveState();
  showToast(created ? `${created} Audit-Finding-Aufgabe(n) angelegt.` : "Audit-Finding-Aufgaben waren bereits vorhanden.");
  render();
}

