function appendMarkdownTable(lines, headers, rows) {
  if (!rows.length) {
    lines.push("- Keine Einträge vorhanden.");
    return;
  }
  lines.push(`| ${headers.map(markdownCell).join(" | ")} |`);
  lines.push(`| ${headers.map(() => "---").join(" | ")} |`);
  rows.forEach((row) => {
    lines.push(`| ${row.map(markdownCell).join(" | ")} |`);
  });
}

function markdownCell(value) {
  return String(value ?? "")
    .replace(/\|/g, "/")
    .replace(/\r?\n/g, " ")
    .trim() || "-";
}

function auditStatusPriority(status) {
  const value = String(status || "");
  if (value === "Fehlt") return 1;
  if (value === "Review überfällig") return 2;
  if (["Blockiert", "Überarbeiten", "Abgelehnt"].includes(value)) return 3;
  if (["In Prüfung", "Entwurf", "In Arbeit", "Offen"].includes(value)) return 4;
  if (["Freigegeben", "Erledigt", "Bereit"].includes(value)) return 8;
  return 5;
}

