async function handleSafeMaintenanceAction(button) {
  const actionKey = String(button?.dataset.maintenanceAction || "");
  const label = String(button?.dataset.maintenanceLabel || "Wartungsaktion");
  const affected = String(button?.dataset.maintenanceAffected || "");
  if (!actionKey) return;
  if (actionKey === "cleanup-job-artifacts") {
    backgroundJobFilter = "artifacts";
    navigateToView("jobs");
    showToast("Job-Artefakte werden in den Hintergrundjobs gefiltert angezeigt.");
    return;
  }
  const countText = affected ? ` Betroffen: ${affected}.` : "";
  if (!window.confirm(`${label} wirklich kontrolliert ausführen?${countText} Die Aktion wird im Audit Trail protokolliert.`)) return;
  button.disabled = true;
  try {
    const payload = await apiRequest(`/api/maintenance/actions/${encodeURIComponent(actionKey)}`, {
      method: "POST",
      json: {}
    });
    productionAdminData = {
      ...productionAdminData,
      operations: payload.operations || productionAdminData.operations
    };
    showToast(`${label}: ${payload.affected || 0} Eintrag/Einträge verarbeitet.`);
    render();
  } catch (error) {
    button.disabled = false;
    showToast(`Wartungsaktion fehlgeschlagen: ${error.message}`, "warning");
  }
}

async function copyCurrentInvitation() {
  const text = productionAdminData.invitation?.text || "";
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
    showToast("Übergabenotiz kopiert.");
  } catch {
    const textarea = appView.querySelector("[data-invitation-text]");
    textarea?.select();
    showToast("Kopieren bitte über Cmd+C abschließen.");
  }
}

function downloadCurrentInvitation() {
  const invitation = productionAdminData.invitation;
  if (!invitation?.text) return;
  const base = invitation.type === "tenant" ? (invitation.tenantName || "kundenprojekt") : (invitation.username || "kunde");
  downloadTextFile(`sfm-compliance-zugang-${slugify(base)}-${today()}.md`, invitation.text, "text/markdown");
  showToast("Übergabenotiz heruntergeladen.");
}

function suggestTenantProjectFields(form) {
  if (!form) return;
  const nameInput = form.querySelector("input[name='name']");
  const slugInput = form.querySelector("input[name='slug']");
  const adminInput = form.querySelector("input[name='adminUsername']");
  const passwordInput = form.querySelector("input[name='adminPassword']");
  const name = String(nameInput?.value || "").trim();
  if (!name) {
    showToast("Bitte zuerst den Mandantennamen eintragen.");
    return;
  }
  const slug = slugify(name) || `kunde-${Date.now()}`;
  if (slugInput && !slugInput.value) slugInput.value = slug;
  if (adminInput && !adminInput.value) adminInput.value = `${slug}.admin`.slice(0, 64);
  if (passwordInput && !passwordInput.value) passwordInput.value = generateInitialPassword();
  showToast("Projektfelder vorgeschlagen.");
}

async function handleAdminCreateInvitation(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = Object.fromEntries(new FormData(form).entries());
  try {
    const payload = await apiRequest("/api/invitations", {
      method: "POST",
      json: {
        displayName: String(data.displayName || "").trim(),
        email: String(data.email || "").trim(),
        role: String(data.role || "customer"),
        tenantId: String(data.tenantId || backendSessionUser.tenant?.id || ""),
        expiresDays: Number(data.expiresDays || 7)
      }
    });
    const invitation = payload.invitation || {};
    productionAdminData.invitation = {
      type: "invitation",
      username: invitation.email,
      tenantName: invitation.tenantName,
      role: invitation.role,
      createdAt: today(),
      text: buildTeamInvitationText(invitation)
    };
    form.reset();
    if (invitation.deliveryStatus === "delivered") {
      showToast("Einladung wurde per E-Mail zugestellt.");
    } else if (invitation.deliveryStatus === "failed") {
      showToast("Einladung erstellt, aber die E-Mail-Zustellung ist fehlgeschlagen. Link bitte kontrolliert teilen.", "warning");
    } else {
      showToast("Einladungslink erstellt. Bitte jetzt kopieren oder herunterladen.");
    }
    await loadProductionAdminData();
  } catch (error) {
    const message = error.payload?.code === "invitation_already_pending"
      ? "Für diese E-Mail-Adresse besteht bereits eine offene Einladung. Nutze dort „Erneut senden“ oder widerrufe sie zuerst."
      : error.payload?.code === "invitation_account_exists"
        ? "Für diese E-Mail-Adresse besteht bereits ein aktiver Zugang in diesem Kunden-Workspace."
        : error.message;
    showToast(`Einladung konnte nicht erstellt werden: ${message}`, "warning");
  }
}

