async function handleLifecycleExport(button) {
  const tenantId = button?.dataset.lifecycleExport;
  const tenant = (productionAdminData.lifecycle?.tenants || []).find((row) => row.id === tenantId);
  if (!tenantId || !tenant) {
    showToast("Kundenraum wurde in der aktuellen Lebenszyklusansicht nicht gefunden.", "warning");
    return;
  }
  const originalLabel = button.textContent;
  button.disabled = true;
  button.textContent = "Export wird geprüft ...";
  try {
    const response = await fetch(`/api/tenants/${encodeURIComponent(tenantId)}/export`, {
      method: "POST",
      credentials: "same-origin",
      headers: { "X-CSRF-Token": backendCsrfToken }
    });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.error || payload.message || `HTTP ${response.status}`);
    }
    const blob = await response.blob();
    const disposition = response.headers.get("Content-Disposition") || "";
    const match = disposition.match(/filename="([^"]+)"/i);
    const filename = match?.[1] || `sfm-compliance-${tenant.slug || tenantId}-export.zip`;
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    showToast(`Mandantenexport für „${tenant.name}“ wurde erstellt und protokolliert.`);
    await loadProductionAdminData();
  } catch (error) {
    showToast(`Mandantenexport konnte nicht erstellt werden: ${error.message}`, "warning");
  } finally {
    button.disabled = false;
    button.textContent = originalLabel;
  }
}

