function nisItemModule(label) {
  if (label.includes("Lieferkette")) return "Vendor Management";
  if (label.includes("Schulung") || label.includes("Sensibilisierung")) return "Aufgaben / Awareness";
  if (label.includes("Sicherheitsvorfällen")) return "Incident Management";
  if (label.includes("Backup") || label.includes("Krisen")) return "Risk Register / Continuity";
  if (label.includes("Kryptograph")) return "Policy Management";
  if (label.includes("Zugriff")) return "Asset Management / Access";
  return "Risk Register";
}

function riskScore(likelihood, impact) {
  return riskEngine.score(likelihood, impact);
}

function riskLevel(score) {
  return riskEngine.level(score);
}

function enrichRisk(risk) {
  const inherentScore = riskScore(risk.likelihood, risk.impact);
  const residualScore = riskScore(risk.residualLikelihood, risk.residualImpact);
  return {
    ...risk,
    riskId: risk.riskId || risk.id?.slice(0, 8) || "-",
    inherent: inherentScore ? `${inherentScore} (${riskLevel(inherentScore)})` : "-",
    residual: residualScore ? `${residualScore} (${riskLevel(residualScore)})` : "-"
  };
}

function nextRiskId() {
  const max = state.risks.reduce((highest, risk) => {
    const match = String(risk.riskId || "").match(/^R-(\d+)$/);
    return match ? Math.max(highest, Number(match[1])) : highest;
  }, state.risks.length);
  return `R-${String(max + 1).padStart(3, "0")}`;
}

function formatCell(value, key) {
  if (value === undefined || value === null || value === "") return "<span class=\"muted\">-</span>";
  if (["status", "criticality", "severity", "review", "inherent", "residual"].includes(key)) return statusTag(value);
  if (key === "fileId") {
    const id = String(value);
    if (!canDownloadDocuments()) return `<code>${escapeHtml(id.slice(0, 8))}</code>`;
    return `<a href="/api/files/${encodeURIComponent(id)}/download" title="Datei aus Backend herunterladen">${escapeHtml(id.slice(0, 8))}</a>`;
  }
  if (key === "sha256") return `<code>${escapeHtml(String(value).slice(0, 12))}</code>`;
  return escapeHtml(String(value));
}

function statusTag(value) {
  const text = String(value || "");
  let cls = "tag";
  if (["Freigegeben", "Erledigt", "Quelle", "Umgesetzt", "Akzeptiert", "Geschlossen", "Aktiv", "Geprüft", "Bereit"].includes(text)) cls += " practice";
  if (["Offen", "Prüfen", "In Prüfung", "Prüfung läuft", "In Behandlung", "In Arbeit", "Entwurf", "In Bewertung", "Restrisiko prüfen", "Meldepflicht prüfen", "Geplant", "In Planung", "In Umsetzung", "Nacharbeiten"].includes(text)) cls += " should";
  if (["Blockiert", "Nachbesserung", "Überarbeiten", "Abgelehnt", "Review überfällig", "Fehlt", "Sehr hoch", "Kritisch", "Pausiert", "Pflichtfelder offen"].includes(text) || text.includes("Sehr hoch") || text.includes("Hoch")) cls += " must";
  if (text.includes("Niedrig") || text.includes("Mittel")) cls += " practice";
  return `<span class="${cls}">${escapeHtml(text)}</span>`;
}

function draftReviewDate(draft) {
  return dateInputValue(draft?.review || draft?.reviewDate || draft?.data?.reviewDate || draft?.data?.review, futureDate(DOCUMENT_REVIEW_DAYS));
}

function showToast(message, tone = "") {
  toast.textContent = message;
  toast.classList.remove("success", "warning", "danger");
  toast.classList.add(toastTone(message, tone));
  toast.classList.add("show");
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove("show"), 2400);
}

function toastTone(message, tone = "") {
  if (["success", "warning", "danger"].includes(tone)) return tone;
  const text = String(message || "").toLowerCase();
  if (/(fehlgeschlagen|konnte nicht|nicht erreichbar|abgebrochen|gesperrt|fehler|blockiert|ungültig)/.test(text)) return "danger";
  if (/(prüfen|offen|überfällig|nachbesserung|nicht verfügbar)/.test(text)) return "warning";
  return "success";
}
